script_name("AutoMiner")
script_author("Moli")
script_version("1.1.3")

require "lib.moonloader"

-- First-run dependency bootstrap.  MoonLoader itself, LuaJIT/ffi and SAMPFUNCS are
-- host prerequisites; AutoMiner can self-install the distributable Lua/UI libraries.
local function _amScriptDir()
    local ok,script=pcall(thisScript)
    if ok and script and script.path then return tostring(script.path):match("^(.*)[/\\]") or getWorkingDirectory() end
    return getWorkingDirectory()
end
local function _amTryRequire(name)
    local ok,mod=pcall(require,name)
    return ok and mod or nil
end
local _amImgui=_amTryRequire("mimgui")
local _amSampev=_amTryRequire("samp.events")
local _amEncoding=_amTryRequire("encoding")
local _amArizona=_amTryRequire("arizona-events")
local _amBit=_amTryRequire("bit")
local _amFfi=_amTryRequire("ffi")
local _amMissing={}
if not _amImgui then _amMissing[#_amMissing+1]="mimgui" end
if not _amSampev then _amMissing[#_amMissing+1]="samp.events" end
if not _amEncoding then _amMissing[#_amMissing+1]="encoding" end
if not _amArizona then _amMissing[#_amMissing+1]="arizona-events" end
if not _amBit then _amMissing[#_amMissing+1]="bit" end
if not _amFfi then _amMissing[#_amMissing+1]="ffi" end

if #_amMissing>0 then
    local function qps(value) return tostring(value or ""):gsub("'","''") end
    local function ensureDir(path)
        if doesDirectoryExist and doesDirectoryExist(path) then return true end
        if createDirectory then local ok,res=pcall(createDirectory,path);return ok and res~=false end
        return false
    end
    local function waitDownload(url,path,timeout)
        if not downloadUrlToFile then return false,"downloadUrlToFile unavailable" end
        pcall(os.remove,path)
        local done,success=false,false
        local ok=pcall(downloadUrlToFile,url,path,function(_,status)
            if status==6 then done=true;success=true end
            if status==7 then done=true;success=false end
        end)
        if not ok then return false,"download start failed" end
        local started=getGameTimer()
        while not done and getGameTimer()-started<(timeout or 60000) do wait(50) end
        if not done then pcall(os.remove,path);return false,"download timeout" end
        return success
    end
    local function expandArchive(zip,destination)
        ensureDir(destination)
        local cmd="powershell -NoProfile -ExecutionPolicy Bypass -Command \"Expand-Archive -LiteralPath '"..qps(zip).."' -DestinationPath '"..qps(destination).."' -Force\""
        local code=os.execute(cmd)
        return code==0 or code==true
    end
    local function copyDir(source,destination)
        ensureDir(destination)
        local cmd="powershell -NoProfile -ExecutionPolicy Bypass -Command \"Copy-Item -LiteralPath '"..qps(source).."' -Destination '"..qps(destination).."' -Recurse -Force\""
        local code=os.execute(cmd)
        return code==0 or code==true
    end
    local function findFolder(root,name)
        local cmd="powershell -NoProfile -Command \"$p=Get-ChildItem -LiteralPath '"..qps(root).."' -Directory -Recurse -ErrorAction SilentlyContinue | Where-Object {$_.Name -eq '"..qps(name).."'} | Select-Object -First 1 -ExpandProperty FullName; if($p){[Console]::Out.Write($p)}\""
        local h=io.popen(cmd,"r");if not h then return nil end
        local out=h:read("*a");h:close();return out~="" and out or nil
    end
    local function bootstrapInstall()
        local root=_amScriptDir().."\\AutoMiner"
        local temp=root.."\\bootstrap"
        local lib=_amScriptDir().."\\lib"
        ensureDir(root);ensureDir(temp);ensureDir(lib)
        local needImgui=not _amImgui
        local needSamp=not _amSampev
        local needArizona=not _amArizona
        local failures={}
        if needImgui then
            local zip=temp.."\\mimgui-v1.7.1.zip"
            local ok,why=waitDownload("https://github.com/THE-FYP/mimgui/releases/download/v1.7.1/mimgui-v1.7.1.zip",zip,90000)
            if ok then
                local out=temp.."\\mimgui";ensureDir(out)
                if expandArchive(zip,out) then
                    local folder=findFolder(out,"mimgui")
                    if folder then copyDir(folder,lib) else failures[#failures+1]="mimgui: package layout" end
                else failures[#failures+1]="mimgui: extract" end
            else failures[#failures+1]="mimgui: "..tostring(why) end
            pcall(os.remove,zip)
        end
        if needSamp then
            local zip=temp.."\\samp-lua-v2.3.0.zip"
            local ok,why=waitDownload("https://github.com/THE-FYP/SAMP.Lua/archive/refs/tags/v2.3.0.zip",zip,90000)
            if ok then
                local out=temp.."\\samp";ensureDir(out)
                if expandArchive(zip,out) then
                    local folder=findFolder(out,"samp")
                    if folder then copyDir(folder,lib) else failures[#failures+1]="samp.events: package layout" end
                else failures[#failures+1]="samp.events: extract" end
            else failures[#failures+1]="samp.events: "..tostring(why) end
            pcall(os.remove,zip)
        end
        if needArizona then
            local zip=temp.."\\arizona-events.zip"
            local ok,why=waitDownload("https://github.com/wojciech941/arizona-events/archive/refs/heads/main.zip",zip,90000)
            if ok then
                local out=temp.."\\arizona-events";ensureDir(out)
                if expandArchive(zip,out) then
                    local folder=findFolder(out,"arizona-events")
                    if folder then copyDir(folder,lib) else failures[#failures+1]="arizona-events: package layout" end
                else failures[#failures+1]="arizona-events: extract" end
            else failures[#failures+1]="arizona-events: "..tostring(why) end
            pcall(os.remove,zip)
        end
        -- encoding/bit/ffi belong to the normal MoonLoader/LuaJIT distribution and
        -- are not replaced from random mirrors.  Report them as a host problem.
        if not _amEncoding then failures[#failures+1]="encoding: MoonLoader library missing" end
        if not _amBit then failures[#failures+1]="bit: LuaJIT library missing" end
        if not _amFfi then failures[#failures+1]="ffi: LuaJIT library missing" end
        return #failures==0,failures
    end
    
function main()
        while not isSampAvailable() do wait(100) end
        sampAddChatMessage("{4CC9F0}[AutoMiner]{FFFFFF} Підготовка компонентів...",-1)
        local ok,failures=bootstrapInstall()
        if ok then
            sampAddChatMessage("{4CC9F0}[AutoMiner]{FFFFFF} Компоненти встановлено. Перезапускаємо AutoMiner...",-1)
            local cleanup="powershell -NoProfile -ExecutionPolicy Bypass -Command \"Remove-Item -LiteralPath '"..qps(_amScriptDir().."\\AutoMiner\\bootstrap").."' -Recurse -Force -ErrorAction SilentlyContinue\""
            pcall(os.execute,cleanup)
            wait(800)
            local status,script=pcall(thisScript)
            if status and script and script.reload then script:reload() end
        else
            sampAddChatMessage("{4CC9F0}[AutoMiner]{FFFFFF} Не вдалося підготувати компоненти. Перевірте moonloader\\AutoMiner\\bootstrap.",-1)
            for _,item in ipairs(failures or {}) do print("[AutoMiner bootstrap] "..tostring(item)) end
        end
        while true do wait(1000) end
    end
    return
end

