local Ignored={}
local function ignoredHouseKey(number)
    return tonumber(number) or tostring(number or "")
end
local function isHouseIgnored(number)
    local key=ignoredHouseKey(number)
    return Ignored[key] or Ignored[tostring(number or "")] or false
end
local function setHouseIgnored(number,value)
    local key=ignoredHouseKey(number)
    Ignored[key]=value and true or nil
    Ignored[tostring(number or "")]=nil
end
