function I18n.text(value)
    local text=tostring(value or "")
    local language=Settings.language or "uk"
    if I18n.language~=language then I18n.cache={};I18n.count=0;I18n.language=language end
    if I18n.cache[text] then return I18n.cache[text] end
    if not I18n.buckets then
        I18n.buckets={}
        table.sort(I18n.entries,function(a,b) return #a[1]>#b[1] end)
        for _,entry in ipairs(I18n.entries) do
            local key=entry[1]:byte(1)
            I18n.buckets[key]=I18n.buckets[key] or {}
            table.insert(I18n.buckets[key],entry)
        end
    end
    local function word(byte)
        return byte and (byte>=128 or byte>=48 and byte<=57 or byte>=65 and byte<=90 or byte>=97 and byte<=122 or byte==95)
    end
    local parts,pos={},1
    while pos<=#text do
        local match=nil
        for _,entry in ipairs(I18n.buckets[text:byte(pos)] or {}) do
            local source=entry[1]
            if text:sub(pos,pos+#source-1)==source
                and not (word(source:byte(1)) and word(text:byte(pos-1)))
                and not (word(source:byte(-1)) and word(text:byte(pos+#source))) then match=entry;break end
        end
        if match then parts[#parts+1]=match[language=="ru" and 3 or 2];pos=pos+#match[1]
        else parts[#parts+1]=text:sub(pos,pos);pos=pos+1 end
    end
    local result=table.concat(parts)
    if I18n.count>1500 then I18n.cache={};I18n.count=0 end
    I18n.cache[text]=result;I18n.count=I18n.count+1
    return result
end
function I18n.setLanguage(language)
    language=(language=="ru") and "ru" or "uk"
    Settings.language=language
    I18n.language=nil;I18n.cache={};I18n.count=0;I18n.buckets=nil
    Runtime.log("LANGUAGE_CHANGED","language="..language)
    return language
end


local Notify={last={},lastVariant={}}
local NotifySetting={
    startup="notifyStartup",collect_result="notifyCollectResult",collect_error="notifyCollectErrors",
    refill_start="notifyRefillStart",refill_end="notifyRefillEnd",refill_error="notifyRefillErrors",
    maintenance="notifyMaintenance",electricity="notifyElectricity",taxes="notifyTaxes",
    critical="notifyCritical",background="notifyBackground"
}
function Notify.enabled(kind)
    if Settings.chatNotifications==false then return false end
    local key=NotifySetting[kind]
    return not key or Settings[key]~=false
end
function Notify.tagColor()
    local hex=tostring(Settings.chatTagColor or "4CC9F0"):gsub("[^%x]",""):upper()
    if #hex~=6 then hex="4CC9F0" end
    return hex
end
function Notify.pick(key,items)
    if not items or #items==0 then return "" end
    if #items==1 then return items[1] end
    local last=Notify.lastVariant[key]
    local index=math.random(1,#items)
    if last and index==last then index=index%#items+1 end
    Notify.lastVariant[key]=index
    return items[index]
end
function Notify.chatText(text,alreadyLocalized)
    -- SA-MP's chat font/codepage renders several typographic Unicode symbols
    -- inconsistently. Keep the UI typography, but normalize chat-only text to
    -- simple CP1251/ASCII-safe separators so notifications never show boxes or
    -- odd glyphs on different Arizona builds.
    local value=alreadyLocalized and tostring(text or "") or I18n.text(tostring(text or ""))
    value=value:gsub("·","-")
        :gsub("—","-")
        :gsub("–","-")
        :gsub("…","...")
        :gsub("→","->")
        :gsub("≤","<=")
        :gsub("≥",">=")
        :gsub("≈","")
        :gsub("×","x")
        :gsub("−","-")
        :gsub("’", "'")
    return value
end
function Notify.localized(uk,ru)
    return tostring(Settings.language or "uk")=="ru" and tostring(ru or uk or "") or tostring(uk or "")
end
function Notify.forceLocalized(uk,ru)
    local msg="{"..Notify.tagColor().."}[AutoMiner]{FFFFFF} "..Notify.chatText(Notify.localized(uk,ru),true)
    pcall(sampAddChatMessage,u8:decode(msg),-1)
    return true
end
function Notify.force(text)
    local msg="{"..Notify.tagColor().."}[AutoMiner]{FFFFFF} "..Notify.chatText(text)
    pcall(sampAddChatMessage,u8:decode(msg),-1)
    return true
end
function Notify.raw(kind,text,key,cooldown)
    if not Notify.enabled(kind) then return false end
    local now=getGameTimer()
    local eventKey=tostring(key or kind or text)
    local ms=math.max(0,tonumber(cooldown) or 0)*1000
    if ms>0 and Notify.last[eventKey] and now-Notify.last[eventKey]<ms then return false end
    Notify.last[eventKey]=now
    local msg="{"..Notify.tagColor().."}[AutoMiner]{FFFFFF} "..Notify.chatText(text)
    pcall(sampAddChatMessage,u8:decode(msg),-1)
    return true
end
function Notify.rawLocalized(kind,uk,ru,key,cooldown)
    if not Notify.enabled(kind) then return false end
    local now=getGameTimer();local eventKey=tostring(key or kind or uk)
    local ms=math.max(0,tonumber(cooldown) or 0)*1000
    if ms>0 and Notify.last[eventKey] and now-Notify.last[eventKey]<ms then return false end
    Notify.last[eventKey]=now
    local text=Notify.localized(uk,ru)
    local msg="{"..Notify.tagColor().."}[AutoMiner]{FFFFFF} "..Notify.chatText(text,true)
    pcall(sampAddChatMessage,u8:decode(msg),-1);return true
end
function Notify.event(event,data)
    data=data or {}
    local ru=Settings.language=="ru"
    if event=="startup" then
        local v=ru and {"загружен · /miner","готов к работе · /miner","активен · /miner"}
            or {"завантажено · /miner","готовий до роботи · /miner","активний · /miner"}
        return Notify.raw("startup",Notify.pick(event,v),"startup",2)
    elseif event=="collect_result" then
        local btc=math.max(0,tonumber(data.btc) or 0)
        local usd=tonumber(data.usd)
        local function chatNumber(value)
            local digits=string.format("%.0f",math.max(0,tonumber(value) or 0))
            return (digits:reverse():gsub("(%d%d%d)","%1 "):reverse():gsub("^ ",""))
        end
        local btcText=(btc>=1000 and chatNumber(btc) or ((btc>=100 and string.format("%.1f",btc)) or (btc>=10 and string.format("%.2f",btc)) or string.format("%.3f",btc))):gsub("0+$",""):gsub("%.$","").." BTC"
        local usdText=usd and (chatNumber(usd).." $") or nil
        local amount
        if Settings.incomeMode=="btc" then
            amount=btcText
        elseif Settings.incomeMode=="virtual" then
            amount=usdText or btcText
        elseif Settings.incomeMode=="money_btc" then
            amount=(usdText and (usdText.." ("..btcText..")")) or btcText
        else
            amount=btcText..(usdText and (" ("..usdText..")") or "")
        end
        local text=(ru and "Собрано " or "Зібрано ")..amount
        return Notify.raw("collect_result",text,"collect_result:"..amount,2)
    elseif event=="collect_error" then
        local reason=tostring(data.reason or (ru and "неизвестная ошибка" or "невідома помилка"))
        local v=ru and {"Сбор прерван · "..reason,"Не удалось завершить сбор · "..reason,"Ошибка сбора · "..reason}
            or {"Збір перервано · "..reason,"Не вдалося завершити збір · "..reason,"Помилка збору · "..reason}
        return Notify.raw("collect_error",Notify.pick(event,v),"collect_error:"..reason,5)
    elseif event=="refill_start" then
        local v=ru and {
            "Автозаправка запущена · подойдите к следующей GPU",
            "Режим заправки активен · двигайтесь к следующей GPU",
            "Готово к обходу · подойдите к следующей видеокарте"
        } or {
            "Автозаправку запущено · підійдіть до наступної GPU",
            "Режим заправки активний · рухайтесь до наступної GPU",
            "Готово до обходу · підійдіть до наступної відеокарти"
        }
        return Notify.raw("refill_start",Notify.pick(event,v),"refill_start",2)
    elseif event=="refill_end" then
        local count=tonumber(data.count) or 0
        local v=ru and {
            "Автозаправка завершена · заправлено GPU: "..count,
            "Обход завершён · GPU заправлено: "..count,
            "Заправка закончена · обработано GPU: "..count
        } or {
            "Автозаправку завершено · заправлено GPU: "..count,
            "Обхід завершено · GPU заправлено: "..count,
            "Заправку закінчено · оброблено GPU: "..count
        }
        return Notify.raw("refill_end",Notify.pick(event,v),"refill_end:"..count,2)
    elseif event=="refill_error" then
        local reason=tostring(data.reason or "")
        local prefix=ru and "Автозаправка остановлена" or "Автозаправку зупинено"
        return Notify.raw("refill_error",prefix..(reason~="" and (" · "..reason) or ""),"refill_error:"..reason,5)
    end
    return false
end

