local Fonts = {}
local FontGlyphRanges = nil
local CardText = {scale=nil,base={},regular={},semi={}}
local function resolveTextFont(font)
    local spec=font and CardText.base[font]
    if not CardText.scale or not spec then return font end
    local size=math.max(14,math.min(32,math.floor(spec.size*CardText.scale+.5)))
    local best,distance=nil,math.huge
    for pixels,candidate in pairs(CardText[spec.weight]) do
        if math.abs(pixels-size)<distance then best=candidate; distance=math.abs(pixels-size) end
    end
    return best or font
end
