local function getScriptDir()
    local ok, script = pcall(thisScript)
    if ok and script and script.path then
        return tostring(script.path):match("^(.*)[/\\]") or getWorkingDirectory()
    end
    return getWorkingDirectory()
end


local Runtime={revision="1.1.3",lastLog={},readySince=nil,sessionKey=nil,initialRetry=0}
function Runtime.failure(message)
    UI.storageError="Не вдалося зберегти дані: "..tostring(message)
end
function Runtime.open(path,mode)
    mode=mode or "r"
    if not mode:find("[wa]") then
        local f=io.open(path,mode)
        if not f then f=io.open(path..".bak",mode) end
        return f
    end
    local atomic=mode:find("w",1,true)~=nil
    local target=atomic and (path..".writing") or path
    local f,err=io.open(target,mode)
    if not f then Runtime.failure(err or path);return nil end
    local failed=false
    local proxy={}
    function proxy:write(...)
        if failed then return nil end
        local ok,result,why=pcall(f.write,f,...)
        if not ok or not result then failed=true;Runtime.failure(why or result or path);return nil end
        return self
    end
    function proxy:close()
        local ok,result=pcall(f.close,f)
        if not ok or not result then failed=true;Runtime.failure(path) end
        if failed then if atomic then os.remove(target) end;return nil end
        if atomic then
            local old=io.open(path,"rb")
            if old then
                old:close();os.remove(path..".bak")
                if not os.rename(path,path..".bak") then os.remove(target);Runtime.failure(path);return nil end
            end
            if not os.rename(target,path) then
                if old then os.rename(path..".bak",path) end
                Runtime.failure(path);return nil
            end
        end
        return true
    end
    return proxy
end
function Runtime.log(kind,detail,interval)
    local now=os.time();local key=kind.."|"..tostring(detail)
    if interval and Runtime.lastLog[key] and now-Runtime.lastLog[key]<interval then return end
    if Runtime.logCount and Runtime.logCount>256 then Runtime.lastLog={};Runtime.logCount=0 end
    Runtime.lastLog[key]=now;Runtime.logCount=(Runtime.logCount or 0)+1
    local path=getScriptDir().."\\AutoMiner\\diagnostic.log"
    local f=io.open(path,"rb")
    if f then local size=f:seek("end") or 0;f:close();if size>2*1024*1024 then os.remove(path..".1");os.rename(path,path..".1") end end
    f=io.open(path,"a")
    if not f then Runtime.failure(path);return end
    local ok=f:write(os.date("%Y-%m-%d %H:%M:%S")," | ",kind," | ",tostring(detail or ""):gsub("[\r\n]"," "),"\n")
    local closed=f:close();if not ok or not closed then Runtime.failure(path) end
end
-- Single owner for every AutoMiner-driven SA-MP dialog transaction.
-- Nested helpers (maintenance -> electricity/taxes) temporarily push their owner.
local DialogGate={owner="none",stage="idle",context=nil,stack={},lastRx=nil,token=0}
function DialogGate.contextText(ctx)
    ctx=ctx or DialogGate.context or {}
    local p={}
    if ctx.house then p[#p+1]="house="..tostring(ctx.house) end
    if ctx.rack then p[#p+1]="rack="..tostring(ctx.rack) end
    if ctx.slot then p[#p+1]="shelf="..tostring(ctx.slot) end
    return table.concat(p," ")
end
function DialogGate.log(event,detail)
    Runtime.log("AM_"..tostring(event),
        "owner="..tostring(DialogGate.owner).." stage="..tostring(DialogGate.stage).." "
