-- Small built-in fallback asset pack. Existing user assets are never overwritten;
-- missing files are recreated locally so a clean install does not depend on a
-- separate asset archive or leave broken/missing texture placeholders.
local EmbeddedAssets={
    ["arizona_springs_villa.png"]="",
    ["neon_frame.png"]="",
    ["glow_dot.png"]="",
    ["neon_border_atlas.png"]="",
    ["elite_badge.png"]="",
    ["card_surface.png"]=""
}
local function decodeBase64(data)
    local alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local map={};for i=1,#alphabet do map[alphabet:sub(i,i)]=i-1 end
    local out={};local i=1
    while i<=#data do
        local a=map[data:sub(i,i)] or 0;local b=map[data:sub(i+1,i+1)] or 0
        local cch=data:sub(i+2,i+2);local dch=data:sub(i+3,i+3)
        local c=map[cch] or 0;local d=map[dch] or 0
        local n=a*262144+b*4096+c*64+d
        out[#out+1]=string.char(math.floor(n/65536)%256)
        if cch~="=" and cch~="" then out[#out+1]=string.char(math.floor(n/256)%256) end
        if dch~="=" and dch~="" then out[#out+1]=string.char(n%256) end
        i=i+4
    end
    return table.concat(out)
end
local function ensureEmbeddedAssets()
    local root=getScriptDir().."\\AutoMiner\\assets"
    if doesDirectoryExist and not doesDirectoryExist(root) and createDirectory then pcall(createDirectory,root) end
    local created=0
    for name,data in pairs(EmbeddedAssets) do
        local path=getAssetPath(name)
        if not doesFileExist or not doesFileExist(path) then
            local ok,body=pcall(decodeBase64,data)
            if ok and body and #body>8 then
                local f=io.open(path,"wb");if f then f:write(body);f:close();created=created+1 end
            end
        end
    end
    if created>0 then Runtime.log("ASSET_SELF_HEAL","created="..tostring(created)) end
    return created
end

