local UPDATE_MANIFEST_URL="https://raw.githubusercontent.com/mihajlobusko5-star/AutoMiner/main/version.json"
local UpdateManager={
    status="idle",latest=nil,downloadUrl=nil,sha256=nil,changelog={},expanded=false,
    error=nil,lastCheck=0,nextCheck=0,installed=false,installedVersion=nil,checking=false,installing=false
}

local function updateQps(value) return tostring(value or ""):gsub("'","''") end
local function updateReadAll(path)
    local f=io.open(path,"rb");if not f then return nil end
    local body=f:read("*a");f:close();return body
end
local function updateWriteAll(path,body)
    local f=io.open(path,"wb");if not f then return false end
    local ok=f:write(body or "");f:close();return ok~=nil
end
local function updateJsonUnescape(value)
    value=tostring(value or "")
    value=value:gsub('\\"','"'):gsub('\\\\','\\'):gsub('\\/','/')
    value=value:gsub('\\n','\n'):gsub('\\r','\r'):gsub('\\t','\t')
    return value
end
local function updateParseManifest(body)
    body=tostring(body or "")
    local version=body:match('"version"%s*:%s*"([^"]+)"')
    local url=body:match('"download_url"%s*:%s*"([^"]+)"')
    local sha=body:match('"sha256"%s*:%s*"([0-9a-fA-F]+)"')
    local block=body:match('"changelog"%s*:%s*%[(.-)%]') or ""
    local changes={}
    local pos=1
    while true do
        local first=block:find('"',pos,true)
        if not first then break end
        local out={};local i=first+1;local escaped=false;local closed=false
        while i<=#block do
            local ch=block:sub(i,i)
            if escaped then out[#out+1]="\\"..ch;escaped=false
            elseif ch=="\\" then escaped=true
            elseif ch=='"' then closed=true;break
            else out[#out+1]=ch end
            i=i+1
        end
        if not closed then break end
        changes[#changes+1]=updateJsonUnescape(table.concat(out))
        pos=i+1
    end
    if not version or version=="" or not url or url=="" then return nil,"manifest fields missing" end
    if sha and #sha~=64 then return nil,"invalid sha256" end
    return {version=version,download_url=updateJsonUnescape(url),sha256=sha and sha:lower() or nil,changelog=changes}
end
local function updateVersionParts(v)
    local a,b,c=tostring(v or "0"):match("^(%d+)%.(%d+)%.(%d+)")
    return tonumber(a) or 0,tonumber(b) or 0,tonumber(c) or 0
end
local function updateVersionNewer(remote,localv)
    local ra,rb,rc=updateVersionParts(remote);local la,lb,lc=updateVersionParts(localv)
    if ra~=la then return ra>la end;if rb~=lb then return rb>lb end;return rc>lc
end
UpdateManager.downloadCallbacks=UpdateManager.downloadCallbacks or {}
UpdateManager.downloadSerial=UpdateManager.downloadSerial or 0
local function updateDownload(url,path,timeout)
    if not downloadUrlToFile then return false,"downloadUrlToFile unavailable" end
    pcall(os.remove,path)
    UpdateManager.downloadSerial=UpdateManager.downloadSerial+1
    local token=UpdateManager.downloadSerial
    local state={done=false,success=false,timedOut=false}
    local callback
    callback=function(_,status)
        if status==6 then state.done=true;state.success=true
        elseif status==7 then state.done=true;state.success=false end
        if state.done then
            -- Keep the callback alive until MoonLoader confirms completion/failure.
            -- Releasing it on our own timeout can leave native downloader code with
            -- a dangling Lua callback and crash lua51.dll later.
            UpdateManager.downloadCallbacks[token]=nil
            if state.timedOut then pcall(os.remove,path) end
        end
    end
    UpdateManager.downloadCallbacks[token]=callback
    local ok,err=pcall(downloadUrlToFile,url,path,callback)
    if not ok then UpdateManager.downloadCallbacks[token]=nil;return false,tostring(err or "download start failed") end
    local started=getGameTimer();timeout=timeout or 60000
    while not state.done and getGameTimer()-started<timeout do wait(50) end
    if not state.done then
        state.timedOut=true
        -- Do not free the callback here. MoonLoader may still invoke it later.
        -- The callback removes itself only after a terminal download status.
        return false,"download timeout"
    end
    if not state.success then pcall(os.remove,path);return false,"download failed" end
    return true
end
local UpdateWin32=nil
local function updateHiddenProcess(command,timeoutMs)
    if not UpdateWin32 then
        local ok=pcall(ffi.cdef,[[
            typedef void* AM_HANDLE;
            typedef unsigned long AM_DWORD;
            typedef int AM_BOOL;
            typedef unsigned short AM_WORD;
            typedef unsigned char AM_BYTE;
            typedef struct _AM_STARTUPINFOA {
                AM_DWORD cb; char* lpReserved; char* lpDesktop; char* lpTitle;
                AM_DWORD dwX; AM_DWORD dwY; AM_DWORD dwXSize; AM_DWORD dwYSize;
                AM_DWORD dwXCountChars; AM_DWORD dwYCountChars; AM_DWORD dwFillAttribute;
                AM_DWORD dwFlags; AM_WORD wShowWindow; AM_WORD cbReserved2; AM_BYTE* lpReserved2;
                AM_HANDLE hStdInput; AM_HANDLE hStdOutput; AM_HANDLE hStdError;
            } AM_STARTUPINFOA;
            typedef struct _AM_PROCESS_INFORMATION {
                AM_HANDLE hProcess; AM_HANDLE hThread; AM_DWORD dwProcessId; AM_DWORD dwThreadId;
            } AM_PROCESS_INFORMATION;
            AM_BOOL CreateProcessA(const char*, char*, void*, void*, AM_BOOL, AM_DWORD, void*, const char*, AM_STARTUPINFOA*, AM_PROCESS_INFORMATION*);
            AM_DWORD WaitForSingleObject(AM_HANDLE, AM_DWORD);
            AM_BOOL TerminateProcess(AM_HANDLE, unsigned int);
            AM_BOOL CloseHandle(AM_HANDLE);
        ]])
        local loaded,lib=pcall(ffi.load,"kernel32")
        if not ok or not loaded then return false,"win32 unavailable" end
        UpdateWin32=lib
    end
    local si=ffi.new("AM_STARTUPINFOA[1]")
    local pi=ffi.new("AM_PROCESS_INFORMATION[1]")
    si[0].cb=ffi.sizeof("AM_STARTUPINFOA")
    si[0].dwFlags=0x00000001 -- STARTF_USESHOWWINDOW
    si[0].wShowWindow=0      -- SW_HIDE
    local buffer=ffi.new("char[?]",#command+2)
    ffi.copy(buffer,command)
    local ok=UpdateWin32.CreateProcessA(nil,buffer,nil,nil,0,0x08000000,nil,nil,si,pi) -- CREATE_NO_WINDOW
    if ok==0 then return false,"CreateProcess failed" end
    local waitResult=UpdateWin32.WaitForSingleObject(pi[0].hProcess,tonumber(timeoutMs) or 15000)
    if waitResult==0x00000102 then UpdateWin32.TerminateProcess(pi[0].hProcess,1) end
    UpdateWin32.CloseHandle(pi[0].hThread);UpdateWin32.CloseHandle(pi[0].hProcess)
    return waitResult==0
end
local function updateSha256(path)
    local outPath=cacheFilePath("update-sha256.tmp")
    pcall(os.remove,outPath)
    local ps="$h=(Get-FileHash -LiteralPath '"..updateQps(path).."' -Algorithm SHA256).Hash;[System.IO.File]::WriteAllText('"..updateQps(outPath).."',$h.ToLower())"
    local cmd='powershell.exe -NoProfile -NonInteractive -WindowStyle Hidden -ExecutionPolicy Bypass -Command "'..ps..'"'
    local ok=updateHiddenProcess(cmd,15000)
    local out=ok and updateReadAll(outPath) or nil
    pcall(os.remove,outPath)
    out=tostring(out or ""):gsub("%s+",""):lower()
    return (#out==64 and out:match("^[0-9a-f]+$")) and out or nil
end
function UpdateManager.check(manual)
    if UpdateManager.checking or UpdateManager.installing then return false end
    UpdateManager.checking=true;UpdateManager.error=nil;UpdateManager.status="checking"
    lua_thread.create(function()
        ensureAutoMinerDirectory(cacheDirPath())
        local path=cacheFilePath("update-manifest.download.tmp")
        local url=UPDATE_MANIFEST_URL.."?t="..tostring(os.time())
        local ok,why=updateDownload(url,path,25000)
        if not ok then
            UpdateManager.error=tostring(why);UpdateManager.status="error";UpdateManager.checking=false
            Runtime.log("UPDATE_CHECK_ERROR",UpdateManager.error,10)
            if manual then UI.notice=Settings.language=="ru" and "Не удалось проверить обновления" or "Не вдалося перевірити оновлення" end
            return
        end
        local manifest,err=updateParseManifest(updateReadAll(path));pcall(os.remove,path)
        if not manifest then
            UpdateManager.error=tostring(err);UpdateManager.status="error";UpdateManager.checking=false
            Runtime.log("UPDATE_MANIFEST_ERROR",UpdateManager.error,10)
            if manual then UI.notice=Settings.language=="ru" and "Некорректный файл обновления" or "Некоректний файл оновлення" end
            return
        end
        UpdateManager.latest=manifest.version;UpdateManager.downloadUrl=manifest.download_url
        UpdateManager.sha256=manifest.sha256;UpdateManager.changelog=manifest.changelog or {}
        UpdateManager.lastCheck=os.time();UpdateManager.nextCheck=os.time()+6*60*60
        UpdateManager.status=updateVersionNewer(manifest.version,Runtime.revision) and "available" or "latest"
        UpdateManager.checking=false
        Runtime.log("UPDATE_CHECK","local="..tostring(Runtime.revision).." remote="..tostring(manifest.version).." status="..UpdateManager.status)
        if manual then
            UI.notice=UpdateManager.status=="available"
                and (Settings.language=="ru" and ("Доступно обновление v"..manifest.version) or ("Доступне оновлення v"..manifest.version))
                or (Settings.language=="ru" and "Установлена последняя версия" or "Встановлена остання версія")
        end
    end)
    return true
end
function UpdateManager.install()
    if UpdateManager.installing or UpdateManager.checking or UpdateManager.status~="available" then return false end
    if not UpdateManager.downloadUrl or not UpdateManager.sha256 then
        UpdateManager.error=Settings.language=="ru" and "В manifest отсутствует SHA-256" or "У manifest відсутній SHA-256"
        UpdateManager.status="error";return false
    end
    UpdateManager.installing=true;UpdateManager.error=nil;UpdateManager.status="downloading"
    lua_thread.create(function()
        ensureAutoMinerDirectory(cacheDirPath())
        local tmp=cacheFilePath("AutoMiner.update.tmp")
        local backup=cacheFilePath("AutoMiner.backup.lua")
        local sep=UpdateManager.downloadUrl:find("?",1,true) and "&" or "?"
        local ok,why=updateDownload(UpdateManager.downloadUrl..sep.."t="..tostring(os.time()),tmp,90000)
        if not ok then
            UpdateManager.error=tostring(why);UpdateManager.status="error";UpdateManager.installing=false
            Runtime.log("UPDATE_DOWNLOAD_ERROR",UpdateManager.error);return
        end
        local body=updateReadAll(tmp)
        if not body or #body<10000 or not body:find('script_name("AutoMiner")',1,true) then
            pcall(os.remove,tmp);UpdateManager.error="invalid AutoMiner.lua";UpdateManager.status="error";UpdateManager.installing=false
            Runtime.log("UPDATE_VALIDATE_ERROR",UpdateManager.error);return
        end
        UpdateManager.status="verifying"
        local digest=updateSha256(tmp)
        if not digest or digest~=tostring(UpdateManager.sha256):lower() then
            pcall(os.remove,tmp);UpdateManager.error="SHA-256 mismatch";UpdateManager.status="error";UpdateManager.installing=false
            Runtime.log("UPDATE_HASH_ERROR","expected="..tostring(UpdateManager.sha256).." actual="..tostring(digest));return
        end
        UpdateManager.status="installing"
        local script=thisScript();local target=script and script.path or (getScriptDir().."\\AutoMiner.lua")
        pcall(os.remove,backup)
        -- Replace with ordinary Lua file I/O so installing an update never opens a console window.
        local current=updateReadAll(target)
        local fresh=updateReadAll(tmp)
        local replaced=false
        if current and fresh then
            local backupOk=updateWriteAll(backup,current)
            replaced=backupOk and updateWriteAll(target,fresh) or false
        end
        if replaced then pcall(os.remove,tmp) end
        if not replaced then
            UpdateManager.error="replace failed";UpdateManager.status="error";UpdateManager.installing=false
            Runtime.log("UPDATE_INSTALL_ERROR",UpdateManager.error);return
        end
        UpdateManager.installed=true;UpdateManager.installedVersion=UpdateManager.latest
        UpdateManager.status="installed";UpdateManager.installing=false
        Runtime.log("UPDATE_INSTALLED","version="..tostring(UpdateManager.installedVersion).." backup="..tostring(backup))
        UI.notice=Settings.language=="ru" and "Обновление установлено. Перезапустите скрипт или игру." or "Оновлення встановлено. Перезапустіть скрипт або гру."
    end)
    return true
end
local function migrateFileIfNeeded(oldPath,newPath)
    if doesFileExist and doesFileExist(oldPath) and not doesFileExist(newPath) then
        local ok=pcall(os.rename,oldPath,newPath)
        if ok and doesFileExist(newPath) then return true end
        local src=io.open(oldPath,"rb")
        if src then local body=src:read("*a");src:close();local dst=io.open(newPath,"wb");if dst then dst:write(body);dst:close();pcall(os.remove,oldPath);return true end end
    end
    return false
end
local function cleanupAutoMinerTemps()
    ensureAutoMinerDirectory(autoMinerRootPath());ensureAutoMinerDirectory(cacheDirPath());ensureAutoMinerDirectory(dataDirPath())
    local removed=0
    local function sweepPattern(directory,pattern)
        if not findFirstFile then return end
        local search,name=findFirstFile(directory.."\\"..pattern)
        while name do
            local path=directory.."\\"..name
            if pcall(os.remove,path) and (not doesFileExist or not doesFileExist(path)) then removed=removed+1 end
            name=findNextFile(search)
        end
        if search and findClose then pcall(findClose,search) end
    end
    sweepPattern(autoMinerRootPath(),"*.tmp");sweepPattern(cacheDirPath(),"*.tmp")
    sweepPattern(autoMinerRootPath(),"*.writing");sweepPattern(cacheDirPath(),"*.writing");sweepPattern(dataDirPath(),"*.writing")
    -- A bootstrap directory is only used during installation; after a restart it is stale.
    local boot=autoMinerRootPath().."\\bootstrap"
    if doesDirectoryExist and doesDirectoryExist(boot) then
        local function qps(v) return tostring(v or ""):gsub("'","''") end
        pcall(os.execute,"powershell -NoProfile -ExecutionPolicy Bypass -Command \"Remove-Item -LiteralPath '"..qps(boot).."' -Recurse -Force -ErrorAction SilentlyContinue\"")
    end
    for _,name in ipairs({"bitcoin-history.cache","bitcoin-hourly.cache","bitcoin-price.cache"}) do
        migrateFileIfNeeded(autoMinerRootPath().."\\"..name,cacheFilePath(name))
    end
    for _,name in ipairs({"ignored.cfg","journal.log","architect.cfg","income-inputs.log","btc-history-hourly.log","income-history.log","miner-parse.log","tax-route.json"}) do
        migrateFileIfNeeded(autoMinerRootPath().."\\"..name,dataDirPath().."\\"..name)
    end
    Runtime.log("CACHE_CLEANUP","removed="..tostring(removed))
    return removed
end

local function loadSettings()
    local file = Runtime.open(settingsPath(), "r")
    if not file then return end
    for line in file:lines() do
        local key, value = line:match("^([%a]+)=(.-)%s*$")
        if key=="autoTaxes" then Settings.autoTaxes=value=="true" end
        if key=="autoElectricity" then Settings.autoElectricity=value=="true" end
        if key=="nextElectricityCheck" and tonumber(value) then Settings.nextElectricityCheck=math.max(0,math.floor(tonumber(value))) end
        if key=="autoRefill" then Settings.autoRefill=value=="true" end
        if key=="chatNotifications" then Settings.chatNotifications=value~="false" end
        if key=="chatTagColor" then
            local hex=tostring(value or ""):gsub("[^%x]",""):upper()
            if #hex==6 then Settings.chatTagColor=hex end
        end
        if key=="notifyStartup" then Settings.notifyStartup=value~="false" end
        if key=="notifyCollectResult" then Settings.notifyCollectResult=value~="false" end
        if key=="notifyCollectErrors" then Settings.notifyCollectErrors=value~="false" end
        if key=="notifyRefillStart" then Settings.notifyRefillStart=value~="false" end
        if key=="notifyRefillEnd" then Settings.notifyRefillEnd=value~="false" end
        if key=="notifyRefillErrors" then Settings.notifyRefillErrors=value~="false" end
        if key=="notifyMaintenance" then Settings.notifyMaintenance=value~="false" end
        if key=="notifyElectricity" then Settings.notifyElectricity=value~="false" end
        if key=="notifyTaxes" then Settings.notifyTaxes=value~="false" end
        if key=="notifyCritical" then Settings.notifyCritical=value~="false" end
        if key=="notifyBackground" then Settings.notifyBackground=value=="true" end
        if key=="language" and (value=="uk" or value=="ru") then Settings.language=value end
        if key=="incomeMode" and (value=="both" or value=="money_btc" or value=="btc" or value=="virtual") then Settings.incomeMode=value end
        if key=="numberMode" then Settings.numberMode="full" end
        if key == "sort" and (value == "attention" or value == "number") then Settings.sort = value end
        if key == "neonSpeed" and tonumber(value) then Settings.neonSpeed = math.max(0.7, math.min(1.3, tonumber(value))) end
        if key == "showCycles" then Settings.showCycles = value ~= "false" end
        if key == "afkEnabled" then Settings.afkEnabled=value=="true" end
        if key == "afkMinutes" then Settings.afkMinutes=math.max(1,math.min(120,math.floor(tonumber(value) or 10))) end
        if key=="coolingMode" and (value=="all" or value=="lowest" or value=="cycle") then Settings.coolingMode=value end
        if key == "cardColumns" then Settings.cardColumns=math.max(3,math.min(5,math.floor(tonumber(value) or 3))) end
        if key == "animations" and (value == "full" or value == "reduced" or value == "off") then Settings.animations = value end
        if key == "startTab" and (value == "home" or value == "houses") then Settings.startTab = value end
        if key == "coolingWarn" and tonumber(value) then Settings.coolingWarn = math.max(0, math.min(100, tonumber(value))) end
        if key == "electricityWarn" and tonumber(value) then Settings.electricityWarn = math.max(0, tonumber(value)) end
        if key == "collectMode" and (value=="manual" or value=="timer" or value=="smart") then Settings.collectMode=value end
        if key == "timerMinutes" and tonumber(value) then Settings.timerMinutes=math.max(1,math.floor(tonumber(value)+.5)) end
        if key == "smartMinMinutes" and tonumber(value) then Settings.smartMinMinutes=math.max(1,math.floor(tonumber(value)+.5)) end
        if key == "smartMaxMinutes" and tonumber(value) then Settings.smartMaxMinutes=math.max(1,math.floor(tonumber(value)+.5)) end
        if key == "nextCollectAt" and tonumber(value) then Settings.nextCollectAt=math.max(0,math.floor(tonumber(value))) end
        if key == "autoRetry" then Settings.autoRetry=value~="false" end
        if key == "autoPaused" then Settings.autoPaused=value=="true" end
        if key == "singleShelfLayout" and (value=="vertical" or value=="horizontal") then Settings.singleShelfLayout=value end
        if key == "allShelvesLayout" and (value=="vertical" or value=="horizontal") then Settings.allShelvesLayout=value end
        if key == "showCoolantPercent" then Settings.showCoolantPercent=value~="false" end
        if key == "refillPreset" and (value=="economy" or value=="balanced" or value=="safe" or value=="custom") then Settings.refillPreset=value end
        if key == "refillThreshold" and tonumber(value) then Settings.refillThreshold=math.max(0,math.min(100,math.floor(tonumber(value)+.5))) end
        if key == "gpuWindowW" and tonumber(value) then Settings.gpuWindowW=tonumber(value) end
        if key == "gpuWindowH" and tonumber(value) then Settings.gpuWindowH=tonumber(value) end
        if key == "windowX" and tonumber(value) then Settings.windowX = tonumber(value) end
        if key == "windowY" and tonumber(value) then Settings.windowY = tonumber(value) end
        if key == "windowW" and tonumber(value) then Settings.windowW=tonumber(value) end
        if key == "windowH" and tonumber(value) then Settings.windowH=tonumber(value) end
    end
    file:close()
    for _,key in ipairs({"timerMinutes","smartMinMinutes","smartMaxMinutes"}) do
        local value=Settings[key]
        Settings[key]=(value==value and value<math.huge) and math.max(1,math.min(10080,value)) or 120
    end
    Settings.smartMaxMinutes=math.max(Settings.smartMinMinutes,Settings.smartMaxMinutes)
    for _,key in ipairs({"windowX","windowY","windowW","windowH","gpuWindowW","gpuWindowH","nextCollectAt","nextElectricityCheck","electricityWarn"}) do
        local value=Settings[key]
        if value and (value~=value or math.abs(value)==math.huge) then Settings[key]=nil end
    end
    Settings.nextCollectAt=Settings.nextCollectAt or 0;Settings.nextElectricityCheck=Settings.nextElectricityCheck or 0;Settings.electricityWarn=Settings.electricityWarn or 0
end

