        "nextCollectAt=" .. tostring(math.max(0,math.floor(Settings.nextCollectAt or 0))) .. "\n",
        "autoRetry=" .. tostring(Settings.autoRetry~=false) .. "\n",
        "autoPaused=" .. tostring(Settings.autoPaused==true) .. "\n",
        "singleShelfLayout=" .. tostring(Settings.singleShelfLayout or "vertical") .. "\n",
        "allShelvesLayout=" .. tostring(Settings.allShelvesLayout or "horizontal") .. "\n",
        "showCoolantPercent=" .. tostring(Settings.showCoolantPercent~=false) .. "\n",
        "refillPreset=" .. tostring(Settings.refillPreset or "balanced") .. "\n",
        "refillThreshold=" .. tostring(math.max(0,math.min(100,math.floor((Settings.refillThreshold or 70)+.5)))) .. "\n",
        Settings.gpuWindowW and ("gpuWindowW="..math.floor(Settings.gpuWindowW+0.5).."\n") or "",
        Settings.gpuWindowH and ("gpuWindowH="..math.floor(Settings.gpuWindowH+0.5).."\n") or "",
