local function v4(c, a)
    return imgui.ImVec4(c[1], c[2], c[3], a or c[4] or 1.0)
end

local function u32(c, a)
    return imgui.ColorConvertFloat4ToU32(v4(c,(a or c[4] or 1)*(Runtime.uiPaintAlpha or 1)))
end

local function mixColor(a, b, t)
    t = math.max(0, math.min(1, t or 0))
    return {
        a[1] + (b[1] - a[1]) * t,
        a[2] + (b[2] - a[2]) * t,
        a[3] + (b[3] - a[3]) * t,
        (a[4] or 1.0) + ((b[4] or 1.0) - (a[4] or 1.0)) * t
    }
end

local function smoothAnim(id, target, speed)
    if Settings and Settings.animations=="off" then
        CardAnim[id]=target
        return target
    end
    local io = imgui.GetIO()
    local dt = tonumber(io.DeltaTime) or 0.016
    local value = CardAnim[id] or 0.0
    local speedMul=(Settings and Settings.animations=="reduced") and 1.55 or 1.0
    local k = 1.0 - math.exp(-(speed or 10.0) * speedMul * dt)
    value = value + (target - value) * k

    if math.abs(value - target) < 0.001 then
        value = target
    end

    CardAnim[id] = value
    return value
end

local Motion={
    pageStart=0,
    pageDir=1,
    graphStart=0,
    numbers={},
    springs={},
    btcLast=nil,
    btcFlashStart=0,
    btcFlashDir=0
}

local function motionEase(t)
    t=math.max(0,math.min(1,tonumber(t) or 0))
    return 1-(1-t)^3
end

local function motionProgress(started,duration)
    if Settings.animations=="off" then return 1 end
    started=tonumber(started) or 0
    if started<=0 then return 1 end
    return math.max(0,math.min(1,(getGameTimer()-started)/math.max(1,duration or 260)))
end

local function motionNumber(id,target,duration)
    target=tonumber(target)
    if not target then return nil end
    if Settings.animations=="off" then
        Motion.numbers[id]={from=target,to=target,value=target,started=getGameTimer()}
        return target
    end
    local now=getGameTimer()
    local n=Motion.numbers[id]
    if not n then
        n={from=0,to=target,value=0,started=now}
        Motion.numbers[id]=n
    elseif math.abs((n.to or 0)-target)>.000001 then
        n.from=n.value or n.to or 0
        n.to=target
        n.started=now
    end
    local ms=duration or (Settings.animations=="reduced" and 360 or 680)
    local t=math.max(0,math.min(1,(now-(n.started or now))/ms))
    local e=t*t*t*(t*(t*6-15)+10)
    n.value=(n.from or 0)+((n.to or target)-(n.from or 0))*e
    if t>=1 then n.value=n.to end
    return n.value
end

local View = {}

local function motionSyncNumber(id,value)
    value=tonumber(value)
    if value==nil then return nil end
    Motion.numbers[id]={from=value,to=value,value=value,started=getGameTimer()}
    return value
end

function View.springValue(id,target,stiffness,damping)
    target=tonumber(target) or 0
    if Settings.animations=="off" then
        Motion.springs[id]={value=target,velocity=0}
        return target
    end
    local io=imgui.GetIO()
    local dt=math.max(.001,math.min(.033,tonumber(io.DeltaTime) or .016))
    local s=Motion.springs[id]
    if not s then s={value=target,velocity=0};Motion.springs[id]=s end
    local k=tonumber(stiffness) or (Settings.animations=="reduced" and 250 or 185)
    local d=tonumber(damping) or (Settings.animations=="reduced" and 30 or 22)
    local a=(target-s.value)*k-s.velocity*d
    s.velocity=s.velocity+a*dt
    s.value=s.value+s.velocity*dt
    if math.abs(target-s.value)<.001 and math.abs(s.velocity)<.01 then s.value=target;s.velocity=0 end
    return s.value
end

local TabOrder={home=1,houses=2,income=3,journal=4,settings=5,problems=6,maintenance=7}
local function switchTab(tab)
    if not tab or UI.activeTab==tab then return end
    local old=TabOrder[UI.activeTab] or 1
    local nxt=TabOrder[tab] or old
    UI.activeTab=tab
    Motion.pageDir=nxt>=old and 1 or -1
    Motion.pageStart=getGameTimer()
    Motion.graphStart=getGameTimer()
end

local function motionSection(delay,duration)
    if Settings.animations=="off" then return 1 end
    if Settings.animations=="reduced" then return motionEase(motionProgress(Motion.pageStart,180)) end
    local elapsed=getGameTimer()-(Motion.pageStart or 0)-(delay or 0)
    return motionEase(math.max(0,math.min(1,elapsed/math.max(1,duration or 240))))
end

local function waitUntil(fn, timeout)
    local started = getGameTimer()
    timeout = timeout or 5000

    while getGameTimer() - started < timeout do
        if fn() then
            return true
        end
        wait(20)
    end

    return false
end


local Journal={items={},filter="all",maxItems=600,loaded=false}
function Journal.path()
    return dataDirPath().."\\journal.log"
end
function Journal.clean(value)
    return tostring(value or ""):gsub("[\r\n\t]"," "):gsub("  +"," ")
end
function Journal.rewrite()
    local f=Runtime.open(Journal.path(),"w")
    if not f then return false end
    for i=#Journal.items,1,-1 do
        local item=Journal.items[i]
        f:write(table.concat({
            tostring(math.floor(tonumber(item.time) or os.time())),
            Journal.clean(item.kind),Journal.clean(item.title),Journal.clean(item.detail),
            tostring(tonumber(item.btc) or 0),tostring(tonumber(item.price) or 0),
            tostring(math.floor(tonumber(item.farms) or 0)),Journal.clean(item.source),Journal.clean(item.house),Journal.clean(item.operation)
        },"\t"),"\n")
    end
    return f:close() and true or false
end
function Journal.load()
    Journal.items={};Journal.loaded=true
    local f=Runtime.open(Journal.path(),"r")
    if not f then return end
    for line in f:lines() do
        local fields={}
        for field in (line.."\t"):gmatch("(.-)\t") do fields[#fields+1]=field end
        local stamp=tonumber(fields[1])
        if stamp then
            table.insert(Journal.items,1,{
                time=stamp,kind=fields[2] or "system",title=fields[3] or "",detail=fields[4] or "",
                btc=tonumber(fields[5]) or 0,price=tonumber(fields[6]) or 0,farms=tonumber(fields[7]) or 0,
                source=fields[8] or "",house=fields[9] or "",operation=(fields[10] and fields[10]~="" and fields[10]~="0") and fields[10] or nil
            })
        end
    end
    f:close()
    while #Journal.items>Journal.maxItems do table.remove(Journal.items) end
    if #Journal.items>=Journal.maxItems then Journal.rewrite() end
end
function Journal.add(kind,title,detail,meta)
    meta=meta or {}
    local now=os.time()
    local cleanTitle=Journal.clean(title)
    local cleanDetail=Journal.clean(detail)
    if kind=="collection" and meta.operation then
        for _,row in ipairs(Journal.items) do
            if row.kind=="collection" and row.operation==meta.operation then
                row.title=cleanTitle;row.detail=cleanDetail;row.btc=tonumber(meta.btc) or row.btc
                row.price=tonumber(meta.price) or row.price;row.farms=tonumber(meta.farms) or row.farms
                Journal.rewrite();return
            end
        end
    end
    local last=Journal.items[1]
    if kind~="collection" and last and last.kind==(kind or "system") and last.title==cleanTitle and last.detail==cleanDetail and now-(tonumber(last.time) or 0)<10 then return end
    local item={
        time=now,kind=kind or "system",title=cleanTitle,detail=cleanDetail,
        btc=tonumber(meta.btc) or 0,price=tonumber(meta.price) or 0,farms=tonumber(meta.farms) or 0,
        source=Journal.clean(meta.source),house=Journal.clean(meta.house),operation=meta.operation
    }
    table.insert(Journal.items,1,item)
    local overflow=#Journal.items>Journal.maxItems
    while #Journal.items>Journal.maxItems do table.remove(Journal.items) end
    if overflow then Journal.rewrite();return end
    local f=Runtime.open(Journal.path(),"a")
    if f then
        f:write(table.concat({tostring(item.time),Journal.clean(item.kind),item.title,item.detail,tostring(item.btc),tostring(item.price),tostring(item.farms),item.source,item.house,Journal.clean(item.operation)},"\t"),"\n")
        f:close()
    end
end
function Journal.countVisible()
    local count=0
    for _,item in ipairs(Journal.items) do
        if Journal.filter=="all" or item.kind==Journal.filter or (Journal.filter=="warning" and item.kind=="error") then count=count+1 end
    end
    return count
end
function Journal.todayStats()
    local day=os.date("%Y-%m-%d")
    local events,collections,btc,usd=0,0,0,0
    for _,item in ipairs(Journal.items) do
        if os.date("%Y-%m-%d",tonumber(item.time) or 0)==day then
            events=events+1
            if item.kind=="collection" then
                collections=collections+1;btc=btc+(tonumber(item.btc) or 0)
                usd=usd+(tonumber(item.btc) or 0)*(tonumber(item.price) or 0)
            end
        end
    end
    return events,collections,btc,usd
end
function Journal.importIncomeHistory(collections)
    local changed=false
    local function validId(v)return type(v)=="string" and v~="" and v~="0" end
    local function sameAmount(a,b)
        return math.abs((tonumber(a.btc) or 0)-(tonumber(b.btc) or 0))<.000001
            and (tonumber(a.farms) or 0)==(tonumber(b.farms) or 0)
            and math.abs((tonumber(a.price) or 0)-(tonumber(b.price) or 0))<.01
    end
    local assigned={}
    for _,income in ipairs(collections or {}) do
        local stamp=tonumber(income.time) or 0
        local op=validId(income.operation) and income.operation or nil
        if stamp>0 and (tonumber(income.btc) or 0)>0 then
            local matches,legacy={},{}
            for _,row in ipairs(Journal.items) do
                if row.kind=="collection" and not assigned[row] then
                    if op and row.operation==op then matches[#matches+1]=row
                    elseif not validId(row.operation) and sameAmount(row,income) then
                        local delta=(row.time or 0)-stamp
                        if row.source=="history" and delta==0 then matches[#matches+1]=row
                        elseif row.source~="history" and delta>=0 and delta<=120 then legacy[#legacy+1]=row end
                    end
                end
            end
            if #legacy==1 then
                local row=legacy[1];local owners=0
                for _,other in ipairs(collections or {}) do
                    local delta=(row.time or 0)-(tonumber(other.time) or 0)
                    if delta>=0 and delta<=120 and sameAmount(row,other) then owners=owners+1 end
                end
                if owners==1 then matches[#matches+1]=row end
            end
            local row=matches[1]
            if not row then
                row={time=stamp,kind="collection",house="",source="history"}
                Journal.items[#Journal.items+1]=row;changed=true
            end
            for i=2,#matches do matches[i]._duplicate=true;assigned[matches[i]]=true;changed=true end
            assigned[row]=true
            local title=(income.status and income.status~="complete") and "Збір частково виконано" or "Збір завершено"
            if row.operation~=op or row.title~=title then changed=true end
            row.operation=op;row.title=title;row.btc=income.btc;row.farms=income.farms or 0
            row.price=income.price or (income.usd and income.usd/income.btc) or 0
            row.detail=Runtime.plural(row.farms,"ферма","ферми","ферм")
        end
    end
    local kept,seen={},{}
    for _,row in ipairs(Journal.items) do
        if not row._duplicate then
            if row.kind=="collection" and validId(row.operation) then
                if seen[row.operation] then changed=true else seen[row.operation]=true;kept[#kept+1]=row end
            else kept[#kept+1]=row end
        end
    end
    Journal.items=kept
    table.sort(Journal.items,function(a,b)return (a.time or 0)>(b.time or 0)end)
    while #Journal.items>Journal.maxItems do table.remove(Journal.items);changed=true end
    if changed then Journal.rewrite() end
end


