        table.remove(ActivityLog.items)
    end
    local journalKind=(kind=="amber" and "warning") or (kind=="red" and "error") or "system"
    Journal.add(journalKind,title,detail)
end

local function kickWater(direction, strength)
    direction = tonumber(direction) or 0
    strength = math.max(0, math.min(1.5, tonumber(strength) or 0.5))

    WaterMotion.tiltVel = WaterMotion.tiltVel + direction * strength * 2.6
    WaterMotion.energy = math.min(1.6, WaterMotion.energy + strength * 0.78)
end

local function springStep(value, velocity, target, stiffness, damping, dt)
    local acceleration = (target - value) * stiffness - velocity * damping
    velocity = velocity + acceleration * dt
    value = value + velocity * dt
    return value, velocity
end

RateTracker.houses={}
RateTracker.withdrawn={}
function RateTracker.sample(house)
    local btc=tonumber(house.btc)
    if not btc then return end
    local id=house.number
    local now=getGameTimer()
    local adjusted=btc+(RateTracker.withdrawn[id] or 0)
    local prev=RateTracker.houses[id]
    if not prev or adjusted<prev.value-.001 then
        RateTracker.houses[id]={time=now,value=adjusted,rate=nil}
    elseif now-prev.time>=15000 then
        prev.rate=math.max(0,(adjusted-prev.value)*3600000/(now-prev.time))
        prev.time=now; prev.value=adjusted
    end
end

local function forecastBlend(previous,current,alpha)
    if current==nil then return previous end
    if previous==nil then return current end
    alpha=alpha or .34
    return previous*(1-alpha)+current*alpha
end

function ForecastTracker.sample(house)
    if not house or not house.number then return end
    local id=house.number
    local now=os.time()
    local currentBtc=tonumber(house.btc)
    local currentCoolant=tonumber(house.coolant)
    for _,gpu in ipairs(house.gpus or {}) do
        local c=tonumber(gpu.coolant)
        if c then currentCoolant=currentCoolant and math.min(currentCoolant,c) or c end
    end
    local currentMoney=parseHouseMoney and parseHouseMoney(house.currentMoney) or nil
    local item=ForecastTracker.houses[id] or {btcSamples=0,coolingSamples=0,electricitySamples=0}
    ForecastTracker.houses[id]=item

    if item.time and now>item.time then
        local dt=now-item.time
        if dt>=30 and dt<=6*3600 then
            if currentBtc and item.btc and currentBtc>=item.btc then
                local delta=currentBtc-item.btc
                if delta>.0001 then
                    local rate=delta*3600/dt
                    if rate>=0 and rate<10000 then
                        item.btcRate=forecastBlend(item.btcRate,rate,.32)
                        item.btcSamples=(item.btcSamples or 0)+1
                    end
                end
            end
            if currentCoolant and item.coolant and currentCoolant<=item.coolant then
                local delta=item.coolant-currentCoolant
                if delta>.01 then
                    local rate=delta*3600/dt
                    if rate>0 and rate<100 then
                        item.coolingRate=forecastBlend(item.coolingRate,rate,.28)
                        item.coolingSamples=(item.coolingSamples or 0)+1
                    end
                end
            end
            if currentMoney and item.money and currentMoney<=item.money then
                local delta=item.money-currentMoney
                if delta>0 then
                    local rate=delta*3600/dt
                    if rate>0 and rate<100000000 then
                        item.electricityRate=forecastBlend(item.electricityRate,rate,.24)
                        item.electricitySamples=(item.electricitySamples or 0)+1
                    end
                end
            end
        end
    end

    item.time=now
    item.btc=currentBtc
    item.coolant=currentCoolant
    item.money=currentMoney
end

function ForecastTracker.get(house)
    if not house or not house.number then return {} end
    local item=ForecastTracker.houses[house.number] or {}
    local btcSamples=item.btcSamples or 0
    local btcRate=btcSamples>=2 and item.btcRate or nil
    local currentBtc=tonumber(house.btc)
    local nextBtc=nil
    if btcRate and btcRate>0 and currentBtc then
        local target=math.floor(currentBtc)+1
        if target-currentBtc<.0001 then target=target+1 end
        nextBtc=math.max(0,(target-currentBtc)/btcRate*3600)
    end

    local coolant=tonumber(house.coolant)
    for _,gpu in ipairs(house.gpus or {}) do
        local c=tonumber(gpu.coolant)
        if c then coolant=coolant and math.min(coolant,c) or c end
    end
    local refillEta=nil
    if (item.coolingSamples or 0)>=2 and item.coolingRate and item.coolingRate>0 and coolant then
        local threshold=View and View.refillThreshold and View.refillThreshold() or (tonumber(Settings.refillThreshold) or 70)
        refillEta=coolant<=threshold and 0 or ((coolant-threshold)/item.coolingRate*3600)
    end

    local money=parseHouseMoney and parseHouseMoney(house.currentMoney) or nil
    local electricityEta=nil
    if (item.electricitySamples or 0)>=2 and item.electricityRate and item.electricityRate>0 and money then
        electricityEta=money<=AUTO_ELECTRICITY_THRESHOLD and 0 or ((money-AUTO_ELECTRICITY_THRESHOLD)/item.electricityRate*3600)
    end

    return {
        btcRate=btcRate,btcSamples=btcSamples,nextBtc=nextBtc,
        coolingRate=item.coolingRate,coolingSamples=item.coolingSamples or 0,refillEta=refillEta,
        electricityRate=item.electricityRate,electricitySamples=item.electricitySamples or 0,electricityEta=electricityEta
    }
end

local function forecastEtaText(seconds)
    seconds=tonumber(seconds)
    if seconds==nil then return I18n.text("Збираємо дані…") end
    if seconds<=30 then return "< 1 хв" end
    local minutes=math.floor(seconds/60+.5)
    if minutes<60 then return tostring(minutes).." хв" end
    local hours=math.floor(minutes/60)
    local rest=minutes%60
    if hours<48 then return rest>0 and (hours.." год "..rest.." хв") or (hours.." год") end
    local days=math.floor(hours/24)
    local remain=hours%24
    return remain>0 and (days.." д "..remain.." год") or (days.." д")
end

local GPU_BASE_RATE={.050325,.100650,.150975,.201300,.503250,.631349,.736575,.876874,1.052250,1.227625}
local MiningModel={courseEnabled=true,price=nil,priceTime=nil,courseRevision=0,epoch=0,houses={},samples={},
    confidence={minSeconds=180,maxSeconds=600,minGain=.10,confirm=3,remove=3}}
local function getBtcMultiplier(price)
    price=tonumber(price)
    if not price or price<=0 then return nil end
    if price>=100000 then return 1 end -- Clamp to the highest known anchor; no invented extrapolation.
    local points={{30000,2.40},{64185,1.62},{72306,1.41},{90000,1},{100000,1}}
    if price<=points[1][1] then return points[1][2] end
    for i=2,#points do
        local left,right=points[i-1],points[i]
        if price<=right[1] then
            return left[2]+(right[2]-left[2])*(price-left[1])/(right[1]-left[1])
        end
    end
end
local function getHouseMultiplier(houseNumber)
    local n=tonumber(houseNumber) or 0
    return n>=1900 and n<=1950 and 3 or 1
end
local function getArchitectMultiplier(houseNumber)
    local id=tonumber(houseNumber)
    local item=MiningModel.houses[id]
    return item and item.confirmed and 1.30 or 1
end
function MiningModel.save()
    local file=Runtime.open(dataDirPath().."\\architect.cfg","w")
    if not file then return end
    for id,item in pairs(MiningModel.houses) do
        if item.confirmed then file:write(tostring(id).."\n") end
    end
    file:close()
end
function MiningModel.load()
    local file=Runtime.open(dataDirPath().."\\architect.cfg","r")
    if not file then return end
    for line in file:lines() do
        local id=tonumber(line:match("^%s*(%d+)%s*$"))
        if id then MiningModel.houses[id]={confirmed=true,hits=0,misses=0} end
    end
    file:close()
end
function MiningModel.setPrice(price)
    price=tonumber(price)
    if not price or price<=0 then return end
    if price~=MiningModel.price then MiningModel.courseRevision=MiningModel.courseRevision+1 end
    MiningModel.price=price;MiningModel.priceTime=getGameTimer()
end
MiningModel.diagnosticSeen={}
function MiningModel.checkInputs(house)
    local missing={}
    local factor=MiningModel.courseEnabled and getBtcMultiplier(MiningModel.price) or 1
    if MiningModel.courseEnabled and MiningModel.price==nil then missing[#missing+1]="btcPrice=nil" end
    -- Lua's and/or idiom cannot represent a missing coefficient: preserve nil.
    if MiningModel.courseEnabled then factor=getBtcMultiplier(MiningModel.price) end
    if factor==nil then missing[#missing+1]="multiplier=nil" end
    if house.number==nil then missing[#missing+1]="houseNumber=nil" end
    if not house.gpus then missing[#missing+1]="gpus=nil"
    else
        if house.gpuCount==nil then missing[#missing+1]="gpuCount=nil"
        elseif #house.gpus~=house.gpuCount then missing[#missing+1]="gpuCount mismatch" end
        for _,gpu in ipairs(house.gpus) do
            local slot=" [rack="..tostring(gpu.rack)..", shelf="..tostring(gpu.shelf or gpu.slot).."]"
            if gpu.level==nil then missing[#missing+1]="level=nil"..slot
            elseif not GPU_BASE_RATE[gpu.level] then missing[#missing+1]="level invalid="..tostring(gpu.level)..slot end
            if gpu.active==nil then missing[#missing+1]="gpuState=nil"..slot end
        end
    end
    if #missing==0 then return factor end
    local details=table.concat(missing,"; ")
    local key=tostring(house.number).."|"..details
    local now=getGameTimer()
    if not MiningModel.diagnosticSeen[key] or now-MiningModel.diagnosticSeen[key]>=60000 then
        MiningModel.diagnosticSeen[key]=now
        local file=Runtime.open(dataDirPath().."\\income-inputs.log","a")
        if file then
            file:write(os.date("%Y-%m-%d %H:%M:%S")," houseNumber=",tostring(house.number),
                " btcPrice=",tostring(MiningModel.price)," multiplier=",tostring(factor),
                " architectMultiplier=",tostring(getArchitectMultiplier(house.number)),"\nMISSING: ",details,"\n\n")
            file:close()
        end
    end
    return nil,"Дім №"..tostring(house.number)..": "..details
end
function MiningModel.rates(house,architect)
    local factor,reason=MiningModel.checkInputs(house)
    if not factor then return nil,nil,reason end
    local active,maximum=0,0
    for _,gpu in ipairs(house.gpus) do
        local rate=GPU_BASE_RATE[gpu.level]*factor*getHouseMultiplier(house.number)
        if architect~=false then rate=rate*getArchitectMultiplier(house.number) end
        maximum=maximum+rate
        if gpu.active then active=active+rate end
    end
    return active,maximum
end
function MiningModel.sample(house)
    local expected=MiningModel.rates(house,false)
    local id=house.number
    local parts={}
    for _,gpu in ipairs(house.gpus or {}) do
        parts[#parts+1]=tostring(gpu.rack)..":"..tostring(gpu.shelf)..":"..tostring(gpu.level)..":"..tostring(gpu.active)
    end
    local signature=table.concat(parts,"|")
    local identified=true
    for _,gpu in ipairs(house.gpus or {}) do if not gpu.rack or not gpu.shelf then identified=false end end
    local now=getGameTimer()
    local current={time=now,btc=house.btc,signature=signature,epoch=MiningModel.epoch,
        course=MiningModel.courseRevision,expected=expected}
    local prev=MiningModel.samples[id]
    local item=MiningModel.houses[id] or {hits=0,misses=0,confirmed=false}
    MiningModel.houses[id]=item
    local valid=identified and MiningModel.courseEnabled and expected and expected>0 and house.btc and not UI.collecting
        and (house.pausedCount or 0)==0
    if not valid or not prev or prev.signature~=signature or prev.epoch~=current.epoch
        or prev.course~=current.course or prev.expected~=expected or not prev.btc
        or now-prev.time>MiningModel.confidence.maxSeconds*1000 or house.btc<prev.btc then
        MiningModel.samples[id]=valid and current or nil
        item.hits=0;item.misses=0
        return
    end
    if now-prev.time<MiningModel.confidence.minSeconds*1000 then return end
    local gain=house.btc-prev.btc
    -- Wait for enough accumulation to outweigh rounded server balance readings.
    if gain<math.max(MiningModel.confidence.minGain,#(house.gpus or {})*.02) then return end
    local ratio=(gain*3600000/(now-prev.time))/expected
    MiningModel.samples[id]=current
    if ratio>1.20 and ratio<=1.36 then
        item.hits=item.hits+1;item.misses=0
        item.state=item.hits>=3 and "confirmed" or (item.hits==2 and "likely" or "suspected")
        if item.hits>=MiningModel.confidence.confirm and not item.confirmed then
            item.confirmed=true;MiningModel.save()
        end
    elseif ratio>=.95 and ratio<=1.10 then
        item.hits=0;item.misses=item.misses+1
        if item.confirmed and item.misses>=MiningModel.confidence.remove then
            item.confirmed=false;item.state=nil;MiningModel.save()
        end
    else item.hits=0;item.misses=0 end
end
local function updateIncomeEstimate()
    MiningModel.missing=nil
    local active,maximum,count=0,0,0
    for _,house in ipairs(UI.houses) do
        if house.miningStatus~="unavailable" and house.gpus then
            local a,m,reason=MiningModel.rates(house)
            if not a then MiningModel.missing=reason;return nil,nil end
            active=active+a;maximum=maximum+m;count=count+1
        elseif house.miningStatus~="unavailable" and (house.gpuCount or 0)>0 then
            local _,reason=MiningModel.checkInputs(house);MiningModel.missing=reason or "gpus=nil";return nil,nil end
    end
    if count==0 then return nil,nil end
    return active,maximum
end


local BitcoinHistory={points={},busy=false,cached=false,token=0,lastSuccess=nil}
local function bitcoinHistoryValid(value)
    return type(value)=="number" and value==value and value>0 and value<100000000
end
function BitcoinHistory.path()
    return cacheFilePath("bitcoin-history.cache")
end
function BitcoinHistory.trim(now)
    now=tonumber(now) or os.time()
    local cutoff=now-35*86400
    local kept={}
    for _,p in ipairs(BitcoinHistory.points) do
        if (tonumber(p.time) or 0)>=cutoff and bitcoinHistoryValid(p.price) then kept[#kept+1]=p end
    end
    BitcoinHistory.points=kept
end
function BitcoinHistory.load()
    local f=Runtime.open(BitcoinHistory.path(),"r")
    if not f then return end
    local points={}
    for line in f:lines() do
        local stamp,price=line:match("^(%d+)%s+([%d%.]+)$")
        stamp,price=tonumber(stamp),tonumber(price)
        if stamp and bitcoinHistoryValid(price) then points[#points+1]={time=stamp,price=price} end
    end
    f:close()
    table.sort(points,function(a,b) return a.time<b.time end)
    BitcoinHistory.points=points
    BitcoinHistory.trim()
    BitcoinHistory.cached=#points>0
end
function BitcoinHistory.save()
    BitcoinHistory.trim()
    local f=Runtime.open(BitcoinHistory.path(),"w")
    if not f then return false end
    for _,p in ipairs(BitcoinHistory.points) do
        f:write(tostring(math.floor(p.time)),"\t",string.format("%.8f",p.price),"\n")
    end
    f:close()
    return true
end
function BitcoinHistory.add(stamp,price,noSave)
    stamp,price=tonumber(stamp),tonumber(price)
    if not stamp or not bitcoinHistoryValid(price) then return end
    local bucket=math.floor(stamp/300)*300
    local replaced=false
    for i=#BitcoinHistory.points,1,-1 do
        local p=BitcoinHistory.points[i]
        if math.floor((p.time or 0)/300)*300==bucket then
            p.time=stamp;p.price=price;replaced=true;break
        end
        if (p.time or 0)<bucket-600 then break end
    end
    if not replaced then BitcoinHistory.points[#BitcoinHistory.points+1]={time=stamp,price=price} end
    table.sort(BitcoinHistory.points,function(a,b) return a.time<b.time end)
    BitcoinHistory.trim(stamp)
    if not noSave then BitcoinHistory.save() end
end
function BitcoinHistory.priceAt(stamp)
    stamp=tonumber(stamp) or os.time()
    local best,bestDist=nil,math.huge
    for _,p in ipairs(BitcoinHistory.points) do
        local dist=math.abs((p.time or 0)-stamp)
        if dist<bestDist then best,bestDist=p.price,dist end
    end
    return best
end
local BitcoinHourly={points={},busy=false,cached=false,token=0,lastSuccess=nil}
function BitcoinHourly.path()
    return dataDirPath().."\\btc-history-hourly.log"
end
function BitcoinHourly.trim(now)
