    f:close()
end
function BitcoinHourly.add(stamp,price,noSave)
    stamp,price=tonumber(stamp),tonumber(price)
    if not stamp or not bitcoinHistoryValid(price) then return end
    local replaced=false
    for i=#BitcoinHourly.points,1,-1 do
        local p=BitcoinHourly.points[i]
        if math.abs((p.time or 0)-stamp)<=120 then p.time=stamp;p.price=price;replaced=true;break end
        if (p.time or 0)<stamp-7200 then break end
    end
    if not replaced then BitcoinHourly.points[#BitcoinHourly.points+1]={time=stamp,price=price} end
    table.sort(BitcoinHourly.points,function(a,b) return a.time<b.time end)
    BitcoinHourly.trim(stamp)
    if not noSave then BitcoinHourly.save() end
end
function BitcoinHourly.accept(body)
    local parsed={}
    for chunk in tostring(body or ""):gmatch("%[([^%[%]]+)%]") do
        local stamp,low,high,open,close,volume=chunk:match("^%s*(%d+)%s*,%s*([%d%.]+)%s*,%s*([%d%.]+)%s*,%s*([%d%.]+)%s*,%s*([%d%.]+)%s*,%s*([%d%.]+)%s*$")
        stamp,close=tonumber(stamp),tonumber(close)
        if stamp and bitcoinHistoryValid(close) then parsed[#parsed+1]={time=stamp,price=close} end
    end
    if #parsed<2 then return false end
    table.sort(parsed,function(a,b) return a.time<b.time end)
    BitcoinHourly.points={}
    for _,p in ipairs(parsed) do BitcoinHourly.add(p.time,p.price,true) end
    if tonumber(MiningModel.price) then BitcoinHourly.add(os.time(),tonumber(MiningModel.price),true) end
    BitcoinHourly.cached=false;BitcoinHourly.lastSuccess=getGameTimer();BitcoinHourly.save();return true
end

function BitcoinHistory.rows(period)
    local span=period=="30d" and 30*86400 or (period=="7d" and 7*86400 or 86400)
    local cutoff=os.time()-span
    local source=BitcoinHistory.points
    if period=="1d" and BitcoinHourly then
        local fresh=0
        for _,p in ipairs(BitcoinHourly.points or {}) do if (p.time or 0)>=cutoff then fresh=fresh+1 end end
        if fresh>=2 then source=BitcoinHourly.points end
    end
    local rows={}
    for _,p in ipairs(source or {}) do
        if (p.time or 0)>=cutoff then rows[#rows+1]={time=p.time,price=p.price,seen=true} end
    end
    table.sort(rows,function(a,b) return a.time<b.time end)
    return rows
end
function BitcoinHistory.accept(body)
    local parsed={}
    for chunk in tostring(body or ""):gmatch("%[([^%[%]]+)%]") do
        local stamp,low,high,open,close,volume=chunk:match("^%s*(%d+)%s*,%s*([%d%.]+)%s*,%s*([%d%.]+)%s*,%s*([%d%.]+)%s*,%s*([%d%.]+)%s*,%s*([%d%.]+)%s*$")
        stamp,close=tonumber(stamp),tonumber(close)
        if stamp and bitcoinHistoryValid(close) then parsed[#parsed+1]={time=stamp,price=close} end
    end
    if #parsed<2 then return false end
    table.sort(parsed,function(a,b) return a.time<b.time end)
    BitcoinHistory.points={}
    for _,p in ipairs(parsed) do BitcoinHistory.add(p.time,p.price,true) end
    if tonumber(MiningModel.price) then BitcoinHistory.add(os.time(),tonumber(MiningModel.price),true) end
    BitcoinHistory.cached=false
    BitcoinHistory.lastSuccess=getGameTimer()
    BitcoinHistory.save()
    return true
end
local function fetchBitcoinHistory()
    if BitcoinHistory.busy or not downloadUrlToFile then return end
    BitcoinHistory.busy=true;BitcoinHistory.token=BitcoinHistory.token+1
    local token=BitcoinHistory.token
    local temp=cacheFilePath("bitcoin-history.download.tmp");pcall(os.remove,temp)
    local finishTime=os.time()
    local startTime=finishTime-30*86400
    local startIso=os.date("!%Y-%m-%dT%H:%M:%SZ",startTime)
    local endIso=os.date("!%Y-%m-%dT%H:%M:%SZ",finishTime)
    local url="https://api.exchange.coinbase.com/products/BTC-USD/candles?granularity=21600&start="..startIso.."&end="..endIso
    local function finish(success)
        pcall(os.remove,temp)
        if token~=BitcoinHistory.token then return end
        BitcoinHistory.busy=false;BitcoinHistory.nextAttempt=getGameTimer()+(success and 3600000 or 60000)
        if not success then BitcoinHistory.cached=#BitcoinHistory.points>0 end
    end
    local ok=pcall(downloadUrlToFile,url,temp,function(id,status)
        if status==6 then
            if token~=BitcoinHistory.token then os.remove(temp);return end
            local f=Runtime.open(temp,"rb")
            local body=f and f:read("*a") or ""
            if f then f:close() end
            local accepted=BitcoinHistory.accept(body)
            os.remove(temp);finish(accepted)
        end
    end)
    if not ok then finish(false);return end
    lua_thread.create(function()
        wait(30000)
        if token==BitcoinHistory.token and BitcoinHistory.busy then
            finish(false);BitcoinHistory.token=BitcoinHistory.token+1;os.remove(temp)
        end
    end)
end

