    lua_thread.create(function()
        wait(30000)
        if token==BitcoinHourly.token and BitcoinHourly.busy then finish(false);BitcoinHourly.token=BitcoinHourly.token+1;os.remove(temp) end
    end)
end

local BitcoinPrice={busy=false,cached=true,lastAttempt=nil,lastSuccess=nil,nextAttempt=0,token=0}
function BitcoinPrice.path()
    return cacheFilePath("bitcoin-price.cache")
end
function BitcoinPrice.valid(value)
    return type(value)=="number" and value==value and value>0 and value<100000000
end
function BitcoinPrice.load()
    local f=Runtime.open(BitcoinPrice.path(),"r")
    if not f then return end
    local price=tonumber(f:read("*l"));local stamp=tonumber(f:read("*l"));f:close();BitcoinPrice.observedAt=stamp
    if BitcoinPrice.valid(price) then MiningModel.setPrice(price);BitcoinPrice.cached=true end
end
function BitcoinPrice.accept(body)
    if not body:find('"base"%s*:%s*"BTC"') or not body:find('"currency"%s*:%s*"USD"') then return false end
    local price=tonumber(body:match('"amount"%s*:%s*"([%d%.]+)"'))
    if not BitcoinPrice.valid(price) then return false end
    MiningModel.setPrice(price);BitcoinPrice.cached=false
    BitcoinPrice.observedAt=os.time()
    BitcoinPrice.lastSuccess=getGameTimer();BitcoinPrice.nextAttempt=getGameTimer()+3600000
    BitcoinHistory.add(os.time(),price)
    if BitcoinHourly then BitcoinHourly.add(os.time(),price) end
    local f=Runtime.open(BitcoinPrice.path(),"w")
    if f then f:write(string.format("%.8f\n",price),tostring(os.time()),"\n");f:close() end
    return true
end
local function fetchBitcoinPrice()
    if BitcoinPrice.busy then return end
    BitcoinPrice.lastAttempt=getGameTimer();BitcoinPrice.busy=true
    BitcoinPrice.token=BitcoinPrice.token+1
    local token=BitcoinPrice.token
    local temp=cacheFilePath("bitcoin-price.download.tmp");pcall(os.remove,temp)
    local function finish(success)
        pcall(os.remove,temp)
        if token~=BitcoinPrice.token then return end
        BitcoinPrice.busy=false
        if not success then BitcoinPrice.cached=true;BitcoinPrice.nextAttempt=getGameTimer()+60000 end
    end
    if not downloadUrlToFile then finish(false);return end
    local ok=pcall(downloadUrlToFile,"https://api.coinbase.com/v2/prices/BTC-USD/spot",temp,
        function(id,status)
            if status==6 then
                if token~=BitcoinPrice.token then os.remove(temp);return end
                local f=Runtime.open(temp,"rb")
                local body=f and f:read(16384) or ""
                if f then f:close() end
                local accepted=BitcoinPrice.accept(body)
                os.remove(temp);finish(accepted)
            end
        end)
    if not ok then finish(false);return end
    lua_thread.create(function()
        wait(30000)
        if token==BitcoinPrice.token and BitcoinPrice.busy then
            finish(false);BitcoinPrice.token=BitcoinPrice.token+1;os.remove(temp)
        end
    end)
end

local function formatHourly(value)
    value = tonumber(value)
    if not value then return "— BTC/год" end
    if value >= 100 then return string.format("%.1f BTC/год", value) end
    if value >= 10 then return string.format("%.2f BTC/год", value) end
    return string.format("%.3f BTC/год", value)
end

local function formatIncomeNumber(value,mode)
    value=math.max(0,tonumber(value) or 0)
    if mode=="full" then
        local digits=string.format("%.0f",value)
        return (digits:reverse():gsub("(%d%d%d)","%1 "):reverse():gsub("^ ",""))
    end
    local unit,scale="",1
    if value>=1e9 then unit,scale=" млрд",1e9
    elseif value>=1e6 then unit,scale=" млн",1e6
    elseif value>=1e3 then unit,scale=" тис",1e3 end
    local n=value/scale
    local decimals=scale==1 and 0 or (n>=100 and 1 or 2)
    local rounded=tonumber(string.format("%."..decimals.."f",n))
    if rounded>=1000 and scale<1e9 then
        scale=scale*1000;unit=scale==1e3 and " тис" or (scale==1e6 and " млн" or " млрд")
        n=value/scale;decimals=2
    end
    local text=string.format("%."..decimals.."f",n)
    if decimals>0 then text=text:gsub("0+$",""):gsub("%.$","") end
    return text..unit
end
local function formatBtcPlain(value)
    value=tonumber(value)
    if value==nil then return "— BTC" end
    value=math.max(0,value)
    local text
    if value>=1000 then text=formatIncomeNumber(value,"full")
    elseif value>=100 then text=string.format("%.1f",value)
    elseif value>=10 then text=string.format("%.2f",value)
    else text=string.format("%.3f",value) end
    if value<1000 then text=text:gsub("0+$",""):gsub("%.$","") end
    return text.." BTC"
end
local function formatUsdPlain(value,approx)
    value=tonumber(value)
    if value==nil then return "— $" end
    local prefix=approx==false and "" or "≈ "
    return prefix..formatIncomeNumber(value,"full").." $"
end
local function currencyPrimaryIsUsd()
    return Settings.incomeMode=="virtual" or Settings.incomeMode=="money_btc"
end
local function currencyPairFromValues(btc,usd,approx)
    local btcText=formatBtcPlain(btc)
    local usdText=formatUsdPlain(usd,approx)
    if Settings.incomeMode=="virtual" then return usdText,"" end
    if Settings.incomeMode=="money_btc" then return usdText,btcText end
    if Settings.incomeMode=="btc" then return btcText,"" end
    return btcText,usdText
end
local function currencyPairFromBtc(btc,price,approx)
    local usd=(tonumber(btc) and tonumber(price)) and tonumber(btc)*tonumber(price) or nil
    return currencyPairFromValues(btc,usd,approx)
end
local function currencyInlineFromValues(btc,usd,approx)
    local primary,secondary=currencyPairFromValues(btc,usd,approx)
    if secondary and secondary~="" then return primary.." · "..secondary end
    return primary
end
local function incomeTexts(income)
    if income==nil then return "—",MiningModel.missing or "Немає активних ферм" end
    return currencyPairFromBtc(income,MiningModel.price,true)
end

local IncomeAnalytics={
    period="1d",
    buckets={},
    verified={},
    collections={},
    houseState={},
    gaps={},
    dirty=false,
    lastSave=0,
    retentionDays=35
}

function IncomeAnalytics.path()
    return dataDirPath().."\\income-history.log"
end

local function analyticsBucketTime(timestamp)
    timestamp=tonumber(timestamp) or os.time()
    return math.floor(timestamp/300)*300
end

local function analyticsSignature(house)
    local parts={tostring(getArchitectMultiplier(house.number)),tostring(select(2,MiningModel.rates(house)))}
    for _,gpu in ipairs(house.gpus or {}) do
        parts[#parts+1]=table.concat({
            tostring(gpu.rack or "?"),
            tostring(gpu.shelf or gpu.slot or "?"),
            tostring(gpu.level or "?")
        },":")
    end
    return table.concat(parts,"|")
end

function IncomeAnalytics.trim(now)
    now=tonumber(now) or os.time()
    local cutoff=now-IncomeAnalytics.retentionDays*86400
    for stamp in pairs(IncomeAnalytics.buckets) do
        if tonumber(stamp) and tonumber(stamp)<cutoff then IncomeAnalytics.buckets[stamp]=nil end
    end
    for t in pairs(IncomeAnalytics.verified) do if t<cutoff then IncomeAnalytics.verified[t]=nil end end
    for t in pairs(IncomeAnalytics.gaps) do if t<cutoff then IncomeAnalytics.gaps[t]=nil end end
    local kept={}
    for _,item in ipairs(IncomeAnalytics.collections) do
        if (tonumber(item.time) or 0)>=cutoff then kept[#kept+1]=item end
    end
    IncomeAnalytics.collections=kept
end

function IncomeAnalytics.load()
    local f=Runtime.open(IncomeAnalytics.path(),"r")
    if not f then return end
    for line in f:lines() do
        local kind,rest=line:match("^([BCUV])\t(.*)$")
        if kind and rest then
            local fields={}
            for field in (rest.."\t"):gmatch("(.-)\t") do fields[#fields+1]=field end
            if kind=="V" then
                local t,a,p=tonumber(fields[1]),tonumber(fields[2]),tonumber(fields[3])
                local estimated=(fields[4]=="1" or fields[4]=="true")
                local confirmedZero=(fields[5]=="1" or fields[5]=="true")
                if t and a and p then IncomeAnalytics.verified[t]={actual=a,potential=p,estimated=estimated,confirmedZero=confirmedZero} end
            elseif kind=="U" then
                local t,d=tonumber(fields[1]),tonumber(fields[2]);if t and d then IncomeAnalytics.gaps[t]=d end
            elseif kind=="B" then
                local stamp=tonumber(fields[1])
                if stamp then
                    IncomeAnalytics.buckets[stamp]={
                        actual=tonumber(fields[2]) or 0,
                        forecast=tonumber(fields[3]) or 0,
                        collections=tonumber(fields[4]) or 0,
                        lost=tonumber(fields[5]) or 0,
                        lostUsd=tonumber(fields[6]) or 0,
                        lostPaused=tonumber(fields[7]) or 0,
                        lostElectricity=tonumber(fields[8]) or 0,
                        lostStalled=tonumber(fields[9]) or 0,
                        lostOther=tonumber(fields[10]) or 0
                    }
                end
            elseif kind=="C" then
                local stamp=tonumber(fields[1])
                if stamp then
                    local btc=tonumber(fields[2]) or 0
                    local price=tonumber(fields[4])
                    local usd=tonumber(fields[5])
                    IncomeAnalytics.collections[#IncomeAnalytics.collections+1]={
                        time=stamp,btc=btc,farms=tonumber(fields[3]) or 0,
                        price=price,usd=usd,status=fields[6] or "complete",operation=fields[7],source=fields[8] or "history"
                    }
                end
            end
        end
    end
    f:close()
    table.sort(IncomeAnalytics.collections,function(x,y) return (x.time or 0)>(y.time or 0) end)
    IncomeAnalytics.trim()
end

function IncomeAnalytics.migrateLossModel()
end
function IncomeAnalytics.markGap(now,seconds)
    local stamp=analyticsBucketTime(now)
    IncomeAnalytics.gaps[stamp]=math.max(IncomeAnalytics.gaps[stamp] or 0,seconds)
    IncomeAnalytics.dirty=true
end

function IncomeAnalytics.save()
    IncomeAnalytics.trim()
    local f=Runtime.open(IncomeAnalytics.path(),"w")
    if not f then return false end
    local stamps={}
    for stamp in pairs(IncomeAnalytics.buckets) do stamps[#stamps+1]=stamp end
    table.sort(stamps)
    for _,stamp in ipairs(stamps) do
        local item=IncomeAnalytics.buckets[stamp]
        f:write("B\t",tostring(stamp),"\t",string.format("%.8f",item.actual or 0),"\t",
            string.format("%.8f",item.forecast or 0),"\t",tostring(item.collections or 0),"\t",
            string.format("%.8f",item.lost or 0),"\t",string.format("%.2f",item.lostUsd or 0),"\t",
            string.format("%.8f",item.lostPaused or 0),"\t",string.format("%.8f",item.lostElectricity or 0),"\t",
            string.format("%.8f",item.lostStalled or 0),"\t",string.format("%.8f",item.lostOther or 0),"\n")
    end
    for stamp,row in pairs(IncomeAnalytics.verified) do
        f:write("V\t",stamp,"\t",string.format("%.8f",row.actual),"\t",string.format("%.8f",row.potential),"\t",
            row.estimated and "1" or "0","\t",row.confirmedZero and "1" or "0","\n")
    end
    for stamp,seconds in pairs(IncomeAnalytics.gaps) do f:write("U\t",stamp,"\t",seconds,"\n") end
    table.sort(IncomeAnalytics.collections,function(x,y) return (x.time or 0)>(y.time or 0) end)
    for _,item in ipairs(IncomeAnalytics.collections) do
        f:write("C\t",tostring(item.time or 0),"\t",string.format("%.8f",item.btc or 0),"\t",
            tostring(item.farms or 0),"\t",item.price and string.format("%.8f",item.price) or "","\t",
            item.usd and string.format("%.2f",item.usd) or "","\t",item.status or "complete","\t",item.operation or "","\t",item.source or "history","\n")
    end
    if not f:close() then return false end
    IncomeAnalytics.dirty=false
    IncomeAnalytics.lastSave=getGameTimer()
    return true
end

function IncomeAnalytics.maybeSave(force)
    if not IncomeAnalytics.dirty then return end
    local now=getGameTimer()
    if force or now-IncomeAnalytics.lastSave>=60000 then IncomeAnalytics.save() end
end

function IncomeAnalytics.add(timestamp,actual,forecast,lost,lostUsd,lostReason)
    local stamp=analyticsBucketTime(timestamp)
    local item=IncomeAnalytics.buckets[stamp]
    if not item then item={actual=0,forecast=0,collections=0,lost=0,lostUsd=0,lostPaused=0,lostElectricity=0,lostStalled=0,lostOther=0};IncomeAnalytics.buckets[stamp]=item end
    item.actual=(item.actual or 0)+math.max(0,tonumber(actual) or 0)
    item.forecast=(item.forecast or 0)+math.max(0,tonumber(forecast) or 0)
    local lostValue=math.max(0,tonumber(lost) or 0)
    item.lost=(item.lost or 0)+lostValue
    item.lostUsd=(item.lostUsd or 0)+math.max(0,tonumber(lostUsd) or 0)
    if lostValue>0 then
        if lostReason=="paused" then item.lostPaused=(item.lostPaused or 0)+lostValue
        elseif lostReason=="electricity" then item.lostElectricity=(item.lostElectricity or 0)+lostValue
        elseif lostReason=="stalled" then item.lostStalled=(item.lostStalled or 0)+lostValue
        else item.lostOther=(item.lostOther or 0)+lostValue end
        SessionStats.lostBtc=(SessionStats.lostBtc or 0)+lostValue
    end
    IncomeAnalytics.dirty=true
    IncomeAnalytics.maybeSave(false)
end

function IncomeAnalytics.observeHouse(house)
    if not house or house.miningStatus=="unavailable" or not house.gpus then return end
    local btc=tonumber(house.btc)
    local id=tonumber(house.number)
    local activeRate,rate=MiningModel.rates(house)
    if not btc or not id or not rate or house.complete==false then return end

    local now=os.time()
    local adjusted=btc+(RateTracker.withdrawn[id] or 0)
    local sig=analyticsSignature(house)
    local prev=IncomeAnalytics.houseState[id]
    local currentPrice=tonumber(MiningModel.price)

    if prev and prev.signature==sig then
        local dt=now-(prev.time or now)
        local delta=adjusted-(prev.adjusted or adjusted)
        if dt>=120 and dt<=600 then
            local previousRate=tonumber(prev.rate) or rate
            local forecast=math.max(0,((previousRate+rate)*.5)*(dt/3600))
            local actual=delta>=-.001 and math.max(0,delta) or 0
            local lost=0
            local ratio=forecast>0 and (actual/forecast) or nil
            local lowElectricity=(tonumber(Settings.electricityWarn) or 0)>0
                and parseHouseMoney(house.currentMoney)
                and parseHouseMoney(house.currentMoney)<Settings.electricityWarn
            local confirmedDowntime=(tonumber(house.pausedCount) or 0)>0 or lowElectricity
            -- FlashMiner balances are coarse/rounded. Short intervals frequently report 0 and
            -- later jump by a whole BTC even though production was continuous. Treat such
            -- quantisation as an estimate from the confirmed GPU rate instead of drawing 0.
            local chartActual=actual
            local chartEstimated=false
            local quantizedZero=(forecast>0 and actual<=.001)
            local quantizedJump=(forecast>0 and forecast<1 and actual>math.max(forecast*1.75,forecast+.35))
            if not confirmedDowntime and (quantizedZero or quantizedJump) then
                chartActual=forecast
                chartEstimated=true
            end

            if dt>=120 and ratio then
                if ratio<.90 and (actual>math.max(.01,forecast*.10) or confirmedDowntime) then
                    house.performanceCandidateSamples=(tonumber(house.performanceCandidateSamples) or 0)+1
                    house.performanceCandidateRatio=((tonumber(house.performanceCandidateRatio) or ratio)
                        *(house.performanceCandidateSamples-1)+ratio)/house.performanceCandidateSamples
                    if house.performanceCandidateSamples>=3 then
                        house.performanceRatio=house.performanceCandidateRatio
                        house.performanceObservedAt=now
                        house.performanceConfirmedSamples=house.performanceCandidateSamples
                    end
                elseif ratio>=.90 then
                    house.performanceCandidateSamples=0
                    house.performanceCandidateRatio=nil
                    house.performanceRatio=nil
                    house.performanceObservedAt=nil
                    house.performanceConfirmedSamples=0
                else
                    house.performanceCandidateSamples=0
                    house.performanceCandidateRatio=nil
                end
            end

            -- Loss uses only an actually observed interval. Unexplained zero production
            -- is not declared lost; it needs a confirmed cause first.
            if dt>=120 and forecast>0 and actual<forecast*.90
                and (actual>math.max(.01,forecast*.10) or confirmedDowntime) then
                lost=math.max(0,forecast-actual)
            end
            local lostReason=nil
            if lost>0 then
                if house.complete==false then return "Стан частини GPU не визначено" end
    if (tonumber(house.pausedCount) or 0)>0 then lostReason="paused"
                elseif lowElectricity then lostReason="electricity"
                else lostReason="other" end
            end
            local prevPrice=tonumber(prev.price)
            local avgPrice=(prevPrice and currentPrice) and (prevPrice+currentPrice)*.5 or (currentPrice or prevPrice)
            local lostUsd=avgPrice and lost*avgPrice or 0
            if delta<-.001 then
                IncomeAnalytics.markGap(now,dt)
                Runtime.log("PRODUCTION_MISMATCH","house="..id.." actual="..actual.." potential="..forecast.." seconds="..dt,60)
            else
                local cursor=prev.time
                while cursor<now do
                    local stamp=analyticsBucketTime(cursor)
                    local finish=math.min(now,stamp+300)
                    local fraction=(finish-cursor)/dt
                    local row=IncomeAnalytics.verified[stamp] or {actual=0,potential=0,estimated=false,confirmedZero=false}
                    row.actual=row.actual+chartActual*fraction;row.potential=row.potential+forecast*fraction
                    row.estimated=(row.estimated==true) or chartEstimated
                    -- A genuine zero is only trusted when we also have a confirmed downtime reason.
                    -- This lets the renderer repair old rounded 0 samples without hiding real pauses.
                    row.confirmedZero=(row.confirmedZero==true) or (confirmedDowntime and actual<=.001)
                    IncomeAnalytics.verified[stamp]=row
                    cursor=finish
                end
                IncomeAnalytics.add(now,chartActual,forecast,lost,lostUsd,lostReason)
            end
        elseif dt>600 then
            IncomeAnalytics.markGap(now,dt)
            Runtime.log("OBSERVATION_GAP","house="..id.." seconds="..dt,60)
        else
            return
        end
    end

    if prev and prev.signature~=sig then IncomeAnalytics.markGap(now,math.max(0,now-prev.time)) end
    IncomeAnalytics.houseState[id]={time=now,adjusted=adjusted,rate=rate,signature=sig,price=currentPrice}
end

function IncomeAnalytics.recordCollection(btc,farms,source,status,operation)
    local now=os.time();btc=math.max(0,tonumber(btc) or 0)
    if btc<=0 then return true end
    status=status or "complete"
    local item=nil
    if operation then for _,row in ipairs(IncomeAnalytics.collections) do if row.operation==operation then item=row;break end end end
    local previous=item and item.btc or 0
    local delta=math.max(0,btc-previous)
    if not item then item={time=now,btc=0,usd=nil};table.insert(IncomeAnalytics.collections,1,item);SessionStats.collections=(SessionStats.collections or 0)+1 end
    local price=tonumber(MiningModel.price)
    item.btc=math.max(previous,btc);item.farms=math.max(item.farms or 0,tonumber(farms) or 0)
    if price and delta>0 then item.usd=(item.usd or 0)+delta*price end
    item.price=item.usd and item.usd/item.btc or nil
    item.status=status;item.operation=operation;item.source=source or "manual"
    SessionStats.collectedBtc=(SessionStats.collectedBtc or 0)+delta
    if price then SessionStats.collectedUsd=(SessionStats.collectedUsd or 0)+delta*price
    elseif delta>0 then SessionStats.missingPrice=true end
    IncomeAnalytics.dirty=true
    local saved=IncomeAnalytics.save()
    if status~="in_progress" then
        local title=status=="complete" and "Збір завершено" or "Збір частково виконано"
        Journal.add("collection",title,Runtime.plural(item.farms,"ферма","ферми","ферм"),
            {btc=btc,price=item.price or 0,farms=item.farms,source=source,operation=operation})
    end
    return saved
end


local function analyticsPeriodSpec(period)
    if period=="7d" then return 7*86400,6*3600,28,7 end
    if period=="30d" then return 30*86400,86400,30,30 end
    return 86400,3600,24,1
end

function IncomeAnalytics.aggregate(period)
    local span,binSeconds,count,days=analyticsPeriodSpec(period)
    local now=os.time()
    local aligned=math.floor(now/binSeconds)*binSeconds
    count=count+1
    local actualStart=aligned-(count-1)*binSeconds
    local actualRows={}
    for i=1,count do
        actualRows[i]={time=actualStart+(i-1)*binSeconds,actualBtc=0,actualUsd=0,actual=0,seen=false,estimated=false,samples=0}
    end

    -- Production chart: use observed 5-minute production samples, not collection events.
    -- A missing observation is unknown data, never a zero-production hour.
    local totalActualBtc,totalActualUsd=0,0
    local collectionCount=0
    local dayTotalsBtc,dayTotalsUsd={},{}
    local rangeStart=now-span

    for stamp,row in pairs(IncomeAnalytics.verified) do
        stamp=tonumber(stamp)
        if stamp and stamp>=rangeStart and stamp<=now then
            local rawActual=math.max(0,tonumber(row.actual) or 0)
            local potential=math.max(0,tonumber(row.potential) or 0)
            local repairedZero=(rawActual<=.001 and potential>.001 and row.confirmedZero~=true)
            local amount=repairedZero and potential or rawActual
            local price=BitcoinHistory.priceAt(stamp) or tonumber(MiningModel.price)
            local usd=price and amount*price or 0
            totalActualBtc=totalActualBtc+amount
            totalActualUsd=totalActualUsd+usd
            local index=math.floor((stamp-actualStart)/binSeconds)+1
            local target=actualRows[index]
            if target then
                target.actualBtc=target.actualBtc+amount
                target.actualUsd=target.actualUsd+usd
                target.samples=(target.samples or 0)+1
                target.estimated=(target.estimated==true) or row.estimated==true or repairedZero
                target.seen=true
            end
            local day=os.date("%Y-%m-%d",stamp)
            dayTotalsBtc[day]=(dayTotalsBtc[day] or 0)+amount
            dayTotalsUsd[day]=(dayTotalsUsd[day] or 0)+usd
        end
    end

    -- Collection events are kept only as metadata/markers. They do not define the line.
    for _,item in ipairs(IncomeAnalytics.collections) do
        local stamp=tonumber(item.time) or 0
        if stamp>=rangeStart and stamp<=now then
            collectionCount=collectionCount+1
            local index=math.floor((stamp-actualStart)/binSeconds)+1
            local target=actualRows[index]
            if target then
                target.collectedBtc=(target.collectedBtc or 0)+math.max(0,tonumber(item.btc) or 0)
                target.collectionEvents=(target.collectionEvents or 0)+1
            end
        end
    end

    local hasProductionSample=false
    local hasPositiveProduction=false
    for _,row in ipairs(actualRows) do
        if row.seen then
            hasProductionSample=true
            if (tonumber(row.actualBtc) or 0)>.001 then hasPositiveProduction=true end
        end
    end
    if not hasProductionSample or not hasPositiveProduction then
        local fallbackRate=select(1,updateIncomeEstimate())
        if fallbackRate and fallbackRate>0 then
            local sessionStart=math.max(rangeStart,tonumber(SessionStats.started) or now)
            local cursor=math.floor(sessionStart/binSeconds)*binSeconds
            while cursor<=now do
                local index=math.floor((cursor-actualStart)/binSeconds)+1
                local target=actualRows[index]
                if target then
                    local from=math.max(cursor,sessionStart)
                    local to=math.min(cursor+binSeconds,now)
                    local seconds=math.max(0,to-from)
                    if seconds>0 and ((not target.seen) or (tonumber(target.actualBtc) or 0)<=.001) then
                        local amount=fallbackRate*(seconds/3600)
                        local price=BitcoinHistory.priceAt(cursor) or tonumber(MiningModel.price)
                        local previous=tonumber(target.actualBtc) or 0
                        target.actualBtc=math.max(previous,amount)
                        target.actualUsd=price and target.actualBtc*price or 0
                        target.samples=math.max(1,tonumber(target.samples) or 0);target.seen=true;target.estimated=true
                        local delta=math.max(0,target.actualBtc-previous)
                        totalActualBtc=totalActualBtc+delta
                        totalActualUsd=totalActualUsd+(price and delta*price or 0)
                    end
                end
                cursor=cursor+binSeconds
            end
        end
    end

    local moneyGraph=currencyPrimaryIsUsd()
    for _,row in ipairs(actualRows) do
        if row.seen then row.actual=moneyGraph and row.actualUsd or row.actualBtc end
    end

    local function valueFor(row) return moneyGraph and row.actualUsd or row.actualBtc end
    local i=1
    while i<=#actualRows do
        if actualRows[i].seen then i=i+1 else
            local gapStart=i
            while i<=#actualRows and not actualRows[i].seen do i=i+1 end
            local gapEnd=i-1
            local left=gapStart-1
            local right=i<=#actualRows and i or nil
            if left>=1 and right and actualRows[left].seen and actualRows[right].seen then
                local lv=valueFor(actualRows[left]);local rv=valueFor(actualRows[right])
                local lb=actualRows[left].actualBtc;local rb=actualRows[right].actualBtc
                local lu=actualRows[left].actualUsd;local ru=actualRows[right].actualUsd
                local width=right-left
                for k=gapStart,gapEnd do
                    local t=(k-left)/width
                    local row=actualRows[k]
                    row.actualBtc=lb+(rb-lb)*t
                    row.actualUsd=lu+(ru-lu)*t
                    row.actual=lv+(rv-lv)*t
                    row.estimated=true
                    row.seen=true
                end
            end
        end
    end

    -- The current bucket is incomplete. Keep it measured rather than scaling it up, and
    -- mark it so the renderer can draw it more softly.
    local currentIndex=math.floor((now-actualStart)/binSeconds)+1
    if actualRows[currentIndex] then actualRows[currentIndex].partial=true end

    local currentRate=select(1,updateIncomeEstimate())
    local totalForecastBtc=currentRate and math.max(0,currentRate)*(span/3600) or nil
    local totalForecastUsd=(totalForecastBtc and MiningModel.price) and totalForecastBtc*MiningModel.price or nil

    local historicalProduced,historicalPotential=0,0
    local historicalSamples=0
    local lostBtc,lostUsd=0,0
    local lostPaused,lostElectricity,lostStalled,lostOther=0,0,0,0
    for stamp,item in pairs(IncomeAnalytics.buckets) do
        stamp=tonumber(stamp)
        if stamp and stamp>=rangeStart and stamp<=now then
            historicalProduced=historicalProduced+math.max(0,tonumber(item.actual) or 0)
            historicalPotential=historicalPotential+math.max(0,tonumber(item.forecast) or 0)
            historicalSamples=historicalSamples+1
            local lb=math.max(0,tonumber(item.lost) or 0)
            lostBtc=lostBtc+lb
            local lu=tonumber(item.lostUsd)
            if not lu or lu<=0 then
                local hp=BitcoinHistory.priceAt(stamp) or tonumber(MiningModel.price)
                lu=hp and lb*hp or 0
            end
            lostUsd=lostUsd+math.max(0,lu or 0)
            lostPaused=lostPaused+math.max(0,tonumber(item.lostPaused) or 0)
            lostElectricity=lostElectricity+math.max(0,tonumber(item.lostElectricity) or 0)
            lostStalled=lostStalled+math.max(0,tonumber(item.lostStalled) or 0)
            lostOther=lostOther+math.max(0,tonumber(item.lostOther) or 0)
        end
    end

    local dayCount,sumBtc,sumUsd=0,0,0
    local bestDay,bestBtc,bestUsd,bestDisplay=nil,0,0,-1
    local allDays={}
    for day in pairs(dayTotalsBtc) do allDays[day]=true end
    for day in pairs(dayTotalsUsd) do allDays[day]=true end
    for day in pairs(allDays) do
        local b,u=dayTotalsBtc[day] or 0,dayTotalsUsd[day] or 0
        dayCount=dayCount+1;sumBtc=sumBtc+b;sumUsd=sumUsd+u
        local display=moneyGraph and u or b
        if display>bestDisplay then bestDisplay=display;bestDay=day;bestBtc=b;bestUsd=u end
    end
    local avgBtc=sumBtc/days
    local avgUsd=sumUsd/days
    local verifiedActual,verifiedPotential=0,0
    for stamp,row in pairs(IncomeAnalytics.verified) do
        if stamp>=rangeStart and stamp+300<=now then
            verifiedActual=verifiedActual+row.actual;verifiedPotential=verifiedPotential+row.potential
        end
    end
    local efficiency=verifiedPotential>0 and verifiedActual/verifiedPotential*100 or nil
    if efficiency and (efficiency<0 or efficiency>100.00001) then efficiency=nil end

    local incomplete=false
    for stamp in pairs(IncomeAnalytics.gaps) do if stamp>=rangeStart then incomplete=true;break end end
    if incomplete then efficiency=nil end
    return {
        incomplete=incomplete or historicalSamples==0,
        actualRows=actualRows,start=actualStart,binSeconds=binSeconds,days=days,
        actualBtc=totalActualBtc,actualUsd=totalActualUsd,
        forecastBtc=totalForecastBtc,forecastUsd=totalForecastUsd,
        efficiency=efficiency,averageDayBtc=avgBtc,averageDayUsd=avgUsd,
        bestDay=bestDay,bestDayBtc=bestBtc,bestDayUsd=bestUsd,
        lostBtc=lostBtc,lostUsd=lostUsd,
        lostPaused=lostPaused,lostElectricity=lostElectricity,lostStalled=lostStalled,lostOther=lostOther,
        collections=collectionCount,hasActual=totalActualBtc>0,hasForecast=currentRate~=nil,
        hasEfficiency=efficiency~=nil,currentRate=currentRate,
        priceRows=BitcoinHistory.rows(period),currentPrice=tonumber(MiningModel.price)
    }
end

local function liquidColor(value)
    value = tonumber(value)
    if not value then
        return {0.44, 0.52, 0.62, 1.0}
    end
    if value < 25 then
        return P.red
    end
    if value < 50 then
        return mixColor(P.amber, {0.52, 0.58, 0.66, 1.0}, (value - 25) / 25)
    end

    return {0.42, 0.56, 0.72, 1.0}
end

local function coolantColor(value)
    value = math.max(0, math.min(100, tonumber(value) or 0))

    local red = {1.000, 0.310, 0.270, 1.0}
    local amber = {1.000, 0.690, 0.190, 1.0}
    local green = {0.220, 0.850, 0.500, 1.0}

    if value <= 50 then
        return mixColor(red, amber, value / 50)
    end

    return mixColor(amber, green, (value - 50) / 50)
end

local function dashboardCoolingColor(value)
    value = tonumber(value)
    if not value then return P.muted end
    if value < 25 then return P.red end
    if value < 50 then return P.amber end
    return {0.82, 0.85, 0.91, 1.0}
end

local function roundedRectPath(x1, y1, x2, y2, r)
    local pts = {}
    local cornerSteps = 30

    local function add(x, y)
        pts[#pts + 1] = {x = x, y = y}
    end

    local function arc(cx, cy, a1, a2)
        for i = 0, cornerSteps do
            local t = i / cornerSteps
            local a = a1 + (a2 - a1) * t
            add(cx + math.cos(a) * r, cy + math.sin(a) * r)
        end
    end

    add(x1 + r, y1)
    add(x2 - r, y1)
    arc(x2 - r, y1 + r, -math.pi * 0.5, 0)
    add(x2, y2 - r)
    arc(x2 - r, y2 - r, 0, math.pi * 0.5)
    add(x1 + r, y2)
    arc(x1 + r, y2 - r, math.pi * 0.5, math.pi)
    add(x1, y1 + r)
    arc(x1 + r, y1 + r, math.pi, math.pi * 1.5)

    add(x1 + r, y1)

    return pts
end

local function pathLengths(pts)
    local lengths = {}
    local total = 0.0

    for i = 1, #pts - 1 do
        local dx = pts[i + 1].x - pts[i].x
        local dy = pts[i + 1].y - pts[i].y
        local len = math.sqrt(dx * dx + dy * dy)
        lengths[i] = len
        total = total + len
    end

    return lengths, total
end

local function drawPathRange(dl, pts, lengths, total, startT, endT, color, thickness)
    if total <= 0 then return end

    local span = (endT or 0) - (startT or 0)
    if span <= 0 then return end
    if span > 1.0 then span = 1.0 end

    local startNorm = (startT or 0) % 1.0

    local function drawOnce(aT, bT)
        if bT <= aT then return end

        local startD = aT * total
        local endD = bT * total
        local passed = 0.0

        for i = 1, #pts - 1 do
            local len = lengths[i]
            local segStart = passed
            local segEnd = passed + len

            if segEnd >= startD and segStart <= endD and len > 0 then
                local a = math.max(startD, segStart)
                local b = math.min(endD, segEnd)

                if b > a then
                    local ta = (a - segStart) / len
                    local tb = (b - segStart) / len

                    local ax = pts[i].x + (pts[i + 1].x - pts[i].x) * ta
                    local ay = pts[i].y + (pts[i + 1].y - pts[i].y) * ta
                    local bx = pts[i].x + (pts[i + 1].x - pts[i].x) * tb
                    local by = pts[i].y + (pts[i + 1].y - pts[i].y) * tb

                    dl:AddLine(
                        imgui.ImVec2(ax, ay),
                        imgui.ImVec2(bx, by),
                        color,
                        thickness
                    )
                end
            end

            passed = segEnd
            if passed > endD then break end
        end
    end

    local finish = startNorm + span
    if finish <= 1.0 then
        drawOnce(startNorm, finish)
    else
        drawOnce(startNorm, 1.0)
        drawOnce(0.0, finish - 1.0)
    end
end

local function drawTexture(texture, x, y, w, h, tint, alpha)
    if not texture then return false end

    local dl = imgui.GetWindowDrawList()
    local col = tint or {1,1,1,1}

    local ok = pcall(function()
        dl:AddImage(
            texture,
            imgui.ImVec2(x, y),
            imgui.ImVec2(x + w, y + h),
            imgui.ImVec2(0, 0),
            imgui.ImVec2(1, 1),
            u32(col, alpha or 1.0)
        )
    end)

    return ok
end


local function drawTextureUV(texture, x, y, w, h, u1, v1, u2, v2, tint, alpha)
    if not texture then return false end

    local dl = imgui.GetWindowDrawList()
    local col = tint or {1,1,1,1}

    local ok = pcall(function()
        dl:AddImage(
            texture,
            imgui.ImVec2(x, y),
            imgui.ImVec2(x + w, y + h),
            imgui.ImVec2(u1, v1),
            imgui.ImVec2(u2, v2),
            u32(col, alpha or 1.0)
        )
    end)

    return ok
end


local BorderMotion = {}

local function drawStatusBorder(dl, p1, p2, rounding, house, hoverT)
    local w = p2.x - p1.x
    local h = p2.y - p1.y
    if w <= 0 or h <= 0 then return end

    local paused = tonumber(house and house.pausedCount) or 0
    local gpuCount = tonumber(house and house.gpuCount) or 0
    local scanned = house and house.scanned

    local miningAvailable = house and (house.miningStatus == "available"
        or (house.miningStatus == nil and scanned))
    local healthy = miningAvailable and scanned and gpuCount > 0 and paused <= 0
    local statusColor = healthy
        and P.green
        or ((scanned and paused > 0)
            and (paused >= math.max(2, math.floor(gpuCount * 0.25)) and P.red or P.amber)
            or P.surface)

    if not Textures.neonAtlas then
        View.drawNeonFallback(p1.x,p1.y,w,h,rounding,statusColor,healthy,hoverT)
        return
    end

    local phase=Settings.animations=="off" and .7 or (getGameTimer()/1000*.075*Settings.neonSpeed)%1
    local frameCount = 400
    local grid = 20

    local frame = math.floor((phase % 1.0) * frameCount + 0.5) % frameCount
    local col = frame % grid
    local row = math.floor(frame / grid)

    local u1 = col / grid
    local v1 = row / grid
    local u2 = (col + 1) / grid
    local v2 = (row + 1) / grid

    local pad = math.max(10, w * 0.035)

    drawTextureUV(
        Textures.neonAtlas,
        p1.x - pad,
        p1.y - pad,
        w + pad * 2,
        h + pad * 2,
        u1, v1, u2, v2,
        statusColor,
        healthy and (View.isArizonaSprings(house) and (.64+hoverT*.03) or (.96+hoverT*.03)) or .78
    )
end

local function trim(s)
    return tostring(s or ""):match("^%s*(.-)%s*$")
end

local function stripColors(s)
    return tostring(s or ""):gsub("{[%x]+}", "")
end


local function serverToUtf8(s)
    local ok, result = pcall(function()
        return u8(tostring(s or ""))
    end)

    if ok and result then
        return result
    end

    return tostring(s or "")
end

local function lowerServerText(text)
    local value = serverToUtf8(stripColors(text)):lower()
    local upper = "АБВГДЕЁЖЗИЙКЛМНОПРСТУФХЦЧШЩЪЫЬЭЮЯІЇЄҐ"
    local lower = "абвгдеёжзийклмнопрстуфхцчшщъыьэюяіїєґ"
    for i = 1, #upper, 2 do value = value:gsub(upper:sub(i, i + 1), lower:sub(i, i + 1)) end
    return value
end

function MiningModel.observe(text) end
local function miningFailureReason(text)
    local t = lowerServerText(text)
    if t:find("вентиляц",1,true) and (t:find("не подведен",1,true) or t:find("не установлен",1,true)
        or t:find("нет ",1,true) or t:find("отсутств",1,true)) then return "Не подключена вентиляция" end
    if t:find("электр",1,true) and (t:find("нет ",1,true) or t:find("не подключ",1,true)
        or t:find("отсутств",1,true)) then return "Нет электропитания" end
    if (t:find("нет доступа",1,true) or t:find("не принадлежит",1,true))
        and (t:find("дом",1,true) or t:find("ферм",1,true)) then return "Нет доступа к майнингу" end
    if (t:find("недоступ",1,true) or t:find("нельзя",1,true) or t:find("не установлен",1,true))
        and (t:find("майнинг",1,true) or t:find("flashminer",1,true)) then return "FlashMiner недоступний" end
    return nil
end

local MinerParseDebug={seen={},count=0}
local function logMinerParse(raw,normalized,balance,level,coolant,rack,shelf,reason)
    local key=reason.."|"..raw
    if MinerParseDebug.seen[key] or MinerParseDebug.count>=64 then return end
    local file=Runtime.open(dataDirPath().."\\miner-parse.log","a")
    if not file then return end
    MinerParseDebug.seen[key]=true;MinerParseDebug.count=MinerParseDebug.count+1
    local function visible(text)
        return tostring(text):gsub("\r","\\r"):gsub("\n","\\n"):gsub("\t","\\t")
    end
    file:write(os.date("%Y-%m-%d %H:%M:%S")," · ",reason,"\n",
        "RAW: ",visible(serverToUtf8(raw)),"\n",
        "RAW_BYTES: ",(raw:gsub(".",function(c) return string.format("%02X ",string.byte(c)) end)),"\n",
        "NORMALIZED: ",visible(normalized),"\n",
        "PARSED balance=",tostring(balance)," / level=",tostring(level)," / coolant=",tostring(coolant),
        " / rack=",tostring(rack)," / shelf=",tostring(shelf),"\n\n")
    file:close()
end
local function minerRackHeader(raw)
    local clean=lowerServerText(raw)
    if clean:find("btc",1,true) then return nil end
    return tonumber(clean:match("стойка.-(%d+)") or clean:match("стійка.-(%d+)"))
end

local function parseMinerStats(text)
    MiningModel.observe(text)
    local coolantSum = 0.0
    local coolantCount = 0
    local btcTotal = 0.0
    local collectible = 0
    local gpus = {}
    local gpuBySlot = {}
    local gpuCount = 0
    local pausedCount = 0
    local unknownCount = 0
    local malformed = false
    local slotCount = 0
    local currentRack=nil

    for rawLine in tostring(text or ""):gmatch("[^\r\n]+") do
        local clean = serverToUtf8(stripColors(rawLine))
        clean = clean:gsub("&#x20;", " ")

        currentRack=minerRackHeader(rawLine) or currentRack
        local slotNo = clean:match("(%d+)%s*|")
        if slotNo then
            slotCount = slotCount + 1

            local btcText = clean:match("(%d+[.,]?%d*)%s*BTC")
            local coolantText = clean:match("([%d]+[%.%,]?[%d]*)%s*%%")

            if btcText and not rawLine:lower():find("{cccccc}",1,true) then
                local btc = tonumber((btcText:gsub(",", ".")))
                if btc then
                    gpuCount = gpuCount + 1
                    btcTotal = btcTotal + btc
                    collectible = collectible + math.floor(btc)

                    if coolantText then
                        local coolant = tonumber((coolantText:gsub(",", ".")))
                        if coolant then
                            coolant = math.max(0, math.min(100, coolant))
                            coolantSum = coolantSum + coolant
                            coolantCount = coolantCount + 1
                        end
                    end

                    local upperRaw = tostring(rawLine):upper()
                    local lowerClean = lowerServerText(rawLine)
                    local paused =
                        upperRaw:find("{F78181}", 1, true) ~= nil or
                        lowerClean:find("пауза", 1, true) ~= nil or
                        lowerClean:find("pause", 1, true) ~= nil or
                        lowerClean:find("не работает", 1, true) ~= nil or
                        lowerClean:find("останов", 1, true) ~= nil or
                        lowerClean:find("выключ", 1, true) ~= nil or
                        lowerClean:find("отключ", 1, true) ~= nil

                    if paused then pausedCount = pausedCount + 1 end
                    local numeric=clean:gsub(" "," "):gsub("|"," ")
                    local level=tonumber(numeric:match("BTC%s+(%d+)%s+.-%d+[.,]?%d*%s*%%"))
                    if level and (level<1 or level>10) then level=nil end
                    local active=nil
                    if paused then active=false
                    elseif upperRaw:find("{BEF781}",1,true) then active=true end
                    if active==nil then unknownCount=unknownCount+1 end
                    local shelf=tonumber(slotNo)
                    local rack=currentRack
                    local gpu={slot=shelf,rack=rack,shelf=shelf,level=level,active=active,coolant=coolantText and tonumber((coolantText:gsub(",","."))) or nil}
                    gpus[#gpus+1]=gpu
                    if rack then gpuBySlot[rack..":"..shelf]=gpu end
                    if not level or not rack then
                        logMinerParse(rawLine,numeric,btc,level,coolantText and tonumber((coolantText:gsub(",","."))),
                            rack,shelf,not level and "GPU level missing" or "Rack header missing")
                    end
                end
            elseif not rawLine:lower():find("{cccccc}",1,true) then
                malformed=true
                logMinerParse(rawLine,clean,nil,nil,coolantText,currentRack,tonumber(slotNo),"GPU balance missing")
            end
        end
    end

    if gpuCount > 0 and slotCount > 0 and slotCount < gpuCount then
        slotCount = gpuCount
    end

    local avgCoolant = coolantCount > 0 and (coolantSum / coolantCount) or nil

    return {
        coolant = avgCoolant,
        gpuCount = gpuCount,
        pausedCount = pausedCount,
        workingCount = math.max(0, gpuCount - pausedCount - unknownCount),
        unknownCount=unknownCount,
        complete=not malformed and unknownCount==0,
        slotCount = slotCount,
        btc = gpuCount > 0 and btcTotal or nil,
        collectible = gpuCount > 0 and collectible or 0,
        gpus = gpus,
        gpuBySlot = gpuBySlot
    }
end

local function splitTabs(s)
    local result = {}

    for value in (tostring(s or "") .. "\t"):gmatch("(.-)\t") do
        result[#result + 1] = trim(value)
    end

    return result
end

parseHouseMoney=function(value)
    local raw=tostring(value or ""):gsub("%s","")
    if raw=="" then return nil end
    local digits=raw:gsub("[^%d]","")
    return digits~="" and tonumber(digits) or nil
end

local function formatWholeMoney(value)
    value=math.floor(math.max(0,tonumber(value) or 0)+0.5)
    local text=tostring(value):reverse():gsub("(%d%d%d)","%1 "):reverse():gsub("^ ","")
    return text.." $"
end

local function isMiningHouseAvailable(house)
    return house and (house.miningStatus=="available" or (house.miningStatus==nil and house.scanned))
end

local function houseAttentionReason(house)
    if not house then return nil end
    if house.miningStatus=="unavailable" then
        return house.miningReason or "Майнінг недоступний"
    end
    if house.miningStatus=="unknown" or house.miningStatus=="checking" then
        return house.miningStatus=="checking" and "Перевіряємо доступ" or (house.miningReason or "Доступ не перевірено")
    end
    if not isMiningHouseAvailable(house) then return nil end

    if (tonumber(house.pausedCount) or 0)>0 then
        return tostring(house.pausedCount).." GPU на паузі"
    end

    local coolingLimit=tonumber(Settings.coolingWarn) or 0
    local coolant=tonumber(house.coolant)
    if coolingLimit>0 and coolant and coolant<coolingLimit then
        return "Низьке охолодження: "..string.format("%.0f%%",coolant)
    end

    local moneyLimit=tonumber(Settings.electricityWarn) or 0
    local currentMoney=parseHouseMoney(house.currentMoney)
    if moneyLimit>0 and currentMoney and currentMoney<moneyLimit then
        return "Мало коштів на електроенергію: "..formatWholeMoney(currentMoney)
    end

    local ratio=tonumber(house.performanceRatio)
    local observed=tonumber(house.performanceObservedAt)
    if ratio and observed and os.time()-observed<=600 and ratio<.90 and (tonumber(house.performanceConfirmedSamples) or 0)>=3 then
        return "Зафіксовано зниження виробітку"
    end

    return nil
end

local function houseHealthScore(house)
    if not house then return nil end
    if house.miningStatus=="unavailable" then return 0 end
    if house.miningStatus=="unknown" or house.miningStatus=="checking" or house.complete==false then return 35 end
    if not isMiningHouseAvailable(house) then return nil end
    local score=100
    local gpu=math.max(1,tonumber(house.gpuCount) or 1)
    local paused=math.max(0,tonumber(house.pausedCount) or 0)
    score=score-math.min(50,(paused/gpu)*70)
    local coolant=tonumber(house.coolant)
    if coolant then
        if coolant<25 then score=score-30 elseif coolant<50 then score=score-18 elseif coolant<70 then score=score-7 end
    end
    local moneyLimit=tonumber(Settings.electricityWarn) or 0
    local money=parseHouseMoney(house.currentMoney)
    if moneyLimit>0 and money and money<moneyLimit then score=score-18 end
    local ratio=tonumber(house.performanceRatio)
    if ratio and os.time()-(house.performanceObservedAt or 0)<=600 and ratio<.90 and (tonumber(house.performanceConfirmedSamples) or 0)>=3 then
        score=score-math.min(25,(.90-ratio)*100)
    end
    return math.max(0,math.min(100,math.floor(score+.5)))
end

local function healthSnapshot()
    local total,count,totalFarms,ignoredCount=0,0,0,0
    local totalGpu,pausedGpu=0,0
    local coolantSum,coolantCount=0,0
    local lowElectricity,anomalies=0,0
    for _,house in ipairs(UI.houses or {}) do
        local score=houseHealthScore(house)
        if score~=nil then
            totalFarms=totalFarms+1
            if isHouseIgnored(house.number) then
                ignoredCount=ignoredCount+1
            else
                total=total+score;count=count+1
                totalGpu=totalGpu+math.max(0,tonumber(house.gpuCount) or 0)
                pausedGpu=pausedGpu+math.max(0,tonumber(house.pausedCount) or 0)
                local coolant=tonumber(house.coolant)
                if coolant then coolantSum=coolantSum+coolant;coolantCount=coolantCount+1 end
                local moneyLimit=tonumber(Settings.electricityWarn) or 0
                local money=parseHouseMoney(house.currentMoney)
                if moneyLimit>0 and money and money<moneyLimit then lowElectricity=lowElectricity+1 end
                local ratio=tonumber(house.performanceRatio)
                if ratio and ratio<.90 and (tonumber(house.performanceConfirmedSamples) or 0)>=3 then anomalies=anomalies+1 end
            end
        end
    end
    return {
        score=count>0 and math.floor(total/count+.5) or nil,
        considered=count,totalFarms=totalFarms,ignored=ignoredCount,
        gpu=totalGpu,paused=pausedGpu,
        coolant=coolantCount>0 and coolantSum/coolantCount or nil,
        lowElectricity=lowElectricity,anomalies=anomalies
    }
end

local function overallHealthScore()
    return healthSnapshot().score
end

local function healthHelpText(snapshot)
    snapshot=snapshot or healthSnapshot()
    local scoreText=snapshot.score and (tostring(snapshot.score).."/100") or "—"
    local lines={
        "Здоров'я ферм — "..scoreText,
        "",
        "Враховано",
        tostring(snapshot.considered or 0).." із "..tostring(snapshot.totalFarms or 0).." ферм",
        "GPU на паузі: "..tostring(snapshot.paused or 0).." з "..tostring(snapshot.gpu or 0)
    }
    if snapshot.coolant then lines[#lines+1]="Середнє охолодження: "..string.format("%.0f%%",snapshot.coolant) end
    if (snapshot.lowElectricity or 0)>0 then lines[#lines+1]="Проблеми з електроенергією: "..tostring(snapshot.lowElectricity) end
    if (snapshot.anomalies or 0)>0 then lines[#lines+1]="Підтверджені аномалії: "..tostring(snapshot.anomalies) end
    lines[#lines+1]=""
    lines[#lines+1]="Що впливає на оцінку"
    lines[#lines+1]="Паузи GPU, охолодження, проблеми з електроживленням і підтверджені несправності."
    if (snapshot.ignored or 0)>0 then
        lines[#lines+1]=""
        lines[#lines+1]="Ігноровані будинки не враховуються в оцінці."
    end
    return table.concat(lines,"\n")
end

function ProblemCenter.build()
    local result={houses={},auto=0,visit=0,blocked=0,soon=0,problemHouses=0}
    local threshold=View and View.refillThreshold and View.refillThreshold() or (tonumber(Settings.refillThreshold) or 70)
    for _,house in ipairs(UI.houses or {}) do
        if not isHouseIgnored(house.number) and (tonumber(house.gpuCount) or 0)>0 then
            local entry={house=house,items={},soon={}}
            local paused=tonumber(house.pausedCount) or 0
            if paused>0 then
                entry.items[#entry.items+1]={kind="auto",label=paused.." GPU на паузі",action="start"}
                result.auto=result.auto+1
            end
            local collectible=tonumber(house.collectible) or 0
            if collectible>=1 then
                entry.items[#entry.items+1]={kind="auto",label="Зібрати BTC · "..tostring(math.floor(collectible)).." BTC",action="btc"}
                result.auto=result.auto+1
            end
            local money=parseHouseMoney(house.currentMoney)
            if money and money<=AUTO_ELECTRICITY_THRESHOLD then
                entry.items[#entry.items+1]={kind="auto",label="Поповнити електроенергію · "..formatWholeMoney(money),action="electricity"}
                result.auto=result.auto+1
            end
            local taxDue=parseHouseMoney(house.tax)
            if taxDue and taxDue>0 then
                entry.items[#entry.items+1]={kind="auto",label="Сплатити податки · "..formatWholeMoney(taxDue),action="taxes"}
                result.auto=result.auto+1
            end

            local refillCount,worst=0,nil
            for _,gpu in ipairs(house.gpus or {}) do
                local coolant=tonumber(gpu.coolant)
                if coolant and coolant<99.95 and coolant<=threshold then
                    refillCount=refillCount+1
                    worst=not worst and coolant or math.min(worst,coolant)
                end
            end
            if refillCount==0 and tonumber(house.coolant) and house.coolant<=threshold and (tonumber(house.gpuCount) or 0)>0 then
                refillCount=tonumber(house.gpuCount) or 1
                worst=tonumber(house.coolant)
            end
            if refillCount>0 then
                entry.items[#entry.items+1]={kind="visit",label="Заправити GPU · "..refillCount.." шт."..(worst and (" · мін. "..string.format("%.0f%%",worst)) or ""),action="coolant"}
                result.visit=result.visit+1
            end

            if house.miningStatus=="unavailable" then
                entry.items[#entry.items+1]={kind="blocked",label="Перевірити ферму · "..tostring(house.miningReason or "Майнінг недоступний")}
                result.blocked=result.blocked+1
            elseif house.complete==false or house.miningStatus=="unknown" then
                entry.items[#entry.items+1]={kind="visit",label="Перевірити ферму · дані неповні"}
                result.visit=result.visit+1
            end

            local f=ForecastTracker.get(house)
            if f.refillEta and f.refillEta>0 and f.refillEta<=4*3600 then
                entry.soon[#entry.soon+1]={label="Охолодження до порогу · "..forecastEtaText(f.refillEta),eta=f.refillEta}
                result.soon=result.soon+1
            end
            if f.electricityEta and f.electricityEta>0 and f.electricityEta<=5*3600 then
                entry.soon[#entry.soon+1]={label="Електроенергія до автопоповнення · "..forecastEtaText(f.electricityEta),eta=f.electricityEta}
                result.soon=result.soon+1
            end
            if f.nextBtc and f.nextBtc>0 and f.nextBtc<=90*60 then
                entry.soon[#entry.soon+1]={label="Наступний цілий BTC · "..forecastEtaText(f.nextBtc),eta=f.nextBtc,minor=true}
            end

            if #entry.items>0 or #entry.soon>0 then
                if #entry.items>0 then result.problemHouses=result.problemHouses+1 end
                result.houses[#result.houses+1]=entry
            end
        end
    end

    local showMaintenanceErrors=Maintenance.busy or (Maintenance.lastRun and os.time()-Maintenance.lastRun<=900)
    for _,err in ipairs(showMaintenanceErrors and (Maintenance.errors or {}) or {}) do
        if err and err.message then
            result.blocked=result.blocked+1
            local attached=false
            for _,entry in ipairs(result.houses) do
                if tostring(entry.house.number)==tostring(err.house) then
                    entry.items[#entry.items+1]={kind="blocked",label=tostring(err.message)}
                    attached=true;break
                end
            end
            if not attached and err.house then
                result.houses[#result.houses+1]={house={number=err.house,gpuCount=0},items={{kind="blocked",label=tostring(err.message)}},soon={}}
                result.problemHouses=result.problemHouses+1
            end
        end
    end

    table.sort(result.houses,function(a,b)
        local function weight(entry)
            local w=0
            for _,item in ipairs(entry.items or {}) do
                if item.kind=="blocked" then w=math.max(w,4)
                elseif item.kind=="visit" then w=math.max(w,3)
                elseif item.kind=="auto" then w=math.max(w,2) end
            end
            if w==0 and #(entry.soon or {})>0 then w=1 end
            return w
        end
        local wa,wb=weight(a),weight(b)
        if wa~=wb then return wa>wb end
        return (tonumber(a.house.number) or 0)<(tonumber(b.house.number) or 0)
    end)
    return result
end

function ProblemCenter.nearestForecast()
    local best=nil
    for _,house in ipairs(UI.houses or {}) do
        if not isHouseIgnored(house.number) and (tonumber(house.gpuCount) or 0)>0 then
            local f=ForecastTracker.get(house)
            local candidates={{eta=f.refillEta,label="Дім №"..tostring(house.number).." · заправка"},
                              {eta=f.electricityEta,label="Дім №"..tostring(house.number).." · електроенергія"}}
            for _,c in ipairs(candidates) do
                if c.eta and c.eta>0 and (not best or c.eta<best.eta) then best=c end
            end
        end
    end
    return best
end

local function parseHouses(text)
    local result = {}
    local serverRow = 0

    for rawLine in tostring(text or ""):gmatch("[^\r\n]+") do
        local clean = stripColors(rawLine)
        local cols = splitTabs(clean)
        local prefix = cols[1] or ""

        local listIndex = prefix:match("%[(%d+)%]")

        if listIndex then
            local houseNumber = nil

            for num in prefix:gmatch("(%d+)") do
                houseNumber = num
            end

            if houseNumber then
                local city = cols[2] or "-"
                local tax = cols[3] or "0"
                local energy = cols[4] or ""

                local cycles =
                    energy:match("^%s*(%d+)") or
                    clean:match("\t%s*(%d+)%s+[%(%$:]") or
                    "0"

                local currentMoney, maxMoney =
                    energy:match(":CASH:([%d%.%,]+)%s*/%s*:CASH:([%d%.%,]+)")

                if not currentMoney then
                    currentMoney, maxMoney =
                        energy:match("%$%s*([%d%.%,]+)%s*/%s*%$%s*([%d%.%,]+)")
                end

                if not currentMoney then
                    currentMoney, maxMoney =
                        clean:match(":CASH:([%d%.%,]+)%s*/%s*:CASH:([%d%.%,]+)")
                end

                if not currentMoney then
                    currentMoney, maxMoney =
                        clean:match("%$%s*([%d%.%,]+)%s*/%s*%$%s*([%d%.%,]+)")
                end

                result[#result + 1] = {
                    row = serverRow,
                    listIndex = tonumber(listIndex) or 0,
                    number = tonumber(houseNumber) or 0,
                    city = serverToUtf8(city),
                    tax = serverToUtf8(tax),
                    cycles = tonumber(cycles) or 0,
                    currentMoney = currentMoney,
                    maxMoney = maxMoney
                }

                -- Server row рахуємо для кожного дому без винятків.
                serverRow = serverRow + 1
            end
        end
    end

    return result
end


local function scanAvailableHouses()
    if UI.balanceUpdating or UI.collecting or UI.scanning or #UI.houses == 0 then return end
    local claimed,owner=DialogGate.claim("scan","scan_start",{})
    if not claimed then UI.notice="Перевірку відкладено: AutoMiner зайнятий ("..tostring(owner)..")";return end
    UI.scanning, UI.loading = true, true
    UI.scanIndex, UI.scanTotal = 0, #UI.houses
    UI.scanHouseDialogReady = true
    UI.notice = nil
    local candidates = UI.houses
    local requestId = UI.requestId
    for _, house in ipairs(candidates) do
        house.scanned = false
        house.miningStatus = "unknown"
        house.miningReason = "Очікує перевірки"
    end

    lua_thread.create(function()
        local scanOK,scanError=pcall(function()
        local function ensureHouseDialog()
            if UI.scanHouseDialogReady then return true end
            local before = UI.scanHouseSerial
            sampSendChat("/flashminer")
            return waitUntil(function() return UI.scanHouseSerial > before end, 3500)
        end

        for i, house in ipairs(candidates) do
            if requestId ~= UI.requestId then break end
            UI.scanIndex = i
            UI.scanMinerText, UI.scanFailureReason = nil, nil
            if not ensureHouseDialog() then
                house.miningReason = "Сервер не відповів"
                break
            end
            house.miningStatus, house.miningReason = "checking", "Перевіряємо доступ"
            UI.scanHouseDialogReady = false
            UI.scanAttemptActive = true
            local before = UI.scanHouseSerial
            DialogGate.stageTo("scan","scan_house",{house=house.number})
            if not DialogGate.tx("scan",DIALOG_HOUSE,1,house.row,"",180,"scan_select_house") then UI.scanFailureReason="Не вдалося вибрати будинок" end
            waitUntil(function()
                return UI.scanMinerText ~= nil or UI.scanFailureReason ~= nil or UI.scanHouseSerial > before
            end, 3000)
            if UI.scanMinerText == nil and UI.scanFailureReason == nil and UI.scanHouseSerial > before then
                waitUntil(function() return UI.scanMinerText ~= nil or UI.scanFailureReason ~= nil end, 200)
            end
            UI.scanAttemptActive = false

            if UI.scanMinerText ~= nil then
                local stats = parseMinerStats(UI.scanMinerText)
                Runtime.apply(house,stats)
                house.scanned = true
                house.miningStatus, house.miningReason = "available", nil
                RateTracker.sample(house)
                ForecastTracker.sample(house)
                MiningModel.sample(house)
                IncomeAnalytics.observeHouse(house)
                local beforeClose = UI.scanHouseSerial
                DialogGate.stageTo("scan","scan_return",{house=house.number})
                DialogGate.tx("scan",DIALOG_MINER_LIST,0,0,"",170,"scan_close_house")
                local returned = waitUntil(function() return UI.scanHouseSerial > beforeClose end, 2200)
                if not returned then UI.scanHouseDialogReady = false end
            elseif UI.scanFailureReason or UI.scanHouseSerial > before then
                house.miningStatus = "unavailable"
                house.miningReason = UI.scanFailureReason or "FlashMiner недоступний"
                house.scanned = true
            else
                house.miningStatus, house.miningReason = "unknown", "Сервер не відповів"
                house.scanned = false
            end
            wait(25)
        end

        end)
        if not scanOK then UI.notice=tostring(scanError);Runtime.log("SCAN_ERROR",scanError) end
        if DialogGate.owner=="scan" then DialogGate.release("scan") end
        if requestId~=UI.requestId then return end
        Runtime.dataReady=true;Runtime.requestStarted=nil
        UI.houses = candidates
        UI.scanAttemptActive = false
        UI.scanning, UI.loading = false, false
        UI.scanIndex = UI.scanTotal
        UI.error = nil
        UI.lastScanTime = getGameTimer()
        local unverified = 0
        for _, house in ipairs(candidates) do
            if house.miningStatus == "unknown" then
                unverified = unverified + 1
                if house.miningReason == "Очікує перевірки" then house.miningReason = "Перевірку не завершено" end
            end
        end
        UI.notice = unverified > 0 and "Є неперевірені будинки" or "Список будинків оновлено"

        pushActivity(
            "Дані оновлено",
            Runtime.plural(#candidates-unverified,"будинок перевірено","будинки перевірено","будинків перевірено"),
            "neutral"
        )

        local attentionCount = 0
        local firstAttention = nil
        for _, house in ipairs(candidates) do
            local reason = houseAttentionReason(house)
            if reason and not isHouseIgnored(house.number) then
                attentionCount = attentionCount + 1
                if not firstAttention then
                    firstAttention = "Будинок №" .. tostring(house.number) .. " · " .. reason
                end
            end
        end

        if attentionCount > 0 then
            pushActivity(
                "Потребують уваги: " .. tostring(attentionCount),
                firstAttention or "Перевірте вкладку «Будинки»",
                "amber"
            )
        else
            pushActivity(
                "Усі ферми справні",
                "Проблем не виявлено",
                "green"
            )
        end
    end)
end

local function cancelCapturedDialog()
    if UI.dialogCaptured then
        sampSendDialogResponse(DIALOG_HOUSE, 0, 0, "")
        UI.dialogCaptured = false
    end
end

local function requestHouses(background)
    if not Runtime.ready() then UI.notice="Очікуємо входу в гру";return false end
    if Runtime.busy() then UI.notice="Перевірка вже триває";return false end
    if Runtime.foreignDialog() and not Runtime.canReplaceNotice() then UI.notice="Оновлення очікує закриття іншого меню";return false end
    if Runtime.canReplaceNotice() then Runtime.log("REPLACE_PASSWORD_NOTICE","request FlashMiner");Runtime.replacingNotice=true;Runtime.passwordNotice=nil end
    Runtime.dataReady=false
    UI.dialogCaptured=false

    UI.requestId = UI.requestId + 1
    local requestId = UI.requestId
    Runtime.requestStarted=os.time()

    UI.error = nil
    UI.notice = nil
    UI.scanHouseSerial = 0
    UI.scanHouseDialogReady = false
    UI.loading = true
    UI.waiting = true
    UI.positionApplied = false
    UI.backgroundRequest=background==true
    if not background then UI.open[0] = true end

    sampSendChat("/flashminer")

    lua_thread.create(function()
        wait(6000)

        if UI.waiting and UI.requestId == requestId then
            UI.waiting = false
            UI.loading = false
            UI.error = "Список будинків не надійшов від сервера."
        end
    end)
    return true
end

-- Follow server dialogs, never send a blind Enter or repeat a withdrawal.
function CollectFlow.isWithdrawalPrompt(title,text,button)
    local prompt=lowerServerText((title or "").." "..(text or ""))
    local action=lowerServerText(button or "")
    local btc=prompt:find("btc",1,true) or prompt:find("битко",1,true)
    local gpu=prompt:find("видеокарт",1,true) or prompt:find("відеокарт",1,true)
    local question=prompt:find("действительно",1,true) or prompt:find("хотите вывести",1,true)
        or prompt:find("підтвер",1,true) or prompt:find("бажаєте",1,true)
    local withdraw=prompt:find("вывод",1,true) or prompt:find("вывести",1,true)
        or prompt:find("вивести",1,true) or prompt:find("вивед",1,true)
    return btc and gpu and question and withdraw and
        (action=="" or action:find("вывод",1,true) or action:find("вывести",1,true)
         or action:find("вив",1,true) or action:find("да",1,true) or action:find("так",1,true)) and true or false
end

function CollectFlow.problem(message)
    local gpu=""
    if CollectFlow.gpuRack and CollectFlow.gpuSlot then
        gpu="GPU "..tostring(CollectFlow.gpuRack)..":"..tostring(CollectFlow.gpuSlot).." · "
    elseif CollectFlow.gpuSlot then
        gpu="GPU "..tostring(CollectFlow.gpuSlot).." · "
    end
    return (CollectFlow.houseNumber and ("Будинок "..CollectFlow.houseNumber.." · ") or "")..gpu..tostring(message or "")
end

local COLLECT_DELAY={
    house=90, list=95, gpu=100, confirm=105, back=80, close=80
}
local function collectDelay(kind)
    return COLLECT_DELAY[kind] or 95
end

function CollectFlow.waitFor(predicate,stage,timeout,timeoutMessage)
    CollectFlow.stage=stage
    DialogGate.stageTo("collect",stage,{house=CollectFlow.houseNumber,rack=CollectFlow.gpuRack,slot=CollectFlow.gpuSlot})
    local start=getGameTimer();local wall=os.time();local generation=Runtime.generation
    while getGameTimer()-start<(timeout or 5000) and os.time()-wall<math.ceil((timeout or 5000)/1000)+2 do
        if generation~=Runtime.generation or not Runtime.ready() then error("З’єднання з грою перервано",0) end
        if not (UI.collecting or UI.balanceUpdating) then error(CollectFlow.problem("Збір скасовано"),0) end
        if CollectFlow.failure then error(CollectFlow.problem(CollectFlow.failure),0) end
        if predicate() then return true end
        wait(0)
    end
    DialogGate.log("TIMEOUT","expected="..tostring(CollectFlow.expected or "-").." lastDialog="..tostring(CollectFlow.id or "-")
        .." reason="..tostring(timeoutMessage or stage or "timeout"))
    return false
end

function CollectFlow.await(id,stage,timeoutMessage,timeout)
    stage=stage or (id==DIALOG_HOUSE and "Чекаємо меню будинків"
        or (id==DIALOG_MINER_LIST and "Чекаємо список GPU" or "Чекаємо меню GPU"))
    local message=timeoutMessage or (id==DIALOG_HOUSE and "Не відкрився вибір будинку"
        or (id==DIALOG_MINER_LIST and "Не відкрився список GPU" or "Не відкрилося меню GPU"))
    if not CollectFlow.waitFor(function() return CollectFlow.id==id end,stage,timeout or 6500,message) then
        error(CollectFlow.problem(message),0)
    end
end

function CollectFlow.answer(id,button,row,input,minDelay,action)
    if CollectFlow.id~=id then error(CollectFlow.problem("Серверне меню змінилося"),0) end
    local nextExpected=(id==DIALOG_HOUSE and button==1) and DIALOG_MINER_LIST
        or ((id==DIALOG_MINER_LIST and button==1) and 25244
        or ((id==DIALOG_MINER_LIST and button==0) and DIALOG_HOUSE or nil))
    CollectFlow.id=-1
    CollectFlow.expected=nextExpected
    if not DialogGate.tx("collect",id,button,row or 0,input or "",minDelay or (id==DIALOG_MINER_LIST and collectDelay("list") or collectDelay("house")),action) then
        error(CollectFlow.problem("Не вдалося відправити відповідь серверному меню"),0)
    end
end

function CollectFlow.withdrawAndRead(house)
    CollectFlow.tooLow=false
    CollectFlow.confirmAmount=nil
    CollectFlow.inventoryCredit=nil
    CollectFlow.withdrawing=true
    CollectFlow.confirmation=nil
    CollectFlow.confirmSent=false
    CollectFlow.confirmFingerprint=nil
    CollectFlow.stage="Чекаємо підтвердження виведення"
    -- Never assume BTC is permanently row 1. Resolve the action from the
    -- server menu that was just received; Arizona has changed list layouts
    -- before, and a wrong row here can stop/toggle a GPU instead of collecting.
    local btcRow=nil
    if View and type(View.basementActionRows)=="function" then
        for _,item in ipairs(View.basementActionRows(CollectFlow.style,CollectFlow.text) or {}) do
            if item.kind=="btc" then btcRow=item.row;break end
        end
    end
    if btcRow==nil then error(CollectFlow.problem("Не знайдено дію збору BTC у меню GPU"),0) end
    CollectFlow.answer(25244,1,btcRow,"",collectDelay("gpu"),"collect_btc")
    if not CollectFlow.waitFor(function()
        return CollectFlow.confirmation~=nil or CollectFlow.tooLow
    end,"Чекаємо підтвердження виведення",7000,"Не відкрилося підтвердження збору BTC") then
        error(CollectFlow.problem("Не відкрилося підтвердження збору BTC"),0)
    end
    if not CollectFlow.tooLow then
        local prompt=CollectFlow.confirmation
        if not prompt or CollectFlow.id~=prompt.id then
            error(CollectFlow.problem("Меню підтвердження змінилося"),0)
        end
        CollectFlow.confirmSent=true
        CollectFlow.confirmFingerprint=prompt.fingerprint
        CollectFlow.confirmation=nil
        CollectFlow.stage="Перевіряємо результат виведення"
        CollectFlow.answer(prompt.id,1,0,"",collectDelay("confirm"),"confirm_btc")
    end
    local returned=CollectFlow.waitFor(function()
        return CollectFlow.id==25244 or CollectFlow.id==DIALOG_MINER_LIST
    end,"Перевіряємо результат виведення",8000,"Не повернувся список GPU після BTC")
    if not returned then
        -- Never repeat a withdrawal after an uncertain result. Re-open read-only
        -- state and verify the balance instead.
        Journal.add("system","Відновлюємо перевірку балансу",
            CollectFlow.problem("Повторно перевіряємо залишок BTC. Виведення не повторюємо."))
        CollectFlow.openHouse(house)
    elseif CollectFlow.id==25244 then
        CollectFlow.answer(25244,0,0,"",collectDelay("back"),"back_to_gpu_list")
        CollectFlow.await(DIALOG_MINER_LIST,"Повертаємо список GPU","Не повернувся список GPU після BTC",7500)
    end
end

local Taxes={busy=false,recording=nil,profile=nil,dialog=nil,result=nil}
function Taxes.lowerUtf8(text)
    local value=text:lower()
    local upper="АБВГДЕЁЖЗИЙКЛМНОПРСТУФХЦЧШЩЪЫЬЭЮЯІЇЄҐ"
    local lower="абвгдеёжзийклмнопрстуфхцчшщъыьэюяіїєґ"
    for i=1,#upper,2 do value=value:gsub(upper:sub(i,i+1),lower:sub(i,i+1)) end
    return value
end
function Taxes.lines(text,style)
    local rows={};local index=style==5 and -1 or 0
    for line in tostring(text or ""):gmatch("[^\r\n]+") do
        if index>=0 then rows[index]=stripColors(serverToUtf8(line)):gsub("^%s+",""):gsub("%s+$","") end
        index=index+1
    end
    return rows
end
function Taxes.taxRow(text,style)
    for index,line in pairs(Taxes.lines(text,style)) do
        local lower=Taxes.lowerUtf8(line)
        if lower:find("оплата всех налогов",1,true) or lower:find("оплатить все налоги",1,true)
            or lower:find("оплатити всі податки",1,true) then return index end
    end
end
function Taxes.note(text)
    UI.notice=text;Notify.raw("taxes",text,"taxes:"..tostring(text),15)
end
function Taxes.recordStep(step)
    local r=Taxes.recording
    if not r or getGameTimer()>r.deadline then return end
    local list=r.paid and r.close or (not r.bankSelected and r.steps or nil)
    if not list then return end
    if #list>=12 then r.invalid=true;return end
    step.delay=math.min(1500,math.max(80,getGameTimer()-(r.last or getGameTimer())))
    r.last=getGameTimer();list[#list+1]=step;r.pendingStep=not r.paid and step or nil
    if r.paid and step.kind=="cef" and step.event=="onArizonaSendKey" then r.pendingClose=step end
end
function Taxes.beginLearning()
    if UI.collecting or UI.scanning or UI.waiting or UI.balanceUpdating or Taxes.busy then return end
    if not Taxes.bridge then Taxes.note("Бібліотека телефону недоступна");return end
    Taxes.result=nil;Taxes.dialog=nil;Taxes.amount=nil;Taxes.abort=nil
    Taxes.recording={steps={},close={},deadline=getGameTimer()+90000,last=getGameTimer()}
    UI.open[0]=false
    Taxes.note("Відкрийте телефон, оплатіть усі податки й закрийте телефон. Потім введіть /minertaxdone")
end
function Taxes.finishLearning()
    local r=Taxes.recording;Taxes.recording=nil
    if not r or not r.bankSelected or not r.paid or #r.steps==0 then
        Taxes.note("Маршрут не збережено: пройдіть оплату до результату");return false
    end
    if r.invalid then Taxes.note("Маршрут містить непідтверджений перехід. Запишіть його ще раз.");return false end
    for _,step in ipairs(r.steps) do
        if step.kind~="dialog" and not step.expect then Taxes.note("Не отримано підтвердження сторінки телефону. Запишіть маршрут ще раз.");return false end
    end
    local closing=nil
    if #r.close==1 and r.closedStep==r.close[1] then closing=r.closedStep end
    local profile={version=2,identity=Runtime.identity(),steps=r.steps,close={},closing=closing}
    if not profile.identity then Taxes.note("Очікуємо готовності гри");return false end
    local file=Runtime.open(dataDirPath().."\\tax-route.json","w")
    if not file then Taxes.note("Не вдалося зберегти маршрут");return false end
    if not file:write(encodeJson(profile)) or not file:close() then Taxes.note("Не вдалося зберегти маршрут");return false end;Taxes.profile=profile
    Taxes.note("Маршрут оплати збережено");return true
end
function Taxes.onDialog(id,style,title,b1,b2,text)
    if not Taxes.busy and not Taxes.recording then return end
    local d={id=id,style=style,title=title or "",button=b1 or "",text=text or ""}
    if Taxes.direct then
        Runtime.log("TAX_DIALOG","id="..id.." style="..style.." taxRow="..tostring(Taxes.taxRow(text,style) or "-").." text="..serverToUtf8(stripColors((title or "").." "..(text or ""))):gsub("[\r\n]"," "):sub(1,1800))
        local lower=lowerServerText(d.title.." "..d.text)
        d.row=Taxes.taxRow(text,style)
        if not (d.row~=nil or lower:find("банк",1,true) or lower:find("банков",1,true) or lower:find("налог",1,true) or lower:find("подат",1,true)) then
            Taxes.abort="Відкрилося стороннє меню — оплату зупинено";return
        end
        Taxes.dialog=d;Taxes.onMessage(d.title.." "..d.text)
        if d.row==nil and Taxes.result~="paid" then
            if lower:find("нет налогов",1,true) or lower:find("немає податків",1,true) or lower:find("налоги оплачены",1,true) or lower:find("не нуждаетесь в оплате",1,true) then Taxes.result="none"
            elseif lower:find("недостат",1,true) or lower:find("не хватает",1,true) or lower:find("бракує",1,true) then Taxes.result="insufficient" end
        end
        return false
    end
    if Taxes.recording and Taxes.recording.pendingStep then
        Taxes.recording.pendingStep.expect={kind="dialog",title=serverToUtf8(d.title)}
        Taxes.recording.pendingStep=nil
    end
    d.row=Taxes.taxRow(text,style);Taxes.dialog=d
    local lower=lowerServerText((title or "").." "..(text or ""))
    local tax=lower:find("налог",1,true) or lower:find("подат",1,true)
    if tax and d.row==nil then
        if lower:find("нет налогов",1,true) or lower:find("немає податків",1,true) then Taxes.result="none"
        elseif lower:find("недостат",1,true) or lower:find("не хватает",1,true) or lower:find("бракує",1,true) then Taxes.result="insufficient" end
        if Taxes.recording and Taxes.recording.bankSelected and Taxes.result then Taxes.recording.paid=true end
    end
    if Taxes.busy then
        if not tax and d.row==nil and not (Taxes.expectedTitles and Taxes.expectedTitles[serverToUtf8(d.title)]) then
            Taxes.abort="Відкрилося стороннє меню — збір зупинено";return
        end
        return false
    end
end
function Taxes.onResponse(id,button,row)
    local r=Taxes.recording;local d=Taxes.dialog
    if not r or not d or d.id~=id then return end
    if d.row~=nil and button==1 and row==d.row then r.bankSelected=true;return end
    if not r.bankSelected and button==1 then
        local choice=Taxes.lines(d.text,d.style)[row]
        if choice then Taxes.recordStep({kind="dialog",title=serverToUtf8(d.title),choice=choice}) end
    end
end
function Taxes.onMessage(text)
    if not Taxes.busy and not Taxes.recording then return end
    local lower=lowerServerText(text)
    if (not Taxes.direct or Taxes.paymentRequested) and (lower:find("оплатили все налоги",1,true) or lower:find("сплатили всі податки",1,true) or lower:find("все налоги успешно оплачены",1,true)) then
        Taxes.result="paid"
        Taxes.amount=serverToUtf8(stripColors(text)):match("%$%s*([%d%., ]+)")
        if Taxes.recording and Taxes.recording.bankSelected then Taxes.recording.paid=true end
    end
end
function Taxes.init()
    local ok,bridge=pcall(require,"arizona-events")
    if not ok then return end
    Taxes.bridge=bridge
    bridge.onArizonaToggleCursor=function(packet)
        Taxes.cursorSerial=(Taxes.cursorSerial or 0)+1;Taxes.cursorOpen=packet.status;Runtime.cefCursor=packet.status
        if packet.status==false then Runtime.phoneOpen=false end
        if Taxes.recording and Taxes.recording.pendingStep and packet.status==true then
            Taxes.recording.pendingStep.expect={kind="cursor",status=true};Taxes.recording.pendingStep=nil
        end
        if Taxes.recording and Taxes.recording.pendingClose and packet.status==false then
            Taxes.recording.closedStep=Taxes.recording.pendingClose;Taxes.recording.pendingClose=nil
        end
        if (Taxes.direct or Electricity.busy) and packet.status==true then return false end
    end
    for _,event in ipairs({"onArizonaDisplay","onArizonaLoadHtml"}) do
        local name=event
        bridge[name]=function(packet)
            local text=tostring(packet.text or packet.url or "")
            if text:find("event.setActiveView",1,true) then
                Runtime.phoneOpen=text:find('"Phone"',1,true)~=nil
            end
            if Taxes.direct then
                Taxes.onMessage(text)
                if text:find("event.setActiveView",1,true) then
                    if text:find('"Phone"',1,true) then Taxes.phoneSeen=true;Taxes.phoneOwned=true
                    elseif Taxes.phoneOwned then Taxes.phoneClosed=true end
                end
            end
            if Electricity.busy then
                Electricity.onMessage(text)
                if text:find("event.setActiveView",1,true) then
                    if text:find('"Phone"',1,true) then Electricity.phoneSeen=true;Electricity.phoneOwned=true
                    elseif Electricity.phoneOwned then Electricity.phoneClosed=true end
                end
            end
            if #text>8192 then return end
            local signature=text
            for _,field in ipairs({"balance","btc","amount","timestamp"}) do
                signature=signature:gsub('("'..field..'"%s*:%s*)[%d%.]+','%1#')
            end
            local state={kind="cef",event=name,server_id=packet.server_id,signature=signature}
            Taxes.cefSerial=(Taxes.cefSerial or 0)+1;Taxes.cefState=state
            if Taxes.recording and Taxes.recording.pendingStep then
                Taxes.recording.pendingStep.expect=state;Taxes.recording.pendingStep=nil
            end
            if (Taxes.direct or Electricity.busy) and text:find("event.setActiveView",1,true) and text:find('"Phone"',1,true) then return false end
        end
    end
    for _,event in ipairs({"onArizonaSendKey","onArizonaSendOpenInterface","onArizonaSend"}) do
        local name=event
        bridge[name]=function(packet)
            if not Taxes.recording then return end
            local payload={}
            if name=="onArizonaSendKey" then payload.key=packet.key;payload._unknown=packet._unknown
            elseif name=="onArizonaSendOpenInterface" then payload.server_id=packet.server_id;payload.menu_id=packet.menu_id
            elseif type(packet.text)=="string" and #packet.text<=512 then payload.text=packet.text;payload.server_id=packet.server_id
            else return end
            Taxes.recordStep({kind="cef",event=name,payload=payload})
        end
    end

end
function Taxes.validStep(step)
    if type(step)~="table" then return false end
    if step.kind=="dialog" then return type(step.title)=="string" and #step.title<=256 and type(step.choice)=="string" and #step.choice<=512 end
    local e=step.expect
    if type(e)~="table" or not ((e.kind=="cursor" and e.status==true) or (e.kind=="dialog" and type(e.title)=="string") or
        (e.kind=="cef" and (e.event=="onArizonaDisplay" or e.event=="onArizonaLoadHtml") and type(e.signature)=="string" and #e.signature<=8192)) then return false end
    if step.kind=="command" then return step.command=="/phone" or step.command=="/tel" end
    if step.kind~="cef" or type(step.payload)~="table" then return false end
    local p=step.payload
    local function uint(v,max) return type(v)=="number" and v==math.floor(v) and v>=0 and v<=max end
    if step.event=="onArizonaSendKey" then return uint(p.key,255) and uint(p._unknown,255) end
    if step.event=="onArizonaSendOpenInterface" then return uint(p.server_id,4294967295) and uint(p.menu_id,4294967295) end
    return step.event=="onArizonaSend" and uint(p.server_id,4294967295) and type(p.text)=="string" and #p.text<=512
end
function Taxes.await(predicate,timeout)
    local start=getGameTimer();local wall=os.time();local generation=Runtime.generation
    while getGameTimer()-start<(timeout or 5000) and os.time()-wall<math.ceil((timeout or 5000)/1000)+2 do
        if generation~=Runtime.generation or not Runtime.ready() then error("З’єднання з грою перервано",0) end
        if Taxes.abort then error(Taxes.abort,0) end
        if predicate() then return true end
        wait(0)
    end
    return false
end
function Taxes.replay(steps)
    local function check(value,message) if not value then error(message,0) end end
    for _,step in ipairs(steps or {}) do
        if Taxes.abort then error(Taxes.abort,0) end
        check(Taxes.validStep(step),"Маршрут телефону застарів. Запишіть його ще раз.")
        local serial=Taxes.cefSerial or 0
        local cursorSerial=Taxes.cursorSerial or 0
        if step.kind~="dialog" then Taxes.dialog=nil end
        wait(80)
        if Taxes.abort then error(Taxes.abort,0) end
        if step.kind=="cef" then
            check(step.event=="onArizonaSendKey" or step.event=="onArizonaSendOpenInterface" or step.event=="onArizonaSend","Пункт меню телефону змінився")
            Taxes.bridge.send(step.event,step.payload)
        elseif step.kind=="command" then
            check(step.command=="/phone" or step.command=="/tel","Пункт меню телефону змінився")
            sampSendChat(step.command)
        elseif step.kind=="dialog" then
            check(Taxes.await(function() return Taxes.dialog and serverToUtf8(Taxes.dialog.title)==step.title end),"Меню телефону не відкрилося")
            local d=Taxes.dialog;local found=nil
            for row,line in pairs(Taxes.lines(d.text,d.style)) do if line==step.choice then found=row;break end end
            check(found~=nil,"Пункт меню телефону змінився")
            Taxes.dialog=nil;sampSendDialogResponse(d.id,1,found,"")
        else error("Пункт меню телефону змінився",0) end
        if step.expect then
            check(Taxes.await(function()
                local e=step.expect
                if e.kind=="cursor" then return (Taxes.cursorSerial or 0)>cursorSerial and Taxes.cursorOpen==e.status end
                if e.kind=="dialog" then return Taxes.dialog and serverToUtf8(Taxes.dialog.title)==e.title end
                local state=Taxes.cefState
                return (Taxes.cefSerial or 0)>serial and state and state.event==e.event and state.server_id==e.server_id and state.signature==e.signature
            end,8000),"Сторінка телефону не підтвердилася. Оплату зупинено.")
        end
    end
end
function Taxes.openBank()
    if not Taxes.bridge or type(Taxes.bridge.send)~="function" then error("Бібліотека телефону недоступна",0) end
    Runtime.log("TAX_BANK_REQUEST","onArizonaSend app=24")
    Taxes.bridge.send("onArizonaSend",{text="launchedApp|24",server_id=0})
end

-- House electricity top-up uses the same phone/bank transport as tax payment,
-- but keeps its own state so the two operations can never answer each other's dialogs.
function Electricity.onDialog(id,style,title,b1,b2,text)
    if not Electricity.busy then return end
    Electricity.dialog={id=id,style=style,title=title or "",button=b1 or "",button2=b2 or "",text=text or ""}
    local lower=lowerServerText((title or "").." "..(text or ""))
    if lower:find("недостат",1,true) or lower:find("не хватает",1,true) or lower:find("бракує",1,true) then
        Electricity.result="insufficient"
    else
        -- A success dialog is authoritative only after AutoMiner has actually
        -- submitted the amount (or is confirming it). Never let navigation
        -- dialogs/messages mark the payment as completed.
        local paymentStage=Electricity.stage=="amount" or Electricity.stage=="confirm"
        local explicitSuccess=(lower:find("успеш",1,true) or lower:find("успіш",1,true)
            or lower:find("пополнен",1,true) or lower:find("пополнили",1,true)
            or lower:find("поповнено",1,true) or lower:find("поповнили",1,true)
            or lower:find("зачислен",1,true) or lower:find("зарахован",1,true)
            or lower:find("внесен",1,true))
        local electricityContext=(lower:find("электр",1,true) or lower:find("електр",1,true)
            or lower:find("счет",1,true) or lower:find("счёт",1,true) or lower:find("рахунк",1,true))
        if paymentStage and explicitSuccess and electricityContext then
            Electricity.result="paid"
            Runtime.log("ELECTRICITY_PAID_CONFIRMED","source=dialog id="..tostring(id).." stage="..tostring(Electricity.stage))
        end
    end
    Runtime.log("ELECTRICITY_DIALOG","id="..tostring(id).." style="..tostring(style).." text="..serverToUtf8(stripColors((title or "").." "..(text or ""))):gsub("[\r\n]"," "):sub(1,1600))
    return false
end

function Electricity.onMessage(text)
    if not Electricity.busy then return end
    local lower=lowerServerText(text)
    if lower:find("недостат",1,true) or lower:find("не хватает",1,true) or lower:find("бракує",1,true) then
        Electricity.result="insufficient";return
    end

    -- Arizona sends an informational prompt before payment, e.g.:
    -- "Выберите дом, в котором хотите пополнить счёт на электроэнергию".
    -- The old broad matcher treated "пополнить" + "дом" as payment success,
    -- so the flow stopped before the house/amount step. Accept only an explicit
    -- completed-payment phrase after the amount has actually been submitted.
    local paymentStage=Electricity.stage=="amount" or Electricity.stage=="confirm"
    local explicitSuccess=(lower:find("успеш",1,true) or lower:find("успіш",1,true)
        or lower:find("пополнен",1,true) or lower:find("пополнили",1,true)
        or lower:find("поповнено",1,true) or lower:find("поповнили",1,true)
        or lower:find("зачислен",1,true) or lower:find("зарахован",1,true)
        or lower:find("внесен",1,true))
    local electricityContext=(lower:find("электр",1,true) or lower:find("електр",1,true)
        or lower:find("счет",1,true) or lower:find("счёт",1,true) or lower:find("рахунк",1,true))
    if paymentStage and explicitSuccess and electricityContext then
        Electricity.result="paid"
        Runtime.log("ELECTRICITY_PAID_CONFIRMED","source=server_message stage="..tostring(Electricity.stage).." text="..serverToUtf8(stripColors(text)):gsub("[\r\n]"," "):sub(1,500))
    elseif lower:find("выберите дом",1,true) or lower:find("виберіть будинок",1,true)
        or lower:find("хотите пополнить",1,true) or lower:find("хочете поповнити",1,true) then
        Runtime.log("ELECTRICITY_PROMPT_IGNORED","stage="..tostring(Electricity.stage).." text="..serverToUtf8(stripColors(text)):gsub("[\r\n]"," "):sub(1,500))
    end
end

function Electricity.await(predicate,timeout)
    local start=getGameTimer();local wall=os.time();local generation=Runtime.generation
    while getGameTimer()-start<(timeout or 6000) and os.time()-wall<math.ceil((timeout or 6000)/1000)+2 do
        if generation~=Runtime.generation or not Runtime.ready() then error("З’єднання з грою перервано",0) end
        if Electricity.abort then error(Electricity.abort,0) end
        if predicate() then return true end
        wait(0)
    end
    return false
end

function Electricity.lines(text,style)
    -- Arizona sometimes uses TABLIST_HEADERS (style 5) for menus with no real
    -- header row. Taxes.lines() always skips the first line for style 5, which
    -- shifts response rows by one in the bank menu. Detect whether the first
    -- visible line is actually selectable and preserve the real server index.
    local raw={}
    for line in tostring(text or ""):gmatch("[^\r\n]+") do
        local clean=stripColors(serverToUtf8(line)):gsub("^%s+",""):gsub("%s+$","")
        if clean:find("%S") then raw[#raw+1]=clean end
    end
    local rows={}
    local start=1
    if style==5 and #raw>0 then
        local first=raw[1]
        local selectable=first:match("^%s*%[%d+%]")~=nil or first:match("^%s*%d+[%.)]%s*")~=nil
        if not selectable then start=2 end
    end
    local row=0
    for i=start,#raw do rows[row]=raw[i];row=row+1 end
    return rows
end

function Electricity.respond(d,button,row,input,delayMs)
    -- Single controller: only Electricity.runHouse answers these dialogs.
    -- This runs inside a MoonLoader worker thread, so yielding here is safe.
    if not d or not Runtime.ready() then return false end
    DialogGate.safeDelay(d.id,math.max(190,tonumber(delayMs) or 190))
    if not Runtime.ready() then return false end
    if button==1 and row~=nil and type(sampSetCurrentDialogListItem)=="function" then
        pcall(sampSetCurrentDialogListItem,row)
        wait(35)
    end
    Runtime.log("ELECTRICITY_RESPONSE","stage="..tostring(Electricity.stage or "step").." id="..tostring(d.id).." button="..tostring(button).." row="..tostring(row or 0).." input="..tostring(input or ""))
    return DialogGate.tx("electricity",d.id,button,row or 0,input or "",0,"electricity_"..tostring(Electricity.stage or "step"))
end

function Electricity.parseBankBalances(d)
    local found,count={},0
    if not d then return found,count end

    -- Electricity.lines() ALREADY strips SA-MP colour tags and converts the
    -- server codepage to UTF-8. Converting the same line through serverToUtf8()
    -- a second time corrupts Cyrillic ("ДОМ"), so no house number is found.
    -- Work only with the normalized UTF-8 lines returned by Electricity.lines().
    local rows=Electricity.lines(d.text,d.style)
    for row,line in pairs(rows) do
        local clean=tostring(line or ""):gsub("^%s+",""):gsub("%s+$","")
        local lower=Taxes.lowerUtf8(clean)
        local number=lower:match("дом%s*№%s*(%d+)")
            or lower:match("дом%s+№?%s*(%d+)")
            or lower:match("будинок%s*№%s*(%d+)")
            or lower:match("будинок%s+№?%s*(%d+)")
            or clean:match("№%s*(%d+)")

        local money=nil
        if number then
            -- Live Arizona electricity selector example:
            -- [1] ДОМ №928    SAN FIERRO    $ 39.558.149
            -- Prefer the explicit $ amount, then the last TAB column, then the
            -- right-most formatted number as a defensive fallback.
            money=clean:match("%$%s*([%d%.,%s]+)")
            if not money then
                local cols=splitTabs(clean)
                for i=#cols,1,-1 do
                    local col=tostring(cols[i] or "")
                    if col:find("%d") and (col:find("%$") or i==#cols) then
                        money=col
                        break
                    end
                end
            end
            if not money then
                local last=nil
                for candidate in clean:gmatch("([%d][%d%.,%s]*)") do last=candidate end
                money=last
            end
        end

        local balance=parseHouseMoney(money)
        local id=tonumber(number)
        Runtime.log("ELECTRICITY_BALANCE_PARSE","row="..tostring(row).." house="..tostring(id).." money="..tostring(money).." balance="..tostring(balance).." line="..clean:sub(1,260))
        if id and balance~=nil then
            found[id]={number=id,row=row,balance=balance,currentMoney=tostring(balance),line=clean}
            count=count+1
        end
    end
    Runtime.log("ELECTRICITY_BALANCE_PARSE_DONE","rows="..tostring((function() local n=0 for _ in pairs(rows) do n=n+1 end return n end)()).." parsed="..tostring(count))
    return found,count
end

function Electricity.findExactHouseRow(d,houseNumber)
    if not d or d.id~=DIALOG_HOUSE then return nil end
    local wanted=tonumber(houseNumber)
    if not wanted then return nil end
    -- The bank's 7238 selector has columns HOUSE / CITY / BALANCE, unlike the
    -- FlashMiner house selector. Parse that layout first so the bank balance
    -- cannot accidentally be copied into the tax field or discarded.
    local bank=Electricity.parseBankBalances(d)
    if bank[wanted] then return bank[wanted].row,bank[wanted] end
    for _,fresh in ipairs(parseHouses(d.text)) do
        if tonumber(fresh.number)==wanted then return fresh.row,fresh end
    end
    return nil
end

function Electricity.findNavigationRow(d,houseNumber,stage)
    local rows=Electricity.lines(d.text,d.style)
    local exactElectricity,direct,account,target,topup,bank=nil,nil,nil,nil,nil,nil
    local number=tostring(math.floor(tonumber(houseNumber) or 0))
    local whole=Taxes.lowerUtf8((d.title or "").." "..(d.text or ""))
    local housePicker=(whole:find("выбор дома",1,true) or whole:find("вибір будинку",1,true)
        or whole:find("выберите дом",1,true) or whole:find("виберіть будинок",1,true))
        and (whole:find("электр",1,true) or whole:find("електр",1,true) or stage=="topup")
    for row,line in pairs(rows) do
        local t=Taxes.lowerUtf8(line)
        local hasTopup=t:find("пополн",1,true) or t:find("поповн",1,true) or t:find("внести",1,true) or t:find("зачисл",1,true)
        local hasHome=t:find("дом",1,true) or t:find("будин",1,true) or t:find("недвиж",1,true)
        local hasAccount=t:find("счет",1,true) or t:find("счёт",1,true) or t:find("рахунок",1,true) or t:find("баланс",1,true)
        local hasElectricity=t:find("электр",1,true) or t:find("електр",1,true)
        if hasTopup and hasElectricity and not exactElectricity then exactElectricity=row end
        if hasTopup and (hasHome or hasAccount) and not direct then direct=row end
        if (hasHome and hasAccount) and not account then account=row end
        if number~="0" and (tostring(line):match("%f[%d]"..number.."%f[%D]")~=nil) and (hasHome or stage=="house_list" or housePicker) and not target then target=row end
        if hasTopup and not topup then topup=row end
        if (t:find("банковские дела",1,true) or t:find("банківські справи",1,true)
            or t:find("управление счетом",1,true) or t:find("керування рахунком",1,true)) and not bank then bank=row end
    end
    -- Once Arizona shows "ВЫБОР ДОМА", select only the exact house requested
    -- by AutoMiner. Never fall back to another house or another navigation row.
    if housePicker then return target end
    if exactElectricity~=nil then return exactElectricity end
    if stage=="start" then return direct or account or bank or target or topup end
    if stage=="bank" then return direct or account or target or topup end
    if stage=="account" or stage=="house_list" then return target or topup or direct end
    if stage=="house" then return topup or direct end
    return direct or target or topup or account or bank
end

function Electricity.nextStage(d,row,current,houseNumber)
    local line=Electricity.lines(d.text,d.style)[row] or ""
    local t=Taxes.lowerUtf8(line)
    local number=tostring(math.floor(tonumber(houseNumber) or 0))
    if t:find("банковские дела",1,true) or t:find("банківські справи",1,true) or t:find("управление счетом",1,true) or t:find("керування рахунком",1,true) then return "bank" end
    if t:find("пополн",1,true) or t:find("поповн",1,true) or t:find("внести",1,true) or t:find("зачисл",1,true) then return "topup" end
    if number~="0" and tostring(line):match("%f[%d]"..number.."%f[%D]") then return "house" end
    if t:find("дом",1,true) or t:find("будин",1,true) or t:find("недвиж",1,true) then return "account" end
    return current
end

function Electricity.closeOwnedPhone()
    if Electricity.dialog and Runtime.ready() then pcall(DialogGate.tx,"electricity",Electricity.dialog.id,0,0,"",140,"electricity_close_dialog");Electricity.dialog=nil end
    if Electricity.phoneOwned and not Electricity.phoneClosed and not Electricity.closeRequested and Runtime.ready() then
        Electricity.closeRequested=true
        pcall(sampSendChat,"/phone")
    end
end

function Electricity.fetchBankBalances()
    if not Taxes.bridge or type(Taxes.bridge.send)~="function" then return nil,"Бібліотека телефону недоступна" end
    if Runtime.foreignDialog() then return nil,"Відкрите інше меню" end

    DialogGate.push("electricity","electricity_balance_scan",{})
    Electricity.busy=true;Electricity.dialog=nil;Electricity.result=nil;Electricity.abort=nil;Electricity.target=nil;Electricity.stage="balance_scan"
    Electricity.phoneSeen=false;Electricity.phoneOwned=false;Electricity.phoneClosed=false;Electricity.closeRequested=false
    Runtime.log("ELECTRICITY_BALANCE_SCAN_START","opening bank")

    local balances=nil
    local ok,err=pcall(function()
        local function check(v,m) if not v then error(m,0) end end
        sampSendChat("/phone")
        check(Electricity.await(function() return Electricity.phoneSeen end,8000),"Телефон не відкрився")
        Taxes.openBank()
        if Electricity.phoneOwned and not Electricity.phoneClosed then Electricity.closeRequested=true;sampSendChat("/phone") end
        check(Electricity.await(function() return Electricity.dialog~=nil or Electricity.result~=nil end,8000),"Банківське меню не відкрилося")

        local stage="start"
        local visited={}
        local deadline=os.time()+20
        while not balances and os.time()<deadline do
            check(Electricity.await(function() return Electricity.dialog~=nil or Electricity.result~=nil end,7000),"Банк не відповів")
            local d=Electricity.dialog;Electricity.dialog=nil
            check(d~=nil,"Банк не повернув меню")
            local fingerprint=tostring(d.id).."|"..tostring(stage).."|"..serverToUtf8(stripColors(d.text)):sub(1,1200)
            if visited[fingerprint] then error("Банк повторив те саме меню на етапі перевірки балансів",0) end
            visited[fingerprint]=true

            if d.id==6565 then
                local row=Electricity.findNavigationRow(d,0,stage)
                check(row~=nil,"Не знайдено пункт «Пополнить счёт на электричество»")
                stage="topup";Electricity.stage="balance_topup"
                DialogGate.stageTo("electricity","electricity_balance_topup",{})
                Runtime.log("ELECTRICITY_BALANCE_MENU","row="..tostring(row))
                check(Electricity.respond(d,1,row,"",210),"Не вдалося відкрити список будинків електроенергії")
            elseif d.id==DIALOG_HOUSE then
                local parsed,count=Electricity.parseBankBalances(d)
                check(count>0,"Не вдалося прочитати баланси будинків із банку")
                balances=parsed
                local parts={}
                for number,info in pairs(parsed) do parts[#parts+1]=tostring(number).."="..tostring(info.balance) end
                table.sort(parts)
                Runtime.log("ELECTRICITY_BALANCE_SNAPSHOT",table.concat(parts,","))
                Electricity.stage="balance_done"
                DialogGate.stageTo("electricity","electricity_balance_done",{})
                Electricity.respond(d,0,0,"",120)
            else
                local row=Electricity.findNavigationRow(d,0,stage)
                check(row~=nil,"Неочікуване меню під час перевірки балансів · dialog "..tostring(d.id))
                stage=Electricity.nextStage(d,row,stage,0);Electricity.stage="balance_"..tostring(stage)
                check(Electricity.respond(d,1,row,"",190),"Не вдалося перейти до списку балансів")
            end
        end
        check(balances~=nil,"Банк не повернув список балансів будинків")
    end)

    Electricity.closeOwnedPhone()
    Electricity.busy=false;Electricity.target=nil;Electricity.dialog=nil;Electricity.stage=nil;Electricity.result=nil
    Runtime.log("ELECTRICITY_BALANCE_SCAN_DONE","ok="..tostring(ok).." error="..tostring(ok and nil or err))
    if DialogGate.owner=="electricity" then DialogGate.pop("electricity") end
    if not ok then return nil,tostring(err) end
    return balances
end

function Electricity.runHouse(house)
    if not house then return false,"Будинок не знайдено" end
    if not Taxes.bridge or type(Taxes.bridge.send)~="function" then return false,"Бібліотека телефону недоступна" end
    if Runtime.foreignDialog() then return false,"Відкрите інше меню" end
    DialogGate.push("electricity","electricity_start",{house=house.number})
    Electricity.busy=true;Electricity.dialog=nil;Electricity.result=nil;Electricity.abort=nil;Electricity.target=house;Electricity.stage="start"
    Electricity.phoneSeen=false;Electricity.phoneOwned=false;Electricity.phoneClosed=false;Electricity.closeRequested=false
    Runtime.log("ELECTRICITY_START","house="..tostring(house.number).." balance="..tostring(parseHouseMoney(house.currentMoney)))
    local ok,err=pcall(function()
        local function check(v,m) if not v then error(m,0) end end
        sampSendChat("/phone")
        check(Electricity.await(function() return Electricity.phoneSeen end,8000),"Телефон не відкрився")
        Taxes.openBank()
        if Electricity.phoneOwned and not Electricity.phoneClosed then Electricity.closeRequested=true;sampSendChat("/phone") end
        check(Electricity.await(function() return Electricity.dialog~=nil or Electricity.result~=nil end,8000),"Банківське меню не відкрилося")

        local stage="start";local amountSent=false;local confirmationSent=false;local visited={};local deadline=os.time()+32
        while not Electricity.result and os.time()<deadline do
            check(Electricity.await(function() return Electricity.dialog~=nil or Electricity.result~=nil end,7000),"Банк не відповів")
            if Electricity.result then break end
            local d=Electricity.dialog;Electricity.dialog=nil
            local lower=lowerServerText((d.title or "").." "..(d.text or ""))
            local fingerprint=tostring(d.id).."|"..tostring(stage).."|"..serverToUtf8(stripColors(d.text)):sub(1,1200)
            if visited[fingerprint] then error("Банк повторив те саме меню на етапі "..tostring(stage),0) end
            visited[fingerprint]=true

            if d.id==6565 then
                local row=Electricity.findNavigationRow(d,house.number,stage)
                if row==nil then error("Не знайдено пункт «Пополнить счёт на электричество»",0) end
                stage="topup";Electricity.stage=stage
                DialogGate.stageTo("electricity","electricity_menu",{house=house.number})
                Runtime.log("ELECTRICITY_MENU_SELECT","row="..tostring(row))
                check(Electricity.respond(d,1,row,"",210),"Не вдалося відкрити поповнення електроенергії")

            elseif d.id==DIALOG_HOUSE and #parseHouses(d.text)>0 then
                local houseRow,freshHouse=Electricity.findExactHouseRow(d,house.number)
                if houseRow==nil then error("Будинок №"..tostring(house.number).." не знайдено у списку поповнення електроенергії",0) end
                if freshHouse then
                    for _,key in ipairs({"row","city","tax","cycles","currentMoney","maxMoney"}) do
                        if freshHouse[key]~=nil and freshHouse[key]~="" then house[key]=freshHouse[key] end
                    end
                end
                stage="house";Electricity.stage=stage
                DialogGate.stageTo("electricity","electricity_house",{house=house.number})
                Runtime.log("ELECTRICITY_HOUSE_SELECT","house="..tostring(house.number).." row="..tostring(houseRow))
                check(Electricity.respond(d,1,houseRow,"",210),"Не вдалося вибрати будинок для поповнення")

            elseif d.id==27039 and d.style==1 then
                amountSent=true;stage="amount";Electricity.stage=stage
                DialogGate.stageTo("electricity","electricity_amount",{house=house.number})
                Runtime.log("ELECTRICITY_AMOUNT","house="..tostring(house.number).." amount="..tostring(AUTO_ELECTRICITY_AMOUNT))
                check(Electricity.respond(d,1,0,tostring(AUTO_ELECTRICITY_AMOUNT),210),"Не вдалося ввести суму поповнення")

            elseif d.style==0 and amountSent and (lower:find("подтверд",1,true) or lower:find("підтверд",1,true)
                or lower:find("продолж",1,true) or lower:find("продовж",1,true) or lower:find("действительно",1,true)
                or lower:find("10000000",1,true) or lower:find("10.000.000",1,true)) then
                confirmationSent=true;stage="confirm";Electricity.stage=stage
                DialogGate.stageTo("electricity","electricity_confirm",{house=house.number})
                check(Electricity.respond(d,1,0,"",190),"Не вдалося підтвердити поповнення")

            else
                -- Compatibility fallback only if Arizona changes one of the menus.
                local row=Electricity.findNavigationRow(d,house.number,stage)
                if row==nil then
                    if amountSent and confirmationSent then break end
                    error("Неочікуване меню електроенергії · dialog "..tostring(d.id).." · stage "..tostring(stage),0)
                end
                stage=Electricity.nextStage(d,row,stage,house.number);Electricity.stage=stage
                check(Electricity.respond(d,1,row,"",190),"Не вдалося перейти до поповнення електроенергії")
            end
        end

        if not Electricity.result and amountSent then
            local untilAt=getGameTimer()+3500
            while getGameTimer()<untilAt and not Electricity.result do wait(0) end
        end
        check(Electricity.result=="paid","Банк не підтвердив поповнення рахунку будинку")
    end)

    Electricity.closeOwnedPhone()
    local result=Electricity.result
    Electricity.busy=false;Electricity.target=nil;Electricity.dialog=nil;Electricity.stage=nil
    Runtime.log("ELECTRICITY_DONE","house="..tostring(house.number).." result="..tostring(result).." error="..tostring(ok and nil or err))
    if DialogGate.owner=="electricity" then DialogGate.pop("electricity") end
    if not ok then
        if result=="insufficient" then return false,I18n.text("Недостатньо грошей для поповнення електроенергії") end
        return false,tostring(err)
    end
    local old=parseHouseMoney(house.currentMoney) or 0
    local max=parseHouseMoney(house.maxMoney) or 60000000
    house.currentMoney=tostring(math.min(max,old+AUTO_ELECTRICITY_AMOUNT))
    return true
end

function Electricity.scheduleCheck(force)
    force=force==true
    if (not Settings.autoElectricity and not force) or Electricity.checking or Electricity.busy then return false end
    if not Runtime.ready() or UI.collecting or UI.balanceUpdating or UI.scanning or UI.waiting or UI.loading or Taxes.busy or Runtime.foreignDialog() then return false end

    local knownGpuNumbers={}
    local function rememberGpuHouse(house,source)
        if not house then return end
        local number=tonumber(house.number)
        if not number then return end
        local gpus=type(house.gpus)=="table" and #house.gpus or 0
        local count=tonumber(house.gpuCount) or 0
        if count>=1 or gpus>=1 then
            knownGpuNumbers[number]=true
            Runtime.log("ELECTRICITY_GPU_EVIDENCE","house="..tostring(number).." source="..tostring(source).." gpuCount="..tostring(count).." gpus="..tostring(gpus))
        end
    end
    for _,house in ipairs(UI.houses or {}) do rememberGpuHouse(house,"ui_before_refresh") end
    for number in pairs(RateTracker.houses or {}) do
        number=tonumber(number)
        if number then knownGpuNumbers[number]=true end
    end
    for number,sample in pairs(MiningModel.samples or {}) do
        number=tonumber(number)
        if number and sample then knownGpuNumbers[number]=true end
    end

    local knownCount=0
    for _ in pairs(knownGpuNumbers) do knownCount=knownCount+1 end
    Runtime.log("ELECTRICITY_CHECK_CONTEXT","force="..tostring(force).." language="..tostring(Settings.language).." knownGpuBefore="..tostring(knownCount))

    if not requestHouses(true) then return false end
    Electricity.checking=true
    lua_thread.create(function()
        local ok,err=pcall(function()
            local deadline=os.time()+90
            while (UI.waiting or UI.scanning or UI.loading) and os.time()<deadline do wait(100) end
            if UI.waiting or UI.scanning or UI.loading then error("Не вдалося оновити список будинків",0) end

            local gpuHouses={}
            local added={}
            for _,house in ipairs(UI.houses or {}) do
                local number=tonumber(house.number)
                local gpus=type(house.gpus)=="table" and #house.gpus or 0
                local count=tonumber(house.gpuCount) or 0
                local fresh=(count>=1 or gpus>=1)
                local remembered=number and knownGpuNumbers[number] or false
                local ignored=number and isHouseIgnored(number) or false
                Runtime.log("ELECTRICITY_GPU_SCAN","house="..tostring(number).." status="..tostring(house.miningStatus).." scanned="..tostring(house.scanned).." gpuCount="..tostring(count).." gpus="..tostring(gpus).." remembered="..tostring(remembered).." ignored="..tostring(ignored))
                if number and (fresh or remembered) and not added[number] then
                    gpuHouses[#gpuHouses+1]=house
                    added[number]=true
                end
            end

            if #gpuHouses==0 then
                Journal.add("warning",I18n.text("Будинки з GPU не потребують поповнення"),"GPU detection returned 0")
                Runtime.log("ELECTRICITY_GPU_NONE","no fresh or remembered GPU evidence after scan")
                return
            end

            local settleUntil=getGameTimer()+1800
            while Runtime.foreignDialog() and getGameTimer()<settleUntil do wait(50) end
            if Runtime.foreignDialog() then error("Після перевірки будинків залишилося відкрите меню",0) end

            local bankBalances,balanceError=Electricity.fetchBankBalances()
            if not bankBalances then error("Не вдалося отримати актуальні баланси банку · "..tostring(balanceError),0) end

            local due={}
            for _,house in ipairs(gpuHouses) do
                local info=bankBalances[tonumber(house.number)]
                if info and info.balance~=nil then
                    house.currentMoney=tostring(info.balance)
                    Runtime.log("ELECTRICITY_BALANCE","house="..tostring(house.number).." balance="..tostring(info.balance).." due="..tostring(info.balance<=AUTO_ELECTRICITY_THRESHOLD))
                    if info.balance<=AUTO_ELECTRICITY_THRESHOLD then due[#due+1]=house end
                else
                    Runtime.log("ELECTRICITY_BALANCE_MISSING","house="..tostring(house.number))
                end
            end
            if #due==0 then
                Journal.add("system",I18n.text("Будинки з GPU не потребують поповнення"),"bank > "..formatWholeMoney(AUTO_ELECTRICITY_THRESHOLD))
                return
            end
            local paidCount,failedCount,totalPaid=0,0,0
            local paidNumbers,failedNumbers={},{}
            for i,house in ipairs(due) do
                if not Settings.autoElectricity and not force then break end
                UI.notice=I18n.text("Поповнюємо будинок").." №"..tostring(house.number).." · "..i.." / "..#due
                local done,why=Electricity.runHouse(house)
                if done then
                    paidCount=paidCount+1;totalPaid=totalPaid+AUTO_ELECTRICITY_AMOUNT;paidNumbers[#paidNumbers+1]=tostring(house.number)
                    pushActivity(I18n.text("Електроенергія поповнена"),"Будинок №"..tostring(house.number).." · +"..formatWholeMoney(AUTO_ELECTRICITY_AMOUNT),"green")
                    Journal.add("system",I18n.text("Електроенергія поповнена"),"№"..tostring(house.number).." · +"..formatWholeMoney(AUTO_ELECTRICITY_AMOUNT))
                else
                    failedCount=failedCount+1;failedNumbers[#failedNumbers+1]=tostring(house.number)
                    pushActivity(I18n.text("Не вдалося поповнити електроенергію"),"Будинок №"..tostring(house.number).." · "..tostring(why),"amber")
                    Journal.add("warning",I18n.text("Не вдалося поповнити електроенергію"),"№"..tostring(house.number).." · "..tostring(why))
                end
                wait(500)
            end
            if paidCount>0 then
                local uk=paidCount==1 and ("Електроенергію поповнено - будинок №"..paidNumbers[1].." - "..formatWholeMoney(totalPaid))
                    or ("Електроенергію поповнено - "..paidCount.." будинки - "..formatWholeMoney(totalPaid))
                local ru=paidCount==1 and ("Электроэнергия пополнена - дом №"..paidNumbers[1].." - "..formatWholeMoney(totalPaid))
                    or ("Электроэнергия пополнена - домов: "..paidCount.." - "..formatWholeMoney(totalPaid))
                Notify.rawLocalized("electricity",uk,ru,"electricity_summary:"..table.concat(paidNumbers,","),3)
            end
            if failedCount>0 then
                Notify.rawLocalized("critical",
                    "Не вдалося поповнити електроенергію - будинків: "..failedCount,
                    "Не удалось пополнить электроэнергию - домов: "..failedCount,
                    "electricity_failed_summary:"..table.concat(failedNumbers,","),8)
            end
        end)
        if not force then
            Settings.nextElectricityCheck=os.time()+AUTO_ELECTRICITY_INTERVAL
            saveSettings()
        end
        Electricity.checking=false;UI.notice=nil
        if not ok then
            Runtime.log("ELECTRICITY_CHECK_ERROR",tostring(err))
            if not force then
                Notify.rawLocalized("critical","Не вдалося перевірити електроенергію","Не удалось проверить электроэнергию","electricity_check_error",15)
            end
        end
    end)
    return true
end

function Taxes.run(force)
    if not Settings.autoTaxes and not force then return false,"disabled" end
    if not Taxes.bridge or type(Taxes.bridge.send)~="function" then
        Journal.add("warning","Податки не перевірено","Бібліотека телефону недоступна")
        return false,"Бібліотека телефону недоступна"
    end
    if Runtime.foreignDialog() or Taxes.cursorOpen then
        Journal.add("warning","Податки не перевірено","Відкрите інше меню")
        return false,"Відкрите інше меню"
    end
    DialogGate.push("taxes","tax_start",{})
    Taxes.busy=true;Taxes.direct=true;Taxes.dialog=nil;Taxes.result=nil;Taxes.abort=nil;Taxes.amount=nil
    Taxes.phoneSeen=false;Taxes.phoneOwned=false;Taxes.phoneClosed=false;Taxes.paymentRequested=false;Taxes.closeRequested=false
    UI.collect.stage="Оплата податків"
    Runtime.log("TAX_START","direct phone bank")
    local ok,err=pcall(function()
        local function check(value,message) if not value then error(message,0) end end
        sampSendChat("/phone")
        check(Taxes.await(function()return Taxes.phoneSeen end,8000),"Телефон не відкрився")
        Taxes.openBank()
        if Taxes.phoneOwned and not Taxes.phoneClosed then
            Taxes.closeRequested=true;sampSendChat("/phone")
        end
        check(Taxes.await(function()return Taxes.dialog~=nil or Taxes.result~=nil end,8000),"Банківське меню не відкрилося")
        local paymentSent,confirmationSent=false,false
        local deadline=os.time()+20
        local visited={}
        while not Taxes.result and os.time()<deadline do
            check(Taxes.await(function()return Taxes.dialog~=nil or Taxes.result~=nil end,6500),"Банк не відповів")
            if Taxes.result then break end
            local d=Taxes.dialog;Taxes.dialog=nil
            local lower=lowerServerText(d.title.." "..d.text)
            local key=tostring(d.id).."|"..d.text
            check(not visited[key],"Банк повторив меню. Оплату зупинено");visited[key]=true
            if d.row~=nil and not paymentSent then
                paymentSent=true;Taxes.paymentRequested=true
                DialogGate.stageTo("taxes","tax_pay",{});DialogGate.tx("taxes",d.id,1,d.row,"",165,"tax_pay")
            elseif paymentSent and not confirmationSent and d.style==0
                and (lower:find("налог",1,true) or lower:find("подат",1,true))
                and (lower:find("подтвер",1,true) or lower:find("хотите",1,true) or lower:find("підтвер",1,true))
                and (lowerServerText(d.button):find("оплат",1,true) or lowerServerText(d.button):find("сплат",1,true)) then
                confirmationSent=true;DialogGate.stageTo("taxes","tax_confirm",{});DialogGate.tx("taxes",d.id,1,0,"",165,"tax_confirm")
            elseif not paymentSent then
                local found=nil
                for row,line in pairs(Taxes.lines(d.text,d.style)) do
                    local t=Taxes.lowerUtf8(line)
                    if t:find("банковские дела",1,true) or t:find("банківські справи",1,true)
                        or t:find("управление счетом",1,true) or t:find("керування рахунком",1,true) then found=row;break end
                end
                check(found~=nil,"Пункт оплати податків не знайдено")
                DialogGate.stageTo("taxes","tax_navigation",{});DialogGate.tx("taxes",d.id,1,found,"",165,"tax_navigation")
            else error("Результат оплати не підтверджено. Повторну оплату не надсилаємо.",0) end
        end
        check(Taxes.result~=nil,"Результат оплати не підтверджено. Повторну оплату не надсилаємо.")
    end)
    -- Only close the phone opened by this operation. Never confirm a residual menu.
    if not Taxes.abort and Taxes.dialog and Runtime.ready() then
        pcall(DialogGate.tx,"taxes",Taxes.dialog.id,0,0,"",140,"tax_close_dialog");Taxes.dialog=nil
    end
    if Taxes.phoneOwned and not Taxes.phoneClosed and not Taxes.closeRequested and not Taxes.abort and Runtime.ready() then
        local serial=Taxes.cursorSerial or 0
        local closed,closeErr=pcall(function()
            sampSendChat("/phone")
            if not Taxes.await(function()return Taxes.phoneClosed or ((Taxes.cursorSerial or 0)>serial and Taxes.cursorOpen==false) end,5000) then
                error("Закриття телефону не підтверджено",0)
            end
        end)
        if not closed then Runtime.log("TAX_CLOSE_ERROR",closeErr) end
    end
    Taxes.busy=false;Taxes.direct=false
    Runtime.log("TAX_DONE","result="..tostring(Taxes.result).." error="..tostring(ok and nil or err))
    if DialogGate.owner=="taxes" then DialogGate.pop("taxes") end
    if not ok then
        Journal.add("warning","Податки не перевірено",tostring(err))
        return false,tostring(err)
    elseif Taxes.result=="insufficient" then
        Journal.add("warning","Бракує грошей на податки","BTC зібрано; податки залишилися несплаченими")
        return false,"insufficient"
    elseif Taxes.result=="none" then
        Journal.add("system","Податків до сплати немає","Перевірено після збору BTC")
        return true,"none"
    else
        Journal.add("system","Податки сплачено",Taxes.amount and (Taxes.amount.." $") or "Оплату підтвердив сервер")
        return true,Taxes.result or "paid"
    end
end


function sampev.onShowDialog(dialogId, style, title, button1, button2, text)
    Runtime.passwordNotice=nil
    Runtime.authDialog=nil
    DialogGate.noteRx(dialogId,title)

    local dialogText=lowerServerText((title or "").." "..(text or ""))
    local noAvailableHouses = dialogId==0
        and dialogText:find("выбор дома",1,true)
        and dialogText:find("нет доступных домов для просмотра",1,true)
    local autoMinerOwned = UI.waiting or UI.scanning or UI.collecting or UI.balanceUpdating
        or (DialogGate.owner and DialogGate.owner~="none")
        or (Electricity and Electricity.busy) or (Taxes and Taxes.busy)
        or (Maintenance and Maintenance.busy) or (AutoRefill and AutoRefill.active)
    if noAvailableHouses and autoMinerOwned then
        Runtime.log("NO_HOUSES_DIALOG_HIDDEN","owner="..tostring(DialogGate.owner).." stage="..tostring(DialogGate.stage))
        if UI.waiting then
            UI.waiting=false;UI.loading=false;UI.dialogCaptured=false;UI.houses={}
            Runtime.dataReady=true
            UI.error=Settings.language=="ru" and "Нет доступных домов для просмотра." or "Немає доступних будинків для перегляду."
        end
        if UI.scanning or DialogGate.owner=="scan" then
            UI.scanFailureReason=Settings.language=="ru" and "Нет доступных домов для просмотра" or "Немає доступних будинків для перегляду"
            UI.scanHouseSerial=(UI.scanHouseSerial or 0)+1
            UI.scanHouseDialogReady=false
        end
        if UI.collecting or UI.balanceUpdating or DialogGate.owner=="collect" then
            CollectFlow.failure=Settings.language=="ru" and "Нет доступных домов для просмотра" or "Немає доступних будинків для перегляду"
        end
        if Maintenance and (Maintenance.busy or DialogGate.owner=="maintenance") then
            Maintenance.remoteError=Settings.language=="ru" and "Нет доступных домов для просмотра" or "Немає доступних будинків для перегляду"
            Maintenance.awaitRemote=false
        end
        return false
    end

    local authText=dialogText
    if style==3 or authText:find("авторизац",1,true) or authText:find("регистрац",1,true)
        or authText:find("введите пароль",1,true) or authText:find("введіть пароль",1,true)
        or authText:find("выбор персонажа",1,true) or authText:find("вибір персонажа",1,true) then
        Runtime.authDialog=dialogId
        Runtime.log("AUTH_DIALOG","id="..tostring(dialogId))
        return
    end

    if DialogGate.owner=="electricity" or Electricity.busy then
        -- Never answer electricity from this SAMP callback. Publishing the dialog
        -- to the worker thread avoids duplicate responses and stale-selector races.
        Electricity.onDialog(dialogId,style,title,button1,button2,text)
        return false
    end

    if DialogGate.owner=="taxes" or Taxes.busy then
        Taxes.onDialog(dialogId,style,title,button1,button2,text)
        return false
    end

    if DialogGate.owner=="collect" or UI.collecting or UI.balanceUpdating then
        MiningModel.observe((title or "").."\n"..(text or ""))
        local fingerprint=tostring(dialogId).."|"..(title or "").."|"..(text or "")
        local isPrompt=UI.collecting and CollectFlow.isWithdrawalPrompt(title,text,button1)
        if isPrompt and CollectFlow.confirmSent and fingerprint==CollectFlow.confirmFingerprint then return false end
        local confirmation=isPrompt and CollectFlow.withdrawing
        local known=(dialogId==DIALOG_HOUSE and #parseHouses(text)>0)
            or (dialogId==DIALOG_MINER_LIST and (#CollectFlow.rows(text,style)>0
                or (lowerServerText(title):find("видеокарт",1,true) and tostring(text):find("|",1,true))))
            or (dialogId==25244 and lowerServerText((title or "").." "..(text or "")):find("видеокарт",1,true))
        local expected=CollectFlow.expected
        if not confirmation and not (known and (not expected or expected==dialogId
            or (CollectFlow.confirmSent and (dialogId==25244 or dialogId==DIALOG_MINER_LIST)))) then
            CollectFlow.failure="Надійшло неочікуване меню"
            DialogGate.log("REJECTED","dialog="..tostring(dialogId).." expected="..tostring(expected))
            return
        end
        CollectFlow.serial=(CollectFlow.serial or 0)+1
        CollectFlow.id=dialogId;CollectFlow.text=text or "";CollectFlow.style=style;CollectFlow.title=title or ""
        CollectFlow.expected=nil
        DialogGate.log("COLLECT_RX","dialog="..tostring(dialogId))
        if confirmation and not CollectFlow.confirmSent then
            local prompt=lowerServerText(text)
            local amount=prompt:match("только%s+(%d+)%s*btc") or prompt:match("лише%s+(%d+)%s*btc")
            CollectFlow.confirmAmount=tonumber(amount)
            CollectFlow.confirmation={id=dialogId,fingerprint=fingerprint}
            return false
        end
        if dialogId==DIALOG_HOUSE or dialogId==DIALOG_MINER_LIST or dialogId==25244 then return false end
        CollectFlow.failure=UI.balanceUpdating and "Оновлення відкладено: відкрите інше меню"
            or "Відкрилося стороннє меню — збір зупинено"
        return
    end

    if DialogGate.owner=="maintenance" or Maintenance.busy then
        if dialogId==DIALOG_HOUSE then
            if Maintenance.pendingHouse then
                local house=Maintenance.pendingHouse;local row=nil
                for _,fresh in ipairs(parseHouses(text)) do
                    if tostring(fresh.number)==tostring(house.number) then
                        row=fresh.row
                        for _,key in ipairs({"row","city","tax","cycles","currentMoney","maxMoney"}) do house[key]=fresh[key] end
                        break
                    end
                end
                Maintenance.pendingHouse=nil
                if row==nil then Maintenance.remoteError="Будинок відсутній у списку сервера";Maintenance.awaitRemote=false;return false end
                local generation=Runtime.generation;local houseNo=house.number
                DialogGate.stageTo("maintenance","select_house",{house=houseNo})
                lua_thread.create(function()
                    DialogGate.safeDelay(DIALOG_HOUSE,190)
                    if Maintenance.busy and generation==Runtime.generation and Runtime.ready() then
                        DialogGate.tx("maintenance",DIALOG_HOUSE,1,row,"",0,"select_house")
                    end
                end)
                return false
            elseif Maintenance.closingHouse then
                local generation=Runtime.generation
                lua_thread.create(function()
                    DialogGate.safeDelay(DIALOG_HOUSE,170)
                    if Maintenance.closingHouse and generation==Runtime.generation and Runtime.ready() then
                        DialogGate.tx("maintenance",DIALOG_HOUSE,0,0,"",0,"close_house_selector")
                        wait(120);Maintenance.houseClosed=true
                    end
                end)
                return false
            end
        end
        if View.captureBasement(dialogId,style,title,button1,button2,text)==false then return false end
        Maintenance.remoteError=Maintenance.remoteError or ("Надійшло неочікуване меню "..tostring(dialogId))
        return false
    end

    if DialogGate.owner=="autorefill" or AutoRefill.active then
        if View.captureBasement(dialogId,style,title,button1,button2,text)==false then return false end
        return
    end

    if DialogGate.owner=="scan" or UI.scanning then
        if dialogId==DIALOG_HOUSE then
            UI.scanHouseSerial=UI.scanHouseSerial+1;UI.scanHouseDialogReady=true;return false
        end
        if dialogId==DIALOG_MINER_LIST then UI.scanMinerText=text or "";return false end
        return
    end

    if View.captureBasement(dialogId,style,title,button1,button2,text)==false then return false end

    if Runtime.isPasswordNotice(style,title,text) then
        Runtime.passwordNotice={id=dialogId,time=os.time()};Runtime.log("PASSWORD_NOTICE","id="..dialogId);return
    end
    if Taxes.recording and Taxes.onDialog(dialogId,style,title,button1,button2,text)==false then return false end
    MiningModel.observe((title or "").."\n"..(text or ""))

    if dialogId==DIALOG_HOUSE then
        if UI.pendingUserHouse then
            local house=UI.pendingUserHouse;UI.pendingUserHouse=nil
            lua_thread.create(function()
                DialogGate.safeDelay(DIALOG_HOUSE,170)
                if Runtime.ready() then DialogGate.tx(nil,DIALOG_HOUSE,1,house.row,"",0,"manual_select_house") end
            end)
            return false
        end
        if not UI.waiting then return end
        UI.dialogCaptured=true;UI.houses=parseHouses(text)
        if Runtime.replacingNotice and #UI.houses>0 then
            Runtime.phoneOpen=false;Runtime.cefCursor=false;Taxes.cursorOpen=false;Runtime.replacingNotice=nil
            Runtime.log("PASSWORD_NOTICE_REPLACED","houses="..#UI.houses)
        end
        UI.loading=false;UI.waiting=false;UI.error=nil;UI.positionApplied=false
        if not UI.backgroundRequest then UI.open[0]=true end
        if #UI.houses==0 then UI.error="Сервер не повернув список будинків."
        else scanAvailableHouses() end
        return false
    end
end

