local ServerMessageFilter={}
function ServerMessageFilter.shouldHide(text)
    local lower=lowerServerText(text)
    if Electricity.busy then
        local electricity=lower:find("электр",1,true) or lower:find("електр",1,true)
        local choose=lower:find("выберите дом",1,true) or lower:find("виберіть будинок",1,true)
        local topup=lower:find("попол",1,true) or lower:find("поповн",1,true)
        local success=lower:find("успешно пополнили",1,true) or lower:find("успішно поповнили",1,true)
            or lower:find("счёт дома за электроэнергию",1,true) or lower:find("рахунок будинку за електроенергію",1,true)
        if electricity and ((choose and topup) or success) then return true,"electricity" end
    end
    if UI.scanning and UI.scanAttemptActive then
        local reason=miningFailureReason(text)
        if reason then return true,"scan:"..tostring(reason) end
    end
    return false
end

function sampev.onServerMessage(color, text)
    Electricity.onMessage(text)
    Taxes.onMessage(text)
    local suppress,suppressReason=ServerMessageFilter.shouldHide(text)
    if suppress then Runtime.log("SERVER_MESSAGE_HIDDEN",tostring(suppressReason),2);return false end
    local rawServerText=stripColors(tostring(text or ""))
    if UI.collecting then
        local ascii=rawServerText:gsub("[%z\1-\31]"," ")
        local asciiLower=ascii:lower()
        if asciiLower:find("bitcoin",1,true) and asciiLower:find("btc",1,true) then
            return false
        end
    end

    MiningModel.observe(text)
    if UI.collecting or UI.balanceUpdating then
        local clean=lowerServerText(text)
        if clean:find("выводить прибыль можно только целыми частями",1,true)
            or clean:find("минимум 1 целый коин",1,true) then CollectFlow.tooLow=true end
        CollectFlow.failure=miningFailureReason(text) or CollectFlow.failure
    end
    if UI.scanning and UI.scanAttemptActive and UI.scanMinerText == nil then
        local scanReason=miningFailureReason(text)
        UI.scanFailureReason = scanReason or UI.scanFailureReason
        if scanReason then
            Runtime.log("SCAN_SERVER_MESSAGE_HIDDEN","reason="..tostring(scanReason).." text="..tostring(stripColors(text)),5)
            return false
        end
    end
    local clean=serverToUtf8(stripColors(text)):gsub("^%s+",""):gsub("%s+$","")
    local active=UI.collecting or UI.balanceUpdating or UI.scanning or UI.waiting or UI.pendingUserHouse
    if active and clean=="[Информация] Выберите дом с майнинг фермой" then return false end
    local now=getGameTimer()
    local credit=CollectFlow.inventoryCredit
    if not UI.collecting or (credit and (credit.token~=UI.collect.token or now-credit.time>3500 or now<credit.time)) then
        CollectFlow.inventoryCredit=nil
        credit=nil
    end
    if UI.collecting and CollectFlow.withdrawing then
        local btcCount=0
        for _ in rawServerText:gmatch("BTC") do btcCount=btcCount+1 end
        if btcCount>=2 then
            CollectFlow.inventoryCredit={time=now,token=UI.collect.token}
            return false
        end
    end
    if UI.collecting and credit then
        if clean:find("В инвентарь добавлен предмет:",1,true) then
            CollectFlow.inventoryCredit=nil
            return false
        end
    end
end

local function selectHouse(house)
    if not house or UI.balanceUpdating or UI.collecting or UI.scanning or UI.waiting or house.miningStatus == "unavailable"
        or house.miningStatus == "unknown" or house.miningStatus == "checking" then
        return
    end

    UI.open[0] = false
    UI.waiting = false
    UI.dialogCaptured = false
    UI.pendingUserHouse = house
    UI.pendingUserDeadline=os.time()+6

    sampSendChat("/flashminer")
end

local function closeMenu()
    UI.open[0] = false
    UI.waiting = false
    UI.closing=false
    if not UI.scanning and not UI.collecting and not UI.balanceUpdating then cancelCapturedDialog() end
end

function View.requestMainClose()
    if not UI.open[0] or UI.closing then return end
    UI.closing=true;UI.closeStarted=getGameTimer();UI.windowDragging=false
end

function View.requestIncomeLogClose()
    if not IncomeLogUI.open or IncomeLogUI.closing then return end
    IncomeLogUI.closing=true;IncomeLogUI.closeStarted=getGameTimer()
end

function View.requestBasementClose()
    local state=View.basement
    if not state.open[0] or state.closing or state.busy then return end
    state.actionPanelOpen=false;state.pending=nil;state.empty=nil;state.confirm=nil;state.refillConfirm=nil
    state.closing=true;state.closeStarted=getGameTimer()
end

function View.anyScriptWindowVisible()
    local state=View.basement
    return UI.open[0] or UI.closing or IncomeLogUI.open or IncomeLogUI.closing or state.open[0] or state.closing
end

function View.handleEscape()
    local state=View.basement
    if AutoRefill and AutoRefill.active and not (state.open[0] or state.closing) then
        AutoRefill.stop("Автозаправку зупинено",true)
        return true
    end
    if IncomeLogUI.open or IncomeLogUI.closing then View.requestIncomeLogClose();return true end
    if state.open[0] or state.closing then
        if state.busy then return true end
        if state.refillConfirm then state.refillConfirm=nil;return true end
        if state.confirm then state.confirm=nil;return true end
        if state.actionPanelOpen then View.closeSingleShelfPanel();return true end
        View.requestBasementClose();return true
    end
    if UI.open[0] or UI.closing then View.requestMainClose();return true end
    return false
end


function View.drawText(x, y, text, font, color)
    text=I18n.text(text)
    font=resolveTextFont(font)
    local dl = imgui.GetWindowDrawList()

    if font then
        imgui.PushFont(font)
    end

    dl:AddText(
        imgui.ImVec2(math.floor(x+.5), math.floor(y+.5)),
        u32(color or P.text),
        tostring(text or "")
    )

    if font then
        imgui.PopFont()
    end
end


function View.drawTextAlpha(x, y, text, font, color, alpha)
    text=I18n.text(text)
    font=resolveTextFont(font)
    local dl = imgui.GetWindowDrawList()

    if font then
        imgui.PushFont(font)
    end

    dl:AddText(
        imgui.ImVec2(math.floor(x+.5), math.floor(y+.5)),
        u32(color or P.text, alpha or 1.0),
        tostring(text or "")
    )

    if font then
        imgui.PopFont()
    end
end

function View.calcText(text, font)
    text=I18n.text(text)
    font=resolveTextFont(font)
    if font then imgui.PushFont(font) end
    local s = imgui.CalcTextSize(tostring(text or ""))
    if font then imgui.PopFont() end
    return s
end

local RollingText={}
function View.drawRollingText(id,x,y,text,font,color)
    if Settings.animations=="off" then View.drawText(x,y,text,font,color);RollingText[id]=nil;return end
    local now=getGameTimer()
    local r=RollingText[id]
    if not r then r={text=text};RollingText[id]=r end
    r.pending=text
    if not r.started and r.text~=r.pending then
        r.previous=r.text;r.text=r.pending;r.started=now
    end
    local height=View.calcText("Ag",font).y+4
    local dl=imgui.GetWindowDrawList()
    local width=math.max(View.calcText(r.text,font).x,View.calcText(r.previous or "",font).x)+4
    dl:PushClipRect(imgui.ImVec2(x-2,y-2),imgui.ImVec2(x+width,y+height),true)
    if r.started then
        local t=math.max(0,math.min(1,(now-r.started)/360))
        local e=t*t*(3-2*t)
        View.drawTextAlpha(x,y-e*height,r.previous,font,color,1-e)
        View.drawTextAlpha(x,y+(1-e)*height,r.text,font,color,e)
        if t>=1 then r.started=nil;r.previous=nil end
    else View.drawText(x,y,r.text,font,color) end
    dl:PopClipRect()
end

function View.drawHouseOutline(x, y, size, color, alpha, lift)
    local dl = imgui.GetWindowDrawList()
    local c = u32(color or P.text, alpha or 0.95)
    local ox = x
    local oy = y - (lift or 0)

    local left = ox + size * 0.22
    local right = ox + size * 0.78
    local top = oy + size * 0.18
    local roofY = oy + size * 0.45
    local bottom = oy + size * 0.80
    local cx = ox + size * 0.50

    local thick = math.max(2.0, size * 0.034)

    dl:AddLine(
        imgui.ImVec2(left, roofY),
        imgui.ImVec2(cx, top),
        c,
        thick
    )
    dl:AddLine(
        imgui.ImVec2(cx, top),
        imgui.ImVec2(right, roofY),
        c,
        thick
    )

    dl:AddLine(
        imgui.ImVec2(left + size * 0.035, roofY - size * 0.015),
        imgui.ImVec2(left + size * 0.035, bottom),
        c,
        thick
    )
    dl:AddLine(
        imgui.ImVec2(right - size * 0.035, roofY - size * 0.015),
        imgui.ImVec2(right - size * 0.035, bottom),
        c,
        thick
    )
    dl:AddLine(
        imgui.ImVec2(left + size * 0.035, bottom),
        imgui.ImVec2(right - size * 0.035, bottom),
        c,
        thick
    )

    local doorW = size * 0.17
    local doorH = size * 0.25
    local doorX1 = cx - doorW * 0.5
    local doorY1 = bottom - doorH
    local doorX2 = cx + doorW * 0.5
    dl:AddRect(
        imgui.ImVec2(doorX1, doorY1),
        imgui.ImVec2(doorX2, bottom),
        c,
        size * 0.025,
        0,
        thick * 0.78
    )

    local chimneyX1 = ox + size * 0.66
    local chimneyX2 = ox + size * 0.72
    local chimneyY1 = oy + size * 0.21
    local chimneyY2 = oy + size * 0.34
    dl:AddLine(imgui.ImVec2(chimneyX1, chimneyY2), imgui.ImVec2(chimneyX1, chimneyY1), c, thick * 0.80)
    dl:AddLine(imgui.ImVec2(chimneyX1, chimneyY1), imgui.ImVec2(chimneyX2, chimneyY1), c, thick * 0.80)
    dl:AddLine(imgui.ImVec2(chimneyX2, chimneyY1), imgui.ImVec2(chimneyX2, chimneyY2), c, thick * 0.80)
end


function View.isArizonaSprings(house)
    local number = tonumber(house and house.number) or 0
    return number >= 1900 and number <= 1950
end

function View.getHouseCity(house)
    if View.isArizonaSprings(house) then
        return "Arizona Springs"
    end

    local city = tostring(house and house.city or "")
    if city == "" then
        return "-"
    end

    return city
end


function View.formatBtc(value)
    value = tonumber(value)
    if not value then
        return "— BTC"
    end

    if value >= 100 then
        return string.format("%.2f BTC", value)
    elseif value >= 10 then
        return string.format("%.2f BTC", value)
    end

    return string.format("%.3f BTC", value)
end

function View.drawDiamond(cx, cy, size, color, alpha)
    local dl = imgui.GetWindowDrawList()
    local c = u32(color, alpha or 1.0)
    local w = size
    local h = size * 0.72

    dl:AddLine(imgui.ImVec2(cx - w * 0.5, cy - h * 0.15), imgui.ImVec2(cx - w * 0.25, cy - h * 0.5), c, 1.6)
    dl:AddLine(imgui.ImVec2(cx - w * 0.25, cy - h * 0.5), imgui.ImVec2(cx + w * 0.25, cy - h * 0.5), c, 1.6)
    dl:AddLine(imgui.ImVec2(cx + w * 0.25, cy - h * 0.5), imgui.ImVec2(cx + w * 0.5, cy - h * 0.15), c, 1.6)
    dl:AddLine(imgui.ImVec2(cx + w * 0.5, cy - h * 0.15), imgui.ImVec2(cx, cy + h * 0.5), c, 1.6)
    dl:AddLine(imgui.ImVec2(cx, cy + h * 0.5), imgui.ImVec2(cx - w * 0.5, cy - h * 0.15), c, 1.6)
    dl:AddLine(imgui.ImVec2(cx - w * 0.5, cy - h * 0.15), imgui.ImVec2(cx + w * 0.5, cy - h * 0.15), c, 1.2)
    dl:AddLine(imgui.ImVec2(cx - w * 0.25, cy - h * 0.5), imgui.ImVec2(cx, cy + h * 0.5), c, 1.1)
    dl:AddLine(imgui.ImVec2(cx + w * 0.25, cy - h * 0.5), imgui.ImVec2(cx, cy + h * 0.5), c, 1.1)
end


function View.drawVillaOutline(x, y, w, h, color, alpha)
    local dl = imgui.GetWindowDrawList()
    local c = u32(color, alpha or 0.94)
    local faint = u32(color, (alpha or 0.94) * 0.46)
    local thick = math.max(1.5, w * 0.006)

    local baseY = y + h * 0.84
    local groundY = y + h * 0.90

    local cx1 = x + w * 0.31
    local cx2 = x + w * 0.72
    local topY = y + h * 0.27

    dl:AddLine(imgui.ImVec2(cx1, topY), imgui.ImVec2(cx2, topY), c, thick)
    dl:AddLine(imgui.ImVec2(cx1, topY), imgui.ImVec2(cx1, baseY), c, thick)
    dl:AddLine(imgui.ImVec2(cx2, topY), imgui.ImVec2(cx2, baseY), c, thick)

    local l1 = x + w * 0.08
    local l2 = x + w * 0.34
    local lroof = y + h * 0.43
    dl:AddLine(imgui.ImVec2(l1, lroof), imgui.ImVec2(x + w * 0.20, y + h * 0.34), c, thick)
    dl:AddLine(imgui.ImVec2(x + w * 0.20, y + h * 0.34), imgui.ImVec2(l2, lroof), c, thick)
    dl:AddLine(imgui.ImVec2(l1 + w * 0.018, lroof), imgui.ImVec2(l1 + w * 0.018, baseY), c, thick)
    dl:AddLine(imgui.ImVec2(l2 - w * 0.010, lroof), imgui.ImVec2(l2 - w * 0.010, baseY), c, thick)

    local r1 = x + w * 0.68
    local r2 = x + w * 0.93
    local rroof = y + h * 0.45
    dl:AddLine(imgui.ImVec2(r1, rroof), imgui.ImVec2(x + w * 0.80, y + h * 0.35), c, thick)
    dl:AddLine(imgui.ImVec2(x + w * 0.80, y + h * 0.35), imgui.ImVec2(r2, rroof), c, thick)
    dl:AddLine(imgui.ImVec2(r2 - w * 0.018, rroof), imgui.ImVec2(r2 - w * 0.018, baseY), c, thick)

    dl:AddLine(imgui.ImVec2(x + w * 0.07, baseY), imgui.ImVec2(x + w * 0.94, baseY), c, thick)
    dl:AddLine(imgui.ImVec2(x + w * 0.03, groundY), imgui.ImVec2(x + w * 0.97, groundY), faint, 1.2)

    local doorX1 = x + w * 0.465
    local doorX2 = x + w * 0.555
    local doorTop = y + h * 0.54
    dl:AddLine(imgui.ImVec2(doorX1, baseY), imgui.ImVec2(doorX1, doorTop + h * 0.055), c, 1.55)
    dl:AddLine(imgui.ImVec2(doorX2, baseY), imgui.ImVec2(doorX2, doorTop + h * 0.055), c, 1.55)
    local archCx = (doorX1 + doorX2) * 0.5
    local archCy = doorTop + h * 0.055
    local archRx = (doorX2 - doorX1) * 0.5
    local archRy = h * 0.080
    local prevX = doorX1
    local prevY = archCy
    for i = 1, 14 do
        local t = i / 14
        local a = math.pi - math.pi * t
        local ax = archCx + math.cos(a) * archRx
        local ay = archCy - math.sin(a) * archRy
        dl:AddLine(imgui.ImVec2(prevX, prevY), imgui.ImVec2(ax, ay), c, 1.55)
        prevX = ax
        prevY = ay
    end

    for _, px in ipairs({0.355, 0.585}) do
        local wx1 = x + w * px
        local wx2 = wx1 + w * 0.060
        local wy1 = y + h * 0.43
        local wy2 = y + h * 0.61
        dl:AddRect(imgui.ImVec2(wx1, wy1), imgui.ImVec2(wx2, wy2), c, 3.0, 0, 1.25)
        dl:AddLine(imgui.ImVec2(wx1, wy1 + h * 0.085), imgui.ImVec2(wx2, wy1 + h * 0.085), faint, 1.0)
    end

    for _, px in ipairs({0.125, 0.235, 0.755, 0.855}) do
        local wx1 = x + w * px
        local wx2 = wx1 + w * 0.050
        local wy1 = y + h * 0.57
        local wy2 = y + h * 0.71
        dl:AddRect(imgui.ImVec2(wx1, wy1), imgui.ImVec2(wx2, wy2), faint, 2.0, 0, 1.05)
    end

    dl:AddRect(
        imgui.ImVec2(x + w * 0.61, y + h * 0.13),
        imgui.ImVec2(x + w * 0.66, topY),
        c,
        1.5,
        0,
        1.35
    )

    for i = 0, 2 do
        local yy = baseY + i * h * 0.025
        local inset = w * (0.040 - i * 0.007)
        dl:AddLine(
            imgui.ImVec2(x + w * 0.43 - inset, yy),
            imgui.ImVec2(x + w * 0.59 + inset, yy),
            faint,
            1.0
        )
    end

    local function palm(px, py, s)
        local pc = faint
        dl:AddLine(imgui.ImVec2(px, py), imgui.ImVec2(px + s * 0.08, py - s * 0.52), pc, 1.15)
        local tx = px + s * 0.08
        local ty = py - s * 0.52
        dl:AddLine(imgui.ImVec2(tx, ty), imgui.ImVec2(tx - s * 0.22, ty - s * 0.10), pc, 1.0)
        dl:AddLine(imgui.ImVec2(tx, ty), imgui.ImVec2(tx + s * 0.24, ty - s * 0.08), pc, 1.0)
        dl:AddLine(imgui.ImVec2(tx, ty), imgui.ImVec2(tx - s * 0.17, ty + s * 0.03), pc, 1.0)
        dl:AddLine(imgui.ImVec2(tx, ty), imgui.ImVec2(tx + s * 0.18, ty + s * 0.05), pc, 1.0)
    end

    palm(x + w * 0.035, groundY, h * 0.36)
    palm(x + w * 0.955, groundY, h * 0.31)
end

