    local hovered = imgui.IsItemHovered()

    dl:AddCircleFilled(
        imgui.ImVec2(x + 17, y + 17),
        16,
        u32(hovered and {.092,.099,.116,1} or {.034,.038,.046,1},.96),
        48
    )

