function View.drawLocationPin(cx, cy, size, color)
    local dl = imgui.GetWindowDrawList()
    local c = u32(color or P.gold, 0.98)
    dl:AddCircleFilled(imgui.ImVec2(cx, cy - size * 0.16), size * 0.30, c, 32)
    dl:AddTriangleFilled(
        imgui.ImVec2(cx - size * 0.21, cy + size * 0.01),
        imgui.ImVec2(cx + size * 0.21, cy + size * 0.01),
        imgui.ImVec2(cx, cy + size * 0.43),
        c
    )
    dl:AddCircleFilled(imgui.ImVec2(cx, cy - size * 0.16), size * 0.105, u32(P.card, 1.0), 24)
end

function View.drawSpringsVillaImage(x, y, w, h, alpha)
    if not Textures.springsVilla then return false end
    local dl = imgui.GetWindowDrawList()
    local ok = pcall(function()
        dl:AddImage(
            Textures.springsVilla,
            imgui.ImVec2(x, y),
            imgui.ImVec2(x + w, y + h),
            imgui.ImVec2(0, 0),
            imgui.ImVec2(1, 1),
            u32({1,1,1,1}, alpha or 1.0)
        )
    end)
    return ok
end

function View.drawEliteBadge(x, y, w, h, scale)
    local dl = imgui.GetWindowDrawList()
    drawTexture(Textures.eliteBadge, x, y, w, h, {1,1,1,1}, 1.0)
    local bx, by = x + w * (11.5 / 257), y + h * (11 / 102)
    local bw, bh = w * (233 / 257), h * (79 / 102)
    if not Textures.eliteBadge then
        dl:AddRectFilled(imgui.ImVec2(bx,by),imgui.ImVec2(bx+bw,by+bh),u32({0.022,0.092,0.060,1}),bh*.5)
    end
    dl:AddRect(imgui.ImVec2(bx,by),imgui.ImVec2(bx+bw,by+bh),u32({0.32,0.87,0.52,1},.82),bh*.5,nil,math.max(.85,scale))
    local color = u32({0.58,0.98,0.71,1})
    local function path(points, closed, thickness)
        dl:PathClear()
        for _, pt in ipairs(points) do dl:PathLineTo(imgui.ImVec2(x+w*pt[1]/257,y+h*pt[2]/102)) end
        dl:PathStroke(color, closed, thickness * scale)
    end
    path({{48,46},{58,34},{84,34},{94,46},{71,70}},true,1.25)
    path({{48,46},{94,46}},false,1.0)
    path({{58,34},{62,46},{71,70},{80,46},{84,34}},false,1.0)
    path({{62,46},{71,34},{80,46}},false,1.0)
    local textSize = View.calcText("ELITE", Fonts.elite)
    View.drawText(x+w*.455,y+h*.505-textSize.y*.5,"ELITE",Fonts.elite,{.64,.95,.74,1})
end

function View.drawArchitectBadge(cx,cy,size,hovered)
    local dl=imgui.GetWindowDrawList()
    local r=size*.5
    local hoverT=smoothAnim("architect_badge_hover_"..tostring(View.architectHouse or "current"),hovered and 1 or 0,14)
    local breathe=Settings.animations=="full" and (.5+.5*math.sin(getGameTimer()/1250)) or .35
    local glow=.035+.018*breathe+.022*hoverT
    dl:AddCircleFilled(imgui.ImVec2(cx,cy),r*1.48,u32(P.gold,glow),48)
    dl:AddCircleFilled(imgui.ImVec2(cx,cy),r*.94,u32(P.gold,.16+.04*hoverT),48)
    dl:AddCircle(imgui.ImVec2(cx,cy),r*.94,u32({.95,.70,.27,1},.86+.10*hoverT),48,1.45)
end

function View.drawHouseCard(house, width, height)
    local p = imgui.GetCursorScreenPos()
    imgui.InvisibleButton("##house_" .. tostring(house.number), imgui.ImVec2(width, height))
    local hovered = imgui.IsItemHovered()
    local clicked = imgui.IsItemClicked(0)
    local id = "house_" .. tostring(house.number)
    local hoverT = smoothAnim(id .. "_hover", hovered and 1.0 or 0.0, 7.0)
    local dataT = smoothAnim(id .. "_data", house.scanned and 1.0 or 0.0, 5.5)
    local dl = imgui.GetWindowDrawList()
    local borderP1 = imgui.ImVec2(p.x + 1.5, p.y + 1.5)
    local borderP2 = imgui.ImVec2(p.x + width - 1.5, p.y + height - 1.5)
    local borderW, borderH = width - 3, height - 3
    local pad = math.max(10, borderW * 0.035)
    local textureW, textureH = borderW + pad * 2, borderH + pad * 2
    local p1 = imgui.ImVec2(borderP1.x - pad + textureW * (15 / 224),
        borderP1.y - pad + textureH * (15 / 224))
    width, height = textureW * (194 / 224), textureH * (194 / 224)
    local p2 = imgui.ImVec2(p1.x + width, p1.y + height)
    local scale = width / 390
    CardText.scale=scale
    local rounding = width * 0.137
    local elite = View.isArizonaSprings(house)
    local bg = mixColor(P.card, P.hover, hoverT * 0.62)

    dl:AddRectFilled(imgui.ImVec2(p1.x + 2, p1.y + 8),
        imgui.ImVec2(p2.x + 2, p2.y + 8), u32(P.shadow, 0.38), rounding + 3)
    if not drawTexture(Textures.cardSurface, p1.x, p1.y, width, height, {1,1,1,1}, 0.995) then
        dl:AddRectFilled(p1, p2, u32(bg, 0.988), rounding)
    end

    drawStatusBorder(dl, borderP1, borderP2, rounding - 1, house, hoverT)

    local heroX = p1.x + width * 0.065
    local heroY = p1.y + height * 0.055
    local heroW = width * 0.870
    local heroH = heroW * (485 / 790)
    local drewVilla = elite and View.drawSpringsVillaImage(heroX, heroY, heroW, heroH, 0.995)
    if not drewVilla then
        if elite then
            View.drawVillaOutline(heroX, heroY + heroH * 0.04, heroW, heroH * 0.80,
                mixColor(P.gold, P.text, 0.42), 0.95)
        else
            View.drawHouseOutline(p1.x + width * 0.30, p1.y + height * 0.19,
                width * 0.40, mixColor(P.muted, P.text, 0.38), 0.94, 0)
        end
    end

    local eliteBadgeX,eliteBadgeY,eliteBadgeW,eliteBadgeH=nil,nil,nil,nil
    if elite then
        eliteBadgeX = math.floor(p1.x + width * .055 + .5)
        eliteBadgeY = math.floor(p1.y + height * .043 + .5)
        eliteBadgeW = math.floor(width * .287 + .5)
        eliteBadgeH = math.floor(eliteBadgeW * 102 / 257 + .5)
        View.drawEliteBadge(eliteBadgeX, eliteBadgeY, eliteBadgeW, eliteBadgeH, scale)
    end
    if getArchitectMultiplier(house.number)>1 then
        local badgeSize=elite and math.max(20,math.min(24,(eliteBadgeH or 30)*.62))
            or math.max(20,math.min(23,width*.058))
        local badgeY=elite and (eliteBadgeY+eliteBadgeH*.5) or (p1.y+math.max(36,height*.095)+badgeSize*.5)
        local badgeX
        if elite then
            badgeX=eliteBadgeX+eliteBadgeW+10+badgeSize*.5
        else
            badgeX=p1.x+math.max(36,width*.095)+badgeSize*.5
        end
        local mouse=imgui.GetMousePos()
        local hoveredArchitect=(mouse.x-badgeX)^2+(mouse.y-badgeY)^2<=(badgeSize*.70)^2
        View.architectHouse=house.number
        View.drawArchitectBadge(badgeX,badgeY,badgeSize,hoveredArchitect)
        if hoveredArchitect then
            local architectTip="AutoMiner визначив набір архітектора\n+30% до майнінгу · +50% до об'єму GPU"
            drawTooltip("architect_"..house.number,architectTip,badgeX-badgeSize*.5,badgeY-badgeSize*.5,badgeSize,badgeSize)
        end
    end


    View.drawHouseNumberTitle(p1.x + width * 0.5, p1.y + height * 0.531,
        house.number, Fonts.houseTitle or Fonts.title, P.text, scale)

    local cityText = View.getHouseCity(house)
    local cityFont = Fonts.city or Fonts.body
    local citySize = View.calcText(cityText, cityFont)
    local pinSize = width * 0.048
    local cityGap = width * 0.021
    local rowX = p1.x + (width - pinSize - cityGap - citySize.x) * 0.5
    local rowY = p1.y + height * 0.602
    View.drawLocationPin(rowX + pinSize * 0.45, rowY + citySize.y * 0.46,
        pinSize, elite and P.gold or P.muted)
    View.drawText(rowX + pinSize + cityGap, rowY, cityText, cityFont, elite and P.gold or P.muted)

    local sepY = p1.y + height * 0.673
    dl:AddLine(imgui.ImVec2(p1.x + width * 0.110, sepY),
        imgui.ImVec2(p2.x - width * 0.110, sepY), u32(P.surface, 0.60), scale)
    local dividerX = p1.x + width * 0.501
    if house.miningStatus == "available" or house.miningStatus == nil then
        dl:AddLine(imgui.ImVec2(dividerX, p1.y + height * 0.709),
            imgui.ImVec2(dividerX, p1.y + height * 0.807), u32(P.surface, 0.65), scale)
    end

    local unavailable = house.miningStatus == "unavailable"
    local pending = house.miningStatus == "unknown" or house.miningStatus == "checking"
    if unavailable or pending then
        local title = unavailable and "Майнинг недоступен" or (house.miningStatus == "checking" and "Проверяем дом" or "Не проверено")
        local reason = house.miningReason or "Обновите список домов"
        local ts = View.calcText(title, Fonts.cardLabel)
        local rs = View.calcText(reason, Fonts.small)
        View.drawText(p1.x+(width-ts.x)*.5,p1.y+height*.727,title,Fonts.cardLabel,unavailable and P.amber or P.muted)
        dl:PushClipRect(imgui.ImVec2(p1.x+12,p1.y),imgui.ImVec2(p2.x-12,p2.y),true)
        View.drawText(math.max(p1.x+12,p1.x+(width-rs.x)*.5),p1.y+height*.795,reason,Fonts.small,P.faint)
        dl:PopClipRect()
        if hovered then drawTooltip("house_reason_"..house.number,reason,p1.x,p1.y,width,height) end
        if Settings.showCycles then
            local text = Runtime.plural(house.cycles,"цикл","цикли","циклів")
            local size = View.calcText(text,Fonts.cycles)
            View.drawText(p1.x+(width-size.x)*.5,p1.y+height*.924,text,Fonts.cycles,P.faint)
        end
        CardText.scale=nil
        return
    end

    local metricTop = p1.y + height * 0.710
    local subTop = p1.y + height * 0.770
    local metricFont = Fonts.metricBig or Fonts.semibold
    local labelFont = Fonts.cardLabel or Fonts.body
    local btcText,btcSub
    if house.scanned then btcText,btcSub=currencyPairFromBtc(house.collectible or 0,MiningModel.price,true) else btcText,btcSub="—","" end
    local btcFont=metricFont
    if View.calcText(btcText,btcFont).x>width*.43 then btcFont=labelFont end
    if View.calcText(btcText,btcFont).x>width*.43 then btcFont=Fonts.small end
    local btcSize = View.calcText(btcText, btcFont)
    local leftCenter = p1.x + width * 0.305
    View.drawTextAlpha(leftCenter - btcSize.x * 0.5, metricTop, btcText, btcFont,
        currencyPrimaryIsUsd() and P.green or P.text, 0.35 + 0.65 * dataT)
    local collectLabel=btcSub~="" and btcSub or "к сбору"
    local collectFont=labelFont
    if View.calcText(collectLabel,collectFont).x>width*.43 then collectFont=Fonts.small end
    local collectSize = View.calcText(collectLabel, collectFont)
    View.drawText(leftCenter - collectSize.x * 0.5, subTop, collectLabel, collectFont, btcSub~="" and (currencyPrimaryIsUsd() and P.text or P.green) or P.muted)

    local installed = tonumber(house.gpuCount) or 0
    local paused = tonumber(house.pausedCount) or 0
    local working = tonumber(house.workingCount) or math.max(0, installed - paused)
    local slots = tonumber(house.slotCount) or 0
    if slots <= 0 and installed > 0 then slots = 20 end
    local gpuText, gpuSub, statusColor
    if not house.scanned then
        gpuText, gpuSub, statusColor = "—/—", "проверяем GPU", P.faint
    elseif installed <= 0 then
        gpuText, gpuSub, statusColor = "0/" .. tostring(slots > 0 and slots or 20), "GPU не найдены", P.faint
    elseif (house.unknownCount or 0)>0 then
        gpuText=tostring(working).."/"..tostring(slots);gpuSub="Стан частини GPU не визначено";statusColor=P.amber
    elseif paused > 0 then
        gpuText = tostring(working) .. "/" .. tostring(slots)
        gpuSub = tostring(paused) .. " на паузе"
        statusColor = paused >= math.max(2, math.floor(installed * 0.25)) and P.red or P.amber
    else
        gpuText, gpuSub, statusColor = tostring(working) .. "/" .. tostring(slots), "GPU работают", P.green
    end
    local rightCenter = p1.x + width * 0.715
    local gpuSize = View.calcText(gpuText, metricFont)
    local dotRadius, dotGap = 6.6 * scale, 12 * scale
    local groupX = rightCenter - (dotRadius * 2 + dotGap + gpuSize.x) * 0.5
    local dotX, dotY = groupX + dotRadius, metricTop + gpuSize.y * 0.55
    dl:AddCircleFilled(imgui.ImVec2(dotX, dotY), 13 * scale, u32(statusColor, 0.025), 32)
    dl:AddCircleFilled(imgui.ImVec2(dotX, dotY), 9 * scale, u32(statusColor, 0.080), 32)
    dl:AddCircleFilled(imgui.ImVec2(dotX, dotY), dotRadius, u32(statusColor, 1.0), 32)
    View.drawTextAlpha(groupX + dotRadius * 2 + dotGap, metricTop, gpuText, metricFont,
        P.text, 0.35 + 0.65 * dataT)
    local gpuSubSize = View.calcText(gpuSub, labelFont)
    View.drawText(rightCenter - gpuSubSize.x * 0.5, subTop, gpuSub, labelFont, P.muted)

    local sep2Y = p1.y + height * 0.840
    dl:AddLine(imgui.ImVec2(p1.x + width * 0.110, sep2Y),
        imgui.ImVec2(p2.x - width * 0.110, sep2Y), u32(P.surface, 0.60), scale)
    local coolant = tonumber(house.coolant)
    local percent = coolant and string.format("%.0f%%", coolant) or "—%"
    local percentFont = Fonts.cooling or Fonts.metricBig
    local labelFont = Fonts.coolingLabel or Fonts.cardLabel
    local percentSize = View.calcText(percent, percentFont)
    local label = "охлаждения"
    local labelSize = View.calcText(label, labelFont)
    local gap = 8 * scale
    local statX = p1.x + (width - percentSize.x - gap - labelSize.x) * 0.5
    local statY = p1.y + height * 0.883
    local coolingTint = coolant and coolantColor(coolant) or P.faint
    View.drawTextAlpha(statX, statY, percent, percentFont, coolingTint, 0.35 + 0.65 * dataT)
    View.drawTextAlpha(statX + percentSize.x + gap, statY + 6 * scale, label,
        labelFont, P.muted, 0.35 + 0.65 * dataT)

    local cycles = Runtime.plural(house.cycles,"цикл","цикли","циклів")
    local cycleFont = Fonts.cycles or Fonts.small
    local cs = View.calcText(cycles, cycleFont)
    if Settings.showCycles then
        View.drawTextAlpha(p1.x + (width - cs.x) * 0.5, p1.y + height * 0.943,
            cycles, cycleFont, P.muted, 0.35 + 0.65 * dataT)
    end

    CardText.scale=nil
    if clicked and not UI.scanning then selectHouse(house) end
end

function View.drawLoading()
    local dl = imgui.GetWindowDrawList()
    local p = imgui.GetCursorScreenPos()
    local width = imgui.GetContentRegionAvail().x

    local centerX = p.x + width * 0.5
    local y = p.y + 86
    local t = getGameTimer() / 220

    for i = 1, 3 do
        local a = 0.28 + 0.55 *
            ((math.sin(t + i * 1.4) + 1) * 0.5)

        dl:AddCircleFilled(
            imgui.ImVec2(centerX + (i - 2) * 18, y),
