local function firstExisting(list)
    for _, path in ipairs(list) do
        if doesFileExist(path) then
            return path
        end
    end
end

local function loadFonts()
    local io = imgui.GetIO()
    local builder = imgui.ImFontGlyphRangesBuilder()
    builder:AddRanges(io.Fonts:GetGlyphRangesDefault())
    builder:AddText("АБВГДЕЁЖЗИЙКЛМНОПРСТУФХЦЧШЩЪЫЬЭЮЯІЇЄҐабвгдеёжзийклмнопрстуфхцчшщъыьэюяіїєґ")
    builder:AddText("№—–·…≈×−→’")
    FontGlyphRanges = imgui.ImVector_ImWchar()
    builder:BuildRanges(FontGlyphRanges)
    local ranges = FontGlyphRanges[0].Data
    local windir = os.getenv("WINDIR") or "C:\\Windows"

    local regular = firstExisting({
        windir .. "\\Fonts\\segoeui.ttf",
        getAssetPath("fonts\\Exo2-Regular.ttf"),
        windir .. "\\Fonts\\arial.ttf",
        windir .. "\\Fonts\\tahoma.ttf"
    })

    local semi = firstExisting({
        windir .. "\\Fonts\\seguisb.ttf",
        getAssetPath("fonts\\Exo2-SemiBold.ttf"),
        windir .. "\\Fonts\\segoeuib.ttf",
        windir .. "\\Fonts\\arialbd.ttf"
    }) or regular

    local medium = regular
    if not regular then return end

    local loaded={}
    local function add(path, size)
        local key=path..":"..size
        if loaded[key] then return loaded[key] end
        local rasterScale=1
        local config = imgui.ImFontConfig()
        config.OversampleH = 2
        config.OversampleV = 2
        config.PixelSnapH = true
        config.RasterizerMultiply = 1.15
        local ok, font = pcall(function()
            return io.Fonts:AddFontFromFileTTF(
                path,
                size*rasterScale,
                config,
                ranges
            )
        end)

        if ok and font~=nil then
            font.Scale=1/rasterScale
            loaded[key]=font
            return font
        end
    end

    io.FontGlobalScale = 1.0
    Fonts.small = add(regular, 16)
    Fonts.note = add(regular, 16)
    Fonts.body = add(regular, 18)
    Fonts.semibold = add(semi, 21)
    Fonts.elite = add(semi, 16)
    Fonts.city = add(medium, 23)
    Fonts.bottom = add(regular, 18)
    Fonts.metric = add(semi, 28)
    Fonts.metricBig = add(semi, 28)
    Fonts.houseTitle = add(semi, 30)
    Fonts.cardLabel = add(regular, 18)
    Fonts.cooling = add(semi, 28)
    Fonts.coolingLabel = add(medium, 20)
    Fonts.cycles = add(regular, 18)
    Fonts.title = add(semi, 27)
    Fonts.dashboard = add(semi, 42)

    CardText.regular[16]=Fonts.small
    CardText.regular[18]=Fonts.body
    CardText.regular[20]=Fonts.coolingLabel
    CardText.regular[23]=Fonts.city
    CardText.semi[16]=Fonts.elite
    CardText.semi[21]=Fonts.semibold
    CardText.semi[27]=Fonts.title
    CardText.semi[28]=Fonts.metric
    CardText.semi[30]=Fonts.houseTitle
    CardText.semi[32]=Fonts.houseTitle

    for _,spec in ipairs({
        {"small",16,"regular"},{"body",18,"regular"},{"semibold",21,"semi"},
        {"elite",16,"semi"},{"city",23,"regular"},{"bottom",18,"regular"},
        {"metric",28,"semi"},{"metricBig",28,"semi"},{"houseTitle",30,"semi"},
        {"cardLabel",18,"regular"},{"cooling",28,"semi"},{"coolingLabel",20,"regular"},
        {"cycles",18,"regular"},{"title",27,"semi"}
    }) do
        if Fonts[spec[1]] then CardText.base[Fonts[spec[1]]]={size=spec[2],weight=spec[3]} end
    end

    pcall(function() io.FontDefault = Fonts.body end)
end

