local function loadNextUiTextureSafe()
    if UIResources.texturesLoaded then return end
    local item=UiTextureQueue[UIResources.textureIndex]
    if not item then
        UIResources.texturesLoaded=true
        Runtime.log("PERF_TEXTURES","complete")
        return
    end
    UIResources.textureIndex=UIResources.textureIndex+1
    if not imgui.CreateTextureFromFile then return end
    local path=getAssetPath(item.file)
    if not doesFileExist(path) then Runtime.log("TEXTURE_MISSING",item.file);return end
    local started=getGameTimer()
    local ok,texture=pcall(imgui.CreateTextureFromFile,path)
    if ok and texture then Textures[item.key]=texture
    else Runtime.log("TEXTURE_ERROR",item.file.." "..tostring(texture)) end
    Runtime.log("PERF_TEXTURE",item.file.."="..tostring(getGameTimer()-started).."ms")
end


