function View.calculateHouseLayout(sx, sy, total)
    total = math.max(0, math.floor(tonumber(total) or 0))
    local gap, aspect = 18, 1.19
    local maxColumns = sx >= 1140 and 3 or (sx >= 760 and 2 or 1)
    local twoRowWidth = (sy - 24 - 194 - gap) / (2 * aspect)
    local maxRows = twoRowWidth >= 310 and 2 or 1
    local columns, rows, baseCard
    if total <= 1 then
        columns, rows, baseCard = 1, 1, 390
    elseif total == 2 then
        columns = math.min(2, maxColumns)
        rows = math.min(maxRows, math.ceil(total / columns))
        baseCard = 360
    elseif total == 3 and maxColumns >= 3 then
        columns, rows, baseCard = 3, 1, 340
    elseif (total <= 4 or total == 7 or total == 8) and maxColumns >= 2 and maxRows >= 2 then
        columns, rows, baseCard = 2, 2, 340
    else
        columns, rows, baseCard = maxColumns, maxRows, 340
    end
    local perPage = columns * rows
    local pageCount = math.max(1, math.ceil(total / perPage))
    local chromeH = 194
    local maxByWidth = (sx - 66 - (columns - 1) * gap) / columns
    local maxByHeight = (sy - 24 - chromeH - (rows - 1) * gap) / (rows * aspect)
    local cardW = math.max(1, math.floor(math.min(baseCard, maxByWidth, maxByHeight)))
    local cardH = math.floor(cardW * aspect)
    return {
        columns = columns, rows = rows, gap = gap,
        cardW = cardW, cardH = cardH, perPage = perPage, pageCount = pageCount,
        gridW = columns * cardW + (columns - 1) * gap,
        gridH = rows * cardH + (rows - 1) * gap,
        chromeH = chromeH
    }
end

