function View.buildDisplayHouses()
    local result = {}

    for i, house in ipairs(UI.houses or {}) do
        result[#result + 1] = house
    end

    table.sort(result, function(a, b)
        if Settings.sort == "number" then return (tonumber(a.number) or 0) < (tonumber(b.number) or 0) end
        local aReason,bReason=not isHouseIgnored(a.number) and houseAttentionReason(a) or nil,not isHouseIgnored(b.number) and houseAttentionReason(b) or nil
        if (aReason~=nil)~=(bReason~=nil) then return aReason~=nil end
        local aPaused = tonumber(a.pausedCount) or 0
        local bPaused = tonumber(b.pausedCount) or 0

        if (aPaused > 0) ~= (bPaused > 0) then
            return aPaused > 0
        end

        local aBtc = tonumber(a.btc) or 0
        local bBtc = tonumber(b.btc) or 0

        if math.abs(aBtc - bBtc) > 0.000001 then
            return aBtc > bBtc
        end

        return (tonumber(a.number) or 0) < (tonumber(b.number) or 0)
    end)

    return result
end

