function View.shellButton(id, label, x, y, w, h, selected, enabled)
    if enabled == nil then enabled = true end
    imgui.SetCursorScreenPos(imgui.ImVec2(x,y))
    imgui.InvisibleButton(id,imgui.ImVec2(w,h))
    local hovered = enabled and imgui.IsItemHovered()
    local held = enabled and imgui.IsItemActive()
    local dl = imgui.GetWindowDrawList()

    local neutral = {0.078,0.087,0.102,1}
    local neutralHover = {0.095,0.106,0.123,1}
    local neutralSelected = {0.118,0.128,0.148,1}
    local hoverT=smoothAnim(tostring(id).."_hover",hovered and 1 or 0,15)
    local selectT=smoothAnim(tostring(id).."_selected",selected and 1 or 0,17)
    local pressT=smoothAnim(tostring(id).."_press",held and 1 or 0,22)
    local fill=mixColor(neutral,neutralHover,hoverT*.96)
    fill=mixColor(fill,neutralSelected,selectT)
    local inset=pressT*.75

    dl:AddRectFilled(imgui.ImVec2(x+inset,y+inset),imgui.ImVec2(x+w-inset,y+h-inset),u32(fill,enabled and .98 or .48),h*.5)
    if selectT>.01 then
        dl:AddRect(imgui.ImVec2(x+.5+inset,y+.5+inset),imgui.ImVec2(x+w-.5-inset,y+h-.5-inset),u32({.43,.46,.54,1},.18+.30*selectT),h*.5,nil,1)
        dl:AddLine(imgui.ImVec2(x+h*.42,y+2+inset),imgui.ImVec2(x+w-h*.42,y+2+inset),u32(P.text,.07*selectT),1)
    end

    local size=View.calcText(label,Fonts.body)
    local textCol=not enabled and P.faint or mixColor(P.muted,P.text,math.max(hoverT,selectT))
    View.drawText(x+(w-size.x)*.5,y+(h-size.y)*.5+pressT*.35,label,Fonts.body,textCol)
    return enabled and imgui.IsItemClicked(0)
end

function View.drawSegmentedControl(id,items,selected,x,y,w,h)
    local dl=imgui.GetWindowDrawList()
    local count=math.max(1,#items)
    local segW=w/count
    dl:AddRectFilled(imgui.ImVec2(x,y),imgui.ImVec2(x+w,y+h),u32({.058,.064,.074,1},.98),h*.5)
    dl:AddRect(imgui.ImVec2(x+.5,y+.5),imgui.ImVec2(x+w-.5,y+h-.5),u32(P.surface,.20),h*.5,nil,1)
    local selectedIndex=1
    for i,item in ipairs(items) do if item[1]==selected then selectedIndex=i break end end

    -- One shared spring makes the active capsule visibly fly to the next option,
    -- overshoot by a few pixels and settle instead of snapping/fading in place.
    local pos=View.springValue("segment_"..id,selectedIndex,Settings.animations=="reduced" and 300 or 205,Settings.animations=="reduced" and 32 or 21)
    local pillX=x+(pos-1)*segW+2
    local travel=math.abs((Motion.springs["segment_"..id] and Motion.springs["segment_"..id].velocity) or 0)
    local glow=math.min(1,travel*.08)
    dl:AddRectFilled(imgui.ImVec2(pillX-2,y+1),imgui.ImVec2(pillX+segW-2,y+h-1),u32(P.text,.018+.025*glow),(h-2)*.5)
    dl:AddRectFilled(imgui.ImVec2(pillX,y+2),imgui.ImVec2(pillX+segW-4,y+h-2),u32({.122,.132,.151,1},.98),(h-4)*.5)
    dl:AddRect(imgui.ImVec2(pillX+.5,y+2.5),imgui.ImVec2(pillX+segW-4.5,y+h-2.5),u32({.43,.46,.54,1},.38),(h-4)*.5,nil,1)

    local clicked=nil
    for i,item in ipairs(items) do
        local sx=x+(i-1)*segW
        imgui.SetCursorScreenPos(imgui.ImVec2(sx,y))
        imgui.InvisibleButton("##segment_"..id.."_"..item[1],imgui.ImVec2(segW,h))
        local hovered=imgui.IsItemHovered()
        local pressed=imgui.IsItemActive()
        local hoverT=smoothAnim("segment_"..id.."_hover_"..i,hovered and 1 or 0,16)
        local pressT=smoothAnim("segment_"..id.."_press_"..i,pressed and 1 or 0,22)
        local distance=math.abs(pos-i)
        local activeT=math.max(0,1-distance)
        local col=mixColor(P.muted,P.text,math.max(activeT,hoverT*.72))
        local ts=View.calcText(item[2],Fonts.body)
        View.drawText(sx+(segW-ts.x)*.5,y+(h-ts.y)*.5+pressT*.35,item[2],Fonts.body,col)
        if imgui.IsItemClicked(0) then clicked=item[1] end
    end
    return clicked
end

function View.smoothRoundedPath(dl,x1,y1,x2,y2,rtl,rtr,rbr,rbl,segments)
    local w=math.max(0,x2-x1)
    local h=math.max(0,y2-y1)
    local maxR=math.min(w,h)
    rtl=math.max(0,math.min(maxR,rtl or 0))
    rtr=math.max(0,math.min(maxR,rtr or 0))
    rbr=math.max(0,math.min(maxR,rbr or 0))
    rbl=math.max(0,math.min(maxR,rbl or 0))
    local scale=math.min(1,w/math.max(1,rtl+rtr),w/math.max(1,rbl+rbr),
        h/math.max(1,rtl+rbl),h/math.max(1,rtr+rbr))
    rtl,rtr,rbr,rbl=rtl*scale,rtr*scale,rbr*scale,rbl*scale
    segments=math.max(6,math.floor(segments or 14))

    local function arc(cx,cy,r,a0,a1,skipFirst)
        if r<=.01 then
            dl:PathLineTo(imgui.ImVec2(cx,cy))
            return
        end
        for i=0,segments do
            if not (skipFirst and i==0) then
                local t=i/segments
                local a=a0+(a1-a0)*t
                dl:PathLineTo(imgui.ImVec2(
                    cx+math.cos(a)*r,
                    cy+math.sin(a)*r
                ))
            end
        end
    end

    dl:PathClear()
    arc(x1+rtl,y1+rtl,rtl,math.pi,math.pi*1.5,false)
    arc(x2-rtr,y1+rtr,rtr,math.pi*1.5,math.pi*2,false)
    arc(x2-rbr,y2-rbr,rbr,0,math.pi*.5,false)
    arc(x1+rbl,y2-rbl,rbl,math.pi*.5,math.pi,false)
end

function View.drawSmoothRoundedRectCorners(x,y,w,h,rtl,rtr,rbr,rbl,fill,border,borderThickness,segments)
    local dl=imgui.GetWindowDrawList()
    local x2,y2=x+w,y+h

    if fill then
        View.smoothRoundedPath(dl,x,y,x2,y2,rtl,rtr,rbr,rbl,segments)
        dl:PathFillConvex(fill)
    end

    if border and (borderThickness or 0)>0 then
        local inset=math.max(.5,(borderThickness or 1)*.5)
        View.smoothRoundedPath(
            dl,
            x+inset,
            y+inset,
            x2-inset,
            y2-inset,
            math.max(0,(rtl or 0)-inset),
            math.max(0,(rtr or 0)-inset),
            math.max(0,(rbr or 0)-inset),
            math.max(0,(rbl or 0)-inset),
            segments
        )
        dl:PathStroke(border,true,borderThickness or 1)
    end
end

function View.drawSmoothRoundedRect(x,y,w,h,r,fill,border,borderThickness,segments)
    View.drawSmoothRoundedRectCorners(
