function View.pageBounds(total,page,pageCount)
    local base=math.floor(total/pageCount)
    local extra=total%pageCount
    local count=base+(page<=extra and 1 or 0)
    local first=(page-1)*base+math.min(page-1,extra)+1
    return first,first+count-1,count
end


function View.coolingValue(houses,now)
    local rows={};local total,count=0,0
    for _,house in ipairs(houses or {}) do
        if house.miningStatus=="available" then
            local sum,n=0,0
            for _,gpu in ipairs(house.gpus or {}) do
                local v=tonumber(gpu.coolant)
                if v and v==v and v>=0 and v<=100 then sum=sum+v;n=n+1 end
            end
            if n>0 then
                rows[#rows+1]={number=house.number,value=sum/n}
                total=total+sum;count=count+n
            end
        end
    end
    table.sort(rows,function(a,b)return tonumber(a.number)<tonumber(b.number)end)
    if #rows==0 then View.coolingCycle=nil;return nil,nil end
    if Settings.coolingMode=="lowest" then
        local value=100;for _,row in ipairs(rows) do value=math.min(value,row.value) end
        View.coolingCycle=nil;return value,nil
    end
    if Settings.coolingMode~="cycle" then View.coolingCycle=nil;return total/count,nil end
    local state=View.coolingCycle or {number=rows[1].number,since=now}
    View.coolingCycle=state
    local index=nil
    for i,row in ipairs(rows) do if row.number==state.number then index=i;break end end
    if not index then index=1;state.since=now end
    if now<state.since then state.since=now end
    if #rows>1 and now-state.since>=10 then
        local steps=math.floor((now-state.since)/10)
        index=(index-1+steps)%#rows+1;state.since=state.since+steps*10
    end
    state.number=rows[index].number
    return rows[index].value,state.number
end


function View.drawCoolingReservoir(x,y,w,h,value,houseNumber)
    local dl=imgui.GetWindowDrawList()

    imgui.SetCursorScreenPos(imgui.ImVec2(x,y))
    imgui.InvisibleButton("##cooling_reservoir",imgui.ImVec2(w,h))
    local hovered=imgui.IsItemHovered()

    local r=30
    local numeric=math.max(0,math.min(100,tonumber(value) or 0))
    local targetLevel=numeric/100

    local io=imgui.GetIO()
    local dt=Settings.animations=="off" and 0 or math.max(.001,math.min(.033,tonumber(io.DeltaTime) or .016))
    if Settings.animations=="off" then WaterMotion.level=targetLevel;WaterMotion.levelVel=0;WaterMotion.tilt=0;WaterMotion.tiltVel=0;WaterMotion.energy=0;WaterMotion.openKick=false end

    if WaterMotion.level==nil then
        WaterMotion.level=targetLevel
        WaterMotion.lastTarget=targetLevel
    end

    if WaterMotion.lastTarget~=targetLevel then
        local delta=targetLevel-(WaterMotion.lastTarget or targetLevel)
        WaterMotion.levelVel=WaterMotion.levelVel*.35
        WaterMotion.energy=math.min(1.45,WaterMotion.energy+math.abs(delta)*.35+.025)
        WaterMotion.lastTarget=targetLevel
    end

    if WaterMotion.openKick then
        WaterMotion.openKick=false
        WaterMotion.energy=math.max(WaterMotion.energy,.12)
        WaterMotion.levelVel=WaterMotion.levelVel
    end

    WaterMotion.level,WaterMotion.levelVel=springStep(
        WaterMotion.level,
        WaterMotion.levelVel,
        targetLevel,
        7,
        5.4,
        dt
    )

    WaterMotion.tilt,WaterMotion.tiltVel=springStep(
        WaterMotion.tilt,
        WaterMotion.tiltVel,
        0,
        22,
        8.6,
        dt
    )

    WaterMotion.energy=.075+(WaterMotion.energy-.075)*math.exp(-2.2*dt)
    WaterMotion.phase=WaterMotion.phase+dt*(1.08+WaterMotion.energy*.55)

    local bg=View.panelFill(hovered,true)

    View.drawSmoothRoundedRect(
        x,y,w,h,r,
        u32(bg,1),
        nil,
        0,
        20
    )

    local level=math.max(0,math.min(1,WaterMotion.level))
    local innerX=x+3
    local innerY=y+3
    local innerRight=x+w-3
    local innerBottom=y+h-3
    local innerW=innerRight-innerX
    local innerH=innerBottom-innerY
    local innerR=r-4

    if level>.001 then
        local visualLevel=level>=.995 and .965 or level
        local fillHeight=innerH*visualLevel
        local surfaceY=innerBottom-fillHeight
        local amp=1.0+WaterMotion.energy*3.25
        local tiltPx=math.max(-8,math.min(8,WaterMotion.tilt*6.2))

        local rawLiquid=liquidColor(value)
        local liquid=mixColor(bg,rawLiquid,.53)
        local liquidU32=u32(liquid,1)

        local function topBoundaryY(xx)
            if xx<innerX+innerR then
                local dx=xx-(innerX+innerR)
                return innerY+innerR-math.sqrt(math.max(0,innerR*innerR-dx*dx))
            elseif xx>innerRight-innerR then
                local dx=xx-(innerRight-innerR)
                return innerY+innerR-math.sqrt(math.max(0,innerR*innerR-dx*dx))
            end
            return innerY
        end

        local function waterY(xx)
            local t=(xx-innerX)/innerW
            local slope=(t-.5)*2*tiltPx
            local wave1=math.sin(WaterMotion.phase*2.0+t*math.pi*2.6)*amp
            local wave2=math.sin(WaterMotion.phase*1.31+1.1+t*math.pi*5.2)*amp*.28
            return math.max(
                surfaceY+slope+wave1+wave2,
                topBoundaryY(xx)+1
            )
        end

        local safeTop=math.min(
            innerBottom-1,
            surfaceY+amp+math.abs(tiltPx)+4
        )

        local xSamples=math.max(32,math.ceil(innerW))
        local sampleX,sampleY={},{}
        for i=0,xSamples do
            sampleX[i]=innerX+innerW*i/xSamples
            sampleY[i]=waterY(sampleX[i])
        end
        local uv=imgui.GetFontTexUvWhitePixel()
        local clear=u32(liquid,0)
        local function quad(xa,ya,xb,yb,xc,yc,xd,yd,c1,c2,c3,c4)
            dl:PrimReserve(6,4)
            local base=dl._VtxCurrentIdx
            for _,index in ipairs({0,1,2,0,2,3}) do dl:PrimWriteIdx(base+index) end
            dl:PrimWriteVtx(imgui.ImVec2(xa,ya),uv,c1)
            dl:PrimWriteVtx(imgui.ImVec2(xb,yb),uv,c2)
            dl:PrimWriteVtx(imgui.ImVec2(xc,yc),uv,c3)
            dl:PrimWriteVtx(imgui.ImVec2(xd,yd),uv,c4)
        end
        local function bottomY(xx)
            local dx=xx<innerX+innerR and xx-(innerX+innerR) or (xx>innerRight-innerR and xx-(innerRight-innerR) or 0)
            return innerBottom-innerR+math.sqrt(math.max(0,innerR*innerR-dx*dx))
        end
        for i=0,xSamples-1 do
            local ax,bx=sampleX[i],sampleX[i+1]
            local ab,bb=bottomY(ax),bottomY(bx)
            local ay,by=math.min(sampleY[i],ab),math.min(sampleY[i+1],bb)
            local af,bf=math.min(ay+.5,ab),math.min(by+.5,bb)
            quad(ax,af,bx,bf,bx,bb,ax,ab,liquidU32,liquidU32,liquidU32,liquidU32)
            quad(ax,ay-.5,bx,by-.5,bx,bf,ax,af,clear,clear,liquidU32,liquidU32)
        end

        local bubblePhase=WaterMotion.phase*.36
        for i,b in ipairs({
            {.23,.22,1.65,.0},
            {.69,.50,1.25,1.6},
            {.46,.74,1.05,3.1}
        }) do
            local travel=(bubblePhase+b[4])%1
            local by=innerBottom-math.max(7,fillHeight*travel)
            local bx=innerX+innerW*b[1]+math.sin(WaterMotion.phase*.75+i)*1.4
            if by>waterY(bx)+9 and by<innerBottom-7 then
                dl:AddCircle(
                    imgui.ImVec2(bx,by),
                    b[3],
                    u32(mixColor(liquid,P.text,.34),.20),
                    18,
                    .75
                )
            end
        end
    end

    View.drawSmoothRoundedRect(
        x,y,w,h,r,
        nil,
        u32({.38,.42,.49,1},hovered and .43 or .31),
        1.05,
        20
    )

    dl:AddLine(
        imgui.ImVec2(x+r+6,y+2),
        imgui.ImVec2(x+w-r-6,y+2),
        u32(P.text,.044),
        1
    )

    View.drawText(x+17,y+15,"ОХОЛОДЖЕННЯ",Fonts.small,P.muted)

    if houseNumber then
        local label="№"..tostring(houseNumber)
        local size=View.calcText(label,Fonts.small)
        View.drawText(x+w-17-size.x,y+15,label,Fonts.small,P.muted)
    end
    local percentText=value and string.format("%.0f%%",WaterMotion.level*100) or "—"
    local ps=View.calcText(percentText,Fonts.dashboard)
    View.drawText(
        x+(w-ps.x)*.5,
        y+53,
        percentText,
        Fonts.dashboard,
        P.text
    )

    local sub=not value and "Немає даних" or (Settings.coolingMode=="lowest" and "Найнижче середнє" or "Середнє охолодження")
    local ss=View.calcText(sub,Fonts.small)
    View.drawText(
        x+(w-ss.x)*.5,
        y+h-27,
        sub,
        Fonts.small,
        P.muted
    )
end


