function View.drawAlertTileIcon(cx,cy,size,color)
    local dl=imgui.GetWindowDrawList()
    local r=size*.38
    dl:AddTriangleFilled(imgui.ImVec2(cx,cy-r),imgui.ImVec2(cx+r,cy+r*.80),
        imgui.ImVec2(cx-r,cy+r*.80),color)
    local ink=u32({.09,.065,.025,1},1)
    dl:AddLine(imgui.ImVec2(cx,cy-r*.32),imgui.ImVec2(cx,cy+r*.17),ink,1.9)
    dl:AddCircleFilled(imgui.ImVec2(cx,cy+r*.48),1.1,ink,20)
