function View.drawGpuTileIcon(cx,cy,size,color)
    local dl=imgui.GetWindowDrawList()
    local body=size*.42
    local x1,y1=cx-body*.5,cy-body*.5
    local x2,y2=cx+body*.5,cy+body*.5

    View.drawSmoothRoundedRect(x1,y1,body,body,body*.18,nil,color,1.45,12)

    local pin=size*.13
    for _,t in ipairs({-.28,0,.28}) do
        local px=cx+body*t
        dl:AddLine(imgui.ImVec2(px,y1-pin),imgui.ImVec2(px,y1),color,1.25)
        dl:AddLine(imgui.ImVec2(px,y2),imgui.ImVec2(px,y2+pin),color,1.25)

        local py=cy+body*t
        dl:AddLine(imgui.ImVec2(x1-pin,py),imgui.ImVec2(x1,py),color,1.25)
        dl:AddLine(imgui.ImVec2(x2,py),imgui.ImVec2(x2+pin,py),color,1.25)
    end

    dl:AddCircleFilled(imgui.ImVec2(cx,cy),size*.055,color,18)
end

function View.drawIncomeTileIcon(cx,cy,size,color)
    local dl=imgui.GetWindowDrawList()
    local w,h=size*.78,size*.48
    View.drawSmoothRoundedRect(cx-w*.5,cy-h*.5,w,h,2.5,nil,color,1.6,12)
    dl:AddCircle(imgui.ImVec2(cx,cy),h*.23,color,40,1.4)
    for _,side in ipairs({-1,1}) do
        dl:AddCircleFilled(imgui.ImVec2(cx+side*w*.33,cy),.85,color,16)
    end
end

function View.drawHousesTileIcon(cx,cy,size,color)
    local dl=imgui.GetWindowDrawList()

    local function house(hx,hy,s,thickness)
        local half=s*.28
        local roof=hy-s*.24
        local base=hy+s*.24

        dl:AddLine(imgui.ImVec2(hx-half,hy),imgui.ImVec2(hx,roof),color,thickness)
        dl:AddLine(imgui.ImVec2(hx,roof),imgui.ImVec2(hx+half,hy),color,thickness)
        dl:AddLine(imgui.ImVec2(hx-half*.82,hy),imgui.ImVec2(hx-half*.82,base),color,thickness)
        dl:AddLine(imgui.ImVec2(hx+half*.82,hy),imgui.ImVec2(hx+half*.82,base),color,thickness)
        dl:AddLine(imgui.ImVec2(hx-half*.82,base),imgui.ImVec2(hx+half*.82,base),color,thickness)
    end

    house(cx-size*.13,cy-size*.05,size*.57,1.15)
    house(cx+size*.13,cy+size*.08,size*.64,1.45)
end

function View.drawMetricIcon(kind,cx,cy,size,accent,hoverT)
    View.drawTileIconBase(cx,cy,size,accent,hoverT)

    local iconColor=u32(mixColor(accent,P.text,.30),.92)

    if kind=="ok" then
        local dl=imgui.GetWindowDrawList()
        dl:PathClear()
        dl:PathLineTo(imgui.ImVec2(cx-size*.19,cy))
        dl:PathLineTo(imgui.ImVec2(cx-size*.045,cy+size*.14))
        dl:PathLineTo(imgui.ImVec2(cx+size*.21,cy-size*.17))
        dl:PathStroke(iconColor,false,2)
    elseif kind=="alert" then
        View.drawAlertTileIcon(cx,cy,size*.72,iconColor)
    elseif kind=="gpu" then
        View.drawGpuTileIcon(cx,cy,size*.72,iconColor)
    elseif kind=="income" then
        View.drawIncomeTileIcon(cx,cy,size*.72,iconColor)
    elseif kind=="houses" then
        View.drawHousesTileIcon(cx,cy,size*.72,iconColor)
    end
end

function View.drawMetricTile(x,y,w,h,label,value,sub,accent,clickable,id,iconKind,iconAccent)
    local dl=imgui.GetWindowDrawList()

    imgui.SetCursorScreenPos(imgui.ImVec2(x,y))
    imgui.InvisibleButton(
        id or ("##metric_"..tostring(label)),
        imgui.ImVec2(w,h)
    )

    local hovered=imgui.IsItemHovered()
    local hoverT=smoothAnim("metric_hover_"..tostring(label),hovered and 1 or 0,10)
    local r=28

    View.drawSmoothRoundedRect(
        x,y,w,h,r,
        u32(View.panelFill(hovered,false),1),
        u32({.27,.30,.36,1},.18+.09*hoverT),
        1,17
    )

    if hoverT>.01 then
        View.drawSmoothRoundedRect(
            x+2,y+2,w-4,h-4,r-2,
            nil,
            u32(P.text,.018+.018*hoverT),
            1,17
        )
    end

    local accentColor=iconAccent or accent or P.muted
    local iconSize=38
    local iconCx=x+w-24-iconSize*.5
    local iconCy=y+20+iconSize*.5

    if iconKind then
        View.drawMetricIcon(iconKind,iconCx,iconCy,iconSize,accentColor,hoverT)
    end

    local heading=label
    if iconKind=="income" then heading="ДОХІД\nЗА ГОДИНУ" end
    View.drawText(x+18,y+16,heading,Fonts.small,P.muted)
    local valueFont=Fonts.title
    if View.calcText(value,valueFont).x>w-36 then valueFont=Fonts.body end
    if View.calcText(value,valueFont).x>w-36 then valueFont=Fonts.small end
    View.drawRollingText(id.."_value",x+18,y+72,value,valueFont,accent or P.text)

    if sub and sub~="" then
        sub=I18n.text(sub)
        local measureFont=iconKind=="income" and (Fonts.semibold or Fonts.body) or Fonts.small
        local lines={};local line=""
        for word in sub:gmatch("%S+") do
            local nextLine=line=="" and word or line.." "..word
            if View.calcText(nextLine,measureFont).x>w-(iconKind=="income" and 58 or 36) and line~="" then lines[#lines+1]=line;line=word else line=nextLine end
        end
        lines[#lines+1]=line
        local lh=View.calcText("Ag",Fonts.small).y+2
        local subColor=P.muted
        local subFont=Fonts.small
        if iconKind=="income" then
            subColor=(Settings.incomeMode=="money_btc") and P.text or P.green
            subFont=Fonts.semibold or Fonts.body
            lh=View.calcText("Ag",subFont).y+2
        end
        for i,text in ipairs(lines) do View.drawText(x+18,y+h-16-(#lines-i+1)*lh,text,subFont,subColor) end
    end

    if iconKind=="income" then
        local qx,qy=x+w-24,y+h-22
        local mouse=imgui.GetMousePos()
        local helpHovered=(mouse.x-qx)^2+(mouse.y-qy)^2<=121
        local helpFill=helpHovered and {.12,.14,.17,1} or {.075,.085,.10,1}
        local helpBorder=helpHovered and P.text or P.muted
        dl:AddCircleFilled(imgui.ImVec2(qx,qy),9,u32(helpFill,helpHovered and .95 or .82),40)
        dl:AddCircle(imgui.ImVec2(qx,qy),9,u32(helpBorder,helpHovered and .72 or .42),40,1)
        local qFont=Fonts.small
        local size=View.calcText("?",qFont)
        View.drawText(qx-size.x*.5,qy-size.y*.5-1,"?",qFont,helpHovered and P.text or P.muted)
        if helpHovered then
            drawTooltip("income_help","Показує загальний дохід з урахуванням усіх активних бонусів.",qx-9,qy-9,18,18)
        end
    end

    return clickable and imgui.IsItemClicked(0)
end

local AttentionCarousel = {
    index = 1,
    fromIndex = nil,
    toIndex = nil,
    animStart = nil,
    lastSwitch = 0,
    lastCount = 0,
    hoverStarted = nil
}

