    View.drawSmoothRoundedRect(x,y,bw,bh,9,u32({.40+.12*t,.055,.075,1},.98),u32({1,.28,.34,1},.58+.18*t),1,14)
    local text="Ігнорувати"
    local size=View.calcText(text,Fonts.small)
    View.drawText(x+(bw-size.x)*.5,y+(bh-size.y)*.5,text,Fonts.small,{1,.91,.92,1})
    return imgui.IsItemClicked(0)
end

function View.drawAttentionTile(x,y,w,h,attention)
    local dl=imgui.GetWindowDrawList()
    local count=math.min(15,#attention)
    local now=getGameTimer()

    imgui.SetCursorScreenPos(imgui.ImVec2(x,y))
    imgui.InvisibleButton("##attention_tile",imgui.ImVec2(w,h))
    if imgui.SetItemAllowOverlap then imgui.SetItemAllowOverlap() end
    local hovered=imgui.IsItemHovered()
    local hoverT=smoothAnim("attention_tile_hover",hovered and 1 or 0,10)
    local r=28

    View.drawSmoothRoundedRect(
        x,y,w,h,r,
        u32(View.panelFill(hovered,false),1),
        u32(count==0 and P.green or P.amber,.075+.055*hoverT),
        1,17
    )

    View.drawMetricIcon(count==0 and not Runtime.dataUnknown() and "ok" or "alert",x+w-43,y+39,38,count==0 and P.green or P.amber,hoverT)
    View.drawText(x+18,y+16,"ПОТРЕБУЮТЬ\nУВАГИ",Fonts.small,P.muted)

    if Runtime.dataUnknown() then
        View.drawText(x+18,y+78,"Перевіряємо ферми",Fonts.body,P.muted)
        View.drawText(x+18,y+h-31,"Відновлюємо дані",Fonts.small,P.faint)
        return false,nil
    end
    if count==0 then
        local fade=AttentionCarousel.ignoreTime and math.min(1,(now-AttentionCarousel.ignoreTime)/320) or 1
        if AttentionCarousel.ignoreOld and fade<1 then
            View.drawTextAlpha(x+18-18*fade,y+74,"Будинок №"..AttentionCarousel.ignoreOld.number,Fonts.semibold,P.text,1-fade)
        end
        dl:AddCircleFilled(imgui.ImVec2(x+22,y+91),3.6,u32(P.green,.92),24)
        View.drawTextAlpha(x+36+18*(1-fade),y+78,"Все гаразд",Fonts.semibold,P.text,fade)
        View.drawTextAlpha(x+18,y+h-31,"Проблем не виявлено",Fonts.small,P.faint,fade)
        return false,nil
    end

    if AttentionCarousel.lastCount~=count then
        AttentionCarousel.index=math.max(1,math.min(AttentionCarousel.index,count))
        AttentionCarousel.fromIndex=nil
        AttentionCarousel.toIndex=nil
        AttentionCarousel.animStart=nil
        AttentionCarousel.lastSwitch=now
        AttentionCarousel.lastCount=count
    end

    if hovered and not AttentionCarousel.hoverStarted then
        AttentionCarousel.hoverStarted=now
    elseif not hovered and AttentionCarousel.hoverStarted then
        AttentionCarousel.lastSwitch=AttentionCarousel.lastSwitch+(now-AttentionCarousel.hoverStarted)
        AttentionCarousel.hoverStarted=nil
    end

    if Settings.animations~="off" and count>1 and not hovered and not AttentionCarousel.animStart
        and now-AttentionCarousel.lastSwitch>=5000 then
        AttentionCarousel.fromIndex=AttentionCarousel.index
        AttentionCarousel.toIndex=AttentionCarousel.index%count+1
        AttentionCarousel.animStart=now
    end

    if Settings.animations=="off" then AttentionCarousel.animStart=nil;AttentionCarousel.fromIndex=nil;AttentionCarousel.toIndex=nil end
    local transition=0
    if AttentionCarousel.animStart then
        transition=math.max(0,math.min(1,(now-AttentionCarousel.animStart)/320))
        if transition>=1 then
            AttentionCarousel.index=AttentionCarousel.toIndex
            AttentionCarousel.fromIndex=nil
            AttentionCarousel.toIndex=nil
            AttentionCarousel.animStart=nil
            AttentionCarousel.lastSwitch=now
            transition=0
        end
    end

    local function ease(t)
        return t*t*(3-2*t)
    end

    local function drawItem(item,offset,alpha,indexShown)
        local ox=offset
        dl:PushClipRect(imgui.ImVec2(x+12,y),imgui.ImVec2(x+w-12,y+h),true)

        View.drawTextAlpha(
            x+18+ox,
            y+74,
            "Будинок №"..tostring(item.number),
            Fonts.semibold,
            P.text,
            alpha
        )

        View.drawTextAlpha(
            x+18+ox,
            y+104,
            item.reason,
            Fonts.small,
            P.muted,
            alpha
        )

        local indicator=string.format("%d / %d",indexShown,count)
        local is=View.calcText(indicator,Fonts.small)

        View.drawTextAlpha(
            x+w-18-is.x+ox*.12,
            y+h-33,
            indicator,
            Fonts.small,
            P.faint,
            alpha
        )
        dl:PopClipRect()
    end

    local clickIndex=AttentionCarousel.index

    if AttentionCarousel.animStart then
        local t=ease(transition)
        local fromIndex=AttentionCarousel.fromIndex
        local toIndex=AttentionCarousel.toIndex

        drawItem(attention[fromIndex],-22*t,1-t,fromIndex)
        drawItem(attention[toIndex],22*(1-t),t,toIndex)
        clickIndex=t>.5 and toIndex or fromIndex
    else
        drawItem(attention[AttentionCarousel.index],0,1,AttentionCarousel.index)
    end

    local selected=attention[clickIndex]
    local cardClicked=imgui.IsItemClicked(0)
    if View.drawIgnoreButton(x+18,y+h-43) and selected then
        setHouseIgnored(selected.number,true);saveIgnored()
        AttentionCarousel.ignoreOld=selected;AttentionCarousel.ignoreTime=now
        return false,nil
    end
    if AttentionCarousel.ignoreOld then
        local t=math.min(1,(now-AttentionCarousel.ignoreTime)/320)
        View.drawSmoothRoundedRect(x+12,y+66,w-24,68,8,u32(P.card,1-t),nil,0,8)
        View.drawTextAlpha(x+18-18*t,y+74,"Будинок №"..AttentionCarousel.ignoreOld.number,Fonts.semibold,P.text,1-t)
        if t>=1 then AttentionCarousel.ignoreOld=nil end
    end
    return cardClicked,selected
end

function View.drawHistoryPanel(x,y,w,h)
    local dl=imgui.GetWindowDrawList()
    local r=29

    View.drawSmoothRoundedRect(
        x,y,w,h,r,
        u32(View.panelFill(false,false),1),
        u32({.27,.30,.36,1},.18),
        1,
        16
    )

    View.drawText(x+20,y+17,"ІСТОРІЯ",Fonts.small,P.muted)
    View.drawText(x+w-74,y+17,"Сесія",Fonts.small,P.faint)

    if #ActivityLog.items==0 then
        View.drawText(x+20,y+56,"Події з’являться після оновлення даних",Fonts.body,P.muted)
        View.drawText(x+20,y+84,"Тут буде історія попереджень і змін стану ферм.",Fonts.small,P.faint)
        return
    end

    local shown=math.min(3,#ActivityLog.items)
    local rowH=38

    for i=1,shown do
        local item=ActivityLog.items[i]
        local yy=y+49+(i-1)*rowH
        local color=item.kind=="amber" and P.amber or (item.kind=="green" and P.green or P.muted)

        dl:AddCircleFilled(imgui.ImVec2(x+22,yy+8),3.2,u32(color,.82),20)
        dl:PushClipRect(imgui.ImVec2(x+35,yy-4),imgui.ImVec2(x+230,yy+30),true)
        View.drawText(x+35,yy-3,item.title,Fonts.body,P.text)
        dl:PopClipRect()
        dl:PushClipRect(imgui.ImVec2(x+238,yy-2),imgui.ImVec2(x+w-76,yy+30),true)
        View.drawText(x+238,yy,item.detail,Fonts.small,P.muted)
        dl:PopClipRect()

        local ts=View.calcText(item.time,Fonts.small)
        View.drawText(x+w-20-ts.x,yy,item.time,Fonts.small,P.faint)

        if i<shown then
            dl:AddLine(
                imgui.ImVec2(x+20,yy+28),
