            View.drawText(x+37,rowY,item.label,Fonts.body,P.text)
            rowY=rowY+24
        end
        if #(entry.soon or {})>0 then
            View.drawText(x+20,rowY+2,I18n.text("Скоро знадобиться увага")..": "..entry.soon[1].label,Fonts.small,P.muted)
            rowY=rowY+24
        end
        local forecastParts={}
        if forecast.btcRate and forecast.btcRate>0 then forecastParts[#forecastParts+1]=string.format("%.3f BTC/год",forecast.btcRate) end
        if forecast.nextBtc then forecastParts[#forecastParts+1]=I18n.text("До наступного BTC")..": "..forecastEtaText(forecast.nextBtc) end
        if forecast.refillEta~=nil then forecastParts[#forecastParts+1]=I18n.text("До порогу заправки")..": "..forecastEtaText(forecast.refillEta) end
        if forecast.electricityEta~=nil then forecastParts[#forecastParts+1]=I18n.text("До автопоповнення")..": "..forecastEtaText(forecast.electricityEta) end
