            lua_thread.create(function() wait(350);local retryOK,retryWhy=Maintenance.start();if not retryOK and retryWhy~="__dialog_recovery__" then UI.notice=retryWhy=="__protected_dialog__" and I18n.text("Очікуємо завершення входу в гру") or tostring(retryWhy) end end)
