    local progressText=Maintenance.busy and (tostring(Maintenance.progress or 0).." / "..tostring(Maintenance.total or 0)) or (Maintenance.lastRun and os.date("%H:%M",Maintenance.lastRun) or "—")
    View.drawText(x+20,yy+80,progressText,Fonts.small,P.muted)
    if not Maintenance.busy and not Maintenance.lastRun then View.drawText(x+20,yy+101,help,Fonts.small,P.faint) end
    yy=yy+146

    local summary=Maintenance.summary or {started=0,btc=0,asc=0,electricity=0}
    local gap=10;local cardW=(w-gap*3)/4;local cardH=102
    local metrics={{"Запущено GPU",tostring(summary.started or 0)},{"Зібрано BTC",string.format("%.0f",summary.btc or 0)},{"Зібрано ASC",string.format("%.0f",summary.asc or 0)},{"Поповнено будинків",tostring(summary.electricity or 0)}}
    for i,m in ipairs(metrics) do
        local bx=x+(i-1)*(cardW+gap)
        View.shellPanel(bx,yy,cardW,cardH)
        View.drawText(bx+16,yy+16,m[1],Fonts.small,P.muted)
        View.drawText(bx+16,yy+49,m[2],Fonts.title,P.text)
    end
    yy=yy+cardH+14

    if Maintenance.lastRun then
        local visits=Maintenance.visits or {}
        local errors=Maintenance.errors or {}
        local sectionH=math.max(112,54+#visits*38+#errors*38)
        View.shellPanel(x,yy,w,sectionH)
        View.drawText(x+20,yy+16,I18n.text("Будинки для візиту")..": "..tostring(#visits),Fonts.semibold,#visits>0 and P.amber or P.green)
        local rowY=yy+48
        if #visits==0 then
            View.drawText(x+20,rowY,I18n.text("Усе, що можна було виправити автоматично — виправлено"),Fonts.body,P.muted)
            rowY=rowY+30
        else
            for _,visit in ipairs(visits) do
                View.drawText(x+20,rowY,"Дім №"..tostring(visit.house),Fonts.body,P.text)
                local reason=table.concat(visit.reasons or {}," · ")
                View.drawText(x+132,rowY,reason,Fonts.small,P.muted)
                rowY=rowY+38
            end
        end
        for _,err in ipairs(errors) do
            View.drawText(x+20,rowY,(err.house and ("Дім №"..tostring(err.house).." · ") or "")..tostring(err.message),Fonts.small,P.red)
            rowY=rowY+38
        end
        yy=yy+sectionH+12
    end
    return yy
end

