function View.analyticsPointY(value,maxValue,top,bottom)
    if not value or maxValue<=0 then return bottom end
    local t=math.max(0,math.min(1,value/maxValue))
    return bottom-(bottom-top)*t
end
function View.analyticsPointYRange(value,minValue,maxValue,top,bottom)
    if not value or maxValue<=minValue then return (top+bottom)*.5 end
    local t=math.max(0,math.min(1,(value-minValue)/(maxValue-minValue)))
    return bottom-(bottom-top)*t
end

function View.drawSmoothSeries(dl,points,color,thickness,progress)
    progress=math.max(0,math.min(1,tonumber(progress) or 1))
    local run={}
    local function flush()
        if #run<2 then run={} return end
        local segmentBudget=(#run-1)*progress
        for i=1,#run-1 do
            local segmentT=math.max(0,math.min(1,segmentBudget-(i-1)))
            if segmentT<=0 then break end
            local p0=run[math.max(1,i-1)];local p1=run[i];local p2=run[i+1];local p3=run[math.min(#run,i+2)]
            local lastX,lastY=p1.x,p1.y
            local steps=math.max(1,math.ceil(7*segmentT))
            for step=1,steps do
                local t=math.min(segmentT,step/7);local t2,t3=t*t,t*t*t
                local xx=.5*((2*p1.x)+(-p0.x+p2.x)*t+(2*p0.x-5*p1.x+4*p2.x-p3.x)*t2+(-p0.x+3*p1.x-3*p2.x+p3.x)*t3)
                local yy=.5*((2*p1.y)+(-p0.y+p2.y)*t+(2*p0.y-5*p1.y+4*p2.y-p3.y)*t2+(-p0.y+3*p1.y-3*p2.y+p3.y)*t3)
                yy=math.max(math.min(p1.y,p2.y),math.min(math.max(p1.y,p2.y),yy))
                dl:AddLine(imgui.ImVec2(lastX,lastY),imgui.ImVec2(xx,yy),color,thickness);lastX,lastY=xx,yy
            end
        end
        run={}
    end
    for _,p in ipairs(points) do if p then run[#run+1]=p else flush() end end
    flush()
end

function View.drawActualIncomeChartCard(x,y,w,h,data,period,graphProgress)
    local dl=imgui.GetWindowDrawList()
    View.drawSmoothRoundedRect(x,y,w,h,24,u32(View.panelFill(false,true),1),u32({.27,.30,.36,1},.18),1,16)
    View.drawText(x+18,y+15,I18n.text("ВИРОБІТОК"),Fonts.small,P.muted)
    View.drawHelpBubble("actual_chart",x+w-24,y+23,"Показує реальний виробіток ферми за вибраний період. Відсутність збору не вважається нульовим доходом.")
    local actualBtc=motionNumber("analytics_actual_btc_"..tostring(period),data.actualBtc or 0,650)
    local actualUsd=motionNumber("analytics_actual_usd_"..tostring(period),data.actualUsd or 0,650)
    local primary,secondary=currencyPairFromValues(actualBtc,actualUsd,false)
    View.drawText(x+18,y+40,primary,Fonts.title,currencyPrimaryIsUsd() and P.green or P.text)
    if secondary~="" then View.drawText(x+18,y+67,secondary,Fonts.small,currencyPrimaryIsUsd() and P.text or P.green) end

    local left=x+18;local right=x+w-18;local top=y+(secondary~="" and 102 or 88);local bottom=y+h-30
    local chartH=math.max(30,bottom-top)
    for i=0,3 do local yy=top+chartH*(i/3);dl:AddLine(imgui.ImVec2(left,yy),imgui.ImVec2(right,yy),u32(P.surface,.12),1) end
    local rows=data.actualRows or {};local anyData=false;local maxValue=.0001
    for _,row in ipairs(rows) do if row.seen then anyData=true;maxValue=math.max(maxValue,row.actual or 0) end end
    if not anyData then
        local empty="Ще немає даних про виробіток";local es=View.calcText(empty,Fonts.body)
        View.drawText(left+(right-left-es.x)*.5,top+(bottom-top-es.y)*.5,empty,Fonts.body,P.faint)
    end
    local points={};local count=#rows
    local rise=motionEase(math.min(1,(tonumber(graphProgress) or 1)*1.22))
    for i,row in ipairs(rows) do
        if row.seen then
            local xx=count>1 and (left+(right-left)*(i-1)/(count-1)) or left
            local targetY=View.analyticsPointY(row.actual,maxValue,top+3,bottom)
            points[i]={x=xx,y=bottom+(targetY-bottom)*rise,row=row,index=i}
        else points[i]=false end
    end
    local col=u32(P.green,.92);View.drawSmoothSeries(dl,points,col,2.0,graphProgress)
    if count>1 then
        local axisIndices={1,math.max(1,math.floor((count+1)/2)),count}
        for n,index in ipairs(axisIndices) do
            local label=View.formatAnalyticsAxisDate(rows[index].time,period);local size=View.calcText(label,Fonts.small)
            local xx=left+(right-left)*(index-1)/(count-1)
            if n==1 then View.drawText(xx,y+h-22,label,Fonts.small,P.faint) elseif n==#axisIndices then View.drawText(xx-size.x,y+h-22,label,Fonts.small,P.faint) else View.drawText(xx-size.x*.5,y+h-22,label,Fonts.small,P.faint) end
        end
    end
    imgui.SetCursorScreenPos(imgui.ImVec2(left,top));imgui.InvisibleButton("##actual_income_chart",imgui.ImVec2(right-left,bottom-top+10))
    if imgui.IsItemHovered() and count>0 then
        local mouse=imgui.GetMousePos();local idx=math.floor(((mouse.x-left)/math.max(1,right-left))*(count-1)+1.5);idx=math.max(1,math.min(count,idx))
        local row=rows[idx];local xx=count>1 and (left+(right-left)*(idx-1)/(count-1)) or left
        dl:AddLine(imgui.ImVec2(xx,top),imgui.ImVec2(xx,bottom),u32(P.text,.13),1)
        if row and row.seen then
            local yy=View.analyticsPointY(row.actual,maxValue,top+3,bottom)
            local dotColor=row.estimated and u32(P.muted,.72) or (row.partial and u32(P.green,.56) or col)
            dl:AddCircleFilled(imgui.ImVec2(xx,yy),4.2,dotColor,24)
            local p,s=currencyPairFromValues(row.actualBtc,row.actualUsd,false)
            local tip=View.formatAnalyticsDate(row.time,period).."\n"..(row.estimated and (I18n.text("Оцінка виробітку")..": ") or (I18n.text("Вироблено")..": "))..p..(s~="" and ("\n"..s) or "")
            if row.partial then tip=tip.."\n"..I18n.text("Поточний неповний період") end
            if (row.collectedBtc or 0)>0 then tip=tip.."\n"..I18n.text("Зібрано")..": "..string.format("%.2f BTC",row.collectedBtc) end
            drawTooltip("analytics_actual",tip,xx-9,top,18,bottom-top)
        end
    end
end

function View.drawBitcoinPriceChartCard(x,y,w,h,rows,period,currentPrice,graphProgress)
    local dl=imgui.GetWindowDrawList()
    View.drawSmoothRoundedRect(x,y,w,h,24,u32(View.panelFill(false,true),1),u32({.27,.30,.36,1},.18),1,16)
