    if currentPrice and Motion.btcLast and math.abs(currentPrice-Motion.btcLast)>.01 then
        Motion.btcFlashDir=currentPrice>Motion.btcLast and 1 or -1
        Motion.btcFlashStart=getGameTimer()
    end
    if currentPrice then Motion.btcLast=currentPrice end
    local animatedPrice=currentPrice and motionNumber("btc_chart_price",currentPrice,620) or nil
    local flashT=1-motionProgress(Motion.btcFlashStart,360)
    if flashT>0 and Motion.btcFlashStart>0 then
        local fc=Motion.btcFlashDir>=0 and P.green or P.red
        View.drawSmoothRoundedRect(x+13,y+34,math.min(w-26,View.calcText(animatedPrice and (formatIncomeNumber(animatedPrice,"full").." $") or "— $",Fonts.title).x+18),34,11,u32(fc,.10*flashT),nil,0,12)
    end
    local priceText=animatedPrice and (formatIncomeNumber(animatedPrice,"full").." $") or "— $"
    local firstPrice,lastPrice=nil,nil
    for _,row in ipairs(rows or {}) do
        if row.seen and row.price then firstPrice=firstPrice or row.price;lastPrice=row.price end
    end
    local pct=firstPrice and lastPrice and firstPrice>0 and ((lastPrice-firstPrice)/firstPrice*100) or nil
    local pctText=pct and string.format("%+.2f%%",pct) or ""
    local priceFont,pf=Fonts.title,Fonts.semibold
    local gap=12
    if View.calcText(priceText,priceFont).x+gap+View.calcText(pctText,pf).x>w-36 then pf=Fonts.small end
    if View.calcText(priceText,priceFont).x+gap+View.calcText(pctText,pf).x>w-36 then priceFont=Fonts.semibold end
    if View.calcText(priceText,priceFont).x+gap+View.calcText(pctText,pf).x>w-36 then priceFont=Fonts.small end
    local priceSize=View.calcText(priceText,priceFont)
    View.drawText(x+18,y+40,priceText,priceFont,P.gold)
    if pct then
        local pctSize=View.calcText(pctText,pf)
        local py=y+40+(priceFont and priceFont.Ascent*priceFont.Scale or priceSize.y)-(pf and pf.Ascent*pf.Scale or pctSize.y)
        View.drawText(x+18+priceSize.x+gap,py,pctText,pf,pct>0 and P.green or (pct<0 and P.red or P.muted))
    end
    View.drawText(x+18,y+67,"BTC / USD",Fonts.small,P.faint)
    local left=x+18;local right=x+w-18;local top=y+102;local bottom=y+h-30
    local minValue,maxValue=math.huge,-math.huge
    for _,row in ipairs(rows or {}) do if row.seen and row.price then minValue=math.min(minValue,row.price);maxValue=math.max(maxValue,row.price) end end
    local anyData=minValue<math.huge
    if anyData then
        local pad=math.max(1,(maxValue-minValue)*.12);minValue=minValue-pad;maxValue=maxValue+pad
    else minValue,maxValue=0,1 end
    for i=0,3 do local yy=top+(bottom-top)*(i/3);dl:AddLine(imgui.ImVec2(left,yy),imgui.ImVec2(right,yy),u32(P.surface,.12),1) end
    if not anyData then
        local empty=(BitcoinHistory.busy or BitcoinHourly.busy) and "Завантажуємо історію курсу…" or "Історія курсу недоступна. Повторимо запит.";local es=View.calcText(empty,Fonts.body)
        View.drawText(left+(right-left-es.x)*.5,top+(bottom-top-es.y)*.5,empty,Fonts.body,P.faint)
    end
    local points={};local count=#(rows or {});local col=u32(P.gold,.92)
    local rise=motionEase(math.min(1,(tonumber(graphProgress) or 1)*1.22))
    for i,row in ipairs(rows or {}) do
        local xx=count>1 and (left+(right-left)*(i-1)/(count-1)) or left
        local targetY=View.analyticsPointYRange(row.price,minValue,maxValue,top+3,bottom)
        points[i]={x=xx,y=bottom+(targetY-bottom)*rise,row=row,index=i}
    end
    View.drawSmoothSeries(dl,points,col,2.0,graphProgress)
    if count>1 then
        local axisIndices
        if period=="1d" and count>=5 then
            axisIndices={1,math.max(1,math.floor(1+(count-1)*.25+.5)),math.max(1,math.floor(1+(count-1)*.50+.5)),math.max(1,math.floor(1+(count-1)*.75+.5)),count}
        else
            axisIndices={1,math.max(1,math.floor((count+1)/2)),count}
        end
        for n,index in ipairs(axisIndices) do
            local label=View.formatAnalyticsAxisDate(rows[index].time,period);local size=View.calcText(label,Fonts.small);local xx=left+(right-left)*(index-1)/(count-1)
            if n==1 then View.drawText(xx,y+h-22,label,Fonts.small,P.faint) elseif n==#axisIndices then View.drawText(xx-size.x,y+h-22,label,Fonts.small,P.faint) else View.drawText(xx-size.x*.5,y+h-22,label,Fonts.small,P.faint) end
        end
    end
    imgui.SetCursorScreenPos(imgui.ImVec2(left,top));imgui.InvisibleButton("##bitcoin_price_chart",imgui.ImVec2(right-left,bottom-top+10))
    if imgui.IsItemHovered() and count>0 then
        local mouse=imgui.GetMousePos();local idx=math.floor(((mouse.x-left)/math.max(1,right-left))*(count-1)+1.5);idx=math.max(1,math.min(count,idx))
        local row=rows[idx];local xx=count>1 and (left+(right-left)*(idx-1)/(count-1)) or left
        dl:AddLine(imgui.ImVec2(xx,top),imgui.ImVec2(xx,bottom),u32(P.text,.13),1)
        if row and row.price then
            local yy=View.analyticsPointYRange(row.price,minValue,maxValue,top+3,bottom);dl:AddCircleFilled(imgui.ImVec2(xx,yy),4.2,col,24)
            drawTooltip("bitcoin_price",View.formatAnalyticsDate(row.time,period).."\nКурс: "..formatIncomeNumber(row.price,"full").." $",xx-9,top,18,bottom-top)
        end
    end
end

