function View.drawIncomeCollections(x,y,w,h,data,period)
    local dl=imgui.GetWindowDrawList()
    View.drawSmoothRoundedRect(x,y,w,h,24,u32(View.panelFill(false,false),1),u32({.27,.30,.36,1},.16),1,16)
    View.drawText(x+18,y+15,"ОСТАННІ ЗБОРИ",Fonts.small,P.muted)
    local logW=104
    if View.shellButton("##income_full_log","Повний лог",x+w-18-logW,y+9,logW,28,false) then IncomeLogUI.open=true;IncomeLogUI.closing=false;IncomeLogUI.openedAt=getGameTimer();IncomeLogUI.scroll=0 end
    local countText="Зборів · "..tostring(data.collections or 0);local cs=View.calcText(countText,Fonts.small)
    View.drawText(x+w-18-logW-16-cs.x,y+15,countText,Fonts.small,P.faint)
    local span=analyticsPeriodSpec(period);local startTime=os.time()-span;local shown=0
    for _,item in ipairs(IncomeAnalytics.collections) do
