            shown=shown+1;local yy=y+47+(shown-1)*35
            dl:AddCircleFilled(imgui.ImVec2(x+20,yy+8),3,u32(P.green,.78),16)
            local price=tonumber(item.price) or BitcoinHistory.priceAt(item.time) or tonumber(MiningModel.price)
            local usd=tonumber(item.usd) or (price and (tonumber(item.btc) or 0)*price) or nil
            local primary,secondary=currencyPairFromValues(item.btc,usd,false)
            local when=View.formatAnalyticsDate(item.time,period);local ws=View.calcText(when,Fonts.small)
            local timeX=x+w-18-ws.x
            View.drawText(timeX,yy,when,Fonts.small,P.faint)
            if item.status and item.status~="complete" then View.drawText(x+w-150,yy+16,"Частково",Fonts.small,P.amber) end
            local farms=(item.farms or 0)==1 and "1 ферма" or Runtime.plural(item.farms,"ферма","ферми","ферм")
            local fs=View.calcText(farms,Fonts.small)
            local farmsX=timeX-18-fs.x
            View.drawText(farmsX,yy,farms,Fonts.small,P.muted)
            local amountX=x+32
            local amountRight=farmsX-16
            local amountText="+"..primary
            local amountFont=Fonts.body
            if View.calcText(amountText,amountFont).x>amountRight-amountX then amountFont=Fonts.small end
            dl:PushClipRect(imgui.ImVec2(amountX,yy-6),imgui.ImVec2(math.max(amountX+4,amountRight),yy+31),true)
            View.drawText(amountX,yy-4,amountText,amountFont,currencyPrimaryIsUsd() and P.green or P.text)
            if secondary~="" then
                local secFont=Fonts.small
                local secText=secondary
                if View.calcText(secText,secFont).x>amountRight-amountX then secText="" end
                if secText~="" then View.drawText(amountX,yy+14,secText,secFont,currencyPrimaryIsUsd() and P.text or P.green) end
            end
            dl:PopClipRect()
            if shown<3 then dl:AddLine(imgui.ImVec2(x+20,yy+30),imgui.ImVec2(x+w-20,yy+30),u32(P.surface,.10),1) end
        end
    end
    if shown==0 then
        View.drawText(x+18,y+56,"Історія з'явиться після першого збору AutoMiner",Fonts.body,P.muted)
        View.drawText(x+18,y+84,"Тут зберігатимуться підтверджені збори.",Fonts.small,P.faint)
    end
end

function View.drawIncomeLogOverlay(x,y,w,h,period)
    if not IncomeLogUI.open and not IncomeLogUI.closing then return end
    imgui.OpenPopup("##income_modal")
    local sx,sy=getScreenResolution()
    w=math.min(w,900);h=math.min(sy-80,600);x=(sx-w)*.5;y=(sy-h)*.5
    local duration=Settings.animations=="off" and 1 or (Settings.animations=="reduced" and 120 or 220)
    local now=getGameTimer();local openT=math.min(1,math.max(0,(now-(IncomeLogUI.openedAt or now))/duration));openT=1-(1-openT)^3
    local closeT=IncomeLogUI.closing and math.min(1,math.max(0,(now-(IncomeLogUI.closeStarted or now))/duration)) or 0;closeT=closeT*closeT*(3-2*closeT)
    local alpha=openT*(1-closeT);local slide=(1-openT)*8-closeT*6
    imgui.SetNextWindowPos(imgui.ImVec2(x,y+slide),imgui.Cond.Always)
    imgui.SetNextWindowSize(imgui.ImVec2(w,h),imgui.Cond.Always)
    imgui.PushStyleVarFloat(imgui.StyleVar.Alpha,alpha)
    if not imgui.BeginPopupModal("##income_modal",nil,bit.bor(imgui.WindowFlags.NoTitleBar,imgui.WindowFlags.NoResize)) then imgui.PopStyleVar();return end
    local dl=imgui.GetWindowDrawList()
    dl:AddRectFilled(imgui.ImVec2(x,y+slide),imgui.ImVec2(x+w,y+h+slide),u32({0,0,0,1},.46*alpha),18)
    local pw=math.min(w-48,820);local ph=math.min(h-42,520)
    local px=x+(w-pw)*.5;local py=y+slide+(h-ph)*.5
    View.drawSmoothRoundedRect(px,py,pw,ph,22,u32({.025,.031,.037,1},.995),u32(P.surface,.28),1,18)
    View.drawText(px+20,py+16,"ПОВНИЙ ЛОГ ЗБОРІВ",Fonts.small,P.muted)
    local totalText=tostring(#IncomeAnalytics.collections).." записів"
    View.drawText(px+20,py+42,totalText,Fonts.small,P.faint)
    if View.shellButton("##close_income_log","Закрити",px+pw-104,py+12,84,28,false) then View.requestIncomeLogClose() end

    local listTop=py+76;local listBottom=py+ph-18;local rowH=46
    local visible=math.max(1,math.floor((listBottom-listTop)/rowH))
    local maxScroll=math.max(0,#IncomeAnalytics.collections-visible)
    imgui.SetCursorScreenPos(imgui.ImVec2(px+12,listTop-4));imgui.InvisibleButton("##income_log_scroll",imgui.ImVec2(pw-24,listBottom-listTop+8))
    if imgui.IsItemHovered() then
        local wheel=tonumber(imgui.GetIO().MouseWheel) or 0
        if wheel~=0 then IncomeLogUI.scroll=math.max(0,math.min(maxScroll,(IncomeLogUI.scroll or 0)-math.floor(wheel))) end
    end
    IncomeLogUI.scroll=math.max(0,math.min(maxScroll,IncomeLogUI.scroll or 0))
    dl:PushClipRect(imgui.ImVec2(px+12,listTop),imgui.ImVec2(px+pw-12,listBottom),true)
    for n=1,visible do
        local index=n+IncomeLogUI.scroll;local item=IncomeAnalytics.collections[index]
        if not item then break end
        local yy=listTop+(n-1)*rowH
        if n>1 then dl:AddLine(imgui.ImVec2(px+18,yy),imgui.ImVec2(px+pw-18,yy),u32(P.surface,.10),1) end
        dl:AddCircleFilled(imgui.ImVec2(px+24,yy+20),3,u32(P.green,.80),16)
        local stamp=tonumber(item.time) or os.time();local when=os.date("%d.%m.%Y · %H:%M",stamp)
        local price=tonumber(item.price) or BitcoinHistory.priceAt(stamp) or tonumber(MiningModel.price)
        local usd=tonumber(item.usd) or (price and (tonumber(item.btc) or 0)*price) or nil
        local primary,secondary=currencyPairFromValues(item.btc,usd,false);local amount="+"..primary
        View.drawText(px+38,yy+6,amount,Fonts.body,currencyPrimaryIsUsd() and P.green or P.text)
        if secondary~="" then View.drawText(px+38,yy+25,secondary,Fonts.small,currencyPrimaryIsUsd() and P.text or P.green) end
        local farms=(item.farms or 0)==1 and "1 ферма" or Runtime.plural(item.farms,"ферма","ферми","ферм")
        local whenSize=View.calcText(when,Fonts.small);View.drawText(px+pw-20-whenSize.x,yy+8,when,Fonts.small,P.faint)
        local farmSize=View.calcText(farms,Fonts.small);View.drawText(px+pw-20-farmSize.x,yy+27,farms,Fonts.small,P.muted)
    end
    dl:PopClipRect()
    if IncomeLogUI.closing and closeT>=.999 then IncomeLogUI.open=false;IncomeLogUI.closing=false;imgui.CloseCurrentPopup() end
    imgui.EndPopup();imgui.PopStyleVar()
end

function View.simulatorRate()
    local factor=getBtcMultiplier(MiningModel.price)
    if not factor then return nil end
    local base=GPU_BASE_RATE[math.max(1,math.min(10,Simulator.level or 10))]
    local rate=base*math.max(1,Simulator.count or 1)*factor
    if Simulator.springs then rate=rate*3 end
    if Simulator.architect then rate=rate*1.30 end
    return rate
end

function View.drawSimulatorPanel(x,y,w,h,period)
    View.drawSmoothRoundedRect(x,y,w,h,22,u32(View.panelFill(false,false),1),u32({.27,.30,.36,1},.15),1,14)
    View.drawText(x+16,y+13,"СИМУЛЯЦІЯ",Fonts.small,P.muted)
    View.drawHelpBubble("simulator",x+w-20,y+21,"Показує, скільки могла б приносити інша конфігурація GPU за поточного курсу.")
    View.drawText(x+16,y+42,"GPU "..tostring(Simulator.level).." рівня · "..tostring(Simulator.count).." шт.",Fonts.body,P.text)
    local inner=w-32
    local gap=6
    local smallW=math.max(28,math.min(34,inner*.08))
    local gpuW=math.max(48,math.min(58,inner*.14))
    local springW=math.max(78,math.min(96,inner*.23))
    local archW=math.max(88,inner-(smallW*2+gpuW*2+springW+gap*5))
    local bx=x+16
    if View.shellButton("##sim_lvl_minus","−",bx,y+72,smallW,28,false) then Simulator.level=math.max(1,(Simulator.level or 10)-1) end;bx=bx+smallW+gap
    if View.shellButton("##sim_lvl_plus","+",bx,y+72,smallW,28,false) then Simulator.level=math.min(10,(Simulator.level or 10)+1) end;bx=bx+smallW+gap
    if View.shellButton("##sim_count_minus","− GPU",bx,y+72,gpuW,28,false) then Simulator.count=math.max(1,(Simulator.count or 8)-1) end;bx=bx+gpuW+gap
    if View.shellButton("##sim_count_plus","+ GPU",bx,y+72,gpuW,28,false) then Simulator.count=math.min(20,(Simulator.count or 8)+1) end;bx=bx+gpuW+gap
    if View.shellButton("##sim_springs","Springs ×3",bx,y+72,springW,28,Simulator.springs) then Simulator.springs=not Simulator.springs end;bx=bx+springW+gap
    if View.shellButton("##sim_arch","Набір +30%",bx,y+72,archW,28,Simulator.architect) then Simulator.architect=not Simulator.architect end
    local rate=View.simulatorRate()
    local span=select(1,analyticsPeriodSpec(period))
    local forecast=rate and rate*(span/3600) or nil
    local p,s="—",""
    if forecast then p,s=currencyPairFromBtc(forecast,MiningModel.price,true) end
    View.drawText(x+16,y+h-42,p,Fonts.semibold,currencyPrimaryIsUsd() and P.green or P.text)
    if s~="" then View.drawText(x+16+View.calcText(p,Fonts.semibold).x+12,y+h-39,s,Fonts.small,currencyPrimaryIsUsd() and P.text or P.green) end
end

