function View.drawIncomePage(x,y,w,h)
    local data=IncomeAnalytics.aggregate(IncomeAnalytics.period)
    View.drawText(x+4,y+3,"Доходи",Fonts.title,P.text)
    View.drawText(x+4,y+36,"Фактичні збори, курс Bitcoin та прогноз",Fonts.small,P.muted)

    local buttons={{"1d","1 день"},{"7d","7 днів"},{"30d","30 днів"}}
    local bw,bh,gap=92,30,8;local totalW=#buttons*bw+(#buttons-1)*gap;local bx=x+w-totalW-4
    for i,item in ipairs(buttons) do
        if View.shellButton("##income_period_"..item[1],item[2],bx+(i-1)*(bw+gap),y+5,bw,bh,IncomeAnalytics.period==item[1]) then
            IncomeAnalytics.period=item[1];data=IncomeAnalytics.aggregate(IncomeAnalytics.period)
            Motion.graphStart=getGameTimer()
        end
    end

    local graphDuration=Settings.animations=="reduced" and 620 or 1320
    local graphRaw=motionProgress(Motion.graphStart,graphDuration)
    local graphProgress=graphRaw*graphRaw*graphRaw*(graphRaw*(graphRaw*6-15)+10)
    local chartLift=(Settings.animations=="full") and (1-motionSection(20,430))*7 or 0
    local metricLift=(Settings.animations=="full") and (1-motionSection(65,270))*9 or 0
    local historyLift=(Settings.animations=="full") and (1-motionSection(115,280))*9 or 0

    local chartY=y+70+chartLift;local chartGap=14;local chartW=(w-chartGap)/2;local chartH=244
    View.drawActualIncomeChartCard(x,chartY,chartW,chartH,data,IncomeAnalytics.period,graphProgress)
    View.drawBitcoinPriceChartCard(x+chartW+chartGap,chartY,chartW,chartH,data.priceRows or {},IncomeAnalytics.period,data.currentPrice,graphProgress)

    local metricY=y+70+chartH+14+metricLift;local metricGap=8;local metricW=(w-metricGap*4)/5;local metricH=102
    local effValue=data.efficiency and motionNumber("analytics_eff_"..IncomeAnalytics.period,data.efficiency,620) or nil
    local efficiency=effValue and string.format("%.1f%%",effValue) or "—"
    local effColor=data.efficiency and (data.efficiency>=90 and P.green or (data.efficiency>=70 and P.amber or P.red)) or P.muted
    View.drawAnalyticsMetric(x,metricY,metricW,metricH,"ЕФЕКТИВНІСТЬ",efficiency,data.efficiency and "За час спостереження" or "Недостатньо даних",effColor,"efficiency","Вироблено за час спостереження / можливий виробіток за той самий час. Збір старих BTC не впливає на відсоток. Якщо є прогалини або суперечливі дані, оцінку не показуємо.")

    local avgBtc=data.hasActual and motionNumber("analytics_avg_btc_"..IncomeAnalytics.period,data.averageDayBtc or 0,650) or nil
    local avgUsd=data.hasActual and motionNumber("analytics_avg_usd_"..IncomeAnalytics.period,data.averageDayUsd or 0,650) or nil
    local avgP,avgS=currencyPairFromValues(avgBtc,avgUsd,false)
    View.drawAnalyticsMetric(x+(metricW+metricGap),metricY,metricW,metricH,"СЕРЕДНІЙ ДОХІД",avgP,avgS~="" and avgS or "за день",currencyPrimaryIsUsd() and P.green or P.text,"average","Середній фактичний дохід за вибраний період.")

    local bestBtc=data.hasActual and motionNumber("analytics_best_btc_"..IncomeAnalytics.period,data.bestDayBtc or 0,650) or nil
    local bestUsd=data.hasActual and motionNumber("analytics_best_usd_"..IncomeAnalytics.period,data.bestDayUsd or 0,650) or nil
    local bestP,bestS=currencyPairFromValues(bestBtc,bestUsd,false)
    local bestDate=data.bestDay and (data.bestDay:sub(9,10).."."..data.bestDay:sub(6,7)) or "даних ще немає"
    View.drawAnalyticsMetric(x+(metricW+metricGap)*2,metricY,metricW,metricH,"НАЙКРАЩИЙ ДЕНЬ",bestP,bestS~="" and bestS or bestDate,currencyPrimaryIsUsd() and P.green or P.text,"best_day","День, у який було отримано найбільше доходу.")

    local lostBtc=motionNumber("analytics_lost_btc_"..IncomeAnalytics.period,data.lostBtc or 0,650)
    local lostUsd=motionNumber("analytics_lost_usd_"..IncomeAnalytics.period,data.lostUsd or 0,650)
    local lostP,lostS=currencyPairFromValues(lostBtc,lostUsd,false)
