        lostHelp=lostHelp.."\nGPU на паузі: "..formatBtcPlain(data.lostPaused or 0).."\nЕлектроенергія: "..formatBtcPlain(data.lostElectricity or 0).."\nПростій: "..formatBtcPlain(data.lostStalled or 0).."\nІнше: "..formatBtcPlain(data.lostOther or 0)
    end
