    dl:AddRectFilled(imgui.ImVec2(cx-thick*.5,cy+thick*.5),imgui.ImVec2(cx+thick*.5,cy+half),ink)


end

function View.collectOverview(houses)
    local result={
        owned=#houses,
        available=0,
        unavailable=0,
        unknown=0,
        btc=0,
        collectible=0,
        working=0,
        gpu=0,
        cooling=nil,
        attention={}
    }

    local coolingSum=0
    local coolingCount=0

    for _,house in ipairs(houses) do
        local available=isMiningHouseAvailable(house)
        local reason=houseAttentionReason(house)

        if available then
            result.available=result.available+1
            result.btc=result.btc+(tonumber(house.btc) or 0)
            result.collectible=result.collectible+(tonumber(house.collectible) or 0)
            result.gpu=result.gpu+(tonumber(house.gpuCount) or 0)
            result.working=result.working+(tonumber(house.workingCount) or 0)

            local coolant=tonumber(house.coolant)
            if coolant then
                coolingSum=coolingSum+coolant
                coolingCount=coolingCount+1
            end
        elseif house.miningStatus=="unavailable" then
            result.unavailable=result.unavailable+1
        else
            result.unknown=result.unknown+1
        end

        if reason and not isHouseIgnored(house.number) then
            result.attention[#result.attention+1]={
                number=house.number,
                reason=reason
            }
        end
    end

    if coolingCount>0 then
        result.cooling=coolingSum/coolingCount
    end

    return result
end

UI.collect = {phase="idle", value=0, token=0, start=nil}
function UI.collect.begin(totalBtc, totalFarms)
    local s=UI.collect
    if Runtime.busy() then return nil end
    s.token=s.token+1
    s.totalBtc=tonumber(totalBtc)
    s.totalFarms=math.max(0,tonumber(totalFarms) or 0)
    s.received=0; s.done=0; s.paidFarms={};s.operation=tostring(Runtime.sessionId or os.time()).."-"..s.token; s.value=0; s.target=0; s.velocity=0
    s.displayStartBtc=tonumber(totalBtc)
    s.phase="loading"; s.lastTick=getGameTimer(); s.reason=nil
    return s.token
end
function UI.collect.report(token, received, done, btcReliable)
    local s=UI.collect
    if token~=s.token or s.phase~="loading" then return false end
    if btcReliable==false then s.totalBtc=nil end
    s.received=math.max(s.received,tonumber(received) or 0)
    s.done=math.min(s.totalFarms,math.max(s.done,tonumber(done) or 0))
    if s.totalBtc and s.received>s.totalBtc+0.000001 then s.totalBtc=nil end
    local target=0
    if s.totalBtc and s.totalBtc>0 then target=s.received/s.totalBtc
    elseif s.totalFarms>0 then target=s.done/s.totalFarms end
    s.target=math.min(.97,math.max(s.target,target))
    return true
end
function UI.collect.complete(token)
    local s=UI.collect
    if token~=s.token or s.phase~="loading" then return false end
    s.phase="finishing"; s.target=1
    return true
end
function UI.collect.fail(token, reason)
    local s=UI.collect
    if token~=s.token or s.phase~="loading" then return false end
    s.phase="error"; s.reason=reason or "Збір перервано"; s.stateTime=getGameTimer()
    return true
end
function UI.collect.ease(t)
    t=math.max(0,math.min(1,t))
    return t*t*t*(t*(t*6-15)+10)
end
function UI.collect.tick(now)
    local s=UI.collect
    local dt=math.max(0,math.min(.05,(now-(s.lastTick or now))/1000))
    s.lastTick=now
    if Settings.animations=="off" then
        s.value=s.target or 0;s.velocity=0
        if s.phase=="finishing" then s.value=1;s.phase="success";s.stateTime=now
        elseif (s.phase=="success" and now-(s.stateTime or now)>=1900) or s.phase=="recovering" or (s.phase=="error" and now-(s.stateTime or now)>=3000) then s.phase="idle";s.value=0 end
        return
    end
    if s.phase=="loading" or s.phase=="finishing" then
        -- A bounded second-order follower keeps velocity continuous across reports.
        -- It follows confirmed progress only and cannot reach 100% before completion.
        -- Keep the ring alive between server confirmations, but never let the
        -- visual progress run far ahead of confirmed work. The final 100% still
        -- remains locked behind complete().
        local visualTarget=s.target
        if s.phase=="loading" and visualTarget<.97 then
            visualTarget=math.min(.97,visualTarget+.045)
        end
        local gap=math.max(0,visualTarget-s.value)
        local desired=math.min(.24,gap*1.8)
        s.velocity=(s.velocity or 0)+(desired-(s.velocity or 0))*(1-math.exp(-dt*7))
        local step=math.min(gap,math.max(0,s.velocity*dt))
        s.value=s.value+step
        if s.phase=="finishing" and s.value>=.9995 then
            s.value=1; s.velocity=0; s.phase="success"; s.stateTime=now
        end
    elseif s.phase=="success" and now-s.stateTime>=1900 then
        s.phase="recovering"; s.stateTime=now
    elseif s.phase=="recovering" and now-s.stateTime>=720 then
        s.phase="idle"; s.value=0; s.velocity=0
    elseif s.phase=="error" and now-s.stateTime>3000 then
        s.phase="idle"; s.value=0; s.velocity=0
    end
end
function UI.collect.visual(now)
    local s=UI.collect
    if Settings.animations=="off" then local done=s.phase=="success";return done and 0 or 1,done and 1 or 0,1,1,1 end
    local arrow,check,ring,scale=1,0,1,1
    if s.phase=="success" then
        local age=now-s.stateTime
        arrow=1-s.ease(age/200)
        check=s.ease((age-140)/560)
        scale=.94+.06*s.ease((age-140)/560)
    elseif s.phase=="recovering" then
        local t=(now-s.stateTime)/720
        check=1
        ring=1-s.ease(t)
        arrow=s.ease((t-.18)/.82)
        scale=1-.06*s.ease(t)
    end
    local checkAlpha=s.phase=="recovering" and (1-s.ease((now-s.stateTime)/520)) or 1
    return arrow,check,ring,scale,checkAlpha
end

-- Shared FlashMiner protocol for manual and scheduled collection.
-- Rows are resolved from fresh server lists; confirmations are followed by readback.
function CollectFlow.rows(text, style)
    local rows={}
    local row=(style==5) and -1 or 0
    local rack=nil
    for raw in tostring(text or ""):gmatch("[^\r\n]+") do
        local clean=stripColors(raw)
        local lower=lowerServerText(raw)
        if lower:find("стойка",1,true) then
            rack=tonumber(clean:match("[№#]?%s*(%d+)")) or rack
        end
        if row>=0 and clean:find("BTC",1,true) and clean:find("|",1,true) then
            local amount=clean:match("(%d+[.,]?%d*)%s*BTC")
            local upper=tostring(raw):upper()
            local paused=
                upper:find("{F78181}",1,true)~=nil
                or lower:find("пауза",1,true)~=nil
                or lower:find("не работает",1,true)~=nil
                or lower:find("останов",1,true)~=nil
                or lower:find("выключ",1,true)~=nil
                or lower:find("отключ",1,true)~=nil
            local active=nil
            if paused then active=false
            elseif upper:find("{BEF781}",1,true)~=nil or lower:find("работает",1,true)~=nil then active=true end
            rows[#rows+1]={row=row,btc=amount and tonumber((amount:gsub(",","."))) or nil,
                slot=tonumber(clean:match("(%d+)%s*|")),rack=rack,active=active}
        end
        row=row+1
    end
    return rows
end

function CollectFlow.ensureGpuRunning(gpu)
    if not gpu or gpu.active~=false then return false end
    if CollectFlow.id~=DIALOG_MINER_LIST then
        error(CollectFlow.problem("Не вдалося перевірити стан GPU після збору"),0)
    end
    -- Resolve the shelf again from the fresh post-withdrawal list. Response row
    -- numbers may shift if the server changed another rack while we were busy.
    for _,fresh in ipairs(CollectFlow.rows(CollectFlow.text,CollectFlow.style)) do
        if fresh.slot==gpu.slot and (gpu.rack==nil or fresh.rack==gpu.rack) then gpu=fresh;break end
    end
    if gpu.active==true then return false end
    DialogGate.stageTo("collect","gpu_start_open",{house=CollectFlow.houseNumber,rack=gpu.rack,slot=gpu.slot})
    CollectFlow.answer(DIALOG_MINER_LIST,1,gpu.row,"",collectDelay("list"),"open_gpu_for_start")
    CollectFlow.await(25244,"Відкриваємо меню GPU для запуску","Не відкрилося меню GPU",7500)

    local actionRow=nil
    local actionLabel=nil
    local row=(CollectFlow.style==5) and -1 or 0
    for raw in tostring(CollectFlow.text or ""):gmatch("[^\r\n]+") do
        if row>=0 then
            local lower=lowerServerText(raw)
            if (lower:find("видеокарт",1,true) or lower:find("відеокарт",1,true))
                and (lower:find("запуст",1,true) or lower:find("включ",1,true)
                    or lower:find("останов",1,true) or lower:find("зупин",1,true)) then
                actionRow=row;actionLabel=lower;break
            end
        end
        row=row+1
    end
    if actionRow==nil then
        CollectFlow.answer(25244,0,0,"",collectDelay("back"),"back_missing_start")
        CollectFlow.await(DIALOG_MINER_LIST,"Повертаємо список GPU","Не повернувся список GPU",7000)
        error(CollectFlow.problem("Не знайдено дію запуску GPU"),0)
    end
    if actionLabel:find("останов",1,true) or actionLabel:find("зупин",1,true) then
        CollectFlow.answer(25244,0,0,"",collectDelay("back"),"already_running")
        CollectFlow.await(DIALOG_MINER_LIST,"Перевіряємо стан GPU","Не повернувся список GPU",7000)
        return false
    end
    DialogGate.stageTo("collect","gpu_start",{house=CollectFlow.houseNumber,rack=gpu.rack,slot=gpu.slot})
    CollectFlow.answer(25244,1,actionRow,"",collectDelay("gpu"),"start_gpu")
    CollectFlow.await(DIALOG_MINER_LIST,"Запускаємо GPU після збору","Не повернулося меню після запуску GPU",8000)
    local refreshed=nil
    for _,item in ipairs(CollectFlow.rows(CollectFlow.text,CollectFlow.style)) do
        if item.slot==gpu.slot and (gpu.rack==nil or item.rack==gpu.rack) then refreshed=item;break end
    end
    if not refreshed or refreshed.active~=true then
        error(CollectFlow.problem("Запуск GPU не підтверджено сервером"),0)
    end
    return true
end
function CollectFlow.ensureHouseSelector(house)
    CollectFlow.houseNumber=house and house.number or CollectFlow.houseNumber
    CollectFlow.gpuSlot=nil;CollectFlow.gpuRack=nil;CollectFlow.failure=nil
    if CollectFlow.id==DIALOG_HOUSE then return true end
    CollectFlow.id=-1;CollectFlow.expected=DIALOG_HOUSE
    DialogGate.stageTo("collect","house_open",{house=CollectFlow.houseNumber})
    sampSendChat("/flashminer")
    CollectFlow.await(DIALOG_HOUSE,"Чекаємо вибір будинку","Не відкрився вибір будинку",8000)
    return true
end
function CollectFlow.openHouse(house)
    CollectFlow.houseNumber=house.number;CollectFlow.gpuSlot=nil;CollectFlow.gpuRack=nil
    CollectFlow.ensureHouseSelector(house)
    local row=nil
    for _,fresh in ipairs(parseHouses(CollectFlow.text)) do
        if fresh.number==house.number then
            row=fresh.row
            for _,key in ipairs({"row","city","tax","cycles","currentMoney","maxMoney"}) do house[key]=fresh[key] end
            break
        end
    end
    if row==nil then error("Будинок відсутній у списку сервера",0) end
    CollectFlow.answer(DIALOG_HOUSE,1,row,"",collectDelay("house"),"select_house")
    CollectFlow.await(DIALOG_MINER_LIST,"Чекаємо список GPU","Не відкрився список GPU",8000)
end
function CollectFlow.closeHouse(keepSelector)
    CollectFlow.answer(DIALOG_MINER_LIST,0,0,"",collectDelay("close"),"close_gpu_list")
    CollectFlow.await(DIALOG_HOUSE,"Повертаємо вибір будинку","Не повернувся вибір будинку",7000)
    if not keepSelector then
        CollectFlow.answer(DIALOG_HOUSE,0,0,"",collectDelay("close"),"close_house_selector")
    end
end
function CollectFlow.refreshHouse(house)
    local stats=parseMinerStats(CollectFlow.text)
    Runtime.apply(house,stats)
    house.scanned=true
    RateTracker.sample(house)
    ForecastTracker.sample(house)
    MiningModel.sample(house)
    IncomeAnalytics.observeHouse(house)
end
function CollectFlow.run(token)
    local s=UI.collect
    local cycleStarted=getGameTimer()
    local queue={}
    s.stage="Перевіряємо баланс…"
    for _,house in ipairs(UI.houses) do
        if house.miningStatus=="available" or (house.miningStatus==nil and house.scanned) then
            queue[#queue+1]={house=house}
        end
    end
    if #queue==0 then error("Немає доступних ферм",0) end
    s.totalFarms=#queue

    for index,entry in ipairs(queue) do
        local houseStarted=getGameTimer()
        s.stage="Перевірка ферми "..index.." / "..#queue
        CollectFlow.openHouse(entry.house)
        entry.rows=CollectFlow.rows(CollectFlow.text,CollectFlow.style)
        if #entry.rows==0 and (tonumber(entry.house.gpuCount) or 0)>0 then
            error("Не вдалося прочитати список GPU",0)
        end
        CollectFlow.refreshHouse(entry.house)

        for gpuIndex,planned in ipairs(entry.rows) do
            s.stage="GPU "..gpuIndex.." / "..#entry.rows
            CollectFlow.gpuSlot=planned.slot or gpuIndex
            CollectFlow.gpuRack=planned.rack
            DialogGate.stageTo("collect","gpu_prepare",{house=entry.house.number,rack=CollectFlow.gpuRack,slot=CollectFlow.gpuSlot})
            local current=CollectFlow.rows(CollectFlow.text,CollectFlow.style)
            local gpu=nil
            for _,item in ipairs(current) do
                if item.slot==planned.slot and (planned.rack==nil or item.rack==planned.rack) then gpu=item; break end
            end
            if not gpu then error("Склад GPU змінився — оновіть список",0) end
            if not gpu.btc or not planned.btc or math.floor(gpu.btc)~=math.floor(planned.btc) then
                s.totalBtc=nil
            end

            local wasPaused=(gpu.active==false)
            if not gpu.btc or gpu.btc>=1 then
                CollectFlow.answer(DIALOG_MINER_LIST,1,gpu.row,"",collectDelay("list"),"open_gpu")
                CollectFlow.await(25244,"Відкриваємо меню GPU","Не відкрилося меню GPU",7500)
                CollectFlow.withdrawAndRead(entry.house)

                local after=nil
                for _,item in ipairs(CollectFlow.rows(CollectFlow.text,CollectFlow.style)) do
                    if item.slot==gpu.slot and (gpu.rack==nil or item.rack==gpu.rack) then after=item.btc; break end
                end
                if not after or not gpu.btc then error("Не вдалося підтвердити баланс GPU",0) end

                if CollectFlow.tooLow then
                    if after>=1 then error("Сервер відхилив виведення BTC",0) end
                else
                    local withdrawn=CollectFlow.confirmAmount or math.floor(gpu.btc)
                    if gpu.btc-after<math.floor(gpu.btc)-.1 then
                        error("Виведення BTC не підтверджено балансом",0)
                    end
                    s.received=s.received+withdrawn
                    RateTracker.withdrawn[entry.house.number]=(RateTracker.withdrawn[entry.house.number] or 0)+withdrawn
                    s.paidFarms[entry.house.number]=true
                    local farms=0;for _ in pairs(s.paidFarms) do farms=farms+1 end
                    Runtime.log("WITHDRAW_CONFIRMED","operation="..s.operation.." house="..entry.house.number.." slot="..tostring(gpu.slot).." btc="..withdrawn)
                    if not IncomeAnalytics.recordCollection(s.received,farms,s.source,"in_progress",s.operation) then error("Не вдалося зберегти результат збору",0) end
                end

                CollectFlow.withdrawing=false
                CollectFlow.refreshHouse(entry.house)
                s.report(token,s.received,index-1,s.totalBtc~=nil)
            end

            if wasPaused then
                s.stage="Запускаємо GPU після збору · "..gpuIndex.." / "..#entry.rows
                CollectFlow.ensureGpuRunning(gpu)
                CollectFlow.refreshHouse(entry.house)
            end
        end

        CollectFlow.refreshHouse(entry.house)
        s.report(token,s.received,index,s.totalBtc~=nil)
        CollectFlow.closeHouse(index<#queue)
        CollectFlow.gpuRack=nil;CollectFlow.gpuSlot=nil
        Runtime.log("COLLECT_HOUSE_TIMING","house="..tostring(entry.house.number).." ms="..tostring(getGameTimer()-houseStarted).." gpus="..tostring(#entry.rows))
    end

    Runtime.log("COLLECT_CYCLE_TIMING","ms="..tostring(getGameTimer()-cycleStarted).." houses="..tostring(#queue).." btc="..tostring(s.received))
    UI.lastScanTime=getGameTimer()
    RateTracker.btc=nil; RateTracker.sampleTime=nil
end
UI.collect.start=function(snapshot,token)
    local claimed,owner=DialogGate.claim("collect","start",{})
    if not claimed then error("AutoMiner зайнятий: "..tostring(owner),0) end
    CollectFlow.inventoryCredit=nil;CollectFlow.confirmation=nil;CollectFlow.confirmSent=false;CollectFlow.confirmFingerprint=nil
    CollectFlow.houseNumber=nil;CollectFlow.gpuSlot=nil;CollectFlow.gpuRack=nil;CollectFlow.expected=nil
    MiningModel.epoch=MiningModel.epoch+1
    for _,house in ipairs(UI.houses or {}) do
        house.performanceCandidateSamples=0
        house.performanceCandidateRatio=nil
        house.performanceRatio=nil
        house.performanceObservedAt=nil
        house.performanceConfirmedSamples=0
    end
    UI.collecting=true
    UI.dialogCaptured=false
    CollectFlow.id=-1; CollectFlow.failure=nil
    Runtime.log("COLLECT_START","operation="..UI.collect.operation.." source="..tostring(UI.collect.source))
    local generation=Runtime.generation
    lua_thread.create(function()
        local ok,reason=pcall(CollectFlow.run,token)
        local received=tonumber(UI.collect.received) or 0
        local source=UI.collect.source or "manual"
        local taxOK,taxError=true,nil
        if received>0 and ok and generation==Runtime.generation and Runtime.ready() then
            local callOK,runOK,runResult=pcall(Taxes.run)
            if not callOK then
                taxOK=false;taxError=runOK
            elseif runOK==false and runResult~="disabled" then
                taxOK=false;taxError=runResult or "Податки не перевірено"
            end
        end
        local farms=0;for _ in pairs(UI.collect.paidFarms or {}) do farms=farms+1 end
        local saved,saveError=pcall(IncomeAnalytics.recordCollection,received,farms,source,ok and "complete" or "partial",UI.collect.operation)
        if not saved or saveError==false then Runtime.failure(tostring(saveError)) end
        UI.collecting=false;UI.balanceUpdating=false;Taxes.busy=false
        Scheduler.blocked=nil
        CollectFlow.withdrawing=false;CollectFlow.inventoryCredit=nil
        CollectFlow.confirmation=nil;CollectFlow.confirmSent=false;CollectFlow.gpuRack=nil;CollectFlow.gpuSlot=nil
        if generation==Runtime.generation and Runtime.ready() and (CollectFlow.id==DIALOG_HOUSE or CollectFlow.id==DIALOG_MINER_LIST or CollectFlow.id==25244) then
            pcall(DialogGate.tx,"collect",CollectFlow.id,0,0,"",140,"collect_cleanup")
        end
        if DialogGate.owner=="collect" then DialogGate.release("collect") end
        CollectFlow.id=-1;CollectFlow.expected=nil
        if ok then UI.collect.complete(token) else UI.collect.fail(token,tostring(reason)) end
        if not taxOK then Runtime.log("TAX_ERROR",taxError);UI.notice="Податки не перевірено" end
        Runtime.log(ok and "COLLECT_DONE" or "COLLECT_PARTIAL","operation="..UI.collect.operation.." btc="..received.." reason="..tostring(reason))
        if not ok then UI.notice=tostring(reason);pcall(pushActivity,"Збір перервано",tostring(reason),"amber") end
        local collectedUsd=MiningModel.price and received*MiningModel.price or nil
        if ok then Notify.event("collect_result",{btc=received,usd=collectedUsd})
        else Notify.event("collect_error",{reason=tostring(reason)}) end
        if generation~=Runtime.generation then return end
        if ok then
            Scheduler.retryAt=0;Scheduler.retryUsed=false
            if Settings.collectMode~="manual" then scheduleNextCollection(true) end
        elseif source~="manual" and Settings.autoRetry~=false and not Scheduler.retryUsed then
            Scheduler.retryUsed=true;Scheduler.retryAt=os.time()+30
        elseif Settings.collectMode~="manual" then
            Scheduler.retryAt=0;Scheduler.retryUsed=false;scheduleNextCollection(true)
        end
    end)
end

function UI.collect.trigger(source)
    if not Runtime.ready() then return false,"Очікуємо готовності гри" end
    if Taxes.recording or Taxes.busy then return false,"Зараз налаштовується оплата податків" end
    if UI.collecting then return false,"Збір уже запущено" end
    if Maintenance.busy then return false,"Триває обслуговування" end
    if AutoRefill.active then return false,"Спочатку зупиніть автозаправку" end
    if Electricity.busy or Electricity.checking then return false,"Триває перевірка електроенергії" end
    if UI.balanceUpdating then return false,"Оновлюємо баланс ферм — зачекайте кілька секунд" end
    if UI.loading or UI.waiting or UI.scanning then return false,"Перевіряємо ферми — зачекайте кілька секунд" end
    if Runtime.dataReady==false or #(UI.houses or {})==0 then
        local started=requestHouses(true)
        if started then return false,"Оновлюємо список ферм — повторіть збір після перевірки" end
        return false,UI.notice or "Не вдалося оновити список ферм"
    end
    if Runtime.busy() then return false,"AutoMiner зайнятий" end
    if Runtime.foreignDialog() then
        local ready,state=Runtime.requestAutomationDialogClose("collect")
        if not ready then
            if state=="closing" then return false,"__dialog_recovery__" end
            if state=="protected" then return false,"__protected_dialog__" end
            return false,"__dialog_blocked__"
        end
    end
    local d=View.collectOverview(UI.houses or {})
    local s=UI.collect
    if d.available<=0 then return false,"Немає доступних ферм" end
    if (tonumber(d.collectible) or 0)<1 then return false,"Немає BTC до збору" end
    local token=s.begin(d.collectible,d.available)
    if not token then return false,"Збір уже запущено" end
    s.source=source or "manual"
    if source~="retry" then Scheduler.retryUsed=false end
    local ok,err=pcall(s.start,{btc=d.btc,farms=d.available},token)
    if not ok then
        if DialogGate.owner=="collect" then DialogGate.release("collect") end
        s.fail(token,"Не вдалося почати збір")
        return false,tostring(err)
    end
    return true
end

function View.drawCollectAction(x,y,w,h,d)
    local s=UI.collect
    local now=getGameTimer()
    s.tick(now)
    local enabled=not Runtime.busy() and type(s.start)=="function"
        and d.collectible>=1 and not UI.pendingUserHouse and not UI.balanceUpdating and not UI.collecting and not UI.waiting and not UI.scanning and not UI.loading
    imgui.SetCursorScreenPos(imgui.ImVec2(x,y))
    imgui.InvisibleButton("##collect_all_btc",imgui.ImVec2(w,h))
    local hovered=imgui.IsItemHovered()
    local pressed=enabled and imgui.IsItemActive()
    if imgui.IsItemClicked(0) then
        local ok,why=UI.collect.trigger("manual")
        if not ok and why=="__dialog_recovery__" then
            UI.notice=I18n.text("Закриваємо відкрите меню…")
            lua_thread.create(function()
                wait(350)
                if Runtime.ready() and not UI.collecting and not Runtime.busy() then
                    local retryOK,retryWhy=UI.collect.trigger("manual")
                    if not retryOK and retryWhy~="__dialog_recovery__" then
                        if retryWhy=="__protected_dialog__" then
                            UI.notice=I18n.text("Очікуємо завершення входу в гру")
                        else
                            UI.notice=I18n.text(tostring(retryWhy or "Не вдалося почати збір"))
                            Runtime.log("COLLECT_BLOCKED",tostring(retryWhy or "unknown"))
                            Notify.event("collect_error",{reason=UI.notice})
                        end
                    end
                end
            end)
        elseif not ok then
            if why=="__protected_dialog__" then
                UI.notice=I18n.text("Очікуємо завершення входу в гру")
            else
                UI.notice=I18n.text(tostring(why or "Не вдалося почати збір"))
                Runtime.log("COLLECT_BLOCKED",tostring(why or "unknown"))
                Notify.event("collect_error",{reason=UI.notice})
            end
        end
    end
    local dl=imgui.GetWindowDrawList()
    local accent=s.phase=="error" and P.amber or P.green
    local alpha=smoothAnim("collect_enabled",(enabled or s.phase~="idle") and 1 or .62,8)
    local arrow,check,ring,iconScale,checkAlpha=s.visual(now)
    local hover=smoothAnim("collect_hover",hovered and 1 or 0,10)
    local r=math.min(w,h)*.46
    local cx,cy=x+w*.5,y+h*.5+(pressed and 1 or 0)
    dl:AddCircleFilled(imgui.ImVec2(cx,cy),r,u32({.065,.080,.078,1},1),96)
    dl:AddCircleFilled(imgui.ImVec2(cx,cy),r-13,u32(accent,.045+.035*hover),80)
    dl:AddCircle(imgui.ImVec2(cx,cy),r,u32(accent,(.30+.20*hover)*alpha),96,1.4)
    dl:AddCircle(imgui.ImVec2(cx,cy),r-14,u32(P.muted,.20*alpha),80,1)
    local rr=r-7
    dl:AddCircle(imgui.ImVec2(cx,cy),rr,u32(P.muted,.10),80,2)
    local function line(ax,ay,bx,by,col,thick)
        dl:AddLine(imgui.ImVec2(ax,ay),imgui.ImVec2(bx,by),col,thick or 2.2)
    end
    if s.value>0 and ring>0 then
        local steps=math.max(2,math.ceil(s.value*180))
        dl:PathClear()
        for i=0,steps do
            local a=-math.pi/2+2*math.pi*s.value*i/steps
            dl:PathLineTo(imgui.ImVec2(cx+math.cos(a)*rr,cy+math.sin(a)*rr))
        end
        dl:PathStroke(u32(accent,.95*ring),false,2.2)
        local a=-math.pi/2+2*math.pi*s.value
        dl:AddCircleFilled(imgui.ImVec2(cx+math.cos(a)*rr,cy+math.sin(a)*rr),1.1,u32(accent,.95*ring),16)
    end
    if arrow>.001 then
        local col=u32(accent,alpha*arrow)
        local shift=(1-arrow)*3
        local thick=2.0
        line(cx,cy-13+shift,cx,cy+3+shift,col,thick)
        dl:PathClear()
        for _,p in ipairs({{-7,-3},{0,4},{7,-3}}) do dl:PathLineTo(imgui.ImVec2(cx+p[1],cy+p[2]+shift)) end
        dl:PathStroke(col,false,thick)
        dl:PathClear();dl:PathLineTo(imgui.ImVec2(cx-12,cy+5+shift))
        for i=0,10 do local a=math.pi-i*math.pi/20;dl:PathLineTo(imgui.ImVec2(cx-10+2*math.cos(a),cy+10+shift+2*math.sin(a))) end
        for i=0,10 do local a=math.pi*.5-i*math.pi/20;dl:PathLineTo(imgui.ImVec2(cx+10+2*math.cos(a),cy+10+shift+2*math.sin(a))) end
        dl:PathLineTo(imgui.ImVec2(cx+12,cy+5+shift));dl:PathStroke(col,false,thick)
        for _,p in ipairs({{0,-13},{-7,-3},{7,-3},{-12,5},{12,5}}) do
            dl:AddCircleFilled(imgui.ImVec2(cx+p[1],cy+p[2]+shift),thick*.5,col,20)
        end
    end
    if check>0 and checkAlpha>0 then
        local ax,ay=cx-12*iconScale,cy
        local bx,by=cx-3*iconScale,cy+9*iconScale
        local ex,ey=cx+14*iconScale,cy-11*iconScale
        local first=math.sqrt(162)
        local second=math.sqrt(689)
        local length=check*(first+second)
        local px,py
        dl:PathClear(); dl:PathLineTo(imgui.ImVec2(ax,ay))
        if length<=first then
            px=ax+(bx-ax)*length/first; py=ay+(by-ay)*length/first
        else
            dl:PathLineTo(imgui.ImVec2(bx,by))
            local t=(length-first)/second
            px=bx+(ex-bx)*t; py=by+(ey-by)*t
        end
        dl:PathLineTo(imgui.ImVec2(px,py))
        local col=u32(accent,alpha*checkAlpha)
        dl:PathStroke(col,false,2.4)
        dl:AddCircleFilled(imgui.ImVec2(ax,ay),1.2,col,16)
        dl:AddCircleFilled(imgui.ImVec2(px,py),1.2,col,16)
    end

end


function View.drawHomePage(x,y,w,h,houses)
    local d=View.collectOverview(houses)
    local dl=imgui.GetWindowDrawList()
    local gap=14
    local income,maximumIncome=updateIncomeEstimate()
    local animatedIncome=income and motionNumber("home_income_rate",income,620) or nil
    local incomeValue,incomeSub=incomeTexts(animatedIncome)
    if Runtime.dataUnknown() then incomeValue="—";incomeSub="Відновлюємо дані" end

    local heroLift=(Settings.animations=="full") and (1-motionSection(0,250))*8 or 0
    local tileLift=(Settings.animations=="full") and (1-motionSection(45,260))*9 or 0
    local historyLift=(Settings.animations=="full") and (1-motionSection(95,275))*9 or 0
    local heroY=y+heroLift

    local reservoirW=math.max(188,math.floor(w*.235))
    local miningW=w-reservoirW-gap
    local topH=184

    View.shellPanel(x,heroY,miningW,topH)

    View.drawSmoothRoundedRect(
        x+4,heroY+4,
        math.min(miningW*.46,330),
        topH-8,
        25,
        u32({.055,.061,.073,1},.10),
        nil,0,16
    )

    local actionSize=108
    View.drawText(x+24,heroY+20,"ВАШ МАЙНІНГ",Fonts.small,P.muted)
    local collect=UI.collect
    collect.tick(getGameTimer())
    local actualCollectible=tonumber(d.collectible) or 0
    local collectionVisual=(collect.phase=="loading" or collect.phase=="finishing"
        or collect.phase=="success" or collect.phase=="recovering")
    local visualCollectible=actualCollectible
    if collectionVisual and tonumber(collect.displayStartBtc) then
        visualCollectible=math.max(0,(tonumber(collect.displayStartBtc) or 0)
            *(1-math.max(0,math.min(1,collect.value or 0))))
    end

    local primaryIsUsd=currencyPrimaryIsUsd()
    local heroPrimary,heroSecondary
    if primaryIsUsd then
        local visualUsd=MiningModel.price and visualCollectible*MiningModel.price or nil
        if collectionVisual then
            motionSyncNumber("home_collectible_primary_usd",visualUsd or 0)
        else
            visualUsd=motionNumber("home_collectible_primary_usd",
                MiningModel.price and actualCollectible*MiningModel.price or 0,720)
        end
        heroPrimary=formatUsdPlain(MiningModel.price and visualUsd or nil,true)
        heroSecondary=(Settings.incomeMode=="money_btc") and formatBtcPlain(actualCollectible) or ""
    else
        local visualBtc
        if collectionVisual then
            visualBtc=motionSyncNumber("home_collectible_primary_btc",visualCollectible)
        else
            visualBtc=motionNumber("home_collectible_primary_btc",actualCollectible,720)
        end
        heroPrimary=formatBtcPlain(visualBtc)
        heroSecondary=(Settings.incomeMode=="both")
            and formatUsdPlain(MiningModel.price and actualCollectible*MiningModel.price or nil,true) or ""
    end

    if Runtime.dataUnknown() then heroPrimary="—";heroSecondary="Відновлюємо дані" end
    local heroFont=Fonts.dashboard
    local heroAvailable=math.max(180,miningW-actionSize-78)
    if View.calcText(heroPrimary,heroFont).x>heroAvailable then heroFont=Fonts.title end
    if View.calcText(heroPrimary,heroFont).x>heroAvailable then heroFont=Fonts.semibold end
    View.drawText(x+24,heroY+54,heroPrimary,heroFont,primaryIsUsd and P.green or P.text)
    if heroSecondary~="" then
        View.drawText(x+24,heroY+96,heroSecondary,Fonts.semibold,primaryIsUsd and P.text or P.green)
    end
    local status=(Settings.collectMode~="manual") and ("Наступний збір · "..nextCollectionText()) or "Доступно до збору"
    if collect.phase=="loading" or collect.phase=="finishing" then
        status=collect.stage=="Перевіряємо баланс…" and collect.stage or ("Збір · "..collect.done.." / "..collect.totalFarms)
    elseif collect.phase=="success" or collect.phase=="recovering" then
        local collectedPrimary=currencyPairFromBtc(collect.received,MiningModel.price,true)
        status="Зібрано "..collectedPrimary
    elseif collect.phase=="error" then status="Збір перервано" end
    if Runtime.dataUnknown() then status=UI.notice or "Відновлюємо дані" end
    View.drawRollingText("hero_status",x+24,heroY+(heroSecondary~="" and 124 or 104),status,Fonts.body,P.muted)

    View.drawCollectAction(x+miningW-actionSize-24,heroY+(topH-actionSize)*.5,actionSize,actionSize,d)

    local coolingValue,coolingHouse=View.coolingValue(houses,os.time())
    View.drawCoolingReservoir(
        x+miningW+gap,
        heroY,
        reservoirW,
        topH,
        coolingValue,
        coolingHouse
    )

    local tilesY=y+topH+gap+tileLift
    local tileH=188
    local tileW=(w-gap*3)/4

    local attentionClicked,attentionItem=View.drawAttentionTile(
        x,tilesY,tileW,tileH,d.attention
    )

    if attentionClicked and attentionItem then
        switchTab("houses")
        UI.focusHouse=attentionItem.number
        kickWater(1,.45)
    end

    local gpuX=x+(tileW+gap)
    local gpuAccent=d.gpu>0 and d.working==d.gpu and P.green or P.amber

    View.drawMetricTile(
        gpuX,tilesY,tileW,tileH,
        "GPU ПРАЦЮЮТЬ",
        Runtime.dataUnknown() and "—" or tostring(math.floor((motionNumber("home_gpu_working",d.working or 0,520) or 0)+.5)).." / "..tostring(math.floor((motionNumber("home_gpu_total",d.gpu or 0,520) or 0)+.5)),
        d.gpu>0 and (d.working==d.gpu and "Усі активні" or "Є GPU на паузі") or "Даних немає",
        P.text,
        false,
        "##home_gpu_tile",
        "gpu",
        gpuAccent
    )

    local incomeX=x+(tileW+gap)*2

    View.drawMetricTile(
        incomeX,tilesY,tileW,tileH,
        "ДОХІД ЗА ГОДИНУ",
        incomeValue,
        incomeSub,
        ((Settings.incomeMode=="money_btc" or Settings.incomeMode=="virtual") and P.green or P.text),
        false,
        "##home_income_tile",
        "income",
        P.green
    )

    local housesX=x+(tileW+gap)*3

    if View.drawMetricTile(
        housesX,tilesY,tileW,tileH,
        "БУДИНКИ",
        Runtime.dataUnknown() and "—" or tostring(math.floor((motionNumber("home_houses_owned",d.owned or 0,520) or 0)+.5)).." / "..tostring(math.max(15,d.owned)),
        Runtime.dataUnknown() and "Відновлюємо дані" or (d.available>0 and tostring(d.available).." з майнінгом" or "Немає доступних"),
        P.text,
        true,
        "##home_houses_tile",
        "houses",
        P.muted
    ) then
        switchTab("houses")
        kickWater(1,.42)
    end

    local historyY=y+topH+gap+tileH+gap+historyLift
    local historyH=154
    View.drawHistoryPanel(x,historyY,w,historyH)

    local problemsY=historyY+historyH+gap
    View.drawProblemCenterPanel(x,problemsY,w,150)
end

function View.ignoredList()
    local list,seen={},{}
    for id in pairs(Ignored) do
        local n=tonumber(id) or id;local k=tostring(n)
        if not seen[k] then list[#list+1]=n;seen[k]=true end
    end
    table.sort(list,function(a,b) return (tonumber(a) or 0)<(tonumber(b) or 0) end)
    return list
end

local SettingSliderState={}
function View.drawSettingSlider(id,x,y,w,value,minValue,maxValue,step,accent)
    value=tonumber(value) or minValue
    minValue=tonumber(minValue) or 0
    maxValue=math.max(minValue+1,tonumber(maxValue) or 100)
    step=math.max(.0001,tonumber(step) or 1)
    local h=28

    imgui.SetCursorScreenPos(imgui.ImVec2(x,y))
    imgui.InvisibleButton("##slider_"..id,imgui.ImVec2(w,h))
    local hovered=imgui.IsItemHovered()
    local active=imgui.IsItemActive()
    local changed=false

    if active and imgui.IsMouseDown(0) then
        SettingSliderState[id]=true
        local mouse=imgui.GetMousePos()
        local t=math.max(0,math.min(1,(mouse.x-x)/math.max(1,w)))
        local raw=minValue+(maxValue-minValue)*t
        local nextValue=math.floor(raw/step+.5)*step
        nextValue=math.max(minValue,math.min(maxValue,nextValue))
        if math.abs(nextValue-value)>.0001 then value=nextValue;changed=true end
    end

    local targetT=math.max(0,math.min(1,(value-minValue)/(maxValue-minValue)))
    local t=smoothAnim("setting_slider_"..id,targetT,20)
    local cy=y+h*.5
    local dl=imgui.GetWindowDrawList()
