    local activeT=smoothAnim("setting_slider_active_"..id,active and 1 or 0,20)
    local trackH=4.0+hoverT*.5
    dl:AddRectFilled(imgui.ImVec2(x,cy-trackH*.5),imgui.ImVec2(x+w,cy+trackH*.5),u32({.090,.104,.116,1},.92),trackH*.5)
    if t>0 then
        dl:AddRectFilled(imgui.ImVec2(x,cy-trackH*.5),imgui.ImVec2(x+w*t,cy+trackH*.5),u32(accent or P.green,.72+.12*activeT),trackH*.5)
    end
    local knobX=x+w*t
    dl:AddCircleFilled(imgui.ImVec2(knobX,cy),10+hoverT*1.2,u32(accent or P.green,.055+.055*hoverT),36)
    dl:AddCircleFilled(imgui.ImVec2(knobX,cy),6.6+activeT*.6,u32(mixColor(P.muted,P.text,math.max(hoverT,activeT)),.98),32)
    dl:AddCircle(imgui.ImVec2(knobX,cy),8.6+hoverT*.7,u32(accent or P.green,.20+.18*hoverT),32,1)

    local released=false
    if not active and SettingSliderState[id] then SettingSliderState[id]=nil;released=true end
    return value,changed,released
end


function View.drawRangeSettingSlider(id,x,y,w,minCurrent,maxCurrent,minValue,maxValue,step,accent)
    minCurrent=tonumber(minCurrent) or minValue
    maxCurrent=tonumber(maxCurrent) or maxValue
    minValue=tonumber(minValue) or 0
    maxValue=math.max(minValue+1,tonumber(maxValue) or 100)
    step=math.max(.0001,tonumber(step) or 1)
    minCurrent=math.max(minValue,math.min(maxValue,minCurrent))
    maxCurrent=math.max(minCurrent,math.min(maxValue,maxCurrent))
    local h=30

    imgui.SetCursorScreenPos(imgui.ImVec2(x,y))
    imgui.InvisibleButton("##range_slider_"..id,imgui.ImVec2(w,h))
    local hovered=imgui.IsItemHovered()
    local active=imgui.IsItemActive()
    local changed=false
    local mouse=imgui.GetMousePos()

    local minT=(minCurrent-minValue)/(maxValue-minValue)
    local maxT=(maxCurrent-minValue)/(maxValue-minValue)
    if active and imgui.IsMouseDown(0) then
        local rawT=math.max(0,math.min(1,(mouse.x-x)/math.max(1,w)))
        local pick=SettingSliderState["range_"..id]
        if not pick then
            pick=(minT==maxT and rawT>=maxT) and "max" or (math.abs(rawT-minT)<=math.abs(rawT-maxT) and "min" or "max")
            SettingSliderState["range_"..id]=pick
        end
        local raw=minValue+(maxValue-minValue)*rawT
        local nextValue=math.floor(raw/step+.5)*step
        nextValue=math.max(minValue,math.min(maxValue,nextValue))
        if pick=="min" then
            nextValue=math.min(nextValue,maxCurrent)
            if math.abs(nextValue-minCurrent)>.0001 then minCurrent=nextValue;changed=true end
        else
            nextValue=math.max(nextValue,minCurrent)
            if math.abs(nextValue-maxCurrent)>.0001 then maxCurrent=nextValue;changed=true end
        end
    end

    local minDraw=smoothAnim("range_min_"..id,(minCurrent-minValue)/(maxValue-minValue),20)
    local maxDraw=smoothAnim("range_max_"..id,(maxCurrent-minValue)/(maxValue-minValue),20)
    local hoverT=smoothAnim("range_hover_"..id,hovered and 1 or 0,16)
    local activeT=smoothAnim("range_active_"..id,active and 1 or 0,20)
    local cy=y+h*.5
    local dl=imgui.GetWindowDrawList()
    local trackH=4+hoverT*.5
    dl:AddRectFilled(imgui.ImVec2(x,cy-trackH*.5),imgui.ImVec2(x+w,cy+trackH*.5),u32({.090,.104,.116,1},.92),trackH*.5)
    dl:AddRectFilled(imgui.ImVec2(x+w*minDraw,cy-trackH*.5),imgui.ImVec2(x+w*maxDraw,cy+trackH*.5),u32(accent or P.green,.74+.10*activeT),trackH*.5)

    for _,tx in ipairs({minDraw,maxDraw}) do
        local knobX=x+w*tx
        dl:AddCircleFilled(imgui.ImVec2(knobX,cy),10+hoverT*1.1,u32(accent or P.green,.05+.05*hoverT),36)
        dl:AddCircleFilled(imgui.ImVec2(knobX,cy),6.5+activeT*.5,u32(mixColor(P.muted,P.text,math.max(hoverT,activeT)),.98),32)
        dl:AddCircle(imgui.ImVec2(knobX,cy),8.5+hoverT*.7,u32(accent or P.green,.20+.18*hoverT),32,1)
    end

    local released=false
    if not active and SettingSliderState["range_"..id] then
        SettingSliderState["range_"..id]=nil
        released=true
    end
    return minCurrent,maxCurrent,changed,released
end

function View.electricitySliderMax()
