formatDurationMinutes=function(minutes)
    minutes=math.max(0,math.floor(tonumber(minutes) or 0))
    local h=math.floor(minutes/60);local m=minutes%60
    if h>0 and m>0 then return tostring(h).." год "..tostring(m).." хв" end
    if h>0 then return tostring(h).." год" end
    return tostring(m).." хв"
end

scheduleNextCollection=function(force)
    local mode=Settings.collectMode or "manual"
    if mode=="manual" then Settings.nextCollectAt=0;return end
    local now=os.time()
    if not force and (tonumber(Settings.nextCollectAt) or 0)>now then return end
    local minutes
    if mode=="smart" then
        local a=math.max(1,math.floor(tonumber(Settings.smartMinMinutes) or 120))
        local b=math.max(a,math.floor(tonumber(Settings.smartMaxMinutes) or 240))
        minutes=math.random(a,b)
    else
        minutes=math.max(1,math.floor(tonumber(Settings.timerMinutes) or 120))
    end
    Settings.nextCollectAt=now+minutes*60
    saveSettings()
end

nextCollectionText=function()
    if (Settings.collectMode or "manual")=="manual" then return "вручну" end
    if Settings.autoPaused then return "на паузі" end
    local remain=(tonumber(Settings.nextCollectAt) or 0)-os.time()
    if remain<=0 then return "зараз" end
    return formatDurationMinutes(math.ceil(remain/60))
end


function View.autoCollectModeLabel()
    if Settings.collectMode=="smart" then return "Випадковий" end
    if Settings.collectMode=="timer" then return "Таймер" end
    return "Вимкнено"
end

function View.autoCollectStateText()
    if Settings.collectMode=="manual" or Settings.autoPaused then return "Вимкнено" end
    return "Увімкнено"
end

function View.toggleAutoPause()
    if Settings.collectMode=="manual" then return end
    Settings.autoPaused=not Settings.autoPaused
    if not Settings.autoPaused and (tonumber(Settings.nextCollectAt) or 0)<=0 then scheduleNextCollection(true) end
    saveSettings()
    Journal.add("system",Settings.autoPaused and "Автозбір призупинено" or "Автозбір відновлено",
        Settings.autoPaused and "Планувальник тимчасово не запускає збір." or ("Наступний збір: "..nextCollectionText()))
end

function View.autoStatusTooltip()
    if Settings.collectMode=="manual" then return "Автозбір вимкнено\nОберіть Таймер або Випадковий режим у налаштуваннях" end
    local active=Settings.autoPaused~=true
    local text=(active and "Автозбір увімкнено" or "Автозбір вимкнено").."\nРежим: "..View.autoCollectModeLabel()
    if not active then return text.."\nНатисніть, щоб увімкнути" end
    if UI.collecting then
        local s=UI.collect or {}
        text=text.."\nЗбір: "..tostring(s.done or 0).." / "..tostring(s.totalFarms or 0)
    elseif Scheduler.blocked then
        text=text.."\n"..tostring(Scheduler.blocked)
    else
        text=text.."\nНаступний збір: "..nextCollectionText()
    end
    if Runtime.afk then text=text.."\nАФК-режим" end
    return text.."\nНатисніть, щоб вимкнути"
end

