function View.settingLines(text,width)
    local lines={};local line=""
    for word in I18n.text(text):gmatch("%S+") do
        local test=line=="" and word or (line.." "..word)
        if line~="" and View.calcText(test,Fonts.small).x>width then lines[#lines+1]=line;line=word else line=test end
    end
    if line~="" then lines[#lines+1]=line end
    return lines
end
function View.settingRow(x,y,w,title,description,draw,controlHeight,helpText,helpId)
    local vertical=w<720
    local controlW=vertical and w-32 or 352
    local textW=vertical and w-32 or w-controlW-56
    description=I18n.text(description or "")
    local lines=description~="" and View.settingLines(description,textW) or {}
    local textH=25+#lines*20
    local ch=controlHeight or 32
    local compact=#lines==0
    local height
    if vertical then
        height=compact and (16+25+10+ch+16) or (16+textH+16+ch+16)
    else
        height=compact and math.max(66,ch+26) or math.max(82,textH+32,ch+32)
    end
    if View.settingsGroup then
        imgui.GetWindowDrawList():AddRectFilled(imgui.ImVec2(x,y),imgui.ImVec2(x+w,y+height),u32(View.panelFill(false,true),1))
    else View.shellPanel(x,y,w,height) end
    View.drawText(x+16,y+(compact and 22 or 14),title,Fonts.body,P.text)
    if helpText and tostring(helpText)~="" then
        local titleSize=View.calcText(title,Fonts.body)
        View.drawHelpBubble(helpId or ("setting_"..tostring(title)),x+16+titleSize.x+15,y+(compact and 32 or 24),I18n.text(helpText))
    end
    for i,line in ipairs(lines) do View.drawText(x+16,y+39+(i-1)*20,line,Fonts.small,P.muted) end
    local cx=vertical and x+16 or x+w-16-controlW
    local cy
    if vertical then cy=compact and y+51 or y+16+textH+16 else cy=y+(height-ch)*.5 end
    if draw then draw(cx,cy,controlW,ch) end
    return y+height+(View.settingsGroup and 0 or 12)
end
function View.settingChoices(id,items,current,x,y,w)
    local bw=(w-(#items-1)*8)/#items
    for i,item in ipairs(items) do
        if View.shellButton("##setting_"..id.."_"..tostring(item[1]),item[2],x+(i-1)*(bw+8),y,bw,32,current==item[1]) then return item[1] end
    end
end
