    local function normalizeSearch(value)
        local s=lowerServerText(tostring(value or ""))
        s=s:gsub("ё","е"):gsub("[%p%c]+"," "):gsub("%s+"," "):gsub("^%s+",""):gsub("%s+$","")
        return s
    end
    local query=normalizeSearch(searchRaw)
    local searching=query~=""
    local function settingMatches(key,title,description,helpText,extra)
        if not searching then return true end
        local hay=normalizeSearch(table.concat({
            tostring(key or ""),tostring(title or ""),I18n.text(title or ""),
            tostring(description or ""),I18n.text(description or ""),
            tostring(helpText or ""),I18n.text(helpText or ""),
            tostring(extra or ""),tostring(SettingsSearchKeywords[key] or "")
        }," "))
        for token in query:gmatch("%S+") do if not hay:find(token,1,true) then return false end end
        return true
    end

    local tabs={{"general","Загальні"},{"appearance","Вигляд"},{"automation","Автоматизація"}}
    local bw=(w-16)/3
    for i,item in ipairs(tabs) do
        if View.shellButton("##settings_tab_"..item[1],I18n.text(item[2]),x+(i-1)*(bw+8),y,bw,34,not searching and UI.settingsSection==item[1]) then
            UI.settingsSection=item[1]
            if searching then ffi.fill(UI.settingsSearch,128,0);query="";searching=false end
        end
    end
    y=y+54

    local pendingGroup=nil
    local groupOpen=false
    local function finishGroup()
        if not groupOpen then pendingGroup=nil;return end
        View.drawSmoothRoundedRectCorners(x,y,w,16,0,0,16,16,u32(View.panelFill(false,true),1),nil,1,16)
        View.drawSmoothRoundedRect(x,View.settingsGroup.y,w,y+16-View.settingsGroup.y,20,nil,u32(P.muted,.18),1,16)
        y=y+32;View.settingsGroup=nil;groupOpen=false;pendingGroup=nil
    end
    local function group(title)
        finishGroup();pendingGroup=title
    end
    local function ensureGroup()
        if groupOpen or not pendingGroup then return end
        View.settingsGroup={y=y};groupOpen=true
        View.drawSmoothRoundedRectCorners(x,y,w,46,20,20,0,0,u32(View.panelFill(false,true),1),nil,1,16)
        View.drawText(x+16,y+15,I18n.text(pendingGroup),Fonts.semibold,P.text);y=y+46
    end
    local function row(key,title,description,draw,controlHeight,helpText,helpId,extra)
        if not settingMatches(key,title,description,helpText,extra) then return false end
        ensureGroup()
        y=View.settingRow(x,y,w,I18n.text(title),description,draw,controlHeight,helpText,helpId)
        return true
    end
    local function choice(key,title,description,items,onChange,helpText,helpId,extra)
        return row(key,title,description,function(cx,cy,cw)
            local localized={}
            for i,item in ipairs(items) do localized[i]={item[1],I18n.text(item[2])} end
            local value=View.settingChoices(key,localized,Settings[key],cx,cy,cw)
            if value~=nil then Settings[key]=value;if onChange then onChange(value) end;saveSettings() end
        end,32,helpText,helpId,extra)
    end
    local function toggle(key,title,description,onChange,helpText,helpId,extra)
        return choice(key,title,description,{{false,"Вимкнено"},{true,"Увімкнено"}},onChange,helpText,helpId,extra)
    end
    local function number(key,title,description,minimum,maximum,onChange,helpText,helpId,extra)
        return row(key,title,description,function(cx,cy,cw)
            local value,changed=View.drawNumericSettingInput(key,cx+cw-132,cy,132,Settings[key],minimum,maximum)
            if changed then Settings[key]=value;if onChange then onChange() end;saveSettings() end
        end,32,helpText,helpId,extra)
    end

