        group("Збір без нагляду")
        toggle("afkEnabled","Режим без активності","",nil,"Якщо ви не користуєтесь грою, AutoMiner може закривати сторонні меню, що заважають автозбору.","afk_mode")
        if Settings.afkEnabled then number("afkMinutes","Бездіяльність, хв","Через скільки хвилин без активності вмикати цей режим",1,120) end
        group("Попередження")
        number("coolingWarn","Охолодження нижче, %","0 вимикає це попередження",0,100)
        number("electricityWarn","Електроенергія нижче, $","0 вимикає це попередження",0,View.electricitySliderMax())
        group("Ігноровані будинки")
        local list=View.ignoredList()
        if #list==0 and settingMatches("ignoredHouse","Ігноровані будинки","Немає ігнорованих будинків","","") then ensureGroup();View.drawText(x+16,y+8,I18n.text("Немає ігнорованих будинків"),Fonts.small,P.muted);y=y+46 end
        for _,id in ipairs(list) do
            row("ignoredHouse","Будинок №"..id,"Повернути будинок у список AutoMiner",function(cx,cy,cw)
                if View.shellButton("##unignore_"..id,I18n.text("Повернути"),cx,cy,cw,32,false) then setHouseIgnored(id,false);saveIgnored() end
            end,32,nil,nil,"ignore house "..id)
        end
    end

    local beforeRows=y
    if searching then renderGeneral();renderAppearance();renderAutomation()
    elseif UI.settingsSection=="general" then renderGeneral()
    elseif UI.settingsSection=="appearance" then renderAppearance()
    else renderAutomation() end
    finishGroup()
    y=y+8
    if searching and y<=beforeRows+12 then
        View.drawText(x+16,y+8,I18n.text("Нічого не знайдено"),Fonts.body,P.muted);y=y+30
        View.drawText(x+16,y+4,I18n.text("Спробуйте інше слово або фразу"),Fonts.small,P.faint);y=y+32
    end
    View.drawText(x+16,y+8,I18n.text("Зміни зберігаються автоматично"),Fonts.small,P.faint)
    if not searching and View.shellButton("##reset_section",I18n.text("Скинути цей розділ"),x+w-222,y,206,32,false) then View.resetSettingsSection(UI.settingsSection) end
    y=y+38
    View.drawTextAlpha(x+16,y+4,"AutoMiner · by Moli · v"..tostring(Runtime.revision),Fonts.small,P.faint,.48)
    UI.settingsExtent=y-origin+72
end


