function Tooltip.render()
    local now=getGameTimer()
    local dt=math.min(.05,math.max(0,(now-Tooltip.last)/1000));Tooltip.last=now
    local requested=Tooltip.requested
    if requested and (not Tooltip.current or Tooltip.current.id==requested.id) then Tooltip.current=requested end
    local show=requested and Tooltip.current and requested.id==Tooltip.current.id
    if Settings.animations=="off" then
        Tooltip.alpha=show and 1 or 0
    else
        local tooltipSpeed=Settings.animations=="reduced" and 20 or 15
        Tooltip.alpha=Tooltip.alpha+((show and 1 or 0)-Tooltip.alpha)*(1-math.exp(-dt*tooltipSpeed))
    end
    if Tooltip.alpha<.02 then Tooltip.current=requested; if not requested then return end end
    local t=Tooltip.current;if not t then return end
    local lines={}
    local width,height=0,28
    local isHealth=t.id=="help_farm_health"
    local maxWidth=isHealth and 340 or 300
    for paragraph in (t.text.."\n"):gmatch("(.-)\n") do
        local font,color=Fonts.small,P.text
        if isHealth then
            if paragraph:find("Здоров'я ферм",1,true)==1 then font=Fonts.body
            elseif paragraph=="Враховано" or paragraph=="Що впливає на оцінку" then color=P.muted
            elseif paragraph:find("Ігноровані",1,true)==1 then font=Fonts.note;color=P.faint
            elseif paragraph:find("Паузи GPU",1,true)==1 then color=P.muted end
        end
        local function addLine(text)
            local size=View.calcText(text=="" and "Ag" or text,font)
            local rowH=text=="" and 9 or size.y+4
            lines[#lines+1]={text=text,font=font,color=color,offset=height-14}
            if text~="" then width=math.max(width,size.x) end
            height=height+rowH
        end
        paragraph=I18n.text(paragraph)
        local line=""
        for word in paragraph:gmatch("%S+") do
            local candidate=line=="" and word or line.." "..word
            if View.calcText(candidate,font).x>maxWidth and line~="" then addLine(line);line=word else line=candidate end
        end
        addLine(line)
    end
    width=width+32
    local sx,sy=getScreenResolution()
    local x=math.max(8,math.min(sx-width-8,t.x+t.w-width))
    local y=t.y+t.h+8
    if y+height>sy-8 then y=t.y-height-8 end
    y=math.max(8,y)+((Settings.animations=="full") and ((1-Tooltip.alpha)*4) or 0)
    local dl=imgui.GetForegroundDrawList and imgui.GetForegroundDrawList() or imgui.GetOverlayDrawList()
    dl:PushClipRect(imgui.ImVec2(0,0),imgui.ImVec2(sx,sy),false)
    local tooltipRadius=12
    View.smoothRoundedPath(dl,x,y,x+width,y+height,tooltipRadius,tooltipRadius,tooltipRadius,tooltipRadius,18)
    dl:PathFillConvex(u32({.055,.063,.072,1},Tooltip.alpha*.98))
    local inset=.5
    View.smoothRoundedPath(dl,x+inset,y+inset,x+width-inset,y+height-inset,tooltipRadius-inset,tooltipRadius-inset,tooltipRadius-inset,tooltipRadius-inset,18)
    dl:PathStroke(u32(P.muted,Tooltip.alpha*.22),true,1)
    for _,row in ipairs(lines) do
        if row.font then imgui.PushFont(row.font) end
        dl:AddText(imgui.ImVec2(math.floor(x+16),math.floor(y+row.offset)),u32(row.color,Tooltip.alpha),I18n.text(row.text))
        if row.font then imgui.PopFont() end
    end
    dl:PopClipRect()
end

function View.drawMainTabs(x,y,w,h,attentionCount)
    local tabs={
        {"home","Головна","dashboard"},
        {"houses","Будинки","buildings"},
        {"income","Доходи","income"},
        {"journal","Журнал","journal"},
        {"settings","Налаштування","settings"}
    }

    local buttonW=58
    local buttonH=58
    local gap=16

    for i,tab in ipairs(tabs) do
        local bx=x
        local by=y+(i-1)*(buttonH+gap)
        local active=UI.activeTab==tab[1]

        imgui.SetCursorScreenPos(imgui.ImVec2(bx,by))
        imgui.InvisibleButton("##tab_"..tab[1],imgui.ImVec2(buttonW,buttonH))
        local hovered=imgui.IsItemHovered()
        local pressed=imgui.IsItemActive()
        local activeT=smoothAnim("nav_active_"..tab[1],active and 1 or 0,12)
        local hoverT=smoothAnim("nav_hover_"..tab[1],hovered and 1 or 0,14)
        local pressT=smoothAnim("nav_press_"..tab[1],pressed and 1 or 0,22)

        local surfaceT=math.max(activeT*.88,hoverT*.30)
        if surfaceT>.01 then
            local fill=mixColor({.012,.014,.018,1},{.118,.126,.145,1},surfaceT)
            View.drawSmoothRoundedRect(
                bx,by,buttonW,buttonH,19,
                u32(fill,.98),
                u32(active and {.56,.59,.67,1} or {.34,.37,.43,1},
                    active and (.22+.14*activeT) or (.08+.10*hoverT)),
                1,18
            )
        end
        if activeT>.01 then
            View.drawSmoothRoundedRect(bx-1,by+(buttonH-24)*.5,3,24,1.5,u32(P.text,.62*activeT),nil,0,8)
        end


        local iconColor=u32(
            active and P.text or mixColor(P.muted,P.text,.28+.34*hoverT),
            active and .99 or (.78+.20*hoverT)
        )
        local cx=bx+buttonW*.5
        local cy=by+buttonH*.5-hoverT*.65+pressT*.8
        local iconSize=1+.022*hoverT-.035*pressT

        if tab[3]=="dashboard" then
            View.drawDashboardIcon(cx,cy,27*iconSize,iconColor)
        elseif tab[3]=="buildings" then
            View.drawBuildingsIcon(cx,cy,28*iconSize,iconColor)
        elseif tab[3]=="income" then
            View.drawIncomeNavIcon(cx,cy,27*iconSize,iconColor)
        elseif tab[3]=="journal" then
            View.drawJournalIcon(cx,cy,27*iconSize,iconColor)
        else
            View.drawSettingsIcon(cx,cy,26*iconSize,iconColor,hoverT*.14)
        end

        if tab[1]=="houses" and (attentionCount or 0)>0 then
            local label=(attentionCount or 0)>9 and "9+" or tostring(attentionCount)
            local fs=View.calcText(label,Fonts.small)
            local badge=math.max(17,fs.x+8)
            local badgeX=bx+buttonW-badge*.48
            local badgeY=by-3
            View.drawSmoothRoundedRect(
                badgeX,badgeY,badge,17,8.5,
                u32(P.amber,.14),u32(P.amber,.43),1,12
            )
            View.drawText(
                badgeX+(badge-fs.x)*.5,
                badgeY+(17-fs.y)*.5-1,
                label,Fonts.small,P.amber
            )
        end

        if imgui.IsItemClicked(0) and not active then
            local oldIndex=TabOrder[UI.activeTab] or 1
            local direction=i>oldIndex and -1 or 1
            switchTab(tab[1])
            kickWater(direction,.72)
        end
    end

    return buttonW
end

function View.formatLastUpdate()
    if UI.scanning or UI.waiting then return "Оновлення…" end
    if not UI.lastScanTime then return "" end

    local elapsed=math.max(0,math.floor((getGameTimer()-UI.lastScanTime)/1000))
    if elapsed<15 then return "Оновлено щойно" end
    if elapsed<60 then return "Оновлено "..tostring(elapsed).." с тому" end

    local minutes=math.floor(elapsed/60)
    if minutes<60 then return "Оновлено "..tostring(minutes).." хв тому" end

    local hours=math.floor(minutes/60)
    return "Оновлено "..tostring(hours).." год тому"
end


function View.drawRefreshButton(x,y,enabled,busy)
    local size=34
    local dl=imgui.GetWindowDrawList()

    imgui.SetCursorScreenPos(imgui.ImVec2(x,y))
    imgui.InvisibleButton("##refresh_icon",imgui.ImVec2(size,size))
    local hovered=enabled and imgui.IsItemHovered()

    dl:AddCircleFilled(
        imgui.ImVec2(x+17,y+17),
        16,
        u32(hovered and {.092,.099,.116,1} or {.034,.038,.046,1},enabled and .96 or .44),
        56
    )

    if hovered then
        dl:AddCircle(
            imgui.ImVec2(x+17,y+17),
            15.5,
            u32({.44,.47,.55,1},.22),
            56,
            1
        )
    end

    local col=u32(not enabled and P.faint or (hovered and P.text or P.muted))
    local spin=busy and ((getGameTimer()/760)%1)*math.pi*2 or 0
    local cx,cy=x+17,y+17
    local radius=6.7

    local endA=-.56+spin
    local startA=endA-5.08
    local steps=46
    local lastX,lastY=nil,nil

    for i=0,steps do
        local a=startA+(endA-startA)*(i/steps)
        local xx=cx+math.cos(a)*radius
        local yy=cy+math.sin(a)*radius
        if lastX then
            dl:AddLine(
                imgui.ImVec2(lastX,lastY),
                imgui.ImVec2(xx,yy),
                col,
                1.55
            )
        end
        lastX,lastY=xx,yy
    end

    local tipX=cx+math.cos(endA)*radius
    local tipY=cy+math.sin(endA)*radius
    local tx=-math.sin(endA)
    local ty= math.cos(endA)
    local nx=-ty
    local ny= tx

    local back=3.6
    local half=2.15

    dl:AddLine(
        imgui.ImVec2(tipX,tipY),
        imgui.ImVec2(
            tipX-tx*back+nx*half,
            tipY-ty*back+ny*half
        ),
        col,
        1.55
    )
    dl:AddLine(
        imgui.ImVec2(tipX,tipY),
        imgui.ImVec2(
            tipX-tx*back-nx*half,
            tipY-ty*back-ny*half
        ),
        col,
        1.55
    )

    return enabled and imgui.IsItemClicked(0)
end


function View.sloganText(now)
    View.slogan=View.slogan or {index=1,start=now,order={},seed=(now%2147483646)+1,items={
        "Ще одна GPU — і точно все",
        "Ти на двіжі, ферми на зміні",
        "BTC самі себе не заберуть — а ми заберемо",
        "Відеокартам робота, тобі свобода",
        "Тихо, тут росте твій баланс",
        "Ферма гріється — гаманець тішиться",
        "Зайшов на хвилинку перевірити мільйони",
        "Плани на вечір: ще одна ферма",
        "Менше кліків, більше на рахунку",
        "Також спробуйте [JF] Mining Tools"
    }}
    local state=View.slogan
    local elapsed=now-state.start
    local previous=state.order[state.index]
    if elapsed>=10000 or elapsed<0 then state.index=state.index+1;state.start=now;elapsed=0 end
    if #state.order==0 or state.index>#state.order then
        for i=1,#state.items do state.order[i]=i end
        for i=#state.order,2,-1 do
            state.seed=(state.seed*16807)%2147483647
            local j=state.seed%i+1;state.order[i],state.order[j]=state.order[j],state.order[i]
        end
        if state.order[1]==previous then state.order[1],state.order[2]=state.order[2],state.order[1] end
        state.index=1
    end
    local label=I18n.text(state.items[state.order[state.index]])
    if Settings.animations=="off" then return label,label end
    local letters={}
    for char in label:gmatch("[%z\1-\127\194-\244][\128-\191]*") do letters[#letters+1]=char end
    local n=#letters
    local visible=n
    if elapsed<1800 then visible=math.floor(n*elapsed/1800)
    elseif elapsed>=8400 then visible=math.max(0,n-math.floor(n*(elapsed-8400)/1250)) end
    return table.concat(letters,"",1,visible),label
end
