function View.refillThreshold()
    local preset=Settings.refillPreset or "balanced"
    if preset=="economy" then return 50 end
    if preset=="balanced" then return 70 end
    if preset=="safe" then return 85 end
    return math.max(0,math.min(100,tonumber(Settings.refillThreshold) or 70))
end

function View.refillWaste(coolant)
    coolant=math.max(0,math.min(100,tonumber(coolant) or 0))
    return math.max(0,coolant+50-100)
end

function View.refillPriority(coolant)
    coolant=math.max(0,math.min(100,tonumber(coolant) or 0))
    if coolant>=99.95 then return .06 end
    local threshold=View.refillThreshold()
    if coolant<=threshold then return 1 end
    return .28
end

function AutoRefill.releaseAlt()
    if type(setGameKeyState)=="function" then pcall(setGameKeyState,21,0) end
    if type(setVirtualKeyDown)=="function" then
        pcall(setVirtualKeyDown,0xA4,false) -- VK_LMENU / Left Alt
        pcall(setVirtualKeyDown,0x12,false) -- VK_MENU fallback
    end
end

function AutoRefill.stop(reason,notify)
    local wasActive=AutoRefill.active
    local processed=AutoRefill.processed or 0
    AutoRefill.active=false;AutoRefill.processing=false;AutoRefill.generation=0;AutoRefill.nextAltAt=0
    AutoRefill.releaseAlt()
    if DialogGate.owner=="autorefill" then DialogGate.release("autorefill") end
    if DialogGate.owner=="autorefill" then DialogGate.release("autorefill") end
    if wasActive and processed>0 then
        pushActivity("Автозаправка","Заправлено GPU: "..tostring(processed),"green")
    end
    AutoRefill.processed=0
    if wasActive and notify~=false then
        local text=I18n.text("Автозаправку зупинено")
        if reason and tostring(reason)~="" then text=text.." · "..I18n.text(tostring(reason)) end
        UI.notice=text
        local normalStop=not reason or tostring(reason)=="" or tostring(reason)=="Автозаправку зупинено"
        if normalStop then Notify.event("refill_end",{count=processed})
        else Notify.event("refill_error",{reason=I18n.text(tostring(reason))}) end
    end
end

function AutoRefill.start()
    if not Settings.autoRefill then return end
    local claimed,current=DialogGate.claim("autorefill","walk_wait",{})
    if not claimed then
        AutoRefill.stop("AutoMiner зайнятий: "..tostring(current),true)
        return
    end
    AutoRefill.active=true;AutoRefill.processing=false;AutoRefill.generation=Runtime.generation
    AutoRefill.lastAltAt=0;AutoRefill.nextAltAt=getGameTimer()+350;AutoRefill.processed=0
    local text=I18n.text("Автозаправку запущено").." · "..I18n.text("Підійдіть до наступної GPU")
    UI.notice=text;Notify.event("refill_start")
    Runtime.log("AUTO_REFILL_START","generation="..tostring(AutoRefill.generation))
    if View.basement and View.basement.open[0] and not View.basement.busy then View.requestBasementClose() end
end

function AutoRefill.tapAlt()
    local hasGameKey=type(setGameKeyState)=="function"
    local hasVirtualKey=type(setVirtualKeyDown)=="function"
    if not hasGameKey and not hasVirtualKey then
        AutoRefill.stop("Не вдалося натиснути Alt",true)
        return false
    end

    AutoRefill.releaseAlt()
    local pulse=math.random(85,115)
    local untilAt=getGameTimer()+pulse
    local pressed=false
    -- Re-apply GTA WALK every frame during the short pulse. Some builds treat
    -- setGameKeyState as frame-scoped, so one write followed by wait() can miss Alt.
    while AutoRefill.active and getGameTimer()<untilAt do
        if hasGameKey then
            local ok=pcall(setGameKeyState,21,255)
            pressed=pressed or ok
        end
        if hasVirtualKey then
            local ok=pcall(setVirtualKeyDown,0xA4,true)
            pressed=pressed or ok
        end
        wait(0)
    end
    AutoRefill.releaseAlt()
    if not pressed then
        AutoRefill.stop("Не вдалося натиснути Alt",true)
        return false
    end
    AutoRefill.lastAltAt=getGameTimer()
    AutoRefill.nextAltAt=AutoRefill.lastAltAt+math.random(260,420)
    Runtime.log("AUTO_REFILL_ALT_TAP","walk=21 pulse="..tostring(pulse),2)
    return true
end

function AutoRefill.nextCandidate()
    local threshold=View.refillThreshold()
    for _,g in ipairs(View.basement.groups or {}) do
        for _,row in ipairs(g.rows or {}) do
            local coolant=tonumber(row.coolant)
            if not row.free and coolant~=nil and coolant<99.95 and coolant<=threshold then return row end
        end
    end
end

function AutoRefill.handleParsed(parsed,id)
    if not AutoRefill.active or AutoRefill.processing or not parsed or parsed.overview or parsed.remote then return false end
    local state=View.basement
    state.groups=parsed.groups;state.overview=parsed.overview;state.remote=parsed.remote;state.house=parsed.house;state.id=id
    state.generation=Runtime.generation;state.cooling={};state.open[0]=false;state.closing=false;state.actionPanelOpen=false;state.actionRow=nil
    AutoRefill.processing=true;state.busy=true
    DialogGate.stageTo("autorefill","rack_open",{})
    Runtime.log("AUTO_REFILL_RACK","dialog="..tostring(id).." groups="..tostring(#(parsed.groups or {})))
    lua_thread.create(function()
        local ok,err=pcall(function()
            local row=AutoRefill.nextCandidate()
            if row and AutoRefill.active and AutoRefill.generation==Runtime.generation then
                DialogGate.stageTo("autorefill","refill_gpu",{rack=row.rack,slot=row.slot})
                Runtime.log("AUTO_REFILL_GPU","slot="..tostring(row.slot).." coolant="..tostring(row.coolant))
                local done,why=View.basementDoOne(row,"coolant")
                if not done then error(why or "Не вдалося заправити GPU",0) end
                AutoRefill.processed=(AutoRefill.processed or 0)+1
                wait(180)
            else
                Runtime.log("AUTO_REFILL_SKIP","no_gpu_below_threshold")
            end
        end)
        if state.id and Runtime.ready() then pcall(View.basementSafeRespond,state.id,0,0,"",190,"autorefill_close") end
        state.flow=nil;state.open[0]=false;state.busy=false;AutoRefill.processing=false
        if AutoRefill.active then
            DialogGate.stageTo("autorefill","walk_wait",{})
            AutoRefill.nextAltAt=getGameTimer()+math.random(300,450)
        end
        if not ok then AutoRefill.stop(tostring(err),true) end
    end)
    return true
end

function AutoRefill.step()
    if not AutoRefill.active then return end
    if not Settings.autoRefill then AutoRefill.stop(nil,false);return end
    if AutoRefill.generation~=Runtime.generation or not Runtime.ready() then AutoRefill.stop("З’єднання з грою перервано",true);return end
    local state=View.basement
    if AutoRefill.processing or state.busy or state.flow or state.open[0] or state.closing then return end
    if UI.collecting or UI.balanceUpdating or UI.scanning or UI.waiting or UI.loading or Taxes.busy or Electricity.busy or Electricity.checking or Maintenance.busy then return end
    -- A stale CEF-cursor flag must not freeze the walking refill loop forever.
    -- Real conflicting UI is covered explicitly by phone/native-dialog/chat checks.
    if Runtime.phoneOpen or (sampIsDialogActive and sampIsDialogActive()) or (sampIsChatInputActive and sampIsChatInputActive()) then return end
    if getGameTimer()<(AutoRefill.nextAltAt or 0) then return end
    AutoRefill.tapAlt()
end

View.basement={open=imgui.new.bool(false),serial=0,groups={},actionRow=nil,actionPanelOpen=false,actionPanelT=0,allActions=false,confirm=nil,refillConfirm=nil,notice=nil,busy=false,flow=nil,resized=false,closing=false,closeStarted=0,lastDialogAt=0,lastDialogId=nil,lastDialogSerial=0}
Runtime.basement=View.basement

function View.drawNeonFallback(x,y,w,h,r,color,healthy,hover)
    local dl=imgui.GetWindowDrawList()
    r=math.min(r,w*.5,h*.5)
    -- Soft rim remains available on devices that cannot load the texture atlas.
    for spread=12,2,-2 do
        View.drawSmoothRoundedRect(x-spread*.3,y-spread*.3,w+spread*.6,h+spread*.6,r+spread*.3,nil,u32(color,healthy and .018 or .006),spread,24)
    end
    View.drawSmoothRoundedRect(x,y,w,h,r,nil,u32(color,healthy and .25 or .12),1,24)
    if not healthy then return end
    local points={}
    local corners={{x+w-r,y+r,-math.pi/2},{x+w-r,y+h-r,0},{x+r,y+h-r,math.pi/2},{x+r,y+r,math.pi}}
    for _,c in ipairs(corners) do
        for i=0,16 do local a=c[3]+i*math.pi/32;points[#points+1]={x=c[1]+math.cos(a)*r,y=c[2]+math.sin(a)*r} end
    end
    points[#points+1]=points[1]
    local total=0
    for i=2,#points do local a,b=points[i-1],points[i];b.distance=math.sqrt((b.x-a.x)^2+(b.y-a.y)^2);total=total+b.distance end
    local phase=Settings.animations=="off" and .7 or (getGameTimer()/1000*.075*Settings.neonSpeed)%1
    local distance=0
    for i=2,#points do
        local a,b=points[i-1],points[i];local parts=math.max(1,math.ceil(b.distance/5))
        for j=1,parts do
            local t0,t1=(j-1)/parts,j/parts
            local pos=(distance+b.distance*(t0+t1)*.5)/total
            local d=(phase-pos)%1;local strength=math.exp(-d*14)*(.8+(hover or 0)*.15)
            local p1=imgui.ImVec2(a.x+(b.x-a.x)*t0,a.y+(b.y-a.y)*t0)
            local p2=imgui.ImVec2(a.x+(b.x-a.x)*t1,a.y+(b.y-a.y)*t1)
            for _,layer in ipairs({{12,.025},{7,.07},{3,.18},{1.2,.75}}) do dl:AddLine(p1,p2,u32(color,strength*layer[2]),layer[1]) end
        end
        distance=distance+b.distance
    end
end

function View.parseBasement(id,style,title,text)
    if style~=5 then return end
    local lower=lowerServerText(title)
    local overview=id==0 and lower:find("обзор",1,true) and lower:find("видеокарт",1,true)
    local remote=id==DIALOG_MINER_LIST and lower:find("видеокарт",1,true) and lower:find("дом",1,true)
    -- 25243 is the confirmed physical rack dialog opened by Left Alt.
    -- Use the exact id and do not depend on translated/localized title text.
    local selectGPU=(id==25243) or (remote and lower:find("видеокарт",1,true))
    if not overview and not selectGPU then return end
    local groups={};local group=nil;local sourceRow=-1
    for raw in (tostring(text or "").."\n"):gmatch("([^\n]*)\n") do
        if sourceRow>=0 then
            local clean=serverToUtf8(stripColors(raw)):gsub("\r","")
            local rowLower=lowerServerText(raw)
            local rack=nil
            if rowLower:find("стойка",1,true) then rack=clean:match("(%d+)") end
            if (overview or remote) and rack then group={number=tonumber(rack),rows={}};groups[#groups+1]=group
            elseif clean:find("|",1,true) then
                if not group then group={rows={}};groups[#groups+1]=group end
                local cols={};for col in (clean.."\t"):gmatch("([^\t]*)\t") do cols[#cols+1]=col end
                local slot=cols[1]:match("(%d+)")
                if not slot then return end
                local free=rowLower:find("свобод",1,true)~=nil
                local paused=rowLower:find("пауз",1,true)~=nil or rowLower:find("останов",1,true)~=nil
                local working=rowLower:find("работает",1,true)~=nil
                local btc=tonumber((cols[2] or ""):match("([%d%.]+)"))
                local level=tonumber((cols[3] or ""):match("(%d+)"))
                local coolant=tonumber((cols[4] or ""):match("([%d%.]+)"))
                if not free and not (btc and level and coolant) then return end
                group.rows[#group.rows+1]={slot=tonumber(slot),rack=group.number,sourceRow=sourceRow,free=free,btc=btc,level=level,coolant=coolant,status=free and "Вільна" or (paused and "На паузі" or (working and "Працює" or "Стан невідомий"))}
            end
        end
        sourceRow=sourceRow+1
    end
    if #groups==0 then return end
    for _,g in ipairs(groups) do if #g.rows<1 or #g.rows>32 then return end end
    if selectGPU and not remote and #groups~=1 then return end
    return {groups=groups,overview=not not overview,id=id,remote=not not remote,house=remote and serverToUtf8(stripColors(title)):match("№%s*(%d+)") or nil}
end

function View.basementActionRows(style,text)
    local rows={};local index=style==5 and -1 or 0
    for raw in (tostring(text or "").."\n"):gmatch("([^\n]*)\n") do
        if index>=0 and raw:find("%S") then
            local label=serverToUtf8(stripColors(raw)):gsub("[\t\r]"," "):gsub("^%s+",""):gsub("%s+$","")
            local lower=lowerServerText(raw)
            local kind=nil
            if (lower:find("останов",1,true) or lower:find("запуст",1,true)) and lower:find("видеокарт",1,true) then kind="toggle"
            elseif lower:find("btc",1,true) and (lower:find("прибыл",1,true) or lower:find("прибут",1,true) or lower:find("забрат",1,true)) then kind="btc"
            elseif lower:find("asc",1,true) and (lower:find("прибыл",1,true) or lower:find("прибут",1,true) or lower:find("забрат",1,true)) then kind="asc"
            elseif lower:find("охлаж",1,true) or lower:find("охолод",1,true) then kind="coolant"
            elseif (lower:find("достать",1,true) or lower:find("дістат",1,true)) and lower:find("видеокарт",1,true) then kind="extract" end
            rows[#rows+1]={row=index,label=label,kind=kind}
        end
        index=index+1
    end
    return rows
end

function View.basementActionDialog(id,style,title,text)
    local lower=lowerServerText((title or "").." "..(text or ""))
    if id~=25244 and not (lower:find("полка",1,true) and lower:find("видеокарт",1,true)) then return nil end
    local rows=View.basementActionRows(style,text)
    local map={}
    for _,item in ipairs(rows) do if item.kind and map[item.kind]==nil then map[item.kind]=item.row end end
    if next(map)==nil then return nil end
    return {id=id,rows=rows,map=map}
end

function View.basementConfirmationLooksRelevant(title,text,kind)
    local lower=lowerServerText((title or "").." "..(text or ""))
    if not (lower:find("видеокарт",1,true) or lower:find("btc",1,true) or lower:find("asc",1,true) or lower:find("охлаж",1,true)) then return false end
    return lower:find("подтверд",1,true) or lower:find("действительно",1,true) or lower:find("продолж",1,true)
        or lower:find("підтверд",1,true) or lower:find("продовж",1,true) or lower:find("бажаєте",1,true)
end

function View.basementFindRowBySlot(slot,rack)
    local state=View.basement
    for _,g in ipairs(state.groups or {}) do for _,r in ipairs(g.rows or {}) do
        if r.slot==slot and not r.free and (rack==nil or tonumber(r.rack or g.number)==tonumber(rack)) then return r end
    end end
end

function View.basementAllRows()
    local result={}
    for _,g in ipairs(View.basement.groups or {}) do for _,r in ipairs(g.rows or {}) do
        if not r.free then result[#result+1]={slot=r.slot,rack=r.rack or g.number,sourceRow=r.sourceRow,coolant=r.coolant,status=r.status,btc=r.btc,level=r.level} end
    end end
    return result
end

function View.basementWaitFor(predicate,timeout,errorMessage)
    local start=getGameTimer();local generation=Runtime.generation
    while getGameTimer()-start<(timeout or 6000) do
        if generation~=Runtime.generation or not Runtime.ready() then return false,"З’єднання з грою перервано" end
        if predicate() then return true end
        wait(0)
    end
    local message=errorMessage or "Сервер не відповів"
    DialogGate.log("TIMEOUT","reason="..tostring(message).." lastDialog="..tostring(View.basement.lastDialogId or "-"))
    return false,message
end

function View.basementMarkDialog(id)
    local state=View.basement
    state.lastDialogAt=getGameTimer();state.lastDialogId=id;state.lastDialogSerial=(state.lastDialogSerial or 0)+1
end

function View.basementSafeRespond(id,button,row,input,minDelay,action)
    -- IMPORTANT: this helper is called both from MoonLoader worker threads and
    -- directly from samp.events callbacks (onShowDialog). Calling wait() from
    -- the latter crashes Lua 5.1 with "attempt to yield across C-call boundary".
    -- Therefore every delayed GPU response is dispatched through its own
    -- MoonLoader thread and this function itself never yields.
    local state=View.basement
    minDelay=tonumber(minDelay) or 170
    local now=getGameTimer()
    local left=0
    if state.lastDialogId==id then
        left=math.max(0,minDelay-(now-(state.lastDialogAt or 0)))
    else
        local rx=DialogGate.lastRx
        if rx and rx.id==id then left=math.max(0,minDelay-(now-(rx.at or 0))) end
    end

    local owner=DialogGate.owner~="none" and DialogGate.owner or nil
    local generation=Runtime.generation
    local sendId=id
    local sendButton=button
    local sendRow=row or 0
    local sendInput=input or ""
    local sendAction=action or "gpu_action"

    lua_thread.create(function()
        if left>0 then wait(left) else wait(0) end
        if generation~=Runtime.generation or not Runtime.ready() then
            Runtime.log("AM_TX_CANCELLED","reason=stale_or_not_ready dialog="..tostring(sendId).." action="..tostring(sendAction))
            return
        end
        if owner then
            if DialogGate.owner~="none" and DialogGate.owner~=owner then
                Runtime.log("AM_TX_CANCELLED","reason=owner_changed wanted="..tostring(owner).." current="..tostring(DialogGate.owner).." dialog="..tostring(sendId))
                return
            end
            DialogGate.tx(owner,sendId,sendButton,sendRow,sendInput,0,sendAction)
            return
        end
        if DialogGate.owner~="none" then
            Runtime.log("AM_TX_CANCELLED","reason=owner_acquired current="..tostring(DialogGate.owner).." dialog="..tostring(sendId))
            return
        end
        Runtime.log("AM_TX","owner=gpu_ui stage=manual dialog="..tostring(sendId).." button="..tostring(sendButton).." row="..tostring(sendRow).." action="..tostring(sendAction))
        sampSendDialogResponse(sendId,sendButton,sendRow,sendInput)
    end)
    return true
end

local function basementResultError(kind)
    if kind=="btc" then return "Не повернувся список GPU після BTC" end
    if kind=="asc" then return "Не повернувся список GPU після ASC" end
    if kind=="toggle" then return "Не повернулося меню після зміни стану GPU" end
    if kind=="coolant" then return "Не повернувся список GPU після заправки" end
    if kind=="extract" then return "Не повернувся список GPU після вилучення GPU" end
    return "Не повернувся список GPU після дії"
end

function View.basementDoOne(row,kind)
    local state=View.basement
    if not row or row.free or state.id==nil then return false,"GPU недоступна" end
    local flow={phase="await_action",kind=kind,sourceRow=row.sourceRow,slot=row.slot,rack=row.rack,generation=Runtime.generation,done=false,error=nil}
    state.flow=flow
    DialogGate.stageTo(nil,"gpu_action_open",{house=state.house,rack=row.rack,slot=row.slot})
    if not View.basementSafeRespond(state.id,1,row.sourceRow,"",210,"open_gpu") then state.flow=nil;return false,"Не вдалося відкрити меню GPU" end
    local ok,err=View.basementWaitFor(function() return flow.action~=nil or flow.error~=nil end,7000,"Не відкрилося меню GPU")
    if not ok or flow.error then state.flow=nil;return false,flow.error or err end
    local actionRow=flow.action.map[kind]
    if actionRow==nil then state.flow=nil;return false,"Сервер не повернув потрібну дію" end
    flow.phase="await_result"
    DialogGate.stageTo(nil,"gpu_action_"..tostring(kind),{house=state.house,rack=row.rack,slot=row.slot})
    if not View.basementSafeRespond(flow.action.id,1,actionRow,"",175,kind) then state.flow=nil;return false,"Не вдалося відправити дію GPU" end
    local ok2,err2=View.basementWaitFor(function() return flow.done or flow.error~=nil end,8000,basementResultError(kind))
    state.flow=nil
    if not ok2 or flow.error then return false,flow.error or err2 end
    return true
end

function View.basementDoProfit(row,kind)
    local state=View.basement
    if kind~="btc" and kind~="asc" then return false,"Невідомий тип прибутку" end
    if not row or row.free or state.id==nil then return false,"GPU недоступна" end
    local flow={phase="await_action",kind=kind,sourceRow=row.sourceRow,slot=row.slot,rack=row.rack,generation=Runtime.generation,done=false,error=nil}
    state.flow=flow
    DialogGate.stageTo(nil,"profit_open_"..kind,{house=state.house,rack=row.rack,slot=row.slot})
    if not View.basementSafeRespond(state.id,1,row.sourceRow,"",210,"open_gpu_"..kind) then state.flow=nil;return false,"Не вдалося відкрити меню GPU" end
    local ok,err=View.basementWaitFor(function() return flow.action~=nil or flow.error~=nil end,7000,"Не відкрилося меню GPU")
    if not ok or flow.error then state.flow=nil;return false,flow.error or err end
    local target=nil
    for _,item in ipairs(flow.action.rows or {}) do if item.kind==kind then target=item;break end end
    local resultError=basementResultError(kind)
    if not target then
        flow.phase="await_result"
        View.basementSafeRespond(flow.action.id,0,0,"",170,"back_no_"..kind)
        local backOK,backErr=View.basementWaitFor(function() return flow.done or flow.error~=nil end,7000,resultError)
        state.flow=nil
        if not backOK or flow.error then return false,flow.error or backErr end
        return true,"none",0
    end
    local upper=kind=="btc" and "BTC" or "ASC"
    local amountText=tostring(target.label or ""):match("([%d]+[.,]?[%d]*)%s*"..upper)
    local amount=amountText and tonumber((amountText:gsub(",","."))) or nil
    if kind=="btc" and amount==nil then amount=tonumber(row.btc) end
    local skip=(kind=="btc" and amount and amount<1) or (kind=="asc" and amount and amount<=0)
    if skip then
        flow.phase="await_result"
        View.basementSafeRespond(flow.action.id,0,0,"",170,"back_skip_"..kind)
        local backOK,backErr=View.basementWaitFor(function() return flow.done or flow.error~=nil end,7000,resultError)
        state.flow=nil
        if not backOK or flow.error then return false,flow.error or backErr end
        return true,"none",amount or 0
    end
    flow.phase="await_result"
    DialogGate.stageTo(nil,"profit_"..kind,{house=state.house,rack=row.rack,slot=row.slot})
    if not View.basementSafeRespond(flow.action.id,1,target.row,"",175,"collect_"..kind) then state.flow=nil;return false,"Не вдалося відправити дію збору" end
    local ok2,err2=View.basementWaitFor(function() return flow.done or flow.error~=nil end,8000,resultError)
    state.flow=nil
    if not ok2 or flow.error then return false,flow.error or err2 end
    return true,"collected",amount
end

function View.basementEnsureRunning(row)
    local state=View.basement
    if not row or row.free or state.id==nil then return false,"GPU недоступна" end
    local flow={phase="await_action",kind="toggle",sourceRow=row.sourceRow,slot=row.slot,rack=row.rack,generation=Runtime.generation,done=false,error=nil}
    state.flow=flow
    DialogGate.stageTo(nil,"gpu_start_check",{house=state.house,rack=row.rack,slot=row.slot})
    if not View.basementSafeRespond(state.id,1,row.sourceRow,"",210,"open_gpu_start_check") then state.flow=nil;return false,"Не вдалося відкрити меню GPU" end
    local ok,err=View.basementWaitFor(function() return flow.action~=nil or flow.error~=nil end,7000,"Не відкрилося меню GPU")
    if not ok or flow.error then state.flow=nil;return false,flow.error or err end
    local toggle=nil
    for _,item in ipairs(flow.action.rows or {}) do if item.kind=="toggle" then toggle=item;break end end
    if not toggle then state.flow=nil;return false,"Не знайдено дію запуску GPU" end
    local label=lowerServerText(toggle.label or "")
    if label:find("останов",1,true) or label:find("зупин",1,true) then
        -- Server is authoritative: the GPU is already running. Back out without toggling.
        flow.phase="await_result"
        View.basementSafeRespond(flow.action.id,0,0,"",170,"gpu_already_running")
        local backOK,backErr=View.basementWaitFor(function() return flow.done or flow.error~=nil end,7000,"Не повернувся список GPU")
        state.flow=nil
        if not backOK or flow.error then return false,flow.error or backErr end
        return true,"already"
    end
    if not (label:find("запуст",1,true) or label:find("включ",1,true)) then
        state.flow=nil;return false,"Стан дії запуску GPU не розпізнано"
    end
    flow.phase="await_result"
    DialogGate.stageTo(nil,"gpu_start",{house=state.house,rack=row.rack,slot=row.slot})
    View.basementSafeRespond(flow.action.id,1,toggle.row,"",175,"start_gpu")
    local ok2,err2=View.basementWaitFor(function() return flow.done or flow.error~=nil end,8000,"Не повернулося меню після запуску GPU")
    state.flow=nil
    if not ok2 or flow.error then return false,flow.error or err2 end
    local current=View.basementFindRowBySlot(row.slot,row.rack)
    if not current or current.status~="Працює" then return false,"Запуск GPU не підтверджено сервером" end
    return true,"started"
end

function View.basementRunAction(kind,row,bulk,forceCoolant)
    local state=View.basement
    if state.busy then return end
    state.busy=true;state.notice=nil
    local generation=Runtime.generation
    lua_thread.create(function()
        local resultMessage=nil
        local ok,reason=pcall(function()
            local rows=bulk and View.basementAllRows() or {row}
            if #rows==0 then error("Немає встановлених GPU",0) end
            local refilled,skipped=0,0
            for i,item in ipairs(rows) do
                if generation~=Runtime.generation then error("З’єднання з грою перервано",0) end
                local current=View.basementFindRowBySlot(item.slot,item.rack) or item
                if kind=="start" and current.status=="Працює" then
                elseif kind=="stop" and current.status~="Працює" then
                elseif kind=="coolant" and bulk then
                    local level=math.max(0,math.min(100,tonumber(current.coolant) or 0))
                    if level>=99.95 or level>View.refillThreshold() then
                        skipped=skipped+1
                    else
                        state.notice="GPU "..i.." / "..#rows.." · Заправляємо охолодження…"
                        local done,why=View.basementDoOne(current,"coolant")
                        if not done then error("GPU "..tostring(current.slot)..": "..tostring(why),0) end
                        refilled=refilled+1
                    end
                elseif kind=="extract" and bulk then
                    local level=math.max(0,math.min(100,tonumber(current.coolant) or 0))
                    local needed=math.max(0,math.ceil((100-level-.001)/50))
                    for n=1,needed do
                        state.notice="Заправляємо GPU "..tostring(current.slot).." до 100% · "..n.." / "..needed
                        local before=level
                        local filled,why=View.basementDoOne(current,"coolant")
                        if not filled then error("GPU "..tostring(current.slot)..": "..tostring(why),0) end
                        local refreshed=View.basementFindRowBySlot(item.slot,item.rack)
                        if refreshed then current=refreshed end
                        level=math.max(0,math.min(100,tonumber(current.coolant) or math.min(100,before+50)))
                        if level<=before+.01 then level=math.min(100,before+50);current.coolant=level end
                    end
                    current=View.basementFindRowBySlot(item.slot,item.rack) or current
                    state.notice="GPU "..tostring(current.slot).." · Забираємо BTC…"
                    local btcOK,btcWhy=View.basementDoProfit(current,"btc")
                    if not btcOK then error("GPU "..tostring(current.slot)..": "..tostring(btcWhy),0) end
                    current=View.basementFindRowBySlot(item.slot,item.rack) or current
                    wait(600)
                    state.notice="GPU "..tostring(current.slot).." · Забираємо ASC…"
                    local ascOK,ascWhy=View.basementDoProfit(current,"asc")
                    if not ascOK then error("GPU "..tostring(current.slot)..": "..tostring(ascWhy),0) end
                    current=View.basementFindRowBySlot(item.slot,item.rack) or current
                    wait(450)
                    state.notice="Дістаємо GPU "..tostring(current.slot).."…"
                    local removed,why=View.basementDoOne(current,"extract")
                    if not removed then error("GPU "..tostring(current.slot)..": "..tostring(why),0) end
                else
                    local serverKind=(kind=="start" or kind=="stop") and "toggle" or kind
                    state.notice=(bulk and ("GPU "..i.." / "..#rows.." · ") or "")..({toggle="Змінюємо стан…",start="Запускаємо GPU…",stop="Зупиняємо GPU…",btc="Забираємо BTC…",asc="Забираємо ASC…",coolant="Заправляємо охолодження…",extract="Дістаємо GPU…"})[kind]
                    local done,why=View.basementDoOne(current,serverKind)
                    if not done then error("GPU "..tostring(current.slot)..": "..tostring(why),0) end
                    if kind=="coolant" then refilled=refilled+1 end
                end
            end
            if kind=="coolant" and bulk then
                resultMessage=I18n.text("Заправлено")..": "..refilled.." · "..I18n.text("Пропущено")..": "..skipped
            end
        end)
        state.busy=false
        state.notice=ok and (resultMessage or "Готово") or tostring(reason)
        if not ok then Runtime.log("BASEMENT_ACTION_ERROR",tostring(reason)) end
        state.allActions=false;state.confirm=nil
        if not bulk and row then
            local refreshed=View.basementFindRowBySlot(row.slot,row.rack)
            if refreshed then
                state.actionRow=refreshed;state.actionPanelOpen=true
            elseif ok then
                state.actionPanelOpen=false
            end
        end
        if ok and kind=="coolant" and not bulk and Settings.autoRefill then AutoRefill.start() end
    end)
end


function Maintenance.addError(house,message)
    Maintenance.errors=Maintenance.errors or {}
    Maintenance.errors[#Maintenance.errors+1]={house=house and house.number or house,message=tostring(message or "Невідома помилка")}
end

function Maintenance.applyBasementToHouse(house)
    if not house then return end
    local count,paused,unknown,slotCount,btcTotal,collectible=0,0,0,0,0,0
    local coolSum,coolN=0,0
    local gpus,gpuBySlot={},{}
    for _,group in ipairs(View.basement.groups or {}) do
        for _,row in ipairs(group.rows or {}) do
            slotCount=slotCount+1
            if not row.free then
                count=count+1
                btcTotal=btcTotal+(tonumber(row.btc) or 0)
                collectible=collectible+math.floor(tonumber(row.btc) or 0)
                if tonumber(row.coolant) then coolSum=coolSum+tonumber(row.coolant);coolN=coolN+1 end
                local active=nil
                if row.status=="Працює" then active=true
                elseif row.status=="На паузі" then active=false
                else unknown=unknown+1 end
                if active==false then paused=paused+1 end
                local gpu={slot=row.slot,shelf=row.slot,rack=group.number,level=row.level,active=active,coolant=row.coolant}
                gpus[#gpus+1]=gpu
                if group.number then gpuBySlot[tostring(group.number)..":"..tostring(row.slot)]=gpu end
            end
        end
    end
    Runtime.apply(house,{
        coolant=coolN>0 and coolSum/coolN or nil,
        gpuCount=count,pausedCount=paused,workingCount=math.max(0,count-paused-unknown),
        unknownCount=unknown,slotCount=slotCount,btc=count>0 and btcTotal or nil,
        collectible=count>0 and collectible or 0,gpus=gpus,gpuBySlot=gpuBySlot,complete=unknown==0
    })
    house.scanned=true
    house.miningStatus="available"
    house.miningReason=nil
    RateTracker.sample(house)
    ForecastTracker.sample(house)
    MiningModel.sample(house)
    IncomeAnalytics.observeHouse(house)
end

function Maintenance.openHouse(house)
    if not house then return false,"Будинок не знайдено" end
    if sampIsDialogActive and sampIsDialogActive() then return false,"Відкрите інше меню" end
    local state=View.basement
    state.open[0]=false;state.flow=nil;state.groups={};state.id=nil;state.busy=false;state.lastDialogId=nil;state.lastDialogAt=0
    DialogGate.stageTo("maintenance","house_open",{house=house.number})
    Maintenance.pendingHouse=house
    Maintenance.awaitRemote=true
    Maintenance.remoteReady=false
    Maintenance.remoteError=nil
    Maintenance.closingHouse=false
    Maintenance.houseClosed=false
    sampSendChat("/flashminer")
    local started=getGameTimer()
    while getGameTimer()-started<9000 do
        if Maintenance.generation~=Runtime.generation or not Runtime.ready() then return false,"З’єднання з грою перервано" end
        if Maintenance.remoteError then return false,Maintenance.remoteError end
        if Maintenance.remoteReady then return true end
        wait(0)
    end
    Maintenance.pendingHouse=nil;Maintenance.awaitRemote=false
    return false,"Не вдалося відкрити ферму"
end

function Maintenance.closeHouse()
    local state=View.basement
    if not state.id or not Runtime.ready() then
        Maintenance.closingHouse=false;Maintenance.houseClosed=true
        return true
    end
    Maintenance.closingHouse=true;Maintenance.houseClosed=false
    DialogGate.stageTo("maintenance","house_close",{house=state.house})
    pcall(View.basementSafeRespond,state.id,0,0,"",175,"close_gpu_list")
    local started=getGameTimer()
    while getGameTimer()-started<4500 do
        if Maintenance.houseClosed then
            Maintenance.closingHouse=false
            state.flow=nil;state.open[0]=false;state.busy=false
            wait(140)
            return true
        end
        if Maintenance.generation~=Runtime.generation or not Runtime.ready() then break end
        wait(0)
    end
    Maintenance.closingHouse=false
    return false
end

function Maintenance.runHouse(house,summary)
    local opened,why=Maintenance.openHouse(house)
    if not opened then return false,why end
    wait(220)
    local rows=View.basementAllRows()
    if #rows==0 then Maintenance.closeHouse();return false,"Не відкрилося меню GPU" end
    for i,item in ipairs(rows) do
        if Maintenance.generation~=Runtime.generation then return false,"З’єднання з грою перервано" end
        local current=View.basementFindRowBySlot(item.slot,item.rack) or item
        local wasPaused=current.status=="На паузі"
        local btcCollected=false

        -- During maintenance profit is collected first. If the GPU was paused,
        -- it is started only after BTC/ASC have finished so the collection
        -- sequence cannot accidentally change the server action menu mid-flow.
        if (tonumber(current.btc) or 0)>=1 then
            Maintenance.stage="Забираємо прибуток · дім №"..tostring(house.number).." · BTC"
            DialogGate.stageTo("maintenance","btc",{house=house.number,rack=item.rack,slot=item.slot})
            local beforeSerial=View.basement.lastDialogSerial or 0
            local done,status,amount=View.basementDoProfit(current,"btc")
            if not done then
                Maintenance.closeHouse()
                local msg=tostring(status)
                if msg=="Сервер не відповів" then msg="Не повернувся список GPU після BTC" end
                return false,"GPU "..tostring(current.slot)..": "..msg
            end
            if status=="collected" then
                btcCollected=true
                summary.btcActions=(summary.btcActions or 0)+1
                summary.btc=(summary.btc or 0)+math.floor(tonumber(amount) or tonumber(current.btc) or 0)
            end
            local freshOK,freshErr=View.basementWaitFor(function()
                return (View.basement.lastDialogSerial or 0)>beforeSerial and View.basement.id==DIALOG_MINER_LIST
            end,2200,"Не повернувся список GPU після BTC")
            if not freshOK then Maintenance.closeHouse();return false,"GPU "..tostring(item.rack or "?")..":"..tostring(item.slot)..": "..tostring(freshErr) end
            current=View.basementFindRowBySlot(item.slot,item.rack) or current
        end

        wait(btcCollected and 420 or 220)

        Maintenance.stage="Забираємо прибуток · дім №"..tostring(house.number).." · ASC"
        DialogGate.stageTo("maintenance","asc",{house=house.number,rack=item.rack,slot=item.slot})
        local beforeAscSerial=View.basement.lastDialogSerial or 0
        local ascDone,ascStatus,ascAmount=View.basementDoProfit(current,"asc")
        if not ascDone then
            Maintenance.closeHouse()
            local msg=tostring(ascStatus)
            if msg=="Сервер не відповів" then msg="Не повернувся список GPU після ASC" end
            return false,"GPU "..tostring(current.slot)..": "..msg
        end
        if ascStatus=="collected" then
            summary.ascActions=(summary.ascActions or 0)+1
            summary.asc=(summary.asc or 0)+(tonumber(ascAmount) or 0)
        end
        local ascFreshOK,ascFreshErr=View.basementWaitFor(function()
            return (View.basement.lastDialogSerial or 0)>beforeAscSerial and View.basement.id==DIALOG_MINER_LIST
        end,2200,"Не повернувся список GPU після ASC")
        if not ascFreshOK then Maintenance.closeHouse();return false,"GPU "..tostring(item.rack or "?")..":"..tostring(item.slot)..": "..tostring(ascFreshErr) end
        current=View.basementFindRowBySlot(item.slot,item.rack) or current
        wait(ascStatus=="collected" and 420 or 220)

        if wasPaused or current.status=="На паузі" then
            Maintenance.stage="Запускаємо GPU після збору · дім №"..tostring(house.number).." · "..i.." / "..#rows
            DialogGate.stageTo("maintenance","gpu_start",{house=house.number,rack=item.rack,slot=item.slot})
            local done,startStatus=View.basementEnsureRunning(current)
            if not done then
                Maintenance.closeHouse()
                return false,"GPU "..tostring(item.rack or "?")..":"..tostring(current.slot)..": "..tostring(startStatus)
            end
            if View.basement.id~=DIALOG_MINER_LIST then
                Maintenance.closeHouse()
                return false,"GPU "..tostring(item.rack or "?")..":"..tostring(item.slot)..": Не повернувся список GPU після запуску"
            end
            current=View.basementFindRowBySlot(item.slot,item.rack) or current
            if startStatus=="started" then summary.started=(summary.started or 0)+1 end
            wait(320)
        end

        wait(260)
    end

    Maintenance.applyBasementToHouse(house)
    local closed=Maintenance.closeHouse()
    if not closed then return false,"Не вдалося закрити меню ферми після обслуговування" end

    local balance=parseHouseMoney(house.currentMoney)
    if balance and balance<=AUTO_ELECTRICITY_THRESHOLD then
        Maintenance.stage="Поповнюємо електроенергію · дім №"..tostring(house.number)
        local paid,err=Electricity.runHouse(house)
        if paid then summary.electricity=(summary.electricity or 0)+1
        else Maintenance.addError(house,"Електроенергія: "..tostring(err)) end
    end
    return true
end

function Maintenance.start()
    if Maintenance.busy then return false,"Обслуговування вже запущено" end
    if AutoRefill.active then AutoRefill.stop(nil,false) end
    if Runtime.busy() then return false,"AutoMiner зайнятий" end
    if Runtime.foreignDialog() then
        local ready,state=Runtime.requestAutomationDialogClose("maintenance")
        if not ready then
            if state=="closing" then return false,"__dialog_recovery__" end
            if state=="protected" then return false,"__protected_dialog__" end
            return false,"Закрийте відкрите меню"
        end
    end
    if not Runtime.ready() then return false,"Очікуємо готовності гри" end
    if #UI.houses==0 then return false,"Немає даних про ферми" end
    local claimed,owner=DialogGate.claim("maintenance","start",{})
    if not claimed then return false,"AutoMiner зайнятий: "..tostring(owner) end

    Maintenance.busy=true
    Maintenance.generation=Runtime.generation
    Maintenance.stage="Готуємо обслуговування…"
    Maintenance.progress=0
    Maintenance.errors={}
    Maintenance.visits={}
    Maintenance.summary={houses=0,started=0,btc=0,btcActions=0,asc=0,ascActions=0,electricity=0}
    UI.notice=I18n.text("Обслуговування запущено")
    Notify.raw("maintenance","Обслуговування запущено · перевіряємо всі ферми","maintenance_start",3)
    pushActivity("Обслуговування","Запущено перевірку всіх ферм","neutral")

    lua_thread.create(function()
        local ok,err=pcall(function()
            local queue={}
            for _,house in ipairs(UI.houses or {}) do
                if not isHouseIgnored(house.number) and (tonumber(house.gpuCount) or 0)>0
                    and house.miningStatus~="unavailable" then queue[#queue+1]=house end
            end
            Maintenance.total=#queue
            for i,house in ipairs(queue) do
                if Maintenance.generation~=Runtime.generation then error("З’єднання з грою перервано",0) end
                Maintenance.progress=i-1
                Maintenance.stage="Перевіряємо будинок №"..tostring(house.number).." · "..i.." / "..#queue
                local done,why=Maintenance.runHouse(house,Maintenance.summary)
                if done then
                    Maintenance.summary.houses=Maintenance.summary.houses+1
                else
                    Maintenance.addError(house,why)
                end
                Maintenance.progress=i
                wait(120)
            end

            Maintenance.stage="Перевіряємо податки"
            local callOK,taxOK,taxResult=pcall(Taxes.run,true)
            if not callOK then
                Maintenance.addError(nil,"Податки: "..tostring(taxOK))
            elseif taxOK==false and taxResult~="disabled" then
                Maintenance.addError(nil,"Податки: "..tostring(taxResult or "не вдалося перевірити"))
            else
                Maintenance.summary.taxes=taxResult or "checked"
            end

            local problems=ProblemCenter.build()
            for _,entry in ipairs(problems.houses or {}) do
                local reasons={}
                for _,item in ipairs(entry.items or {}) do
                    if item.kind=="visit" or item.kind=="blocked" then reasons[#reasons+1]=item.label end
                end
                if #reasons>0 and entry.house and entry.house.number then
                    Maintenance.visits[#Maintenance.visits+1]={house=entry.house.number,reasons=reasons}
                end
            end
        end)

        Maintenance.busy=false
        Maintenance.pendingHouse=nil;Maintenance.awaitRemote=false;Maintenance.remoteReady=false
        Maintenance.closingHouse=false
        if DialogGate.owner=="maintenance" then DialogGate.release("maintenance") end
        Maintenance.lastRun=os.time()
        Maintenance.stage=ok and "done" or "error"
        UI.notice=nil
        if not ok then
            Maintenance.addError(nil,err)
            Runtime.log("MAINTENANCE_ERROR",tostring(err))
        end
        local s=Maintenance.summary or {}
        local detail="Запущено GPU: "..tostring(s.started or 0).." · BTC: "..string.format("%.0f",s.btc or 0).." · електроенергія: "..tostring(s.electricity or 0)
        if s.taxes then detail=detail.." · податки: перевірено" end
        if #(Maintenance.visits or {})>0 then detail=detail.." · потрібен візит: "..tostring(#Maintenance.visits) end
        pushActivity("Обслуговування завершено",detail,(#(Maintenance.errors or {})>0) and "amber" or "green")
        Notify.raw("maintenance","Обслуговування завершено · "..detail,"maintenance_done:"..detail,3)
    end)
    return true
end

function View.coolantSelectionFromDialog(style,text)
    if style~=5 then return nil,nil,0 end

    -- TABLIST_HEADERS usually has a header, but Arizona also uses style 5 for
    -- lists where the first visible line is already selectable. Build response
    -- rows from the actual layout instead of blindly assuming coolant == row 0.
    local lines={}
    for raw in (tostring(text or "").."\n"):gmatch("([^\n]*)\n") do
        if raw:find("%S") then
            local clean=serverToUtf8(stripColors(raw)):gsub("\194\160"," "):gsub("^%s+",""):gsub("%s+$","")
            lines[#lines+1]={raw=raw,clean=clean,lower=lowerServerText(raw)}
        end
    end
    if #lines==0 then return nil,nil,0 end

    local function isCoolant(lower)
        return lower:find("охлаж",1,true) or lower:find("охолод",1,true)
            or lower:find("coolant",1,true) or lower:find("жидк",1,true)
            or lower:find("рідин",1,true)
    end
    local function itemCount(clean)
        return tonumber(clean:match("%[%s*(%d+)%s*%]"))
            or tonumber(clean:match("[xXхХ]%s*(%d+)%s*$"))
            or tonumber(clean:match("[Кк]оличеств[%w%s:]*([%d]+)"))
            or tonumber(clean:match("[Кк]ількіст[%w%s:]*([%d]+)"))
            or tonumber(clean:match("(%d+)%s*[шШ][тТ]%.?%s*$"))
            or tonumber(clean:match("%((%d+)%)%s*$"))
    end
    local first=lines[1]
    local firstSelectable=isCoolant(first.lower)
        or first.clean:match("^%s*%d+[%.)]%s*")~=nil
        or first.clean:match("%[%s*%d+%s*%]")~=nil
        or first.clean:match("[xXхХ]%s*%d+%s*$")~=nil
    local firstItem=firstSelectable and 1 or 2
    local candidates={}
    local responseRow=0
    for i=firstItem,#lines do
        local item=lines[i]
        local count=itemCount(item.clean)
        if isCoolant(item.lower) then
            Runtime.log("COOLANT_ROW","row="..tostring(responseRow).." count="..tostring(count or 0).." label="..item.clean)
            return responseRow,"1",count or 0
        end
        if count~=nil then candidates[#candidates+1]={row=responseRow,count=count,label=item.clean} end
        responseRow=responseRow+1
    end

    -- Safe compatibility fallback: only when there is exactly one selectable
    -- counted item. With multiple inventory entries we refuse to guess.
    if #candidates==1 then
        Runtime.log("COOLANT_ROW_FALLBACK","row="..tostring(candidates[1].row).." count="..tostring(candidates[1].count))
        return candidates[1].row,"1",candidates[1].count or 0
    end
    Runtime.log("COOLANT_ROW_MISSING","items="..tostring(#lines).." candidates="..tostring(#candidates))
    return nil,nil,0
end

function View.captureBasement(id,style,title,b1,b2,text)
    local state=View.basement
    View.basementMarkDialog(id)
    if state.flow and state.flow.generation==Runtime.generation then
        local flow=state.flow
        if flow.phase=="await_result" and flow.kind=="coolant" and id==DIALOG_COOLANT_SELECT then
            local coolantRow,input,count=View.coolantSelectionFromDialog(style,text)
            if coolantRow==nil or count<=0 then
                flow.error=I18n.text("Немає охолоджувальної рідини в інвентарі")
            else
                View.basementSafeRespond(id,1,coolantRow,input or "1",175,"select_coolant")
            end
            return false
        end
        local action=View.basementActionDialog(id,style,title,text)
        if flow.phase=="await_action" and action then
            flow.action=action
            return false
        end
        if flow.phase=="await_result" then
            if View.basementConfirmationLooksRelevant(title,text,flow.kind) then
                View.basementSafeRespond(id,1,0,"",175,"confirm_gpu_action")
                return false
            end
            local parsedResult=View.parseBasement(id,style,title,text)
            if parsedResult then
                state.groups=parsedResult.groups;state.overview=parsedResult.overview;state.remote=parsedResult.remote;state.house=parsedResult.house;state.id=id;state.generation=Runtime.generation;state.cooling={}
                if state.actionRow then
                    local refreshed=View.basementFindRowBySlot(flow.slot,flow.rack)
                    if refreshed then state.actionRow=refreshed else state.actionPanelOpen=false end
                end
                state.open[0]=not AutoRefill.active and not Maintenance.busy;state.serial=state.serial+1;flow.done=true
                return false
            end
            if action then
                View.basementSafeRespond(id,0,0,"",170,"back_gpu_action")
                return false
            end
        end
    end
    if AutoRefill.active and not state.flow then
        local autoParsed=View.parseBasement(id,style,title,text)
        if autoParsed and not autoParsed.overview and not autoParsed.remote and AutoRefill.handleParsed(autoParsed,id) then return false end
    end
    local installExpected=state.installExpected;state.installExpected=nil
    state.open[0]=false;state.serial=state.serial+1;state.pending=nil;state.empty=nil;state.installActions=nil;state.actionRow=nil;state.actionPanelOpen=false;state.actionPanelT=0;state.allActions=false;state.confirm=nil;state.refillConfirm=nil;state.closing=false
    if UI.collecting or UI.balanceUpdating or UI.scanning or UI.waiting or UI.loading or Taxes.busy or Electricity.busy or Electricity.checking then return end
    local parsed=View.parseBasement(id,style,title,text)
    if not parsed and installExpected and installExpected.generation==Runtime.generation and getGameTimer()-installExpected.time<8000 then
        local lower=lowerServerText((title or "").." "..(text or ""))
        if (style==2 or style==4 or style==5) and (lower:find("видеокарт",1,true) or lower:find("video card",1,true) or lower:find("gpu",1,true)) then
            local actions={};local index=style==5 and -1 or 0
            for raw in (tostring(text or "").."\n"):gmatch("([^\n]*)\n") do
                if index>=0 and raw:find("%S") then actions[#actions+1]={sourceRow=index,label=serverToUtf8(stripColors(raw)):gsub("[\t\r]"," ")} end
                index=index+1
            end
            if #actions>0 and #actions<=100 then state.installActions=actions;parsed={groups={},id=id,overview=false} end
        end
    end
    if not parsed then return end
    state.groups=parsed.groups;state.overview=parsed.overview;state.remote=parsed.remote;state.house=parsed.house;state.id=id;state.generation=Runtime.generation;state.cooling={}
    if Maintenance.busy and parsed.remote then
        if Maintenance.awaitRemote then
            Maintenance.remoteReady=true
            Maintenance.awaitRemote=false
            Maintenance.remoteError=nil
        end
        state.open[0]=false
        state.closing=false
        state.serial=state.serial+1
        return false
    end
    state.closing=false;state.closeStarted=0;state.openedAt=getGameTimer();state.open[0]=true
    Runtime.log("BASEMENT_OPEN",(parsed.overview and "overview" or "select").." id="..id)
    return false
end

function View.basementRespond(row)
    local state=View.basement
    if not state.open[0] then return end
    if row==nil and state.empty then state.empty=nil;state.pending=nil;return end
    if row~=nil and not state.overview and not state.empty and not state.installActions then
        for _,g in ipairs(state.groups) do for _,r in ipairs(g.rows) do
            if r.sourceRow==row then
                state.pending=nil
                if r.free then return end
                if state.actionPanelOpen and state.actionRow and state.actionRow.sourceRow==r.sourceRow then
                    View.closeSingleShelfPanel()
                else
                    state.actionRow=r;state.actionPanelOpen=true;state.allActions=false;state.confirm=nil;state.refillConfirm=nil
                end
                return
            end
        end end
    end
    state.open[0]=false
    if not Runtime.ready() or state.generation~=Runtime.generation then return end
    if row~=nil then
        if state.overview then return end
        local valid=false
        if state.installActions then for _,action in ipairs(state.installActions) do if action.sourceRow==row then valid=true end end end
        for _,g in ipairs(state.groups) do for _,r in ipairs(g.rows) do if r.sourceRow==row then valid=true end end end
        if not valid then return end
    end
    if row~=nil and state.empty then state.installExpected={time=getGameTimer(),generation=Runtime.generation};state.empty=nil end
    sampSendDialogResponse(state.id,row~=nil and 1 or 0,row or 0,"")
end

function View.basementText(x,y,text,font,color)
