function View.drawGPUSymbol(x,y,size,color,free,hover,phase)
    local dl=imgui.GetWindowDrawList();local w=size;local h=size*.53
    local ink=u32(color,.55+(hover or 0)*.4)
    if free then
        dl:AddCircle(imgui.ImVec2(x+w*.5,y+h*.5),h*.45,ink,40,1.5)
        dl:AddLine(imgui.ImVec2(x+w*.5-h*.17,y+h*.5),imgui.ImVec2(x+w*.5+h*.17,y+h*.5),ink,1.8)
        dl:AddLine(imgui.ImVec2(x+w*.5,y+h*.33),imgui.ImVec2(x+w*.5,y+h*.67),ink,1.8)
        return
    end
    View.drawSmoothRoundedRect(x,y,w,h,7,u32(color,.035),ink,1.5,16)
    for i=1,2 do
        local cx=x+w*(i==1 and .29 or .71);local cy=y+h*.5;local r=h*.30
        dl:AddCircle(imgui.ImVec2(cx,cy),r,ink,32,1.2)
        dl:AddCircleFilled(imgui.ImVec2(cx,cy),r*.19,ink,20)
        local angle=phase or 0
        for j=0,3 do
            local a=angle+j*math.pi/2
            dl:AddLine(imgui.ImVec2(cx+math.cos(a)*r*.3,cy+math.sin(a)*r*.3),imgui.ImVec2(cx+math.cos(a+.45)*r*.76,cy+math.sin(a+.45)*r*.76),ink,1.2)
        end
    end
    for i=0,5 do dl:AddLine(imgui.ImVec2(x+w*.33+i*w*.055,y+h+2),imgui.ImVec2(x+w*.33+i*w*.055,y+h+5),ink,2) end
end

function View.basementLayout(sx,sy,overview,remote)
    local defaultW=math.min(860,sx-32)
    local w=math.max(700,math.min(sx-16,tonumber(Settings.gpuWindowW) or defaultW))
    local content=156
    if View.basement.installActions then
        content=740
    else
        local allCount=#View.basementAllRows()
        if not overview and allCount>0 then
            content=content+(Settings.allShelvesLayout=="vertical" and 166 or 116)
            if View.basement.confirm then content=content+158 end
        end
        for _,g in ipairs(View.basement.groups or {}) do
            content=content+46
            for _,r in ipairs(g.rows) do content=content+(r.free and 84 or 120)+12 end
        end
    end
    local autoH=math.min(sy-32,880,math.max(420,content))
    local h=tonumber(Settings.gpuWindowH) and math.max(420,math.min(sy-16,Settings.gpuWindowH)) or autoH
    return w,h,1,132,620
end

