function View.drawCoolantRing(cx,cy,r,value,color,alpha)
    local dl=imgui.GetWindowDrawList()
    value=math.max(0,math.min(100,tonumber(value) or 0));alpha=alpha or 1
    dl:AddCircle(imgui.ImVec2(cx,cy),r,u32(P.muted,.10*alpha),64,3.2)
    if value<=.05 then return end
    local startA=-math.pi*.5
    local sweep=math.pi*2*(value/100)
    local parts=math.max(3,math.floor(64*value/100))
    local previous=nil
    for i=0,parts do
        local a=startA+sweep*(i/parts)
        local point=imgui.ImVec2(cx+math.cos(a)*r,cy+math.sin(a)*r)
        if previous then dl:AddLine(previous,point,u32(color,.82*alpha),3.2) end
        previous=point
    end
    if value>0 then
        dl:AddCircle(imgui.ImVec2(cx,cy),r+2.5,u32(color,.025*alpha),64,6.0)
    end
end

function View.drawGpuInlineButton(id,label,x,y,w,h,kind,accent,enabled,alpha,tooltip,priority)
    if w<12 or h<12 or (alpha or 0)<=.015 then return false end
    alpha=math.max(0,math.min(1,alpha or 1)); enabled=enabled~=false and alpha>.80
    priority=math.max(0,math.min(1,tonumber(priority) or (kind=="coolant" and .55 or 0)))
    imgui.SetCursorScreenPos(imgui.ImVec2(x,y));imgui.InvisibleButton(id,imgui.ImVec2(w,h))
    local hovered=enabled and imgui.IsItemHovered();local held=enabled and imgui.IsItemActive()
    local hoverT=smoothAnim(id.."_hover",hovered and 1 or 0,16)
    local pressT=smoothAnim(id.."_press",held and 1 or 0,24)
    local dl=imgui.GetWindowDrawList()

    local base={.034,.039,.053,1}
    local hoverBase={.046,.052,.070,1}
    local border={.22,.27,.38,1}
    local neutralTint={.46,.51,.62,1}
    local refillTint={.24,.86,.66,1}
    local tint=kind=="coolant" and refillTint or neutralTint

    local coolantAccent=(kind=="coolant") and priority or 0
    local surface=mixColor(base,hoverBase,hoverT*.86)
    if coolantAccent>0 then
        surface=mixColor(surface,{.045,.145,.105,1},.34+.26*coolantAccent+.10*hoverT)
    end
    local borderCol=kind=="coolant" and mixColor(border,refillTint,.40+.28*coolantAccent+.18*hoverT) or mixColor(border,neutralTint,.10+.16*hoverT)
    local inset=pressT*.9;local radius=math.min(15,h*.28)

    if coolantAccent>.08 and enabled then
        dl:AddRect(imgui.ImVec2(x-.5,y-.5),imgui.ImVec2(x+w+.5,y+h+.5),u32(refillTint,(.055+.055*coolantAccent+.045*hoverT)*alpha),radius+1,nil,2.2)
    end
    dl:AddRectFilled(imgui.ImVec2(x+2,y+3),imgui.ImVec2(x+w+2,y+h+3),u32(P.shadow,.09*alpha),radius)
    dl:AddRectFilled(imgui.ImVec2(x+inset,y+inset),imgui.ImVec2(x+w-inset,y+h-inset),u32(surface,.965*alpha),radius)
    dl:AddRect(imgui.ImVec2(x+.5+inset,y+.5+inset),imgui.ImVec2(x+w-.5-inset,y+h-.5-inset),u32(borderCol,(.16+.10*hoverT+.12*coolantAccent)*alpha),radius,nil,1)

    if coolantAccent>.08 then
        dl:AddRectFilled(imgui.ImVec2(x+14,y+1),imgui.ImVec2(x+w-14,y+2),u32(refillTint,(.045+.055*coolantAccent+.045*hoverT)*alpha),1)
    elseif hoverT>.01 then
        dl:AddRectFilled(imgui.ImVec2(x+12,y+1),imgui.ImVec2(x+w-12,y+2),u32(neutralTint,.045*hoverT*alpha),1)
    end

    local font=(w<70 or h<36) and Fonts.small or Fonts.body
    local size=View.calcText(label,font)
    if size.x>w-12 then font=Fonts.small;size=View.calcText(label,font) end
    local textColor=mixColor(P.muted,P.text,.80+hoverT*.16+coolantAccent*.12)
    if not enabled then textColor=mixColor(textColor,P.bg,.35) end
    View.drawTextAlpha(x+(w-size.x)*.5,y+(h-size.y)*.5+pressT*.4,label,font,textColor,alpha)
    if hovered and tooltip then drawTooltip("gpu_tip_"..id,I18n.text(tooltip),x,y,w,h) end
    return enabled and imgui.IsItemClicked(0)
end

function View.drawGpuInlineActions(row,x,y,w,h,reveal,accent)
    local state=View.basement
    reveal=math.max(0,math.min(1,reveal or 0));if reveal<=.01 then return end
    local ease=1-(1-reveal)^3;local pad=12
    local actionW=math.min(360,math.max(300,w*.45));local innerH=h-pad*2
    local targetX=x+w-pad-actionW;local startX=x+w+30;local ax=startX+(targetX-startX)*ease
    local gap=7;local enabled=not state.busy;local clicked=nil;local dl=imgui.GetWindowDrawList()
    local coolant=math.max(0,math.min(100,tonumber(row.coolant) or 0))
    local refillPriority=View.refillPriority(coolant)
    local coolantEnabled=enabled and coolant<99.95
    dl:PushClipRect(imgui.ImVec2(x+1,y+1),imgui.ImVec2(x+w-1,y+h-1),true)
    if ease>.15 then
        local sepX=ax-10
        dl:AddLine(imgui.ImVec2(sepX,y+16),imgui.ImVec2(sepX,y+h-16),u32({.45,.52,.78,1},.10*ease),1)
    end

    if state.refillConfirm and state.refillConfirm.sourceRow==row.sourceRow then
        local waste=View.refillWaste(coolant)
        View.drawSmoothRoundedRect(ax,y+pad,actionW,innerH,16,u32({.025,.060,.064,1},.96*ease),u32({.22,.91,.82,1},.28*ease),1,16)
        local line=string.format("%.0f%%  →  100%%  ·  %s %.0f%%",coolant,I18n.text("буде втрачено"),waste)
        local ls=View.calcText(line,Fonts.small);View.drawTextAlpha(ax+(actionW-ls.x)*.5,y+pad+11,line,Fonts.small,P.text,ease)
        local by=y+pad+innerH-38;local bw=(actionW-gap)/2
        if View.drawGpuInlineButton("##refill_force_"..row.sourceRow,I18n.text("Все одно заправити"),ax,by,bw,32,"coolant",accent,enabled,ease,I18n.text("Використати 1 охолоджувач (+50%)"),1) then
            state.refillConfirm=nil;dl:PopClipRect();View.basementRunAction("coolant",row,false,true);return
        end
        if View.drawGpuInlineButton("##refill_cancel_"..row.sourceRow,I18n.text("Скасувати"),ax+bw+gap,by,bw,32,"neutral",accent,enabled,ease,nil,0) then state.refillConfirm=nil end
        dl:PopClipRect();return
    end

    local toggleLabel=row.status=="Працює" and I18n.text("Зупинити") or I18n.text("Запустити")
    local toggleTip=row.status=="Працює" and I18n.text("Зупинити відеокарту") or I18n.text("Запустити відеокарту")
    if Settings.singleShelfLayout=="vertical" then
        local rowH=(innerH-gap)/2
        local topW=(actionW-gap*2)/3
        if View.drawGpuInlineButton("##gpu_inline_toggle_"..row.sourceRow,toggleLabel,ax,y+pad,topW,rowH,"toggle",accent,enabled,ease,toggleTip) then clicked="toggle" end
        if View.drawGpuInlineButton("##gpu_inline_btc_"..row.sourceRow,"BTC",ax+topW+gap,y+pad,topW,rowH,"btc",accent,enabled,ease,"Забрати прибуток BTC") then clicked="btc" end
        if View.drawGpuInlineButton("##gpu_inline_asc_"..row.sourceRow,"ASC",ax+(topW+gap)*2,y+pad,topW,rowH,"asc",accent,enabled,ease,"Забрати прибуток ASC") then clicked="asc" end
        local bottomY=y+pad+rowH+gap
        local refillW=(actionW-gap)*.68;local extractW=actionW-gap-refillW
        if View.drawGpuInlineButton("##gpu_inline_coolant_"..row.sourceRow,I18n.text("Заправити"),ax,bottomY,refillW,rowH,"coolant",accent,coolantEnabled,ease,I18n.text("Використати 1 охолоджувач (+50%)"),math.max(.72,refillPriority)) then clicked="coolant" end
        if View.drawGpuInlineButton("##gpu_inline_extract_"..row.sourceRow,I18n.text("Дістати"),ax+refillW+gap,bottomY,extractW,rowH,"extract",accent,enabled,ease,"Дістати відеокарту з полиці") then clicked="extract" end
    else
        local primaryW=math.max(104,math.min(128,actionW*.34));local sideX=ax+primaryW+gap;local sideW=actionW-primaryW-gap
        local cellH=(innerH-gap)/2
        if View.drawGpuInlineButton("##gpu_inline_toggle_"..row.sourceRow,toggleLabel,ax,y+pad,primaryW,innerH,"toggle",accent,enabled,ease,toggleTip) then clicked="toggle" end
        local topW=(sideW-gap)/2
        if View.drawGpuInlineButton("##gpu_inline_btc_"..row.sourceRow,"BTC",sideX,y+pad,topW,cellH,"btc",accent,enabled,ease,"Забрати прибуток BTC") then clicked="btc" end
        if View.drawGpuInlineButton("##gpu_inline_asc_"..row.sourceRow,"ASC",sideX+topW+gap,y+pad,topW,cellH,"asc",accent,enabled,ease,"Забрати прибуток ASC") then clicked="asc" end
        local bottomY=y+pad+cellH+gap
        local refillW=(sideW-gap)*.68;local extractW=sideW-gap-refillW
        if View.drawGpuInlineButton("##gpu_inline_coolant_"..row.sourceRow,I18n.text("Заправити"),sideX,bottomY,refillW,cellH,"coolant",accent,coolantEnabled,ease,I18n.text("Використати 1 охолоджувач (+50%)"),math.max(.72,refillPriority)) then clicked="coolant" end
        if View.drawGpuInlineButton("##gpu_inline_extract_"..row.sourceRow,I18n.text("Дістати"),sideX+refillW+gap,bottomY,extractW,cellH,"extract",accent,enabled,ease,"Дістати відеокарту з полиці") then clicked="extract" end
    end
    dl:PopClipRect()
    if clicked and enabled then
        if clicked=="coolant" then
            if coolant>=99.95 then state.notice=I18n.text("Охолодження вже 100%")
            elseif coolant>View.refillThreshold() then state.refillConfirm={sourceRow=row.sourceRow,slot=row.slot,coolant=coolant}
            else View.basementRunAction("coolant",row,false,false) end
        else View.basementRunAction(clicked,row,false) end
    end
end

function View.drawBasementCard(row,x,y,w,h,overview)
    local state=View.basement
    local selected=not overview and not row.free and state.actionPanelOpen and state.actionRow and state.actionRow.sourceRow==row.sourceRow
    local reveal=smoothAnim("gpu_inline_reveal_"..tostring(row.sourceRow),selected and 1 or 0,Settings.animations=="reduced" and 18 or 9)
    if Settings.animations=="off" then reveal=selected and 1 or 0 end
    local ease=reveal*reveal*(3-2*reveal);local actionW=math.min(360,math.max(300,w*.45))
    local hovered,pressed=false,false
    if not overview and not row.free and not state.busy then
        local clickW=math.max(118,w-(actionW+16)*ease)
        imgui.SetCursorScreenPos(imgui.ImVec2(x,y));imgui.InvisibleButton("##basement_gpu_"..row.sourceRow,imgui.ImVec2(clickW,h))
        hovered=imgui.IsItemHovered();pressed=imgui.IsItemActive() and imgui.IsMouseDown(0)
        if imgui.IsItemClicked(0) and not state.pending then state.pending={row=row.sourceRow,serial=state.serial,at=getGameTimer()} end
    end
    local pendingSelected=state.pending and state.pending.row==row.sourceRow
    local hover=smoothAnim("gpu_hover_"..state.serial.."_"..row.sourceRow,hovered and 1 or 0,11)
    local push=smoothAnim("gpu_press_"..state.serial.."_"..row.sourceRow,(pressed or pendingSelected) and 1 or 0,20)
    local selectGlow=smoothAnim("gpu_selected_"..tostring(row.sourceRow),selected and 1 or 0,10)
    y=y+push*.7;x=x+push*.7;w=w-push*1.4
    local accent=row.free and P.muted or (row.status=="Працює" and P.green or P.amber)
    local glass=mixColor({.030,.036,.053,1},{.045,.064,.092,1},hover*.38+selectGlow*.22)
    View.drawSmoothRoundedRect(x,y,w,h,25,u32(glass,.84),u32(mixColor({.36,.40,.54,1},accent,.32),.20+hover*.16+selectGlow*.20),1,24)
    if hover>.01 or selectGlow>.01 then
        local glow=math.max(hover,selectGlow)
        View.drawSmoothRoundedRect(x-1,y-1,w+2,h+2,26,nil,u32(accent,.045*glow),3,24)
    end
    local dl=imgui.GetWindowDrawList();local text=View.basementText
    local iconCx=x+57-4*ease;local iconCy=y+h*.5
    -- Coolant becomes part of the GPU identity instead of another horizontal meter.
    if not row.free then
        local target=math.max(0,math.min(100,tonumber(row.coolant) or 0));state.cooling=state.cooling or {};local key=tostring(row.sourceRow)
        local current=state.cooling[key] or target
        current=Settings.animations=="off" and target or current+(target-current)*(1-math.exp(-5*math.min(.05,tonumber(imgui.GetIO().DeltaTime) or .016)))
        state.cooling[key]=current
        local coolantColor=current<math.max(18,Settings.coolingWarn or 0) and P.red or (current<55 and P.amber or {.28,.72,1.0,1})
        View.drawCoolantRing(iconCx,iconCy,39,current,coolantColor,1)
        local mouse=imgui.GetMousePos()
        if (mouse.x-iconCx)^2+(mouse.y-iconCy)^2<=43^2 then
            drawTooltip("coolant_ring_"..row.sourceRow,I18n.text("Охолодження")..": "..string.format("%.1f%%",current),iconCx-43,iconCy-43,86,86)
        end
    end
    View.drawSmoothRoundedRect(iconCx-31,iconCy-22,62,44,14,u32(accent,.032),u32(accent,.09),1,18)
    state.fans=state.fans or {};local key=tostring(row.sourceRow);local phase=state.fans[key] or 0
    if Settings.animations=="full" then phase=(phase+math.min(.05,tonumber(imgui.GetIO().DeltaTime) or .016)*(hover+selectGlow*.6)*2.3)%(math.pi*2) end
    state.fans[key]=phase;View.drawGPUSymbol(iconCx-23,iconCy-13,46,accent,row.free,math.max(hover,selectGlow),phase)
    if not row.free and Settings.showCoolantPercent~=false then
        local shown=state.cooling and state.cooling[tostring(row.sourceRow)] or tonumber(row.coolant) or 0
        local pctText=string.format("%.0f%%",shown);local ps=View.calcText(pctText,Fonts.small)
        View.drawTextAlpha(iconCx-ps.x*.5,iconCy+21,pctText,Fonts.small,P.text,.90)
    end
    local tx=x+110-8*ease
    text(tx,y+20,I18n.text("Полиця ")..row.slot,Fonts.semibold,P.text)
    if row.free then text(tx,y+52,I18n.text("Вільна полиця"),Fonts.body,P.muted);return end
    local status=row.status=="Стан невідомий" and I18n.text("Невідомо") or I18n.text(row.status)
    text(tx+14,y+52,status,Fonts.body,accent)
    for i=3,1,-1 do dl:AddCircleFilled(imgui.ImVec2(tx+3,y+63),3+i*1.4,u32(accent,.022),24) end
    dl:AddCircleFilled(imgui.ImVec2(tx+3,y+63),3,u32(accent,.9),24)

    local metricsAlpha=math.max(0,1-ease*1.18);local metricsShift=22*ease
    if metricsAlpha>.01 then
        local rightEdge=x+w-22+metricsShift
        local amount=string.format("%.6f BTC",tonumber(row.btc) or 0);local font=w<620 and Fonts.semibold or Fonts.metric
        local aw=View.calcText(amount,font).x
        View.drawTextAlpha(rightEdge-aw,y+20,amount,font,P.green,metricsAlpha)
        local badge=tostring(row.level or "—").." "..I18n.text("рівень");local bw=View.calcText(badge,Fonts.body).x+22
        View.drawSmoothRoundedRect(rightEdge-bw,y+58,bw,27,10,u32(accent,.05*metricsAlpha),u32(accent,.11*metricsAlpha),1,16)
        View.drawTextAlpha(rightEdge-bw+11,y+61,badge,Fonts.body,P.muted,metricsAlpha)
    end
    View.drawGpuInlineActions(row,x,y,w,h,reveal,accent)
end

function View.drawActionGrid(x,y,w,items,layout,prefix,maxCols,buttonH)
    local vertical=layout~="horizontal"
    local gap=8
    local cols=vertical and 1 or math.min(maxCols or 3,#items)
    local bw=(w-gap*(cols-1))/cols
    local bh=buttonH or (vertical and 40 or 42)
    local kind=nil
    for i,item in ipairs(items) do
        local col=(i-1)%cols;local row=math.floor((i-1)/cols)
        local bx=x+col*(bw+gap);local by=y+row*(bh+gap)
        local danger=item.kind=="extract"
        if View.shellButton("##"..prefix.."_"..item.kind,item.label,bx,by,bw,bh,danger) then kind=item.kind end
    end
    local rows=math.max(1,math.ceil(#items/cols))
    return kind,y+rows*bh+(rows-1)*gap
end

function View.closeSingleShelfPanel()
