    state.actionPanelOpen=false;state.actionRow=nil;state.pending=nil;state.refillConfirm=nil
end

function View.drawSingleShelfPanel(x,y,w,h,row)
    local state=View.basement
    local accent=row.status=="Працює" and P.green or P.amber
    View.drawSmoothRoundedRect(x,y,w,h,25,u32(View.panelFill(false,true),.98),u32(accent,.14),1,24)
    View.basementText(x+18,y+16,"Керування GPU",Fonts.semibold,P.text)
    View.basementText(x+18,y+43,"Полиця "..tostring(row.slot),Fonts.body,P.muted)
    if View.shellButton("##single_panel_close","×",x+w-50,y+14,32,30,false) and not state.busy then View.closeSingleShelfPanel() end

    local status=row.status=="Стан невідомий" and "Невідомо" or row.status
    View.basementText(x+18,y+82,status,Fonts.body,accent)
    local btc=string.format("%.6f BTC",tonumber(row.btc) or 0)
    View.basementText(x+w-18-View.calcText(btc,Fonts.semibold).x,y+80,btc,Fonts.semibold,P.green)
    local level=tostring(row.level or "—").." "..I18n.text("рівень")
    View.basementText(x+18,y+111,level,Fonts.small,P.muted)

    local coolant=math.max(0,math.min(100,tonumber(row.coolant) or 0))
    View.basementText(x+18,y+143,"Охолодження",Fonts.small,P.muted)
    local pct=string.format("%.1f%%",coolant)
    View.basementText(x+w-18-View.calcText(pct,Fonts.small).x,y+143,pct,Fonts.small,P.text)
    View.drawSmoothRoundedRect(x+18,y+166,w-36,4,2,u32(P.muted,.12),nil,1,8)
    local fill=(w-36)*coolant/100
    if fill>0 then View.drawSmoothRoundedRect(x+18,y+166,fill,4,math.min(2,fill*.5),u32(coolant<Settings.coolingWarn and P.amber or P.green,.68),nil,1,8) end

    local actionY=y+196
    local toggleLabel=row.status=="Працює" and "Зупинити відеокарту" or "Запустити відеокарту"
