function View.drawExtractAllInline(x,y,w)
    local state=View.basement;local panelH=170
    local dl=imgui.GetWindowDrawList()
    View.drawSmoothRoundedRect(x,y,w,panelH,20,u32({.064,.049,.048,1},.80),u32(P.red,.18),1,18)
    dl:AddCircleFilled(imgui.ImVec2(x+22,y+25),4,u32(P.amber,.9),20)
    View.basementText(x+36,y+14,I18n.text("Дістати всі"),Fonts.semibold,P.text)
    local message=I18n.text("Перед зняттям усі відеокарти будуть заправлені до 100%, після цього AutoMiner збере доступний прибуток BTC і ASC, і лише потім дістане GPU. На заправку буде витрачена охолоджувальна рідина з інвентарю. Продовжити?")
    local lines=View.settingLines(message,w-32)
    for i=1,math.min(#lines,3) do View.basementText(x+16,y+44+(i-1)*18,lines[i],Fonts.small,P.muted) end
    local needed=0
    for _,r in ipairs(View.basementAllRows()) do
        local c=math.max(0,math.min(100,tonumber(r.coolant) or 0))
        needed=needed+math.max(0,math.ceil((100-c-.001)/50))
    end
    View.basementText(x+16,y+101,I18n.text("Орієнтовно потрібно охолоджувачів")..": "..needed,Fonts.small,P.amber)
    local by=y+126;local gap=8;local bw=(w-gap)/2
    if View.drawGpuInlineButton("##extract_all_confirm",I18n.text("Підготувати й дістати всі"),x,by,bw,36,"extract",P.red,not state.busy,1) then state.confirm=nil;View.basementRunAction("extract",nil,true) end
    if View.drawGpuInlineButton("##extract_all_cancel",I18n.text("Скасувати"),x+bw+gap,by,bw,36,"neutral",P.muted,not state.busy,1) then state.confirm=nil end
    return y+panelH
