function View.basementStats()
    local count,working,btc,coolantSum,coolantN=0,0,0,0,0
    for _,g in ipairs(View.basement.groups or {}) do for _,r in ipairs(g.rows or {}) do
        if not r.free then
            count=count+1;if r.status=="Працює" then working=working+1 end
            btc=btc+(tonumber(r.btc) or 0)
            if tonumber(r.coolant) then coolantSum=coolantSum+tonumber(r.coolant);coolantN=coolantN+1 end
        end
    end end
    return {count=count,working=working,btc=btc,coolant=coolantN>0 and coolantSum/coolantN or 0}
end

