    local actionY=y+50;local gap=7;local clicked=nil
    if vertical then
        local cols=3;local bw=(w-28-gap*(cols-1))/cols;local bh=40
        for i,item in ipairs(actions) do
            local col=(i-1)%cols;local row=math.floor((i-1)/cols);local bx=x+14+col*(bw+gap);local by=actionY+row*(bh+gap)
