function View.drawBasementBackdrop(x,y,w,h)
    local dl=imgui.GetWindowDrawList();local t=(getGameTimer()/1000)
    local anim=Settings.animations~="off"

    local baseShift=anim and ((math.sin(t*.10)+1)*.5) or .5
    local base=mixColor({.007,.012,.024,1},{.010,.016,.032,1},baseShift)
    View.drawSmoothRoundedRect(x+1,y+1,w-2,h-2,36,u32(base,.992),u32({.28,.34,.52,1},.16),1,32)

    local gx=x+8;local gy=y+8;local gw=w-16;local gh=h-16
    local cols,rows=6,5
    local uv=imgui.GetFontTexUvWhitePixel()
    local function quad(xa,ya,xb,yb,xc,yc,xd,yd,c1,c2,c3,c4)
        dl:PrimReserve(6,4)
        local baseIdx=dl._VtxCurrentIdx
        for _,index in ipairs({0,1,2,0,2,3}) do dl:PrimWriteIdx(baseIdx+index) end
        dl:PrimWriteVtx(imgui.ImVec2(xa,ya),uv,c1)
        dl:PrimWriteVtx(imgui.ImVec2(xb,yb),uv,c2)
        dl:PrimWriteVtx(imgui.ImVec2(xc,yc),uv,c3)
        dl:PrimWriteVtx(imgui.ImVec2(xd,yd),uv,c4)
    end
    local function sampleColor(u,v)
        local top=mixColor({.055,.32,.54,1},{.020,.040,.150,1},u)
        local bottom=mixColor({.010,.12,.22,1},{.32,.06,.34,1},u)
        local color=mixColor(top,bottom,v)
        local wave1=(math.sin(t*.16+u*3.1+v*2.7)+1)*.5
        local wave2=(math.cos(t*.12+u*4.3-v*2.2)+1)*.5
        color=mixColor(color,{.08,.42,.62,1},wave1*.18)
        color=mixColor(color,{.34,.10,.42,1},wave2*.16)
        color=mixColor(color,{.015,.020,.052,1},.26)
        return color
    end
    local vertices={}
    for iy=0,rows do
        vertices[iy]={}
        local v=iy/rows
        for ix=0,cols do
            local u=ix/cols
            local px=gx+gw*u
            local py=gy+gh*v
            if ix>0 and ix<cols then px=px+((anim and math.sin(t*.18+v*4.2+u*2.4) or 0)*12) end
            if iy>0 and iy<rows then py=py+((anim and math.cos(t*.15+u*3.6-v*2.1) or 0)*10) end
            vertices[iy][ix]={x=px,y=py,c=u32(sampleColor(u,v),.24)}
        end
    end
    for iy=0,rows-1 do
        for ix=0,cols-1 do
            local a=vertices[iy][ix]
            local b=vertices[iy][ix+1]
            local c=vertices[iy+1][ix+1]
            local d=vertices[iy+1][ix]
            quad(a.x,a.y,b.x,b.y,c.x,c.y,d.x,d.y,a.c,b.c,c.c,d.c)
        end
    end

    quad(gx,gy,gx+gw,gy,gx+gw,gy+gh,gx,gy+gh,
        u32({.010,.012,.020,1},.10),u32({.010,.012,.020,1},.03),u32({.010,.012,.020,1},.18),u32({.010,.012,.020,1},.12))

    View.drawSmoothRoundedRect(x+1,y+1,w-2,h-2,36,u32({.006,.010,.020,1},.36),nil,1,32)
    for i=1,6 do
        View.drawSmoothRoundedRect(x+i,y+i,w-i*2,h-i*2,36-i,nil,u32(P.shadow,.014*i),i,32)
    end
end

