function CollectFlow.updateBalances()
    if Taxes.recording or Taxes.busy then return end
    if UI.collecting or UI.balanceUpdating or UI.scanning or UI.waiting or UI.pendingUserHouse then return end
    if Runtime.foreignDialog() then return end
    if #UI.houses==0 then return end
    local claimed=DialogGate.claim("collect","balance_refresh",{})
    if not claimed then return end
    UI.balanceUpdating=true;UI.dialogCaptured=false
    CollectFlow.id=-1;CollectFlow.failure=nil;CollectFlow.expected=nil
    local ok,err=pcall(function()
        for _,house in ipairs(UI.houses) do
            if house.miningStatus=="available" then
                CollectFlow.openHouse(house)
                CollectFlow.refreshHouse(house)
                CollectFlow.closeHouse()
                wait(120)
            end
        end
    end)
    if not ok and (CollectFlow.id==DIALOG_HOUSE or CollectFlow.id==DIALOG_MINER_LIST or CollectFlow.id==25244) then
        pcall(DialogGate.tx,"collect",CollectFlow.id,0,0,"",140,"balance_abort")
        wait(160)
    end
    CollectFlow.id=-1;CollectFlow.expected=nil;UI.balanceUpdating=false
    if DialogGate.owner=="collect" then DialogGate.release("collect") end
    if not ok then Runtime.log("BALANCE_ERROR",err,30) else UI.lastBalanceTime=os.time() end
    IncomeAnalytics.maybeSave(false)
end

-- Clear only transient transaction state after reconnect/session replacement.
-- Persistent settings, analytics and saved history are intentionally preserved.
function Runtime.resetTransient(reason)
    if AutoRefill and type(AutoRefill.releaseAlt)=="function" then pcall(AutoRefill.releaseAlt) end
    AutoRefill.active=false;AutoRefill.processing=false;AutoRefill.generation=0;AutoRefill.nextAltAt=0;AutoRefill.processed=0
    UI.collecting=false;UI.balanceUpdating=false;UI.scanning=false;UI.waiting=false;UI.loading=false;UI.pendingUserHouse=nil;UI.dialogCaptured=false
    if UI.collect then UI.collect.phase="idle";UI.collect.value=0;UI.collect.target=0;UI.collect.velocity=0;UI.collect.reason=nil end
    CollectFlow.id=-1;CollectFlow.text="";CollectFlow.title="";CollectFlow.expected=nil;CollectFlow.failure=nil
    CollectFlow.confirmation=nil;CollectFlow.confirmSent=false;CollectFlow.confirmFingerprint=nil;CollectFlow.confirmAmount=nil
    CollectFlow.inventoryCredit=nil;CollectFlow.withdrawing=false;CollectFlow.tooLow=false;CollectFlow.houseNumber=nil;CollectFlow.gpuSlot=nil;CollectFlow.gpuRack=nil;CollectFlow.stage=nil
    Taxes.busy=false;Taxes.direct=false;Taxes.dialog=nil;Taxes.result=nil;Taxes.abort=nil;Taxes.recording=nil;Taxes.phoneSeen=false;Taxes.phoneOwned=false;Taxes.phoneClosed=false
    Electricity.busy=false;Electricity.checking=false;Electricity.dialog=nil;Electricity.result=nil;Electricity.abort=nil;Electricity.target=nil;Electricity.stage=nil
    Maintenance.busy=false;Maintenance.pendingHouse=nil;Maintenance.awaitRemote=false;Maintenance.remoteReady=false;Maintenance.remoteError=nil;Maintenance.closingHouse=false;Maintenance.houseClosed=false
    local bs=Runtime.basement
    if bs then
        bs.open[0]=false;bs.busy=false;bs.flow=nil;bs.groups={};bs.id=nil;bs.pending=nil;bs.empty=nil;bs.actionRow=nil;bs.actionPanelOpen=false;bs.confirm=nil;bs.refillConfirm=nil;bs.closing=false;bs.lastDialogId=nil;bs.lastDialogAt=0
    end
    Runtime.phoneOpen=false;Runtime.cefCursor=false;Runtime.replacingNotice=nil
    DialogGate.reset(reason or "transient reset")
end

function Runtime.activity()
    Runtime.lastActivity=os.time()
    if Runtime.afk then Runtime.afk=false;Runtime.log("AFK_OFF","player input") end
end
function Runtime.afkStep(now)
    Runtime.lastActivity=Runtime.lastActivity or now
    if getCharCoordinates and Runtime.ready() then
        local ok,x,y,z=pcall(getCharCoordinates,PLAYER_PED)
        if ok and x and y and z then
            local p=Runtime.playerPosition
            if p and (x-p[1])^2+(y-p[2])^2+(z-p[3])^2>.04 then Runtime.activity() end
            Runtime.playerPosition={x,y,z}
        end
    end
    local active=Settings.afkEnabled and now-Runtime.lastActivity>=(Settings.afkMinutes or 10)*60
    if active~=Runtime.afk then Runtime.afk=active;Runtime.log(active and "AFK_ON" or "AFK_OFF","idle="..math.max(0,now-Runtime.lastActivity)) end
end
function Runtime.isPasswordNotice(style,title,text)
    if style~=0 then return false end
    local t=lowerServerText((title or "").." "..(text or ""))
    if not t:find("парол",1,true) then return false end
    for _,word in ipairs({"введите","введіть","неверн","неправил","авторизац","регистрац","реєстрац"}) do if t:find(word,1,true) then return false end end
    return t:find("не установлен",1,true)~=nil or t:find("не задан",1,true)~=nil
        or t:find("отсутств",1,true)~=nil or t:find("нет парол",1,true)~=nil
        or t:find("не встановлен",1,true)~=nil or t:find("відсут",1,true)~=nil
end
function Runtime.canReplaceNotice()
    local d=Runtime.passwordNotice
    return d and Runtime.ready() and Runtime.readySince and os.time()-Runtime.readySince>=5
        and sampIsDialogActive and sampIsDialogActive() and sampGetCurrentDialogId and sampGetCurrentDialogId()==d.id
end
function Runtime.dataUnknown()
    return Runtime.dataReady==false or #UI.houses==0
end
function Runtime.clearAfkDialog()
    if not Runtime.afk or not Runtime.ready() or Runtime.busy() or Taxes.busy or Taxes.recording then return false end
    if not Runtime.foreignDialog() then return true end
    local now=os.time()
    if now<(Runtime.cancelAfter or 0) then return false end
    Runtime.cancelAfter=now+5
    local id=sampGetCurrentDialogId and sampGetCurrentDialogId() or -1
    if Runtime.canReplaceNotice() then return false end
    if Runtime.authDialog==id then Scheduler.blocked="Очікуємо входу в гру";return false end
    if Runtime.cancelId~=id then Runtime.cancelId=id;Runtime.cancelAttempts=0 end
    Runtime.cancelAttempts=(Runtime.cancelAttempts or 0)+1
    if Runtime.cancelAttempts>3 then
        Runtime.cancelAfter=now+60
        Runtime.log("DIALOG_RECOVERY_BLOCKED","id="..tostring(id).." native="..tostring(sampIsDialogActive and sampIsDialogActive()).." phone="..tostring(Runtime.phoneOpen).." cursor="..tostring(Runtime.cefCursor),60)
        return false
    end
    Runtime.log("AFK_CANCEL_DIALOG","id="..tostring(id))
    if sampIsDialogActive and sampIsDialogActive() then
        if sampCloseCurrentDialogWithButton then sampCloseCurrentDialogWithButton(0) end
    elseif Runtime.phoneOpen then
        sampSendChat("/phone")
        Runtime.cancelAfter=now+8
    end
    return not Runtime.foreignDialog()
end
if addEventHandler then
    addEventHandler("onWindowMessage",function(msg,wparam,lparam)
        if msg==0x0006 then Runtime.focused=(wparam%65536)~=0;return end
        if msg==0x001C then Runtime.focused=wparam~=0;return end
        if Runtime.focused==false then return end
        if AutoRefill.active and (msg==0x0100 or msg==0x0101) and tonumber(wparam)==0x1B then
            if consumeWindowMessage then consumeWindowMessage(true,true) end
            if msg==0x0100 then
                if not Runtime.escapeDown then AutoRefill.stop(nil,true) end
                Runtime.escapeDown=true
            else Runtime.escapeDown=false end
            return
        end
        if View.anyScriptWindowVisible and View.anyScriptWindowVisible() then
            if msg==0x0201 or msg==0x0202 then
                if consumeWindowMessage then consumeWindowMessage(true,true) end
            elseif (msg==0x0100 or msg==0x0101) and tonumber(wparam)==0x1B then
                if consumeWindowMessage then consumeWindowMessage(true,true) end
                if msg==0x0100 then
                    if not Runtime.escapeDown and View.handleEscape then View.handleEscape() end
                    Runtime.escapeDown=true
                else Runtime.escapeDown=false end
                return
            end
        end
        if (msg>=0x0100 and msg<=0x0107) or (msg>=0x0201 and msg<=0x020E) then Runtime.activity()
        elseif msg==0x0200 then
            if Runtime.mousePosition and Runtime.mousePosition~=lparam then Runtime.activity() end
            Runtime.mousePosition=lparam
        end
    end)
end
function Runtime.schedulerStep()
    local now=os.time()
    if now>=(Runtime.cacheSweep or 0) then
        Runtime.cacheSweep=now+600
        local count=0;for _ in pairs(CardAnim) do count=count+1 end
        if count>2048 then CardAnim={} end
    end
    if Runtime.lastBeat and now-Runtime.lastBeat>5 then
        Runtime.log("EXECUTION_GAP","seconds="..(now-Runtime.lastBeat))
        if now-Runtime.lastBeat>600 then IncomeAnalytics.markGap(now,now-Runtime.lastBeat) end
    end
    Runtime.lastBeat=now
    Runtime.afkStep(now)
    Runtime.log("RECOVERY_STATE","ready="..tostring(Runtime.ready()).." houses="..#UI.houses.." waiting="..tostring(UI.waiting).." scanning="..tostring(UI.scanning).." native="..tostring(sampIsDialogActive and sampIsDialogActive()).." phone="..tostring(Runtime.phoneOpen).." cursor="..tostring(Runtime.cefCursor),60)
    local connected=Runtime.ready()
    local identity=connected and Runtime.identity() or nil
    if not connected or (Runtime.sessionKey and identity and Runtime.sessionKey~=identity) then
        if Runtime.readySince then
            Runtime.log("CONNECTION_RESET","gamestate="..tostring(sampGetGamestate()).." spawned="..tostring(sampIsLocalPlayerSpawned()))
            Runtime.generation=(Runtime.generation or 0)+1
            Runtime.dataReady=false;Runtime.initialRetry=0;Runtime.rescanAt=0;Runtime.requestStarted=nil
            Runtime.cancelId=nil;Runtime.cancelAttempts=0;Runtime.cancelAfter=0
            Scheduler.attemptAt=0;Scheduler.retryAt=0
            Runtime.playerPosition=nil;Runtime.activity()
            UI.requestId=UI.requestId+1;UI.houses={}
            Runtime.resetTransient("connection/session reset")
            ForecastTracker.houses={}
            IncomeAnalytics.markGap(now,1)
            IncomeAnalytics.houseState={};MiningModel.samples={};RateTracker.houses={};RateTracker.withdrawn={}
        end
        Runtime.readySince=nil;Runtime.sessionKey=nil;return
    end
    Runtime.sessionKey=identity
    Runtime.readySince=Runtime.readySince or now
    if now-Runtime.readySince<5 then Scheduler.blocked="Відновлюємо дані";return end
    if UI.pendingUserHouse and now>(UI.pendingUserDeadline or 0) then
        UI.pendingUserHouse=nil;UI.notice="Будинок не відкрився. Спробуйте ще раз.";Runtime.log("MANUAL_TIMEOUT","")
    end
    if Runtime.requestStarted and now-Runtime.requestStarted>45 and not UI.collecting and not UI.balanceUpdating then
        UI.requestId=UI.requestId+1;UI.waiting=false;UI.scanning=false;UI.loading=false
        Runtime.requestStarted=nil;Runtime.initialRetry=now+5
        Runtime.log("RECOVERY_REQUEST_TIMEOUT","cancel stale scan")
    end
    if #UI.houses==0 or Runtime.dataReady==false then
        if Runtime.foreignDialog() and not Runtime.canReplaceNotice() then Runtime.clearAfkDialog() end
        if now>=Runtime.initialRetry and not Runtime.busy() then Runtime.initialRetry=now+10;requestHouses(true) end
        Scheduler.blocked="Перевіряємо ферми";return
    end
    if Runtime.canReplaceNotice() and not Runtime.busy() and now>=Runtime.initialRetry then Runtime.initialRetry=now+10;requestHouses(true);return end
    if Settings.autoElectricity then
        local electricDue=tonumber(Settings.nextElectricityCheck) or 0
        if electricDue<=0 then
            Settings.nextElectricityCheck=now+AUTO_ELECTRICITY_INTERVAL;saveSettings()
        elseif now>=electricDue and not Runtime.busy() then
            if Runtime.foreignDialog() then
                local _,state=Runtime.requestAutomationDialogClose("electricity")
                if state=="closing" then Scheduler.blocked=I18n.text("Закриваємо відкрите меню…");return end
                if state=="protected" then Scheduler.blocked=I18n.text("Очікуємо завершення входу в гру");return end
            elseif Electricity.scheduleCheck() then
                Scheduler.blocked=I18n.text("Відкриваємо банк для поповнення електроенергії");return
            end
        end
    end
    if Settings.collectMode=="manual" or Settings.autoPaused then Scheduler.blocked=nil;return end
    local due=Scheduler.retryAt>0 and Scheduler.retryAt or (Settings.nextCollectAt or 0)
    if due<=0 then scheduleNextCollection(true);return end
    if now>=due and now>=(Scheduler.attemptAt or 0) then
        Scheduler.attemptAt=now+10
        local source=Scheduler.retryAt>0 and "retry" or "scheduled"
        if Runtime.foreignDialog() then Runtime.clearAfkDialog() end
        local ok,reason=UI.collect.trigger(source)
        if ok then
            Scheduler.blocked=nil;Scheduler.retryAt=0;Runtime.log("SCHEDULE_STARTED","due="..due.." late="..(now-due))
        elseif reason=="__dialog_recovery__" then
            Scheduler.blocked=I18n.text("Закриваємо відкрите меню…");Scheduler.attemptAt=now+1
            Runtime.log("SCHEDULE_DIALOG_RECOVERY","due="..due,5)
        elseif reason=="__protected_dialog__" then
            Scheduler.blocked=I18n.text("Очікуємо завершення входу в гру");Scheduler.attemptAt=now+10
            Runtime.log("SCHEDULE_PROTECTED_DIALOG","due="..due,10)
        else
            Scheduler.blocked=reason;Runtime.log("SCHEDULE_BLOCKED","due="..due.." reason="..tostring(reason),60)
        end
    end
    if not Runtime.busy() and not Runtime.foreignDialog() and now>=(Runtime.rescanAt or 0) then
        for _,h in ipairs(UI.houses) do
            if h.miningStatus=="unknown" or h.miningStatus=="checking" then Runtime.rescanAt=now+120;requestHouses(true);break end
        end
    end
    Runtime.log("HEARTBEAT","phase="..UI.collect.phase.." collecting="..tostring(UI.collecting).." due="..tostring(Settings.nextCollectAt).." blocked="..tostring(Scheduler.blocked),60)
end

function main()
    Runtime.sessionId=tostring(os.time()).."-"..tostring(getGameTimer())
    Runtime.log("START",Runtime.revision)
    cleanupAutoMinerTemps();ensureAutoMinerDirectory(autoMinerRootPath().."\assets")
    Runtime.log("LANGUAGE_LOADED","language="..tostring(Settings.language))
    Taxes.init()
    local ignoredFile=Runtime.open(dataDirPath().."\\ignored.cfg","r")
    if ignoredFile then for line in ignoredFile:lines() do local id=tonumber(line);if id then Ignored[id]=true end end;ignoredFile:close() end
    MiningModel.load()
    IncomeAnalytics.load()
    IncomeAnalytics.migrateLossModel()
    IncomeAnalytics.markGap(os.time(),1)
    BitcoinHistory.load()
    BitcoinHourly.load()
    BitcoinPrice.load()
    Journal.load()
    Journal.importIncomeHistory(IncomeAnalytics.collections)
    while not isSampAvailable() do wait(100) end
    Runtime.log("UI_INIT_MODE","fonts_only_safe_prewarm")
    lua_thread.create(function()
        local stableSince=nil
        while true do
            wait(100)
            if Runtime.ready() then
                stableSince=stableSince or getGameTimer()
                if getGameTimer()-stableSince>=1800 then break end
            else
                stableSince=nil
            end
        end
        UIResources.prewarmRequested=true
        UIResources.prewarmRequestedAt=getGameTimer()
        Runtime.log("PERF_PREWARM_REQUEST","runtime_ready_1800ms")
    end)
    lua_thread.create(function() wait(8000);if not UI.open[0] and not UI.closing then UpdateManager.check(false) else wait(5000);UpdateManager.check(false) end end)
    Journal.add("system","AutoMiner запущено","Нова сесія · /miner")
    local function toggleMiner()
        if UI.open[0] or UI.closing then View.requestMainClose(); return end
        UI.activeTab = Settings.startTab
        Motion.pageDir=1;Motion.pageStart=getGameTimer();Motion.graphStart=getGameTimer()
        UI.open[0] = true
        WaterMotion.openKick = true
        kickWater(0,.34)
        if #UI.houses == 0 and not UI.scanning and not UI.waiting then requestHouses() end
    end
    sampRegisterChatCommand("miner",toggleMiner)
    sampRegisterChatCommand("autominer",toggleMiner)

    sampRegisterChatCommand("minercenter",function()
        Settings.windowX=nil;Settings.windowY=nil;UI.open[0]=true;saveSettings()
    end)
    lua_thread.create(function()
        while true do
            wait(50)
            UI.collect.tick(getGameTimer())
            AutoRefill.step()
            if Taxes.recording and getGameTimer()>Taxes.recording.deadline then
                Taxes.recording=nil;Taxes.note("Час запису маршруту минув. Спробуйте ще раз.")
            end
        end
    end)
    math.randomseed(os.time()+getGameTimer())
    Notify.event("startup")
    if Settings.collectMode~="manual" and not Settings.autoPaused and (tonumber(Settings.nextCollectAt) or 0)<=0 then scheduleNextCollection(true) end
    fetchBitcoinPrice()
    fetchBitcoinHistory()
    fetchBitcoinHourly()
    lua_thread.create(function()
        while true do
            wait(1000)
            if not BitcoinPrice.busy and getGameTimer()>=BitcoinPrice.nextAttempt then fetchBitcoinPrice() end
            if not BitcoinHistory.busy and getGameTimer()>=(BitcoinHistory.nextAttempt or 0) then fetchBitcoinHistory() end
            if not BitcoinHourly.busy and getGameTimer()>=(BitcoinHourly.nextAttempt or 0) then fetchBitcoinHourly() end
        end
    end)
    lua_thread.create(function()
        while true do
            wait(60000)
            if not UpdateManager.checking and not UpdateManager.installing and os.time()>=(UpdateManager.nextCheck or 0) then UpdateManager.check(false) end
        end
    end)
    lua_thread.create(function()
        while true do
            wait(1000)
            local ok,err=pcall(Runtime.schedulerStep)
            if not ok then Runtime.log("SCHEDULER_ERROR",err,30);Scheduler.blocked="Помилка автозбору — дивіться журнал" end
        end
    end)
    while true do wait(60000);if Runtime.ready() then CollectFlow.updateBalances() end end
end


function onExitScript()
    AutoRefill.stop(nil,false)
    pcall(IncomeAnalytics.save)
    Runtime.log("STOP",Runtime.revision)
end
